CREATE TABLE "account_enforcement" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"auth_user_id" uuid NOT NULL,
	"kind" "enforcement_kind" NOT NULL,
	"starts_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"expires_at" timestamp(3) with time zone,
	"decision_action_id" uuid NOT NULL CONSTRAINT "account_enforcement_decision_action_key" UNIQUE,
	"revocation_action_id" uuid,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "account_enforcement_time_check" CHECK ("expires_at" is null or "expires_at" > "starts_at"),
	CONSTRAINT "account_enforcement_action_check" CHECK ("revocation_action_id" is null or "revocation_action_id" <> "decision_action_id")
);

CREATE TABLE "account_enforcement_action" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"decision_id" uuid,
	"actor_auth_user_id" uuid NOT NULL,
	"target_auth_user_id" uuid NOT NULL,
	"kind" "account_enforcement_action_kind" NOT NULL,
	"enforcement_kind" "enforcement_kind" NOT NULL,
	"reverses_action_id" uuid,
	"request_id" text,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "account_enforcement_action_reversal_check" CHECK (("kind" = 'revoke'::account_enforcement_action_kind) = ("reverses_action_id" is not null)),
	CONSTRAINT "account_enforcement_action_not_self_reverse" CHECK ("reverses_action_id" is null or "reverses_action_id" <> "id")
);

CREATE TABLE "account_entity_block" (
	"blocker_auth_user_id" uuid,
	"blocked_entity_id" uuid,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "account_entity_block_pkey" PRIMARY KEY("blocker_auth_user_id","blocked_entity_id")
);

CREATE TABLE "account_erasure" (
	"auth_user_id" uuid PRIMARY KEY,
	"self_entity_id" uuid,
	"prior_email" text,
	"stage" text DEFAULT 'sessions' NOT NULL,
	"completed_batches" integer DEFAULT 0 NOT NULL,
	"available_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"completed_at" timestamp(3) with time zone,
	CONSTRAINT "account_erasure_stage_check" CHECK ("stage" in ('sessions', 'credentials', 'quota_account_leases', 'quota_account_daily', 'quota_account_rates', 'quota_reservations', 'quota_account_binding', 'api_tokens', 'verification', 'auth_mail', 'preferences', 'notifications', 'notification_preferences', 'notification_stats', 'sent_messages', 'conversation_reads', 'conversation_stats', 'account_blocks', 'progress', 'progress_entries', 'progress_nodes', 'recommendation_events', 'recommendation_exclusions', 'studio_visits', 'studio_candidates', 'follow_preferences', 'membership_sent_invitations', 'organization_membership_events', 'organization_memberships', 'membership_received_invitations', 'favorite_history', 'favorites', 'favorites_state', 'tag_subscriptions', 'personal_tags', 'private_images', 'complete')),
	CONSTRAINT "account_erasure_complete_check" CHECK (("stage" = 'complete') = ("completed_at" is not null) and ("stage" <> 'complete' or ("prior_email" is null and "self_entity_id" is null)))
);

CREATE TABLE "account_favorite" (
	"auth_user_id" uuid,
	"target_unit_id" uuid,
	"target_unit_publishing_id" uuid,
	"target_unit_music_id" uuid,
	"target_unit_program_id" uuid,
	"target_unit_software_id" uuid,
	"target_unit_entity_id" uuid,
	"target_unit_grouping_id" uuid,
	"target_unit_reference_id" uuid,
	"target_unit_distribution_id" uuid,
	"target_unit_video_id" uuid,
	"target_unit_audio_id" uuid,
	"target_unit_post_id" uuid,
	"target_unit_poll_id" uuid,
	"target_unit_zone_id" uuid,
	"target_unit_realm_id" uuid,
	"target_unit_realm_rule_id" uuid,
	"target_unit_custom_theme_id" uuid,
	"target_unit_collection_id" uuid,
	"target_unit_tag_id" uuid,
	"target_unit_tag_path_id" uuid,
	"target_unit_label_id" uuid,
	"target_owner" text GENERATED ALWAYS AS (case when "target_unit_publishing_id" is not null then 'publishing' when "target_unit_music_id" is not null then 'music' when "target_unit_program_id" is not null then 'program' when "target_unit_software_id" is not null then 'software' when "target_unit_entity_id" is not null then 'entity' when "target_unit_grouping_id" is not null then 'grouping' when "target_unit_reference_id" is not null then 'reference' when "target_unit_distribution_id" is not null then 'distribution' when "target_unit_video_id" is not null then 'video' when "target_unit_audio_id" is not null then 'audio' when "target_unit_post_id" is not null then 'post' when "target_unit_poll_id" is not null then 'poll' when "target_unit_zone_id" is not null then 'zone' when "target_unit_realm_id" is not null then 'realm' when "target_unit_realm_rule_id" is not null then 'realm_rule' when "target_unit_custom_theme_id" is not null then 'custom_theme' when "target_unit_collection_id" is not null then 'collection' when "target_unit_tag_id" is not null then 'tag' when "target_unit_tag_path_id" is not null then 'tag_path' when "target_unit_label_id" is not null then 'label' else null end) STORED NOT NULL,
	"position" text collate "C" NOT NULL,
	"note" text,
	"snapshot" jsonb NOT NULL,
	"revision" bigint NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "account_favorite_pkey" PRIMARY KEY("auth_user_id","target_unit_id"),
	CONSTRAINT "account_favorite_position_key" UNIQUE("auth_user_id","position"),
	CONSTRAINT "account_favorite_target_unit_target_check" CHECK (num_nonnulls("target_unit_publishing_id", "target_unit_music_id", "target_unit_program_id", "target_unit_software_id", "target_unit_entity_id", "target_unit_grouping_id", "target_unit_reference_id", "target_unit_distribution_id", "target_unit_video_id", "target_unit_audio_id", "target_unit_post_id", "target_unit_poll_id", "target_unit_zone_id", "target_unit_realm_id", "target_unit_realm_rule_id", "target_unit_custom_theme_id", "target_unit_collection_id", "target_unit_tag_id", "target_unit_tag_path_id", "target_unit_label_id") = 1),
	CONSTRAINT "account_favorite_target_unit_id_check" CHECK ("target_unit_id" is not distinct from coalesce("target_unit_publishing_id", "target_unit_music_id", "target_unit_program_id", "target_unit_software_id", "target_unit_entity_id", "target_unit_grouping_id", "target_unit_reference_id", "target_unit_distribution_id", "target_unit_video_id", "target_unit_audio_id", "target_unit_post_id", "target_unit_poll_id", "target_unit_zone_id", "target_unit_realm_id", "target_unit_realm_rule_id", "target_unit_custom_theme_id", "target_unit_collection_id", "target_unit_tag_id", "target_unit_tag_path_id", "target_unit_label_id")),
	CONSTRAINT "account_favorite_note_check" CHECK ("note" is null or octet_length("note") <= 65536),
	CONSTRAINT "account_favorite_snapshot_check" CHECK (jsonb_typeof("snapshot") = 'object' and octet_length("snapshot"::text) <= 8192),
	CONSTRAINT "account_favorite_revision_check" CHECK ("revision" between 1 and 9007199254740991),
	CONSTRAINT "account_favorite_position_check" CHECK (octet_length("position") <= 1024)
);

CREATE TABLE "account_favorite_revision" (
	"auth_user_id" uuid,
	"revision" bigint,
	"target_unit_id" uuid NOT NULL,
	"target_unit_publishing_id" uuid,
	"target_unit_music_id" uuid,
	"target_unit_program_id" uuid,
	"target_unit_software_id" uuid,
	"target_unit_entity_id" uuid,
