	"target_unit_post_id" uuid,
	"target_unit_poll_id" uuid,
	"target_unit_zone_id" uuid,
	"target_unit_realm_id" uuid,
	"target_unit_realm_rule_id" uuid,
	"target_unit_custom_theme_id" uuid,
	"target_unit_collection_id" uuid,
	"target_unit_tag_id" uuid,
	"target_unit_tag_path_id" uuid,
	"target_unit_label_id" uuid,
	"target_owner" text GENERATED ALWAYS AS (case when "target_unit_publishing_id" is not null then 'publishing' when "target_unit_music_id" is not null then 'music' when "target_unit_program_id" is not null then 'program' when "target_unit_software_id" is not null then 'software' when "target_unit_entity_id" is not null then 'entity' when "target_unit_grouping_id" is not null then 'grouping' when "target_unit_reference_id" is not null then 'reference' when "target_unit_distribution_id" is not null then 'distribution' when "target_unit_video_id" is not null then 'video' when "target_unit_audio_id" is not null then 'audio' when "target_unit_post_id" is not null then 'post' when "target_unit_poll_id" is not null then 'poll' when "target_unit_zone_id" is not null then 'zone' when "target_unit_realm_id" is not null then 'realm' when "target_unit_realm_rule_id" is not null then 'realm_rule' when "target_unit_custom_theme_id" is not null then 'custom_theme' when "target_unit_collection_id" is not null then 'collection' when "target_unit_tag_id" is not null then 'tag' when "target_unit_tag_path_id" is not null then 'tag_path' when "target_unit_label_id" is not null then 'label' else null end) STORED NOT NULL,
	"operation" text NOT NULL,
	"snapshot" jsonb,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "account_favorite_revision_pkey" PRIMARY KEY("auth_user_id","revision"),
	CONSTRAINT "account_favorite_revision_target_unit_target_check" CHECK (num_nonnulls("target_unit_publishing_id", "target_unit_music_id", "target_unit_program_id", "target_unit_software_id", "target_unit_entity_id", "target_unit_grouping_id", "target_unit_reference_id", "target_unit_distribution_id", "target_unit_video_id", "target_unit_audio_id", "target_unit_post_id", "target_unit_poll_id", "target_unit_zone_id", "target_unit_realm_id", "target_unit_realm_rule_id", "target_unit_custom_theme_id", "target_unit_collection_id", "target_unit_tag_id", "target_unit_tag_path_id", "target_unit_label_id") = 1),
	CONSTRAINT "account_favorite_revision_target_unit_id_check" CHECK ("target_unit_id" is not distinct from coalesce("target_unit_publishing_id", "target_unit_music_id", "target_unit_program_id", "target_unit_software_id", "target_unit_entity_id", "target_unit_grouping_id", "target_unit_reference_id", "target_unit_distribution_id", "target_unit_video_id", "target_unit_audio_id", "target_unit_post_id", "target_unit_poll_id", "target_unit_zone_id", "target_unit_realm_id", "target_unit_realm_rule_id", "target_unit_custom_theme_id", "target_unit_collection_id", "target_unit_tag_id", "target_unit_tag_path_id", "target_unit_label_id")),
	CONSTRAINT "account_favorite_revision_number_check" CHECK ("revision" between 1 and 9007199254740991),
	CONSTRAINT "account_favorite_revision_operation_check" CHECK ("operation" in ('save','update','delete','restore')),
	CONSTRAINT "account_favorite_revision_target_snapshot_check" CHECK ("snapshot" is null or (("snapshot"#>>'{target,id}'="target_unit_id"::text and "snapshot"#>>'{target,owner}'="target_owner") is true)),
	CONSTRAINT "account_favorite_revision_snapshot_check" CHECK (("operation" = 'delete' and "snapshot" is null) or ("operation" <> 'delete' and jsonb_typeof("snapshot") = 'object' and octet_length("snapshot"::text) <= 98304))
);

