	"auth_user_id" uuid PRIMARY KEY,
	"revision" bigint DEFAULT 0 NOT NULL,
	CONSTRAINT "account_favorites_state_revision_check" CHECK ("revision" between 0 and 9007199254740991)
);

CREATE TABLE "account_follow_preference" (
	"auth_user_id" uuid,
	"follower_entity_id" uuid NOT NULL,
	"unit_id" uuid,
	"position" text collate "C" DEFAULT 'a0' || replace(uuidv7()::text, '-', '') || 'V' NOT NULL,
	"favorite" boolean DEFAULT false NOT NULL,
	"in_app" boolean DEFAULT true NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "account_follow_preference_pkey" PRIMARY KEY("auth_user_id","unit_id"),
	CONSTRAINT "account_follow_preference_follow_key" UNIQUE("follower_entity_id","unit_id"),
	CONSTRAINT "account_follow_preference_position_check" CHECK (octet_length("position") <= 1024)
);

CREATE TABLE "account_preference" (
	"auth_user_id" uuid PRIMARY KEY,
	"default_licenses" text[] DEFAULT '{}'::text[] NOT NULL,
	"default_realm_manage_mode" boolean DEFAULT false NOT NULL,
	"default_score_realm_id" uuid,
	"score_visibility" "resource_visibility" DEFAULT 'public'::"resource_visibility" NOT NULL,
	"progress_visibility" "resource_visibility" DEFAULT 'public'::"resource_visibility" NOT NULL,
	"personalized_feed" boolean DEFAULT true NOT NULL,
	"custom_themes_enabled" boolean DEFAULT true NOT NULL,
	"filter_feed_by_preferred_languages" boolean DEFAULT false NOT NULL,
	"always_show_spoilers" boolean DEFAULT false NOT NULL,
	"always_show_nsfw" boolean DEFAULT false NOT NULL,
	"collection_config" jsonb,
	"interface_locale" text DEFAULT 'zh-Hant' NOT NULL,
	"chinese_content_display" text DEFAULT 'original' NOT NULL,
	"content_ratings" "content_rating"[] DEFAULT array['general', 'r15']::"content_rating"[] NOT NULL,
	"preferred_languages" text[] DEFAULT array['en']::text[] NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "account_preference_languages_check" CHECK (cardinality("preferred_languages") > 0
				and "preferred_languages" <@ array['zh', 'en', 'ja', 'ko', 'de', 'fr', 'es']::text[]
				and cardinality(array_positions("preferred_languages", 'zh')) <= 1 and cardinality(array_positions("preferred_languages", 'en')) <= 1 and cardinality(array_positions("preferred_languages", 'ja')) <= 1 and cardinality(array_positions("preferred_languages", 'ko')) <= 1 and cardinality(array_positions("preferred_languages", 'de')) <= 1 and cardinality(array_positions("preferred_languages", 'fr')) <= 1 and cardinality(array_positions("preferred_languages", 'es')) <= 1),
	CONSTRAINT "account_preference_content_ratings_check" CHECK (cardinality("content_ratings") > 0),
	CONSTRAINT "account_preference_interface_locale_check" CHECK ("interface_locale" in ('en', 'zh-Hant', 'zh-Hans', 'ja', 'ko', 'de', 'fr', 'es')),
	CONSTRAINT "account_preference_chinese_content_display_check" CHECK ("chinese_content_display" in ('original', 'hant', 'hans')),
	CONSTRAINT "account_preference_collection_config_json_object_check" CHECK ("collection_config" is null or jsonb_typeof("collection_config") = 'object')
);

