	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "account_realm_tag_subscription_pkey" PRIMARY KEY("auth_user_id","realm_id"),
	CONSTRAINT "account_realm_tag_subscription_position_byte_length_check" CHECK (octet_length("position") <= 1024)
);

CREATE TABLE "account_unit_tag" (
	"auth_user_id" uuid,
	"unit_id" uuid,
	"unit_publishing_id" uuid,
	"unit_music_id" uuid,
	"unit_program_id" uuid,
	"unit_software_id" uuid,
	"unit_entity_id" uuid,
	"unit_grouping_id" uuid,
	"unit_reference_id" uuid,
	"unit_distribution_id" uuid,
	"unit_video_id" uuid,
	"unit_audio_id" uuid,
	"unit_post_id" uuid,
	"unit_poll_id" uuid,
	"unit_zone_id" uuid,
	"unit_realm_id" uuid,
	"unit_realm_rule_id" uuid,
	"unit_custom_theme_id" uuid,
	"unit_collection_id" uuid,
	"unit_tag_id" uuid,
	"unit_tag_path_id" uuid,
	"unit_label_id" uuid,
	"tag_id" uuid,
	"position" text collate "C" DEFAULT 'a0' NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "account_unit_tag_pkey" PRIMARY KEY("auth_user_id","unit_id","tag_id"),
	CONSTRAINT "account_unit_tag_unit_target_check" CHECK (num_nonnulls("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id") = 1),
	CONSTRAINT "account_unit_tag_unit_id_check" CHECK ("unit_id" is not distinct from coalesce("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id")),
	CONSTRAINT "account_unit_tag_not_self_check" CHECK ("unit_id" <> "tag_id"),
	CONSTRAINT "account_unit_tag_position_byte_length_check" CHECK (octet_length("position") <= 1024)
);

CREATE TABLE "accounts" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"issuer" text DEFAULT 'local:credential' NOT NULL,
	"account_id" text NOT NULL,
	"provider_id" text NOT NULL,
	"user_id" uuid NOT NULL,
	"access_token" text,
	"refresh_token" text,
	"id_token" text,
	"access_token_expires_at" timestamp(3) with time zone,
	"refresh_token_expires_at" timestamp(3) with time zone,
	"scope" text,
	"password" text,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "api_account_quota_binding" (
	"user_id" uuid PRIMARY KEY,
	"policy_id" uuid NOT NULL,
	"policy_subject_kind" text DEFAULT 'account' NOT NULL,
	"configuration_override" jsonb DEFAULT '{}' NOT NULL,
	"valid_until" timestamp(3) with time zone,
	"assignment_reason" text NOT NULL,
	"assigned_by_profile_id" uuid NOT NULL,
	"revision" integer DEFAULT 1 NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "api_account_quota_binding_revision_check" CHECK ("revision" > 0),
	CONSTRAINT "api_account_quota_binding_policy_kind_check" CHECK ("policy_subject_kind" = 'account'),
	CONSTRAINT "api_account_quota_binding_configuration_json_object_check" CHECK (jsonb_typeof("configuration_override") = 'object'),
	CONSTRAINT "api_account_quota_binding_validity_check" CHECK ("valid_until" is null or "valid_until" > "created_at"),
	CONSTRAINT "api_account_quota_binding_reason_check" CHECK (btrim("assignment_reason") <> '')
);

CREATE TABLE "api_quota_daily_usage" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"account_user_id" uuid,
	"token_id" uuid,
	"scope" text NOT NULL,
	"usage_date" date NOT NULL,
	"used_cost_units" bigint NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "api_quota_daily_usage_subject_check" CHECK (num_nonnulls("account_user_id", "token_id") = 1),
	CONSTRAINT "api_quota_daily_usage_scope_check" CHECK (btrim("scope") <> '' and length("scope") <= 256),
	CONSTRAINT "api_quota_daily_usage_used_cost_check" CHECK ("used_cost_units" >= 0)
);

CREATE TABLE "api_quota_policy" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"key" text NOT NULL UNIQUE,
	"subject_kind" text NOT NULL,
	"class" text NOT NULL,
	"current_revision" integer DEFAULT 1 NOT NULL,
	"enabled" boolean DEFAULT true NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "api_quota_policy_key_check" CHECK ("key" ~ '^[a-z][a-z0-9_-]{0,63}$'),
	CONSTRAINT "api_quota_policy_subject_kind_check" CHECK ("subject_kind" in ('account', 'token')),
	CONSTRAINT "api_quota_policy_class_check" CHECK ("class" in ('standard', 'privileged')),
	CONSTRAINT "api_quota_policy_current_revision_check" CHECK ("current_revision" > 0)
);

CREATE TABLE "api_quota_policy_revision" (
	"policy_id" uuid,
	"revision" integer,
	"schema_version" integer NOT NULL,
	"configuration" jsonb NOT NULL,
	"change_reason" text NOT NULL,
	"created_by_profile_id" uuid,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "api_quota_policy_revision_pkey" PRIMARY KEY("policy_id","revision"),
	CONSTRAINT "api_quota_policy_revision_revision_check" CHECK ("revision" > 0),
	CONSTRAINT "api_quota_policy_revision_schema_version_check" CHECK ("schema_version" > 0),
	CONSTRAINT "api_quota_policy_revision_configuration_json_object_check" CHECK (jsonb_typeof("configuration") = 'object'),
	CONSTRAINT "api_quota_policy_revision_change_reason_check" CHECK (btrim("change_reason") <> '')
);

CREATE TABLE "api_quota_rate_state" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"account_user_id" uuid,
	"token_id" uuid,
	"scope" text NOT NULL,
	"available_rate_units" bigint NOT NULL,
	"refilled_at" timestamp(3) with time zone NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "api_quota_rate_state_subject_check" CHECK (num_nonnulls("account_user_id", "token_id") = 1),
	CONSTRAINT "api_quota_rate_state_scope_check" CHECK (btrim("scope") <> '' and length("scope") <= 256),
	CONSTRAINT "api_quota_rate_state_available_units_check" CHECK ("available_rate_units" >= 0)
);

CREATE TABLE "api_quota_request_lease" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"request_id" uuid NOT NULL,
	"account_user_id" uuid,
	"token_id" uuid,
	"scope" text NOT NULL,
	"expires_at" timestamp(3) with time zone NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "api_quota_request_lease_subject_check" CHECK (num_nonnulls("account_user_id", "token_id") = 1),
	CONSTRAINT "api_quota_request_lease_scope_check" CHECK (btrim("scope") <> '' and length("scope") <= 256),
	CONSTRAINT "api_quota_request_lease_expiry_check" CHECK ("expires_at" > "created_at")
);

CREATE TABLE "api_token_creation_reservation" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"account_user_id" uuid NOT NULL,
	"expires_at" timestamp(3) with time zone NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "api_token_creation_reservation_expiry_check" CHECK ("expires_at" > "created_at")
);

CREATE TABLE "api_token_quota_binding" (
	"token_id" uuid PRIMARY KEY,
	"policy_id" uuid NOT NULL,
	"policy_subject_kind" text DEFAULT 'token' NOT NULL,
	"configuration_override" jsonb DEFAULT '{}' NOT NULL,
	"valid_until" timestamp(3) with time zone,
	"assignment_reason" text NOT NULL,
	"assigned_by_profile_id" uuid NOT NULL,
	"revision" integer DEFAULT 1 NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "api_token_quota_binding_policy_kind_check" CHECK ("policy_subject_kind" = 'token'),
	CONSTRAINT "api_token_quota_binding_revision_check" CHECK ("revision" > 0),
	CONSTRAINT "api_token_quota_binding_configuration_json_object_check" CHECK (jsonb_typeof("configuration_override") = 'object'),
	CONSTRAINT "api_token_quota_binding_validity_check" CHECK ("valid_until" is null or "valid_until" > "created_at"),
	CONSTRAINT "api_token_quota_binding_reason_check" CHECK (btrim("assignment_reason") <> '')
);

CREATE TABLE "api_token_quota_override" (
	"token_id" uuid PRIMARY KEY,
	"configuration_override" jsonb NOT NULL,
	"revision" integer DEFAULT 1 NOT NULL,
	"updated_by_profile_id" uuid NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "api_token_quota_override_revision_check" CHECK ("revision" > 0),
	CONSTRAINT "api_token_quota_override_configuration_json_object_check" CHECK (jsonb_typeof("configuration_override") = 'object')
);

CREATE TABLE "apikeys" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"config_id" text DEFAULT 'default' NOT NULL,
	"name" text,
	"start" text,
	"reference_id" uuid NOT NULL,
	"prefix" text,
	"key" text NOT NULL,
	"refill_interval" integer,
	"refill_amount" integer,
	"last_refill_at" timestamp(3) with time zone,
	"enabled" boolean DEFAULT true,
	"rate_limit_enabled" boolean DEFAULT true,
	"rate_limit_time_window" integer DEFAULT 60000,
	"rate_limit_max" integer DEFAULT 5000,
	"request_count" integer DEFAULT 0,
	"remaining" integer,
	"last_request" timestamp(3) with time zone,
	"expires_at" timestamp(3) with time zone,
	"created_at" timestamp(3) with time zone NOT NULL,
	"updated_at" timestamp(3) with time zone NOT NULL,
	"permissions" text,
	"metadata" text
);

CREATE TABLE "audio" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"revision" bigint DEFAULT 1 NOT NULL,
	"routing_generation" integer DEFAULT 1 NOT NULL,
	"created_by_auth_user_id" uuid,
	"status" "unit_status" DEFAULT 'draft'::"unit_status" NOT NULL,
	"visibility" "resource_visibility" DEFAULT 'public'::"resource_visibility" NOT NULL,
	"content_rating" "content_rating" DEFAULT 'general'::"content_rating" NOT NULL,
	"ai_disclosure" "ai_disclosure" DEFAULT 'unknown'::"ai_disclosure" NOT NULL,
	"moderation_status" "moderation_status" DEFAULT 'approved'::"moderation_status" NOT NULL,
	"post_targeting_locked" boolean DEFAULT false NOT NULL,
	"published_at" timestamp(3) with time zone,
	"deleted_at" timestamp(3) with time zone,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"duration_seconds" integer,
	CONSTRAINT "audio_identity_revision_check" CHECK ("revision" between 1 and 9007199254740991 and "routing_generation" between 1 and 2147483647),
	CONSTRAINT "audio_identity_publication_check" CHECK ("status" <> 'published' or "published_at" is not null),
	CONSTRAINT "audio_identity_deleted_at_check" CHECK ("deleted_at" is null or "deleted_at" >= "created_at"),
	CONSTRAINT "audio_duration_seconds_check" CHECK ("duration_seconds" is null or "duration_seconds" > 0)
);

CREATE TABLE "audit_event" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"schema_version" integer DEFAULT 2 NOT NULL,
	"category" "audit_event_category" NOT NULL,
	"outcome" "audit_event_outcome" NOT NULL,
	"actor_kind" "audit_actor_kind" NOT NULL,
	"actor_profile_id" uuid,
	"actor_auth_user_id" uuid,
	"actor_credential_kind" "audit_credential_kind" NOT NULL,
	"actor_credential_id" text,
	"authority_kind" "audit_authority_kind" NOT NULL,
	"authority_id" uuid,
	"action" text NOT NULL,
	"outcome_code" text,
	"governance_decision_id" uuid,
	"request_id" text,
	"trace_id" text,
	"target_kind" text,
	"target_id" uuid,
	"target_path" text,
	"details" jsonb,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "audit_event_schema_version_check" CHECK ("schema_version" in (1, 2)),
	CONSTRAINT "audit_event_action_check" CHECK (btrim("action") <> ''),
	CONSTRAINT "audit_event_outcome_code_check" CHECK ("outcome_code" is null or (btrim("outcome_code") <> '' and octet_length("outcome_code") <= 128)),
	CONSTRAINT "audit_event_actor_check" CHECK ((("actor_kind" = 'profile'::audit_actor_kind) = ("actor_profile_id" is not null)) and ("actor_kind" <> 'auth'::audit_actor_kind or "actor_auth_user_id" is not null)),
	CONSTRAINT "audit_event_authority_check" CHECK (("authority_kind" = 'platform'::audit_authority_kind) = ("authority_id" is null)),
	CONSTRAINT "audit_event_target_check" CHECK ("target_kind" is not null or ("target_id" is null and "target_path" is null)),
	CONSTRAINT "audit_event_details_json_object_check" CHECK ("details" is null or jsonb_typeof("details") = 'object')
);

CREATE TABLE "auth_entity" (
	"auth_user_id" uuid PRIMARY KEY,
	"entity_id" uuid NOT NULL,
	"revision" bigint DEFAULT 1 NOT NULL,
	"state" text DEFAULT 'active' NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "auth_entity_revision_check" CHECK ("revision" between 1 and 9007199254740991),
	CONSTRAINT "auth_entity_state_check" CHECK ("state" in ('active', 'suspended'))
);

CREATE TABLE "book_chapter_draft_job" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"book_id" uuid NOT NULL,
	"structure_id" uuid,
	"requested_by_profile_id" uuid NOT NULL,
	"book_updated_at" timestamp(3) with time zone NOT NULL,
	"state" "book_chapter_draft_job_state" DEFAULT 'pending'::"book_chapter_draft_job_state" NOT NULL,
	"cursor_node_id" uuid,
	"processed_node_count" bigint DEFAULT 0 NOT NULL,
	"drafted_chapter_count" bigint DEFAULT 0 NOT NULL,
	"skipped_chapter_count" bigint DEFAULT 0 NOT NULL,
	"attempt_count" integer DEFAULT 0 NOT NULL,
	"available_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"lease_token" uuid,
	"lease_expires_at" timestamp(3) with time zone,
	"last_error_message" text,
	"completed_at" timestamp(3) with time zone,
	"cancelled_at" timestamp(3) with time zone,
	"failed_at" timestamp(3) with time zone,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "book_chapter_draft_job_processed_count_check" CHECK ("processed_node_count" >= 0),
	CONSTRAINT "book_chapter_draft_job_drafted_count_check" CHECK ("drafted_chapter_count" >= 0),
	CONSTRAINT "book_chapter_draft_job_skipped_count_check" CHECK ("skipped_chapter_count" >= 0),
	CONSTRAINT "book_chapter_draft_job_attempt_count_check" CHECK ("attempt_count" >= 0),
	CONSTRAINT "book_chapter_draft_job_lease_shape_check" CHECK (("state" = 'processing') = ("lease_token" is not null and "lease_expires_at" is not null))
);

CREATE TABLE "book_localized_content_metric_stat" (
	"book_unit_id" uuid,
	"language" text,
	"chapter_count" bigint DEFAULT 0 NOT NULL,
	"word_count" bigint DEFAULT 0 NOT NULL,
	"character_count" bigint DEFAULT 0 NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "book_localized_content_metric_stat_pkey" PRIMARY KEY("book_unit_id","language"),
	CONSTRAINT "book_localized_content_metric_stat_language_check" CHECK ("language" in ('zh', 'en', 'ja', 'ko', 'de', 'fr', 'es')),
	CONSTRAINT "book_localized_content_metric_stat_count_check" CHECK ("chapter_count" >= 0 and "word_count" >= 0 and "character_count" >= 0)
);

CREATE TABLE "catalog_definition" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"namespace" text NOT NULL,
	"key" text NOT NULL,
	"kind" text NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "catalog_definition_namespace_key" UNIQUE("namespace","key"),
	CONSTRAINT "catalog_definition_namespace_check" CHECK ("namespace" ~ '^[a-z][a-z0-9_.-]{0,95}$'),
	CONSTRAINT "catalog_definition_key_check" CHECK (length("key") between 1 and 160),
	CONSTRAINT "catalog_definition_kind_check" CHECK ("kind" in ('class', 'property', 'predicate', 'role', 'vocabulary'))
