CREATE TABLE "catalog_definition_revision" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"definition_id" uuid NOT NULL,
	"version" bigint NOT NULL,
	"value_kind" text,
	"constraints" jsonb DEFAULT '{"nullable":false,"integer":false}' NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "catalog_definition_revision_version_key" UNIQUE("definition_id","version"),
	CONSTRAINT "catalog_definition_revision_constraints_check" CHECK (jsonb_typeof("constraints") = 'object' and octet_length("constraints"::text) <= 262144),
	CONSTRAINT "catalog_definition_revision_version_check" CHECK ("version" between 1 and 9007199254740991),
	CONSTRAINT "catalog_definition_revision_value_kind_check" CHECK ("value_kind" in ('null', 'string', 'number', 'boolean', 'object', 'array'))
);

