CREATE TABLE "catalog_source_adoption_proposal" (
	"source_record_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"snapshot_id" uuid NOT NULL,
	"mapping_key" uuid NOT NULL,
	"mapping_owner" text NOT NULL,
	"mapping_version" text NOT NULL,
	"expected_target_revision" bigint NOT NULL,
	"expected_binding_revision" bigint DEFAULT 1 NOT NULL,
	"expected_policy_revision" bigint DEFAULT 1 NOT NULL,
	"decided_at" timestamp(3) with time zone,
	"decision_reason" text,
	"applied_target_revision" bigint,
	"proposer_auth_user_id" uuid,
	"state" text DEFAULT 'pending' NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "catalog_source_adoption_proposal_pkey" PRIMARY KEY("source_record_id","id"),
	CONSTRAINT "catalog_adoption_snapshot_mapping_key" UNIQUE("source_record_id","snapshot_id","mapping_key","mapping_version","expected_binding_revision","expected_policy_revision","expected_target_revision"),
	CONSTRAINT "catalog_adoption_owner_check" CHECK ("mapping_owner" in ('publishing', 'music', 'program', 'software', 'entity', 'grouping', 'reference', 'distribution')),
	CONSTRAINT "catalog_adoption_revision_check" CHECK ("expected_target_revision" between 1 and 9007199254740991),
	CONSTRAINT "catalog_adoption_state_check" CHECK ("state" in ('pending', 'applied', 'rejected', 'superseded', 'withdrawn')),
	CONSTRAINT "catalog_adoption_version_check" CHECK (octet_length("mapping_version") between 1 and 128)
) PARTITION BY HASH ("source_record_id");
