CREATE TABLE "catalog_source_application" (
	"source_record_id" uuid,
	"proposal_id" uuid,
	"mapping_key" uuid NOT NULL,
	"action" text,
	"previous_snapshot_id" uuid,
	"previous_observed_snapshot_id" uuid,
	"previous_correspondence_revision" bigint,
	"previous_evidence_source_record_id" uuid,
	"previous_evidence_snapshot_id" uuid,
	"previous_evidence_path" text,
	"before_revision" bigint NOT NULL,
	"after_revision" bigint NOT NULL,
	"change_count" integer NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "catalog_source_application_pkey" PRIMARY KEY("source_record_id","proposal_id","action"),
	CONSTRAINT "catalog_source_application_previous_evidence_check" CHECK (num_nonnulls("previous_evidence_source_record_id","previous_evidence_snapshot_id","previous_evidence_path") = 0 or ("previous_snapshot_id" is null and num_nonnulls("previous_evidence_source_record_id","previous_evidence_snapshot_id","previous_evidence_path") = 3 and octet_length("previous_evidence_path") between 1 and 512)),
	CONSTRAINT "catalog_source_application_values" CHECK ("action" in ('apply','withdraw') and "before_revision" >= 1 and "after_revision" > "before_revision" and "after_revision" <= 9007199254740991 and "change_count" between 0 and 32896)
) PARTITION BY HASH ("source_record_id");
