CREATE TABLE "catalog_source_binding_revision" (
	"source_record_id" uuid,
	"mapping_key" uuid,
	"owner" text NOT NULL,
	"revision" bigint,
	"correspondence_revision" bigint NOT NULL,
	"policy_revision" bigint NOT NULL,
	"mapping_version" text NOT NULL,
	"state" text NOT NULL,
	"mode" text NOT NULL,
	"publishing_id" uuid,
	"music_id" uuid,
	"program_id" uuid,
	"software_id" uuid,
	"entity_id" uuid,
	"grouping_id" uuid,
	"reference_id" uuid,
	"distribution_id" uuid,
	"actor_auth_user_id" uuid NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"reason" text NOT NULL,
	CONSTRAINT "catalog_source_binding_revision_pkey" PRIMARY KEY("source_record_id","mapping_key","revision"),
	CONSTRAINT "catalog_source_binding_correspondence_check" CHECK ("revision" between 1 and 9007199254740991 and "policy_revision" between 1 and 9007199254740991 and "correspondence_revision" between 1 and "revision"),
	CONSTRAINT "catalog_source_binding_revision_target_check" CHECK (num_nonnulls("publishing_id", "music_id", "program_id", "software_id", "entity_id", "grouping_id", "reference_id", "distribution_id") = 1 and case "owner" when 'publishing' then "publishing_id" when 'music' then "music_id" when 'program' then "program_id" when 'software' then "software_id" when 'entity' then "entity_id" when 'grouping' then "grouping_id" when 'reference' then "reference_id" when 'distribution' then "distribution_id" end is not null),
	CONSTRAINT "catalog_source_binding_revision_values_check" CHECK ("revision" between 1 and 9007199254740991 and "policy_revision" between 1 and 9007199254740991 and "state" in ('active','paused','withdrawn') and "mode" in ('review','manual') and octet_length("reason") between 1 and 2048)
) PARTITION BY HASH ("source_record_id");
