CREATE TABLE "catalog_source_mapping_claim" (
	"source_record_id" uuid,
	"path" text,
	"mapping_key" uuid DEFAULT uuidv7() NOT NULL,
	"owner" text NOT NULL,
	"observed_snapshot_id" uuid,
	"evidence_source_record_id" uuid,
	"evidence_snapshot_id" uuid,
	"evidence_path" text,
	"binding_revision" bigint DEFAULT 1 NOT NULL,
	"correspondence_revision" bigint DEFAULT 1 NOT NULL,
	"applied_correspondence_revision" bigint,
	"policy_revision" bigint DEFAULT 1 NOT NULL,
	"state" text DEFAULT 'active' NOT NULL,
	"baseline_target_revision" bigint,
	"mapping_version" text DEFAULT 'source.manual.1' NOT NULL,
	CONSTRAINT "catalog_source_mapping_claim_pkey" PRIMARY KEY("source_record_id","path"),
	CONSTRAINT "catalog_source_mapping_claim_record_key" UNIQUE("source_record_id","mapping_key","owner"),
	CONSTRAINT "catalog_source_mapping_revisions_check" CHECK ("binding_revision" between 1 and 9007199254740991 and "policy_revision" between 1 and 9007199254740991 and "correspondence_revision" between 1 and "binding_revision" and ("applied_correspondence_revision" is null or "applied_correspondence_revision" between 1 and "binding_revision")),
	CONSTRAINT "catalog_source_mapping_evidence_check" CHECK (("observed_snapshot_id" is not null and "evidence_source_record_id" is null and "evidence_snapshot_id" is null and "evidence_path" is null) or ("observed_snapshot_id" is null and "evidence_source_record_id" is not null and "evidence_snapshot_id" is not null and "evidence_path" is not null and octet_length("evidence_path") between 1 and 512)),
	CONSTRAINT "catalog_source_mapping_claim_path_check" CHECK (octet_length("path") between 1 and 512),
	CONSTRAINT "catalog_source_mapping_claim_owner_check" CHECK ("owner" in ('publishing', 'music', 'program', 'software', 'entity', 'grouping', 'reference', 'distribution'))
) PARTITION BY HASH ("source_record_id");
