CREATE TABLE "catalog_source_proposal_dependency" (
	"source_record_id" uuid,
	"proposal_id" uuid,
	"position" integer,
	"snapshot_id" uuid NOT NULL,
	"source_path" text NOT NULL,
	"dependency_source_record_id" uuid NOT NULL,
	"dependency_mapping_key" uuid NOT NULL,
	"dependency_binding_revision" bigint NOT NULL,
	"publishing_id" uuid,
	"music_id" uuid,
	"program_id" uuid,
	"software_id" uuid,
	"entity_id" uuid,
	"grouping_id" uuid,
	"reference_id" uuid,
	"distribution_id" uuid,
	"prepared_by_auth_user_id" uuid,
	"revoked_at" timestamp(3) with time zone,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "catalog_source_proposal_dependency_pkey" PRIMARY KEY("source_record_id","proposal_id","position"),
	CONSTRAINT "catalog_source_dependency_position_check" CHECK ("position" between 0 and 32767),
	CONSTRAINT "catalog_source_dependency_path_check" CHECK (left("source_path",1)='/' and octet_length("source_path") between 1 and 512),
	CONSTRAINT "catalog_source_dependency_target_check" CHECK (num_nonnulls("publishing_id","music_id","program_id","software_id","entity_id","grouping_id","reference_id","distribution_id")=1)
) PARTITION BY HASH ("source_record_id");
