	"next_allowed_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "catalog_source_provider_budget_check" CHECK ("source" in ('musicbrainz','vndb','bangumi','openlibrary') and "minimum_interval_ms" between 1000 and 86400000)
);

CREATE TABLE "catalog_source_record" (
	"id" uuid PRIMARY KEY,
	"source" text NOT NULL,
	"object_type" text NOT NULL,
	"external_id" text NOT NULL,
	"acquisition_generation" bigint DEFAULT 0 NOT NULL,
	"accepted_generation" bigint DEFAULT 0 NOT NULL,
	"head_snapshot_id" uuid,
	"last_checked_at" timestamp(3) with time zone,
	"last_check_outcome" text,
	CONSTRAINT "catalog_source_record_identity_check" CHECK (replace("id"::text, '-', '') = overlay(overlay(substr(encode(sha256(convert_to("source" || chr(10) || "object_type" || chr(10) || "external_id", 'UTF8')), 'hex'), 1, 32) placing '8' from 13 for 1) placing '8' from 17 for 1)),
	CONSTRAINT "catalog_source_record_namespace_check" CHECK ("source" ~ '^[a-z][a-z0-9_.-]{0,95}$' and "object_type" ~ '^[a-z][a-z0-9_.-]{0,95}$'),
	CONSTRAINT "catalog_source_record_generation_check" CHECK ("accepted_generation" between 0 and "acquisition_generation" and "acquisition_generation" <= 9007199254740991),
	CONSTRAINT "catalog_source_record_outcome_check" CHECK ("last_check_outcome" is null or "last_check_outcome" in ('changed','unchanged','error','tombstone')),
	CONSTRAINT "catalog_source_record_key_check" CHECK (octet_length("source") between 1 and 96 and octet_length("object_type") between 1 and 96 and octet_length("external_id") between 1 and 512)
) PARTITION BY HASH ("id");
