CREATE TABLE "catalog_source_snapshot_part" (
	"source_record_id" uuid,
	"snapshot_id" uuid,
	"key" text,
	"position" integer NOT NULL,
	"profile" text NOT NULL,
	"kind" text NOT NULL,
	"content_sha256" text NOT NULL,
	"payload_ref" text NOT NULL,
	"byte_length" integer NOT NULL,
	"request_url" text,
	"observed_at" timestamp(3) with time zone NOT NULL,
	CONSTRAINT "catalog_source_snapshot_part_pkey" PRIMARY KEY("source_record_id","snapshot_id","key"),
	CONSTRAINT "catalog_source_snapshot_part_values" CHECK ("key" ~ '^[a-z][a-z0-9_]{0,63}$' and "position" between 0 and 3 and octet_length("profile") between 1 and 128 and "content_sha256" ~ '^[0-9a-f]{64}$' and octet_length("payload_ref") between 1 and 2048 and "byte_length" between 1 and 8000000 and (("kind"='derived_view' and "key"='native_view' and "request_url" is null) or ("kind"='upstream_response' and "key"<>'native_view' and "request_url" is not null and octet_length("request_url") between 1 and 2048)))
) PARTITION BY HASH ("source_record_id");
