CREATE TABLE "content_governance_action" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"decision_id" uuid,
	"case_id" uuid NOT NULL,
	"actor_profile_id" uuid NOT NULL,
	"kind" "content_governance_action_kind" NOT NULL,
	"resulting_post_targeting_locked" boolean,
	"license_grant_id" uuid,
	"previous_recognition_status" "unit_license_recognition_status",
	"resulting_recognition_status" "unit_license_recognition_status",
	"reverses_action_id" uuid,
	"previous_state" text,
	"resulting_state" text,
	"previous_post_targeting_locked" boolean,
	"request_id" text,
	"idempotency_key" text,
	"request_fingerprint" text,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "content_governance_action_state_outcome_check" CHECK (("previous_state" is null) = ("resulting_state" is null)),
	CONSTRAINT "content_governance_action_post_targeting_lock_outcome_check" CHECK (("previous_post_targeting_locked" is null) = ("resulting_post_targeting_locked" is null)),
	CONSTRAINT "content_governance_action_single_outcome_check" CHECK (num_nonnulls(
				"previous_state",
				"previous_post_targeting_locked",
				"previous_recognition_status"
			) <= 1),
	CONSTRAINT "content_governance_action_kind_outcome_check" CHECK ((
				"kind" in ('approve', 'hide', 'remove', 'restore')
				and "previous_state" is not null
			) or (
				"kind" in ('lock_post_targeting', 'unlock_post_targeting')
				and "previous_post_targeting_locked" is not null
			) or (
				"kind" in ('invalidate_license', 'restore_license')
				and "previous_recognition_status" is not null
			) or (
				"kind" = 'reverse'
				and num_nonnulls(
					"previous_state",
					"previous_post_targeting_locked"
				) = 1
			)),
	CONSTRAINT "content_governance_action_license_grant_transition_check" CHECK ((
				"kind" = 'invalidate_license'
				and "license_grant_id" is not null
				and "previous_recognition_status" is not null
				and "previous_recognition_status" = 'recognized'
				and "resulting_recognition_status" is not null
				and "resulting_recognition_status" = 'invalidated'
			) or (
				"kind" = 'restore_license'
				and "license_grant_id" is not null
				and "previous_recognition_status" is not null
				and "previous_recognition_status" = 'invalidated'
				and "resulting_recognition_status" is not null
				and "resulting_recognition_status" = 'recognized'
			) or (
				"kind" not in (
					'invalidate_license',
					'restore_license'
				)
				and "license_grant_id" is null
				and "previous_recognition_status" is null
				and "resulting_recognition_status" is null
			)),
	CONSTRAINT "content_governance_action_request_fingerprint_check" CHECK ("request_fingerprint" is null or "request_fingerprint" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "content_governance_action_not_self_reverse" CHECK ("reverses_action_id" is null or "reverses_action_id" <> "id"),
	CONSTRAINT "content_governance_action_reversal_check" CHECK (("kind" in ('reverse', 'restore_license')) = ("reverses_action_id" is not null))
);

