	"kind" text NOT NULL,
	"minor" boolean DEFAULT false NOT NULL,
	"replay_byte_size" integer NOT NULL,
	"checkpoint_byte_size" integer NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "content_structure_revision_id_structure_key" UNIQUE("id","structure_id"),
	CONSTRAINT "content_structure_revision_replay_byte_size_check" CHECK ("replay_byte_size" >= 0),
	CONSTRAINT "content_structure_revision_checkpoint_byte_size_check" CHECK ("checkpoint_byte_size" >= 0),
	CONSTRAINT "content_structure_revision_kind_check" CHECK ("kind" in ('create', 'update', 'delete', 'restore')),
	CONSTRAINT "content_structure_revision_source_shape_check" CHECK (("kind" = 'restore') = ("source_revision_id" is not null))
);

CREATE TABLE "content_structure_revision_head" (
	"structure_id" uuid PRIMARY KEY,
	"revision_id" uuid NOT NULL CONSTRAINT "content_structure_revision_head_revision_key" UNIQUE
);

CREATE TABLE "conversation" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"participant_low_entity_id" uuid NOT NULL,
	"participant_high_entity_id" uuid NOT NULL,
	"participant_low_auth_user_id" uuid NOT NULL,
	"participant_high_auth_user_id" uuid NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "conversation_participant_pair_key" UNIQUE("participant_low_auth_user_id","participant_high_auth_user_id"),
	CONSTRAINT "conversation_participant_order_check" CHECK ("participant_low_auth_user_id" < "participant_high_auth_user_id")
);

CREATE TABLE "conversation_participant_stat" (
	"conversation_id" uuid,
	"auth_user_id" uuid,
	"last_message_id" uuid,
	"last_message_at" timestamp(3) with time zone,
	"sort_at" timestamp(3) with time zone NOT NULL,
	"unread_count" bigint DEFAULT 0 NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "conversation_participant_stat_pkey" PRIMARY KEY("conversation_id","auth_user_id"),
	CONSTRAINT "conversation_participant_stat_count_check" CHECK ("unread_count" >= 0)
);

CREATE TABLE "conversation_read" (
	"conversation_id" uuid,
	"auth_user_id" uuid,
	"last_read_message_id" uuid,
	"read_at" timestamp(3) with time zone,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "conversation_read_pkey" PRIMARY KEY("conversation_id","auth_user_id")
);

CREATE TABLE "conversation_stat" (
	"conversation_id" uuid PRIMARY KEY,
	"last_message_id" uuid,
	"last_message_at" timestamp(3) with time zone,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "credit_attribution" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"source_unit_id" uuid NOT NULL,
	"credited_entity_id" uuid NOT NULL,
	"role" text NOT NULL,
	"position" text collate "C" DEFAULT 'a0' NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"source_unit_publishing_id" uuid,
	"source_unit_music_id" uuid,
	"source_unit_program_id" uuid,
	"source_unit_software_id" uuid,
	"source_unit_entity_id" uuid,
	"source_unit_grouping_id" uuid,
	"source_unit_reference_id" uuid,
	"source_unit_distribution_id" uuid,
	"source_unit_video_id" uuid,
	"source_unit_audio_id" uuid,
	"source_unit_post_id" uuid,
	"source_unit_poll_id" uuid,
	"source_unit_zone_id" uuid,
	"source_unit_realm_id" uuid,
	"source_unit_realm_rule_id" uuid,
	"source_unit_custom_theme_id" uuid,
	"source_unit_collection_id" uuid,
	"source_unit_tag_id" uuid,
	"source_unit_tag_path_id" uuid,
	"source_unit_label_id" uuid,
	CONSTRAINT "credit_attribution_source_credited_role_key" UNIQUE("source_unit_id","credited_entity_id","role"),
	CONSTRAINT "credit_attribution_source_unit_target_check" CHECK (num_nonnulls("source_unit_publishing_id", "source_unit_music_id", "source_unit_program_id", "source_unit_software_id", "source_unit_entity_id", "source_unit_grouping_id", "source_unit_reference_id", "source_unit_distribution_id", "source_unit_video_id", "source_unit_audio_id", "source_unit_post_id", "source_unit_poll_id", "source_unit_zone_id", "source_unit_realm_id", "source_unit_realm_rule_id", "source_unit_custom_theme_id", "source_unit_collection_id", "source_unit_tag_id", "source_unit_tag_path_id", "source_unit_label_id") = 1),
	CONSTRAINT "credit_attribution_source_unit_id_check" CHECK ("source_unit_id" is not distinct from coalesce("source_unit_publishing_id", "source_unit_music_id", "source_unit_program_id", "source_unit_software_id", "source_unit_entity_id", "source_unit_grouping_id", "source_unit_reference_id", "source_unit_distribution_id", "source_unit_video_id", "source_unit_audio_id", "source_unit_post_id", "source_unit_poll_id", "source_unit_zone_id", "source_unit_realm_id", "source_unit_realm_rule_id", "source_unit_custom_theme_id", "source_unit_collection_id", "source_unit_tag_id", "source_unit_tag_path_id", "source_unit_label_id")),
	CONSTRAINT "credit_attribution_role_check" CHECK ("role" in ('author', 'co-author', 'translator', 'illustrator', 'editor', 'publisher', 'letterer', 'colorist', 'developer', 'composer', 'designer', 'director', 'producer', 'writer', 'actor', 'narrator', 'studio', 'distributor')),
	CONSTRAINT "credit_attribution_not_self_check" CHECK ("source_unit_id" <> "credited_entity_id"),
	CONSTRAINT "credit_attribution_position_byte_length_check" CHECK (octet_length("position") <= 1024)
);

CREATE TABLE "custom_theme" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"revision" bigint DEFAULT 1 NOT NULL,
	"routing_generation" integer DEFAULT 1 NOT NULL,
	"created_by_auth_user_id" uuid,
	"status" "unit_status" DEFAULT 'draft'::"unit_status" NOT NULL,
	"visibility" "resource_visibility" DEFAULT 'public'::"resource_visibility" NOT NULL,
	"content_rating" "content_rating" DEFAULT 'general'::"content_rating" NOT NULL,
	"ai_disclosure" "ai_disclosure" DEFAULT 'unknown'::"ai_disclosure" NOT NULL,
	"moderation_status" "moderation_status" DEFAULT 'approved'::"moderation_status" NOT NULL,
	"post_targeting_locked" boolean DEFAULT false NOT NULL,
	"published_at" timestamp(3) with time zone,
	"deleted_at" timestamp(3) with time zone,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "custom_theme_identity_revision_check" CHECK ("revision" between 1 and 9007199254740991 and "routing_generation" between 1 and 2147483647),
	CONSTRAINT "custom_theme_identity_publication_check" CHECK ("status" <> 'published' or "published_at" is not null),
	CONSTRAINT "custom_theme_identity_deleted_at_check" CHECK ("deleted_at" is null or "deleted_at" >= "created_at")
);

CREATE TABLE "custom_theme_execution_control" (
	"id" boolean PRIMARY KEY DEFAULT true,
	"enabled" boolean DEFAULT true NOT NULL,
	"updated_by_profile_id" uuid,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "custom_theme_execution_control_singleton_check" CHECK ("id" = true)
);

CREATE TABLE "custom_theme_revision" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"custom_theme_unit_id" uuid NOT NULL,
	"target_contract" text NOT NULL,
	"execution_mode" text NOT NULL,
	"resource_mode" text NOT NULL,
	"manifest_document" jsonb NOT NULL,
	"manifest_sha256" text NOT NULL,
	"source_archive_sha256" text NOT NULL,
	"review_state" text DEFAULT 'pending_automated' NOT NULL,
	"approval_scope" text DEFAULT 'host_unit' NOT NULL,
	"approved_host_unit_id" uuid,
	"approved_host_unit_publishing_id" uuid,
	"approved_host_unit_music_id" uuid,
	"approved_host_unit_program_id" uuid,
	"approved_host_unit_software_id" uuid,
	"approved_host_unit_entity_id" uuid,
	"approved_host_unit_grouping_id" uuid,
	"approved_host_unit_reference_id" uuid,
	"approved_host_unit_distribution_id" uuid,
	"approved_host_unit_video_id" uuid,
	"approved_host_unit_audio_id" uuid,
	"approved_host_unit_post_id" uuid,
	"approved_host_unit_poll_id" uuid,
	"approved_host_unit_zone_id" uuid,
	"approved_host_unit_realm_id" uuid,
	"approved_host_unit_realm_rule_id" uuid,
	"approved_host_unit_custom_theme_id" uuid,
	"approved_host_unit_collection_id" uuid,
	"approved_host_unit_tag_id" uuid,
	"approved_host_unit_tag_path_id" uuid,
	"approved_host_unit_label_id" uuid,
	"review_evidence" jsonb,
	"review_evidence_sha256" text,
	"automated_review_lease_until" timestamp(3) with time zone,
	"automated_review_attempts" integer DEFAULT 0 NOT NULL,
	"next_automated_review_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"submitted_by_profile_id" uuid NOT NULL,
	"reviewed_by_profile_id" uuid,
	"reviewed_at" timestamp(3) with time zone,
	"decision_reason" text,
	"killed_by_profile_id" uuid,
	"killed_at" timestamp(3) with time zone,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "custom_theme_revision_id_target_key" UNIQUE("id","target_contract"),
	CONSTRAINT "custom_theme_revision_approved_host_unit_target_check" CHECK (num_nonnulls("approved_host_unit_publishing_id", "approved_host_unit_music_id", "approved_host_unit_program_id", "approved_host_unit_software_id", "approved_host_unit_entity_id", "approved_host_unit_grouping_id", "approved_host_unit_reference_id", "approved_host_unit_distribution_id", "approved_host_unit_video_id", "approved_host_unit_audio_id", "approved_host_unit_post_id", "approved_host_unit_poll_id", "approved_host_unit_zone_id", "approved_host_unit_realm_id", "approved_host_unit_realm_rule_id", "approved_host_unit_custom_theme_id", "approved_host_unit_collection_id", "approved_host_unit_tag_id", "approved_host_unit_tag_path_id", "approved_host_unit_label_id") between 0 and 1),
	CONSTRAINT "custom_theme_revision_approved_host_unit_id_check" CHECK ("approved_host_unit_id" is not distinct from coalesce("approved_host_unit_publishing_id", "approved_host_unit_music_id", "approved_host_unit_program_id", "approved_host_unit_software_id", "approved_host_unit_entity_id", "approved_host_unit_grouping_id", "approved_host_unit_reference_id", "approved_host_unit_distribution_id", "approved_host_unit_video_id", "approved_host_unit_audio_id", "approved_host_unit_post_id", "approved_host_unit_poll_id", "approved_host_unit_zone_id", "approved_host_unit_realm_id", "approved_host_unit_realm_rule_id", "approved_host_unit_custom_theme_id", "approved_host_unit_collection_id", "approved_host_unit_tag_id", "approved_host_unit_tag_path_id", "approved_host_unit_label_id")),
	CONSTRAINT "custom_theme_revision_automated_review_attempts_check" CHECK ("automated_review_attempts" >= 0),
	CONSTRAINT "custom_theme_revision_target_contract_check" CHECK ("target_contract" = 'rezics.unit.presentation@0'),
	CONSTRAINT "custom_theme_revision_execution_mode_check" CHECK ("execution_mode" = 'host_full_trust'),
	CONSTRAINT "custom_theme_revision_resource_mode_check" CHECK ("resource_mode" = 'external_live'),
	CONSTRAINT "custom_theme_revision_review_state_check" CHECK ("review_state" in ('pending_automated', 'pending_human', 'approved', 'rejected', 'killed', 'revalidation_required')),
	CONSTRAINT "custom_theme_revision_approval_scope_check" CHECK ("approval_scope" = 'host_unit'),
	CONSTRAINT "custom_theme_revision_manifest_sha256_check" CHECK ("manifest_sha256" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "custom_theme_revision_source_archive_sha256_check" CHECK ("source_archive_sha256" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "custom_theme_revision_review_evidence_sha256_check" CHECK ("review_evidence_sha256" is null or "review_evidence_sha256" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "custom_theme_revision_review_shape_check" CHECK ((
				"review_state" in ('pending_automated', 'pending_human')
				and "reviewed_by_profile_id" is null
				and "reviewed_at" is null
				and "approved_host_unit_id" is null
				and "decision_reason" is null
			) or (
				"review_state" = 'rejected'
				and "reviewed_by_profile_id" is not null
				and "reviewed_at" is not null
				and "approved_host_unit_id" is null
				and "decision_reason" is not null
			) or (
				"review_state" in ('approved', 'killed', 'revalidation_required')
				and "reviewed_by_profile_id" is not null
				and "reviewed_at" is not null
				and "approved_host_unit_id" is not null
				and "review_evidence" is not null
				and "review_evidence_sha256" is not null
			)),
	CONSTRAINT "custom_theme_revision_reviewer_separation_check" CHECK ("reviewed_by_profile_id" is null or "reviewed_by_profile_id" <> "submitted_by_profile_id"),
	CONSTRAINT "custom_theme_revision_kill_shape_check" CHECK (("review_state" = 'killed') = ("killed_at" is not null and "killed_by_profile_id" is not null)),
	CONSTRAINT "custom_theme_revision_review_evidence_json_object_check" CHECK ("review_evidence" is null or jsonb_typeof("review_evidence") = 'object')
);

CREATE TABLE "custom_theme_revision_external_resource" (
	"revision_id" uuid,
	"resource_key" text,
	"role" text NOT NULL,
	"requested_url" text NOT NULL,
	"final_url" text NOT NULL,
	"origin" text NOT NULL,
	"observed_sha256" text NOT NULL,
	"observed_byte_length" integer NOT NULL,
	"observed_content_type" text NOT NULL,
	"integrity_metadata" text,
	"integrity_waiver_reason" text,
	"cors_allows_anonymous" boolean NOT NULL,
	"observed_at" timestamp(3) with time zone NOT NULL,
	"current_health_state" text DEFAULT 'unchecked' NOT NULL,
	"last_checked_at" timestamp(3) with time zone,
	"next_check_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"monitor_lease_until" timestamp(3) with time zone,
	"monitor_failure_count" integer DEFAULT 0 NOT NULL,
	"review_evidence" jsonb NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "custom_theme_revision_external_resource_pkey" PRIMARY KEY("revision_id","resource_key"),
	CONSTRAINT "custom_theme_external_resource_key_check" CHECK (length("resource_key") between 1 and 200),
	CONSTRAINT "custom_theme_external_resource_urls_check" CHECK ("requested_url" like 'https://%' and "final_url" like 'https://%' and "origin" like 'https://%'),
	CONSTRAINT "custom_theme_external_resource_sha256_check" CHECK ("observed_sha256" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "custom_theme_external_resource_byte_length_check" CHECK ("observed_byte_length" between 0 and 5242880),
	CONSTRAINT "custom_theme_external_resource_integrity_check" CHECK ((
				"integrity_metadata" is not null
				and btrim("integrity_metadata") <> ''
				and "integrity_waiver_reason" is null
			) or (
				"integrity_metadata" is null
				and "integrity_waiver_reason" is not null
				and btrim("integrity_waiver_reason") <> ''
			)),
	CONSTRAINT "custom_theme_external_resource_health_check" CHECK ("current_health_state" in ('current', 'drifted', 'unavailable', 'unchecked')),
	CONSTRAINT "custom_theme_external_resource_monitor_failure_count_check" CHECK ("monitor_failure_count" >= 0),
	CONSTRAINT "custom_theme_external_resource_review_evidence_json_object_check" CHECK ("review_evidence" is null or jsonb_typeof("review_evidence") = 'object')
);

CREATE TABLE "custom_theme_revision_file" (
	"revision_id" uuid,
	"path" text,
	"role" text NOT NULL,
	"content_type" text NOT NULL,
	"sha256" text NOT NULL,
	"byte_length" integer NOT NULL,
	"storage_key" text NOT NULL CONSTRAINT "custom_theme_revision_file_storage_key_key" UNIQUE,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "custom_theme_revision_file_pkey" PRIMARY KEY("revision_id","path"),
	CONSTRAINT "custom_theme_revision_file_role_check" CHECK ("role" in ('manifest', 'source_archive', 'html', 'css', 'js', 'worker', 'wasm', 'font', 'svg', 'asset')),
	CONSTRAINT "custom_theme_revision_file_path_check" CHECK (length("path") between 1 and 512
				and "path" !~ '(^|/)\.\.?(/|$)'
				and "path" !~ '[\\]'
				and left("path", 1) <> '/'),
	CONSTRAINT "custom_theme_revision_file_content_type_check" CHECK (btrim("content_type") <> ''),
	CONSTRAINT "custom_theme_revision_file_sha256_check" CHECK ("sha256" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "custom_theme_revision_file_byte_length_check" CHECK ("byte_length" between 0 and case
				when "role" = 'source_archive' then 20971520
				else 5242880
			end),
	CONSTRAINT "custom_theme_revision_file_storage_key_check" CHECK (btrim("storage_key") <> '')
);

CREATE TABLE "custom_theme_revision_review_event" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"revision_id" uuid NOT NULL,
	"kind" text NOT NULL,
	"actor_profile_id" uuid,
	"evidence" jsonb NOT NULL,
	"evidence_sha256" text NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "custom_theme_review_event_kind_check" CHECK ("kind" in ('automated', 'approve', 'reject', 'revalidation', 'kill')),
	CONSTRAINT "custom_theme_review_event_evidence_sha256_check" CHECK ("evidence_sha256" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "custom_theme_review_event_evidence_json_object_check" CHECK ("evidence" is null or jsonb_typeof("evidence") = 'object')
);

CREATE TABLE "distribution_catalog_change" (
	"id" uuid DEFAULT uuidv7(),
	"owner_id" uuid,
	"version" bigint NOT NULL,
	"actor_auth_user_id" uuid,
	"operation" text NOT NULL,
	"recorded_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"withdrawn_at" timestamp(3) with time zone,
	CONSTRAINT "distribution_change_identity_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "distribution_change_version_key" UNIQUE("owner_id","version"),
	CONSTRAINT "distribution_change_version_check" CHECK ("version" between 1 and 9007199254740991),
	CONSTRAINT "distribution_change_operation_check" CHECK (length("operation") between 1 and 96)
);

CREATE TABLE "distribution_catalog_relation" (
	"id" uuid DEFAULT uuidv7(),
	"owner_id" uuid,
	"definition_revision_id" uuid NOT NULL,
	"semantic_id" uuid DEFAULT uuidv7() NOT NULL,
	"expected_head_version" bigint DEFAULT 0 NOT NULL,
	"state" text DEFAULT 'active' NOT NULL,
	"revision" bigint DEFAULT 1 NOT NULL,
	"spoiler" integer DEFAULT 0 NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "distribution_relation_owner_id_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "distribution_relation_head_version_check" CHECK ("expected_head_version" between 0 and 9007199254740990),
	CONSTRAINT "distribution_relation_spoiler_check" CHECK ("spoiler" between 0 and 2),
	CONSTRAINT "distribution_relation_state_check" CHECK ("state" in ('active', 'disputed', 'withdrawn', 'superseded')),
	CONSTRAINT "distribution_relation_revision_check" CHECK ("revision" between 1 and 9007199254740991)
);

CREATE TABLE "distribution_editorial" (
	"owner_id" uuid,
	"language" text,
	"revision" bigint NOT NULL,
	"state" text NOT NULL,
	"summary" text,
	"description" jsonb,
	"avatar_type" text,
	"avatar_asset_id" uuid,
	"avatar_emoji" text,
	"avatar_icon_prefix" text,
	"avatar_icon_name" text,
	"banner_asset_id" uuid,
	"cover_asset_id" uuid,
	"operator_auth_user_id" uuid NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "distribution_editorial_pkey" PRIMARY KEY("owner_id","language"),
	CONSTRAINT "distribution_editorial_revision_check" CHECK ("revision" between 1 and 9007199254740991),
	CONSTRAINT "distribution_editorial_language_check" CHECK (octet_length("language") between 1 and 255),
	CONSTRAINT "distribution_editorial_state_check" CHECK ("state" in ('active','withdrawn')),
	CONSTRAINT "distribution_editorial_summary_check" CHECK ("summary" is null or char_length("summary") <= 500),
	CONSTRAINT "distribution_editorial_description_check" CHECK ("description" is null or (jsonb_typeof("description")='object' and octet_length("description"::text) <= 1048576)),
	CONSTRAINT "distribution_editorial_avatar_check" CHECK (
		 ("avatar_type" is null and num_nonnulls("avatar_asset_id","avatar_emoji","avatar_icon_prefix","avatar_icon_name")=0)
		 or ("avatar_type"='image' and "avatar_asset_id" is not null and num_nonnulls("avatar_emoji","avatar_icon_prefix","avatar_icon_name")=0)
		 or ("avatar_type"='emoji' and char_length("avatar_emoji") between 1 and 64 and "avatar_emoji" is not null and num_nonnulls("avatar_asset_id","avatar_icon_prefix","avatar_icon_name")=0)
		 or ("avatar_type"='icon' and "avatar_icon_prefix" in ('fas','fab') and "avatar_icon_prefix" is not null and "avatar_icon_name" is not null and "avatar_icon_name" ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length("avatar_icon_name") <= 128 and num_nonnulls("avatar_asset_id","avatar_emoji")=0))
) PARTITION BY HASH ("owner_id");
