	"name_id" uuid,
	"authority_id" uuid,
	"identifier_id" uuid,
	CONSTRAINT "distribution_source_owned_baseline_pkey" PRIMARY KEY("source_record_id","mapping_key","correspondence_revision","owner_id","kind","component_key"),
	CONSTRAINT "distribution_source_owned_base_owner" CHECK ("mapping_owner" in ('publishing', 'music', 'program', 'software', 'entity', 'grouping', 'reference', 'distribution')),
	CONSTRAINT "distribution_source_owned_base_values" CHECK (octet_length("source_path") between 1 and 512 and "source_revision" between 1 and 9007199254740991 and "current_revision" between 1 and 9007199254740991),
	CONSTRAINT "distribution_source_owned_base_kind" CHECK (num_nonnulls("semantic_id","name_id","authority_id","identifier_id") = 1 and (("kind" = 'catalog-semantic' and "component_key" = "semantic_id") or ("kind" = 'catalog-name' and "component_key" = "name_id") or ("kind" = 'catalog-name-authority' and "component_key" = "authority_id") or ("kind" = 'catalog-identifier' and "component_key" = "identifier_id")))
) PARTITION BY HASH ("source_record_id");
