CREATE TABLE "dock_revision" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"dock_id" uuid NOT NULL,
	"parent_revision_id" uuid,
	"source_revision_id" uuid,
	"content_id" uuid NOT NULL,
	"actor_profile_id" uuid,
	"edit_summary" text,
	"kind" text NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "dock_revision_id_dock_key" UNIQUE("id","dock_id"),
	CONSTRAINT "dock_revision_kind_check" CHECK ("kind" in ('create', 'update', 'delete', 'restore')),
	CONSTRAINT "dock_revision_source_shape_check" CHECK (("kind" = 'restore') = ("source_revision_id" is not null))
);

CREATE TABLE "dock_revision_head" (
	"dock_id" uuid PRIMARY KEY,
	"revision_id" uuid NOT NULL CONSTRAINT "dock_revision_head_revision_key" UNIQUE
);

CREATE TABLE "email_outbox" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"kind" "email_outbox_kind" NOT NULL,
	"notification_id" uuid,
	"recipient_email" text,
	"locale" text,
	"action_url" text,
	"status" "email_outbox_status" DEFAULT 'pending'::"email_outbox_status" NOT NULL,
	"attempt_count" integer DEFAULT 0 NOT NULL,
	"available_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"lease_expires_at" timestamp(3) with time zone,
	"accepted_at" timestamp(3) with time zone,
	"failed_at" timestamp(3) with time zone,
	"provider_message_id" text,
	"provider_status" "email_provider_status",
	"last_error" text,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "email_outbox_attempt_count_check" CHECK ("attempt_count" >= 0),
	CONSTRAINT "email_outbox_intent_check" CHECK ((
				"kind" = 'notification'::email_outbox_kind
				and "notification_id" is not null
				and "recipient_email" is null
				and "locale" is null
				and "action_url" is null
			) or (
				"kind" in (
					'verify_email'::email_outbox_kind,
					'reset_password'::email_outbox_kind
				)
				and "notification_id" is null
				and (
					(
						"status" in (
							'pending'::email_outbox_status,
							'processing'::email_outbox_status
						)
						and nullif(btrim("recipient_email"), '') is not null
						and nullif(btrim("action_url"), '') is not null
						and "locale" is not null
						and "locale" in ('zh', 'en', 'ja', 'ko', 'de', 'fr', 'es')
					) or (
						"status" in (
							'accepted'::email_outbox_status,
							'failed'::email_outbox_status
						)
						and "recipient_email" is null
						and "locale" is null
						and "action_url" is null
					)
				)
			)),
	CONSTRAINT "email_outbox_state_check" CHECK ((
				"status" = 'pending'::email_outbox_status
				and "lease_expires_at" is null
				and "accepted_at" is null
				and "failed_at" is null
				and "provider_message_id" is null
				and "provider_status" is null
			) or (
				"status" = 'processing'::email_outbox_status
				and "lease_expires_at" is not null
				and "accepted_at" is null
				and "failed_at" is null
				and "provider_message_id" is null
				and "provider_status" is null
				and "last_error" is null
			) or (
				"status" = 'accepted'::email_outbox_status
				and "lease_expires_at" is null
				and "accepted_at" is not null
				and "failed_at" is null
				and "provider_status" is not null
				and (
					"provider_status" = 'logged'::email_provider_status
					or nullif(btrim("provider_message_id"), '') is not null
				)
				and "last_error" is null
			) or (
				"status" = 'failed'::email_outbox_status
				and "lease_expires_at" is null
				and "accepted_at" is null
				and "failed_at" is not null
				and "provider_message_id" is null
				and "provider_status" is null
				and nullif(btrim("last_error"), '') is not null
			))
);

CREATE TABLE "entity_catalog_change" (
	"id" uuid DEFAULT uuidv7(),
	"owner_id" uuid,
	"version" bigint NOT NULL,
	"actor_auth_user_id" uuid,
	"operation" text NOT NULL,
	"recorded_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"withdrawn_at" timestamp(3) with time zone,
	CONSTRAINT "entity_change_identity_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "entity_change_version_key" UNIQUE("owner_id","version"),
	CONSTRAINT "entity_change_version_check" CHECK ("version" between 1 and 9007199254740991),
	CONSTRAINT "entity_change_operation_check" CHECK (length("operation") between 1 and 96)
);

CREATE TABLE "entity_catalog_profile" (
	"id" uuid PRIMARY KEY,
	"identity_shape" text NOT NULL,
	"type_revision_id" uuid,
	"gender_revision_id" uuid,
	"area_id" uuid,
	"begin_area_id" uuid,
	"end_area_id" uuid,
	"begin_year" integer,
	"begin_month" smallint,
	"begin_day" smallint,
	"begin_text" text,
	"end_year" integer,
	"end_month" smallint,
	"end_day" smallint,
	"end_text" text,
	"ended" boolean,
	CONSTRAINT "entity_catalog_profile_shape_check" CHECK ("identity_shape" in ('person', 'organization', 'character', 'label', 'collective', 'unresolved', 'service_actor')),
	CONSTRAINT "entity_catalog_profile_gender_shape_check" CHECK ("gender_revision_id" is null or "identity_shape" in ('person','character','unresolved')),
	CONSTRAINT "entity_catalog_profile_begin_check" CHECK (
		("begin_month" is null or "begin_month" between 1 and 12)
		and ("begin_day" is null or "begin_day" between 1 and 31)
		and ("begin_month" is null or "begin_day" is null or "begin_day" <= case
			when "begin_month" in (4, 6, 9, 11) then 30
			when "begin_month" = 2 then case when "begin_year" is null
				or mod("begin_year", 400) = 0 or (mod("begin_year", 4) = 0 and mod("begin_year", 100) <> 0) then 29 else 28 end
			else 31 end)),
	CONSTRAINT "entity_catalog_profile_end_check" CHECK (
		("end_month" is null or "end_month" between 1 and 12)
		and ("end_day" is null or "end_day" between 1 and 31)
		and ("end_month" is null or "end_day" is null or "end_day" <= case
			when "end_month" in (4, 6, 9, 11) then 30
			when "end_month" = 2 then case when "end_year" is null
				or mod("end_year", 400) = 0 or (mod("end_year", 4) = 0 and mod("end_year", 100) <> 0) then 29 else 28 end
			else 31 end))
);

CREATE TABLE "entity_catalog_profile_revision" (
	"owner_id" uuid,
	"revision" bigint,
	"removed" boolean DEFAULT false NOT NULL,
	"snapshot" jsonb NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "entity_catalog_profile_revision_pkey" PRIMARY KEY("owner_id","revision"),
	CONSTRAINT "entity_catalog_profile_revision_number_check" CHECK ("revision" between 1 and 9007199254740991),
	CONSTRAINT "entity_catalog_profile_revision_snapshot_check" CHECK (jsonb_typeof("snapshot") = 'object' and octet_length("snapshot"::text) <= 32768)
);

CREATE TABLE "entity_catalog_relation" (
	"id" uuid DEFAULT uuidv7(),
	"owner_id" uuid,
	"definition_revision_id" uuid NOT NULL,
	"semantic_id" uuid DEFAULT uuidv7() NOT NULL,
	"expected_head_version" bigint DEFAULT 0 NOT NULL,
	"state" text DEFAULT 'active' NOT NULL,
	"revision" bigint DEFAULT 1 NOT NULL,
	"spoiler" integer DEFAULT 0 NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "entity_relation_owner_id_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "entity_relation_head_version_check" CHECK ("expected_head_version" between 0 and 9007199254740990),
	CONSTRAINT "entity_relation_spoiler_check" CHECK ("spoiler" between 0 and 2),
	CONSTRAINT "entity_relation_state_check" CHECK ("state" in ('active', 'disputed', 'withdrawn', 'superseded')),
	CONSTRAINT "entity_relation_revision_check" CHECK ("revision" between 1 and 9007199254740991)
);

CREATE TABLE "entity_editorial" (
	"owner_id" uuid,
	"language" text,
	"revision" bigint NOT NULL,
	"state" text NOT NULL,
	"summary" text,
	"description" jsonb,
	"avatar_type" text,
	"avatar_asset_id" uuid,
	"avatar_emoji" text,
	"avatar_icon_prefix" text,
	"avatar_icon_name" text,
	"banner_asset_id" uuid,
	"cover_asset_id" uuid,
	"operator_auth_user_id" uuid NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "entity_editorial_pkey" PRIMARY KEY("owner_id","language"),
	CONSTRAINT "entity_editorial_revision_check" CHECK ("revision" between 1 and 9007199254740991),
	CONSTRAINT "entity_editorial_language_check" CHECK (octet_length("language") between 1 and 255),
	CONSTRAINT "entity_editorial_state_check" CHECK ("state" in ('active','withdrawn')),
	CONSTRAINT "entity_editorial_summary_check" CHECK ("summary" is null or char_length("summary") <= 500),
	CONSTRAINT "entity_editorial_description_check" CHECK ("description" is null or (jsonb_typeof("description")='object' and octet_length("description"::text) <= 1048576)),
	CONSTRAINT "entity_editorial_avatar_check" CHECK (
		 ("avatar_type" is null and num_nonnulls("avatar_asset_id","avatar_emoji","avatar_icon_prefix","avatar_icon_name")=0)
		 or ("avatar_type"='image' and "avatar_asset_id" is not null and num_nonnulls("avatar_emoji","avatar_icon_prefix","avatar_icon_name")=0)
		 or ("avatar_type"='emoji' and char_length("avatar_emoji") between 1 and 64 and "avatar_emoji" is not null and num_nonnulls("avatar_asset_id","avatar_icon_prefix","avatar_icon_name")=0)
		 or ("avatar_type"='icon' and "avatar_icon_prefix" in ('fas','fab') and "avatar_icon_prefix" is not null and "avatar_icon_name" is not null and "avatar_icon_name" ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length("avatar_icon_name") <= 128 and num_nonnulls("avatar_asset_id","avatar_emoji")=0))
) PARTITION BY HASH ("owner_id");
