	CONSTRAINT "entity_participation_revision_check" CHECK ("revision" between 1 and 9007199254740991)
);

CREATE TABLE "entity_presentation" (
	"entity_id" uuid,
	"language" text,
	"name_id" uuid,
	"name_revision" bigint,
	"avatar_type" text,
	"avatar_asset_id" uuid,
	"avatar_emoji" text,
	"avatar_icon_prefix" text,
	"avatar_icon_name" text,
	"banner_asset_id" uuid,
	"summary" text,
	"description" jsonb,
	"revision" bigint DEFAULT 1 NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "entity_presentation_pkey" PRIMARY KEY("entity_id","language"),
	CONSTRAINT "entity_presentation_name_shape_check" CHECK (num_nonnulls("name_id", "name_revision") in (0,2)),
	CONSTRAINT "entity_presentation_language_check" CHECK (octet_length("language") between 1 and 255),
	CONSTRAINT "entity_presentation_summary_check" CHECK ("summary" is null or char_length("summary") <= 500),
	CONSTRAINT "entity_presentation_description_check" CHECK ("description" is null or (jsonb_typeof("description") = 'object' and octet_length("description"::text) <= 1048576)),
	CONSTRAINT "entity_presentation_revision_check" CHECK ("revision" between 1 and 9007199254740991),
	CONSTRAINT "entity_presentation_avatar_type_check" CHECK ("avatar_type" in ('image', 'emoji', 'icon')),
	CONSTRAINT "entity_presentation_avatar_check" CHECK (
		("avatar_type" is null and num_nonnulls("avatar_asset_id","avatar_emoji","avatar_icon_prefix","avatar_icon_name") = 0)
		or ("avatar_type" = 'image' and "avatar_asset_id" is not null and num_nonnulls("avatar_emoji","avatar_icon_prefix","avatar_icon_name") = 0)
		or ("avatar_type" = 'emoji' and "avatar_emoji" is not null and char_length("avatar_emoji") between 1 and 64 and num_nonnulls("avatar_asset_id","avatar_icon_prefix","avatar_icon_name") = 0)
		or ("avatar_type" = 'icon' and "avatar_asset_id" is null and "avatar_emoji" is null
			and "avatar_icon_prefix" in ('fas', 'fab')
			and "avatar_icon_name" is not null and "avatar_icon_name" ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' and char_length("avatar_icon_name") <= 128))
);

CREATE TABLE "entity_presentation_revision" (
	"entity_id" uuid,
