CREATE TABLE "entity_relation_participant" (
	"id" uuid DEFAULT uuidv7(),
	"owner_id" uuid,
	"relation_id" uuid NOT NULL,
	"role_revision_id" uuid NOT NULL,
	"position" bigint NOT NULL,
	"credited_as" text,
	"publishing_id" uuid,
	"music_id" uuid,
	"program_id" uuid,
	"software_id" uuid,
	"entity_id" uuid,
	"grouping_id" uuid,
	"reference_id" uuid,
	"distribution_id" uuid,
	CONSTRAINT "entity_participant_identity_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "entity_participant_position_key" UNIQUE("owner_id","relation_id","position"),
	CONSTRAINT "entity_participant_target_check" CHECK (num_nonnulls("publishing_id", "music_id", "program_id", "software_id", "entity_id", "grouping_id", "reference_id", "distribution_id") = 1),
	CONSTRAINT "entity_participant_position_check" CHECK ("position" between 0 and 9007199254740991)
);

CREATE TABLE "entity_relation_scope" (
