);

CREATE TABLE "entity_semantic_revision" (
	"owner_id" uuid,
	"semantic_id" uuid,
	"version" bigint,
	"fact_id" uuid,
	"relation_id" uuid,
	"state" text DEFAULT 'active' NOT NULL,
	"actor_auth_user_id" uuid,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "entity_semantic_revision_key" PRIMARY KEY("owner_id","semantic_id","version"),
	CONSTRAINT "entity_semantic_revision_target_check" CHECK (num_nonnulls("fact_id","relation_id") = 1),
	CONSTRAINT "entity_semantic_revision_state_check" CHECK ("state" in ('active', 'disputed', 'withdrawn', 'superseded')),
	CONSTRAINT "entity_semantic_revision_version_check" CHECK ("version" between 1 and 9007199254740991)
);

