CREATE TABLE "governance_decision" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"action" text NOT NULL,
	"basis_kind" "governance_decision_basis_kind" NOT NULL,
	"actor_profile_id" uuid NOT NULL,
	"authority_kind" "governance_authority_kind" NOT NULL,
	"authority_realm_id" uuid,
	"authority_zone_id" uuid,
	"authority_unit_id" uuid,
	"target_unit_id" uuid,
	"target_user_id" uuid,
	"subject_kind" text NOT NULL,
	"subject_id" uuid NOT NULL,
	"reverses_decision_id" uuid,
	"request_id" text,
	"finalized" boolean DEFAULT false NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"authority_unit_publishing_id" uuid,
	"authority_unit_music_id" uuid,
	"authority_unit_program_id" uuid,
	"authority_unit_software_id" uuid,
	"authority_unit_entity_id" uuid,
	"authority_unit_grouping_id" uuid,
	"authority_unit_reference_id" uuid,
	"authority_unit_distribution_id" uuid,
	"authority_unit_video_id" uuid,
	"authority_unit_audio_id" uuid,
	"authority_unit_post_id" uuid,
	"authority_unit_poll_id" uuid,
	"authority_unit_zone_id" uuid,
	"authority_unit_realm_id" uuid,
	"authority_unit_realm_rule_id" uuid,
	"authority_unit_custom_theme_id" uuid,
	"authority_unit_collection_id" uuid,
	"authority_unit_tag_id" uuid,
	"authority_unit_tag_path_id" uuid,
	"authority_unit_label_id" uuid,
	"target_unit_publishing_id" uuid,
	"target_unit_music_id" uuid,
	"target_unit_program_id" uuid,
	"target_unit_software_id" uuid,
	"target_unit_entity_id" uuid,
	"target_unit_grouping_id" uuid,
	"target_unit_reference_id" uuid,
	"target_unit_distribution_id" uuid,
	"target_unit_video_id" uuid,
	"target_unit_audio_id" uuid,
	"target_unit_post_id" uuid,
	"target_unit_poll_id" uuid,
	"target_unit_zone_id" uuid,
	"target_unit_realm_id" uuid,
	"target_unit_realm_rule_id" uuid,
	"target_unit_custom_theme_id" uuid,
	"target_unit_collection_id" uuid,
	"target_unit_tag_id" uuid,
	"target_unit_tag_path_id" uuid,
	"target_unit_label_id" uuid,
	CONSTRAINT "governance_decision_authority_unit_target_check" CHECK (num_nonnulls("authority_unit_publishing_id", "authority_unit_music_id", "authority_unit_program_id", "authority_unit_software_id", "authority_unit_entity_id", "authority_unit_grouping_id", "authority_unit_reference_id", "authority_unit_distribution_id", "authority_unit_video_id", "authority_unit_audio_id", "authority_unit_post_id", "authority_unit_poll_id", "authority_unit_zone_id", "authority_unit_realm_id", "authority_unit_realm_rule_id", "authority_unit_custom_theme_id", "authority_unit_collection_id", "authority_unit_tag_id", "authority_unit_tag_path_id", "authority_unit_label_id") between 0 and 1),
	CONSTRAINT "governance_decision_authority_unit_id_check" CHECK ("authority_unit_id" is not distinct from coalesce("authority_unit_publishing_id", "authority_unit_music_id", "authority_unit_program_id", "authority_unit_software_id", "authority_unit_entity_id", "authority_unit_grouping_id", "authority_unit_reference_id", "authority_unit_distribution_id", "authority_unit_video_id", "authority_unit_audio_id", "authority_unit_post_id", "authority_unit_poll_id", "authority_unit_zone_id", "authority_unit_realm_id", "authority_unit_realm_rule_id", "authority_unit_custom_theme_id", "authority_unit_collection_id", "authority_unit_tag_id", "authority_unit_tag_path_id", "authority_unit_label_id")),
	CONSTRAINT "governance_decision_target_unit_target_check" CHECK (num_nonnulls("target_unit_publishing_id", "target_unit_music_id", "target_unit_program_id", "target_unit_software_id", "target_unit_entity_id", "target_unit_grouping_id", "target_unit_reference_id", "target_unit_distribution_id", "target_unit_video_id", "target_unit_audio_id", "target_unit_post_id", "target_unit_poll_id", "target_unit_zone_id", "target_unit_realm_id", "target_unit_realm_rule_id", "target_unit_custom_theme_id", "target_unit_collection_id", "target_unit_tag_id", "target_unit_tag_path_id", "target_unit_label_id") between 0 and 1),
	CONSTRAINT "governance_decision_target_unit_id_check" CHECK ("target_unit_id" is not distinct from coalesce("target_unit_publishing_id", "target_unit_music_id", "target_unit_program_id", "target_unit_software_id", "target_unit_entity_id", "target_unit_grouping_id", "target_unit_reference_id", "target_unit_distribution_id", "target_unit_video_id", "target_unit_audio_id", "target_unit_post_id", "target_unit_poll_id", "target_unit_zone_id", "target_unit_realm_id", "target_unit_realm_rule_id", "target_unit_custom_theme_id", "target_unit_collection_id", "target_unit_tag_id", "target_unit_tag_path_id", "target_unit_label_id")),
	CONSTRAINT "governance_decision_target_check" CHECK (num_nonnulls("target_unit_id", "target_user_id") = 1),
	CONSTRAINT "governance_decision_action_check" CHECK (btrim("action") <> '' and octet_length("action") <= 128),
	CONSTRAINT "governance_decision_subject_kind_check" CHECK (btrim("subject_kind") <> '' and octet_length("subject_kind") <= 64),
	CONSTRAINT "governance_decision_request_id_check" CHECK ("request_id" is null or (btrim("request_id") <> '' and octet_length("request_id") <= 200)),
	CONSTRAINT "governance_decision_authority_check" CHECK ((
				"authority_kind" = 'platform'::governance_authority_kind
				and num_nonnulls("authority_realm_id", "authority_zone_id", "authority_unit_id") = 0
			) or (
				"authority_kind" = 'realm'::governance_authority_kind
				and "authority_realm_id" is not null
				and num_nonnulls("authority_zone_id", "authority_unit_id") = 0
			) or (
				"authority_kind" = 'zone'::governance_authority_kind
				and "authority_zone_id" is not null
				and num_nonnulls("authority_realm_id", "authority_unit_id") = 0
			) or (
				"authority_kind" = 'unit'::governance_authority_kind
				and "authority_unit_id" is not null
				and num_nonnulls("authority_realm_id", "authority_zone_id") = 0
			)),
	CONSTRAINT "governance_decision_basis_check" CHECK (("basis_kind" = 'reversal'::governance_decision_basis_kind) = ("reverses_decision_id" is not null)),
	CONSTRAINT "governance_decision_not_self_reverse" CHECK ("reverses_decision_id" is null or "reverses_decision_id" <> "id")
);

CREATE TABLE "governance_decision_rule" (
	"decision_id" uuid,
	"rule_source_realm_id" uuid NOT NULL,
	"rule_revision_id" uuid NOT NULL,
	"rule_id" uuid,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "governance_decision_rule_pkey" PRIMARY KEY("decision_id","rule_id")
);

