CREATE TABLE "governance_post_binding" (
	"post_id" uuid PRIMARY KEY,
	"subject_kind" "governance_note_subject_kind" NOT NULL,
	"subject_id" uuid NOT NULL,
	"role" "governance_note_role" NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "governance_report_delivery" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"case_id" uuid NOT NULL,
	"action_id" uuid,
	"public_notice_post_id" uuid,
	"actor_entity_id" uuid NOT NULL,
	"actor_auth_user_id" uuid NOT NULL,
	"kind" text NOT NULL,
	"shard" smallint NOT NULL,
	"through_referral_id" uuid NOT NULL,
	"after_referral_id" uuid,
	"available_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"failure_count" integer DEFAULT 0 NOT NULL,
	"last_error" text,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"completed_at" timestamp(3) with time zone,
	CONSTRAINT "governance_report_delivery_kind_check" CHECK ("kind" in ('action','dismissal','notice') and ("kind" = 'action') = ("action_id" is not null) and ("kind" <> 'notice' or "public_notice_post_id" is not null)),
	CONSTRAINT "governance_report_delivery_shard_check" CHECK ("shard" between 0 and 63),
	CONSTRAINT "governance_report_delivery_cursor_check" CHECK ("after_referral_id" is null or "after_referral_id" <= "through_referral_id"),
	CONSTRAINT "governance_report_delivery_failure_check" CHECK ("failure_count" >= 0 and ("last_error" is null or octet_length("last_error") <= 2048))
);

CREATE TABLE "grouping_catalog_change" (
	"id" uuid DEFAULT uuidv7(),
	"owner_id" uuid,
	"version" bigint NOT NULL,
	"actor_auth_user_id" uuid,
	"operation" text NOT NULL,
	"recorded_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"withdrawn_at" timestamp(3) with time zone,
	CONSTRAINT "grouping_change_identity_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "grouping_change_version_key" UNIQUE("owner_id","version"),
	CONSTRAINT "grouping_change_version_check" CHECK ("version" between 1 and 9007199254740991),
	CONSTRAINT "grouping_change_operation_check" CHECK (length("operation") between 1 and 96)
);

CREATE TABLE "grouping_catalog_relation" (
	"id" uuid DEFAULT uuidv7(),
	"owner_id" uuid,
	"definition_revision_id" uuid NOT NULL,
	"semantic_id" uuid DEFAULT uuidv7() NOT NULL,
	"expected_head_version" bigint DEFAULT 0 NOT NULL,
	"state" text DEFAULT 'active' NOT NULL,
	"revision" bigint DEFAULT 1 NOT NULL,
	"spoiler" integer DEFAULT 0 NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "grouping_relation_owner_id_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "grouping_relation_head_version_check" CHECK ("expected_head_version" between 0 and 9007199254740990),
	CONSTRAINT "grouping_relation_spoiler_check" CHECK ("spoiler" between 0 and 2),
	CONSTRAINT "grouping_relation_state_check" CHECK ("state" in ('active', 'disputed', 'withdrawn', 'superseded')),
	CONSTRAINT "grouping_relation_revision_check" CHECK ("revision" between 1 and 9007199254740991)
);

CREATE TABLE "grouping_class_assignment" (
	"grouping_id" uuid,
	"class_revision_id" uuid,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "grouping_class_assignment_pkey" PRIMARY KEY("grouping_id","class_revision_id")
);

CREATE TABLE "grouping_command_revision" (
	"owner_id" uuid,
	"revision" bigint,
	"snapshot" jsonb NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "grouping_command_revision_pkey" PRIMARY KEY("owner_id","revision"),
	CONSTRAINT "grouping_command_revision_number_check" CHECK ("revision" between 1 and 9007199254740991),
	CONSTRAINT "grouping_command_revision_snapshot_check" CHECK (jsonb_typeof("snapshot") = 'object' and octet_length("snapshot"::text) <= 32768)
);

CREATE TABLE "grouping_editorial" (
	"owner_id" uuid,
	"language" text,
	"revision" bigint NOT NULL,
	"state" text NOT NULL,
	"summary" text,
	"description" jsonb,
	"avatar_type" text,
	"avatar_asset_id" uuid,
	"avatar_emoji" text,
	"avatar_icon_prefix" text,
	"avatar_icon_name" text,
	"banner_asset_id" uuid,
	"cover_asset_id" uuid,
	"operator_auth_user_id" uuid NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "grouping_editorial_pkey" PRIMARY KEY("owner_id","language"),
	CONSTRAINT "grouping_editorial_revision_check" CHECK ("revision" between 1 and 9007199254740991),
	CONSTRAINT "grouping_editorial_language_check" CHECK (octet_length("language") between 1 and 255),
	CONSTRAINT "grouping_editorial_state_check" CHECK ("state" in ('active','withdrawn')),
	CONSTRAINT "grouping_editorial_summary_check" CHECK ("summary" is null or char_length("summary") <= 500),
	CONSTRAINT "grouping_editorial_description_check" CHECK ("description" is null or (jsonb_typeof("description")='object' and octet_length("description"::text) <= 1048576)),
	CONSTRAINT "grouping_editorial_avatar_check" CHECK (
		 ("avatar_type" is null and num_nonnulls("avatar_asset_id","avatar_emoji","avatar_icon_prefix","avatar_icon_name")=0)
		 or ("avatar_type"='image' and "avatar_asset_id" is not null and num_nonnulls("avatar_emoji","avatar_icon_prefix","avatar_icon_name")=0)
		 or ("avatar_type"='emoji' and char_length("avatar_emoji") between 1 and 64 and "avatar_emoji" is not null and num_nonnulls("avatar_asset_id","avatar_icon_prefix","avatar_icon_name")=0)
		 or ("avatar_type"='icon' and "avatar_icon_prefix" in ('fas','fab') and "avatar_icon_prefix" is not null and "avatar_icon_name" is not null and "avatar_icon_name" ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length("avatar_icon_name") <= 128 and num_nonnulls("avatar_asset_id","avatar_emoji")=0))
) PARTITION BY HASH ("owner_id");
