	"language_tag" text,
	"private_use_namespace" text,
	"language_policy" text,
	"kind" text NOT NULL,
	"value" text NOT NULL,
	"sort_name" text,
	"origin" text DEFAULT 'unknown' NOT NULL,
	"translation_method" text DEFAULT 'unknown' NOT NULL,
	"primary_for_language" boolean,
	"scope_owner_id" uuid,
	"territory" text,
	"context" text,
	"derivation_name_id" uuid,
	"derivation_revision" bigint,
	"begin" jsonb,
	"end" jsonb,
	"ended" boolean,
	"spoiler" integer DEFAULT 0 NOT NULL,
	"state" text DEFAULT 'active' NOT NULL,
	CONSTRAINT "grouping_named_form_identity_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "grouping_named_form_state_check" CHECK ("state" in ('active', 'disputed', 'withdrawn', 'superseded')),
	CONSTRAINT "grouping_named_form_revision_check" CHECK ("revision" between 1 and 9007199254740991),
	CONSTRAINT "grouping_named_form_kind_check" CHECK (octet_length("kind") between 1 and 96),
	CONSTRAINT "grouping_named_form_value_check" CHECK (octet_length("value") between 1 and 131072 and ("sort_name" is null or octet_length("sort_name") between 1 and 131072)),
	CONSTRAINT "grouping_named_form_language_check" CHECK (("language_tag" is null and "language_policy" is null and "private_use_namespace" is null) or ("language_tag" is not null and octet_length("language_tag") between 1 and 255 and "language_policy" is not null and ("private_use_namespace" is null or octet_length("private_use_namespace") between 1 and 512))),
	CONSTRAINT "grouping_named_form_origin_check" CHECK ("origin" in ('original', 'translation', 'transliteration', 'abbreviation', 'variant', 'unknown')),
	CONSTRAINT "grouping_named_form_method_check" CHECK ("translation_method" in ('human', 'machine', 'mixed', 'unknown', 'not_applicable')),
	CONSTRAINT "grouping_named_form_derivation_check" CHECK (num_nonnulls("derivation_name_id","derivation_revision") in (0,2)),
	CONSTRAINT "grouping_named_form_spoiler_check" CHECK ("spoiler" between 0 and 2),
	CONSTRAINT "grouping_named_form_scope_check" CHECK (("territory" is null or octet_length("territory") between 1 and 96) and ("context" is null or octet_length("context") between 1 and 512))
);

