CREATE TABLE "guide_node" (
	"id" uuid PRIMARY KEY,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "guide_node_localization" (
	"node_id" uuid,
	"language" text,
	"title" text NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "guide_node_localization_pkey" PRIMARY KEY("node_id","language"),
	CONSTRAINT "guide_node_localization_language_check" CHECK ("language" in ('zh', 'en', 'ja', 'ko', 'de', 'fr', 'es')),
	CONSTRAINT "guide_node_localization_title_check" CHECK (btrim("title") <> '' and octet_length("title") <= 512)
);

CREATE TABLE "image_asset" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"uploader_auth_user_id" uuid NOT NULL,
	"owner_auth_user_id" uuid NOT NULL,
	"status" "image_asset_status" DEFAULT 'pending'::"image_asset_status" NOT NULL,
	"access" "image_asset_access" DEFAULT 'private'::"image_asset_access" NOT NULL,
	"deleted_at" timestamp(3) with time zone,
	"content_erased_at" timestamp(3) with time zone,
	"erasure_fence_version_id" text,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "image_asset_erasure_fence_check" CHECK ("erasure_fence_version_id" is null or octet_length("erasure_fence_version_id") between 1 and 4096),
	CONSTRAINT "image_asset_content_erasure_check" CHECK ("content_erased_at" is null or ("deleted_at" is not null and "erasure_fence_version_id" is not null)),
	CONSTRAINT "image_asset_deleted_at_check" CHECK ("deleted_at" is null or "deleted_at" >= "created_at")
);

CREATE TABLE "image_asset_presentation" (
	"asset_id" uuid,
	"role" "image_asset_presentation_role",
	"fit" "image_asset_presentation_fit" NOT NULL,
	"crop_x" double precision,
	"crop_y" double precision,
	"crop_width" double precision,
	"crop_height" double precision,
	"revision" integer DEFAULT 1 NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "image_asset_presentation_pkey" PRIMARY KEY("asset_id","role"),
	CONSTRAINT "image_asset_presentation_shape_check" CHECK ((
				"role" = 'cover'::image_asset_presentation_role
				and "fit" = 'contain'::image_asset_presentation_fit
				and "crop_x" is null
				and "crop_y" is null
				and "crop_width" is null
				and "crop_height" is null
			) or (
				"fit" = 'crop'::image_asset_presentation_fit
				and "crop_x" is not null
				and "crop_y" is not null
				and "crop_width" is not null
				and "crop_height" is not null
			)),
	CONSTRAINT "image_asset_presentation_crop_bounds_check" CHECK ("fit" <> 'crop'::image_asset_presentation_fit or (
				"crop_x" >= 0
				and "crop_y" >= 0
				and "crop_width" > 0
				and "crop_height" > 0
				and "crop_x" + "crop_width" <= 1
				and "crop_y" + "crop_height" <= 1
			)),
	CONSTRAINT "image_asset_presentation_revision_check" CHECK ("revision" > 0)
);

CREATE TABLE "image_object" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"asset_id" uuid NOT NULL CONSTRAINT "image_object_asset_id_key" UNIQUE,
	"storage_key" text NOT NULL CONSTRAINT "image_object_storage_key_key" UNIQUE,
	"media_type" text,
	"byte_size" bigint,
	"width" integer,
	"height" integer,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "image_object_storage_key_not_blank" CHECK (btrim("storage_key") <> ''),
	CONSTRAINT "image_object_metadata_shape_check" CHECK ((
				"media_type" is null
				and "byte_size" is null
				and "width" is null
				and "height" is null
			) or (
				"media_type" is not null
				and "byte_size" is not null
				and "byte_size" > 0
				and "width" is not null
				and "width" > 0
				and "height" is not null
				and "height" > 0
			))
);

CREATE TABLE "label" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"revision" bigint DEFAULT 1 NOT NULL,
	"routing_generation" integer DEFAULT 1 NOT NULL,
	"created_by_auth_user_id" uuid,
	"status" "unit_status" DEFAULT 'draft'::"unit_status" NOT NULL,
	"visibility" "resource_visibility" DEFAULT 'public'::"resource_visibility" NOT NULL,
	"content_rating" "content_rating" DEFAULT 'general'::"content_rating" NOT NULL,
	"ai_disclosure" "ai_disclosure" DEFAULT 'unknown'::"ai_disclosure" NOT NULL,
	"moderation_status" "moderation_status" DEFAULT 'approved'::"moderation_status" NOT NULL,
	"post_targeting_locked" boolean DEFAULT false NOT NULL,
	"published_at" timestamp(3) with time zone,
	"deleted_at" timestamp(3) with time zone,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "label_identity_revision_check" CHECK ("revision" between 1 and 9007199254740991 and "routing_generation" between 1 and 2147483647),
	CONSTRAINT "label_identity_publication_check" CHECK ("status" <> 'published' or "published_at" is not null),
	CONSTRAINT "label_identity_deleted_at_check" CHECK ("deleted_at" is null or "deleted_at" >= "created_at")
);

CREATE TABLE "message" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"conversation_id" uuid NOT NULL,
	"sender_entity_id" uuid NOT NULL,
	"sender_auth_user_id" uuid NOT NULL,
	"content" text,
	"deleted_at" timestamp(3) with time zone,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "message_content_byte_size_check" CHECK ("content" is null or octet_length("content") <= 80000),
	CONSTRAINT "message_content_state_check" CHECK (("deleted_at" is null and nullif(btrim("content"), '') is not null) or ("deleted_at" is not null and "content" is null)),
	CONSTRAINT "message_deleted_at_check" CHECK ("deleted_at" is null or "deleted_at" >= "created_at")
);

CREATE TABLE "music_alternative_track" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"name" text,
	"artist_credit_id" uuid,
	CONSTRAINT "music_alternative_track_value_check" CHECK (("name" is not null or "artist_credit_id" is not null) and ("name" is null or length("name") > 0))
);

CREATE TABLE "music_artist_credit" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"rendered_name" text,
	"created_by_auth_user_id" uuid,
	"created_for_music_id" uuid,
	"publicly_reusable" boolean DEFAULT false NOT NULL,
	"member_count" bigint DEFAULT 0 NOT NULL,
	"last_position" bigint DEFAULT -1 NOT NULL,
	"sealed_at" timestamp(3) with time zone,
	"retired_at" timestamp(3) with time zone,
	CONSTRAINT "music_credit_prefix_check" CHECK ("member_count" between 0 and 9007199254740991 and "last_position" between -1 and 9007199254740991 and ("sealed_at" is null or ("member_count" > 0 and "last_position" = "member_count" - 1)))
);

CREATE TABLE "music_artist_credit_name" (
	"credit_id" uuid,
	"position" bigint,
	"source_position" bigint,
	"artist_id" uuid,
	"credited_name" text NOT NULL,
	"join_phrase" text DEFAULT '' NOT NULL,
	CONSTRAINT "music_artist_credit_name_pkey" PRIMARY KEY("credit_id","position"),
	CONSTRAINT "music_credit_position_check" CHECK ("position" between 0 and 9007199254740991),
	CONSTRAINT "music_credit_name_check" CHECK (length("credited_name") > 0)
);

CREATE TABLE "music_candidate_toc" (
	"candidate_id" uuid,
	"toc_id" uuid,
	CONSTRAINT "music_candidate_toc_pkey" PRIMARY KEY("candidate_id","toc_id")
);

CREATE TABLE "music_candidate_track" (
	"candidate_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"position" bigint NOT NULL,
	"name" text NOT NULL,
	"credited_artist_text" text,
	CONSTRAINT "music_candidate_track_pkey" PRIMARY KEY("candidate_id","id"),
	CONSTRAINT "music_candidate_track_position_key" UNIQUE("candidate_id","position"),
	CONSTRAINT "music_candidate_track_position_check" CHECK ("position" between 0 and 9007199254740991)
);

CREATE TABLE "music_catalog_change" (
	"id" uuid DEFAULT uuidv7(),
	"owner_id" uuid,
	"version" bigint NOT NULL,
	"actor_auth_user_id" uuid,
	"operation" text NOT NULL,
	"recorded_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"withdrawn_at" timestamp(3) with time zone,
	CONSTRAINT "music_change_identity_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "music_change_version_key" UNIQUE("owner_id","version"),
	CONSTRAINT "music_change_version_check" CHECK ("version" between 1 and 9007199254740991),
	CONSTRAINT "music_change_operation_check" CHECK (length("operation") between 1 and 96)
);

CREATE TABLE "music_catalog_relation" (
	"id" uuid DEFAULT uuidv7(),
	"owner_id" uuid,
	"definition_revision_id" uuid NOT NULL,
	"semantic_id" uuid DEFAULT uuidv7() NOT NULL,
	"expected_head_version" bigint DEFAULT 0 NOT NULL,
	"state" text DEFAULT 'active' NOT NULL,
	"revision" bigint DEFAULT 1 NOT NULL,
	"spoiler" integer DEFAULT 0 NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "music_relation_owner_id_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "music_relation_head_version_check" CHECK ("expected_head_version" between 0 and 9007199254740990),
	CONSTRAINT "music_relation_spoiler_check" CHECK ("spoiler" between 0 and 2),
	CONSTRAINT "music_relation_state_check" CHECK ("state" in ('active', 'disputed', 'withdrawn', 'superseded')),
	CONSTRAINT "music_relation_revision_check" CHECK ("revision" between 1 and 9007199254740991)
);

CREATE TABLE "music_component_head" (
	"owner_id" uuid,
	"component" text,
	"component_key" text,
	"component_sequence" bigint NOT NULL,
	"history_id" uuid NOT NULL,
	CONSTRAINT "music_component_head_pkey" PRIMARY KEY("owner_id","component","component_key"),
	CONSTRAINT "music_component_head_values" CHECK (octet_length("component_key") between 1 and 1536 and "component_sequence" between 1 and 9007199254740991)
);

CREATE TABLE "music_component_revision" (
	"owner_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"component" text NOT NULL,
	"component_key" text NOT NULL,
	"component_sequence" bigint NOT NULL,
	"owner_revision" bigint NOT NULL,
	"operation" text NOT NULL,
	"value" jsonb NOT NULL,
	"recorded_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "music_component_revision_pkey" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "music_component_revision_sequence_key" UNIQUE("owner_id","component","component_key","component_sequence"),
	CONSTRAINT "music_component_revision_operation_check" CHECK ("operation" in ('INSERT', 'UPDATE', 'DELETE')),
	CONSTRAINT "music_component_revision_value_check" CHECK (jsonb_typeof("value") = 'object' and octet_length("component_key") between 1 and 1536 and "owner_revision" > 0 and "component_sequence" between 1 and 9007199254740991)
);

CREATE TABLE "music_component_source_baseline" (
	"source_record_id" uuid,
	"mapping_key" uuid,
	"correspondence_revision" bigint,
	"mapping_owner" text NOT NULL,
	"owner_id" uuid,
	"component" text,
	"component_key" text,
	"snapshot_id" uuid NOT NULL,
	"source_path" text NOT NULL,
	"source_history_id" uuid NOT NULL,
	"current_history_id" uuid NOT NULL,
	"absent" boolean NOT NULL,
	"proposal_id" uuid NOT NULL,
	"action" text NOT NULL,
	CONSTRAINT "music_component_source_baseline_pkey" PRIMARY KEY("source_record_id","mapping_key","correspondence_revision","owner_id","component","component_key"),
	CONSTRAINT "music_source_baseline_action_check" CHECK ("action" in ('apply','withdraw')),
	CONSTRAINT "music_source_baseline_owner_check" CHECK ("mapping_owner" in ('publishing', 'music', 'program', 'software', 'entity', 'grouping', 'reference', 'distribution'))
) PARTITION BY HASH ("source_record_id");
