CREATE TABLE "music_component_source_occurrence" (
	"source_record_id" uuid,
	"mapping_key" uuid,
	"correspondence_revision" bigint,
	"snapshot_id" uuid,
	"owner_id" uuid,
	"component" text,
	"component_key" text NOT NULL,
	"source_path" text,
	"history_id" uuid NOT NULL,
	"source_value" jsonb NOT NULL,
	CONSTRAINT "music_component_source_occurrence_pkey" PRIMARY KEY("source_record_id","mapping_key","correspondence_revision","snapshot_id","owner_id","component","source_path"),
	CONSTRAINT "music_component_source_key_check" CHECK (octet_length("source_path") between 1 and 512 and left("source_path", 1) = '/' and octet_length("component") between 1 and 96 and octet_length("component_key") between 1 and 1536),
	CONSTRAINT "music_component_source_value_object" CHECK (jsonb_typeof("source_value") = 'object' and octet_length("source_value"::text) <= 524288)
);

CREATE TABLE "music_credit_identifier" (
	"credit_id" uuid,
	"namespace" text,
	"value" text,
	CONSTRAINT "music_credit_identifier_pkey" PRIMARY KEY("credit_id","namespace","value"),
	CONSTRAINT "music_credit_identifier_size_check" CHECK (octet_length("namespace") between 1 and 96 and octet_length("value") between 1 and 512)
);

CREATE TABLE "music_disc_toc" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"disc_id" text,
	"free_db_id" text,
	"track_count" integer NOT NULL,
	"leadout_offset" bigint NOT NULL,
	CONSTRAINT "music_disc_toc_count_check" CHECK ("track_count" between 1 and 99 and "leadout_offset" between 0 and 9007199254740991)
);

CREATE TABLE "music_disc_toc_offset" (
	"toc_id" uuid,
	"position" integer,
	"offset" bigint NOT NULL,
	CONSTRAINT "music_disc_toc_offset_pkey" PRIMARY KEY("toc_id","position"),
	CONSTRAINT "music_disc_toc_offset_check" CHECK ("position" between 0 and 98 and "offset" between 0 and 9007199254740991)
);

CREATE TABLE "music_editorial" (
	"owner_id" uuid,
	"language" text,
	"revision" bigint NOT NULL,
	"state" text NOT NULL,
	"summary" text,
	"description" jsonb,
	"avatar_type" text,
	"avatar_asset_id" uuid,
	"avatar_emoji" text,
	"avatar_icon_prefix" text,
	"avatar_icon_name" text,
	"banner_asset_id" uuid,
	"cover_asset_id" uuid,
	"operator_auth_user_id" uuid NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "music_editorial_pkey" PRIMARY KEY("owner_id","language"),
	CONSTRAINT "music_editorial_revision_check" CHECK ("revision" between 1 and 9007199254740991),
	CONSTRAINT "music_editorial_language_check" CHECK (octet_length("language") between 1 and 255),
	CONSTRAINT "music_editorial_state_check" CHECK ("state" in ('active','withdrawn')),
	CONSTRAINT "music_editorial_summary_check" CHECK ("summary" is null or char_length("summary") <= 500),
	CONSTRAINT "music_editorial_description_check" CHECK ("description" is null or (jsonb_typeof("description")='object' and octet_length("description"::text) <= 1048576)),
	CONSTRAINT "music_editorial_avatar_check" CHECK (
		 ("avatar_type" is null and num_nonnulls("avatar_asset_id","avatar_emoji","avatar_icon_prefix","avatar_icon_name")=0)
		 or ("avatar_type"='image' and "avatar_asset_id" is not null and num_nonnulls("avatar_emoji","avatar_icon_prefix","avatar_icon_name")=0)
		 or ("avatar_type"='emoji' and char_length("avatar_emoji") between 1 and 64 and "avatar_emoji" is not null and num_nonnulls("avatar_asset_id","avatar_icon_prefix","avatar_icon_name")=0)
		 or ("avatar_type"='icon' and "avatar_icon_prefix" in ('fas','fab') and "avatar_icon_prefix" is not null and "avatar_icon_name" is not null and "avatar_icon_name" ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length("avatar_icon_name") <= 128 and num_nonnulls("avatar_asset_id","avatar_emoji")=0))
) PARTITION BY HASH ("owner_id");
