CREATE TABLE "music_fact" (
	"id" uuid DEFAULT uuidv7(),
	"owner_id" uuid,
	"definition_revision_id" uuid NOT NULL,
	"semantic_id" uuid DEFAULT uuidv7() NOT NULL,
	"expected_head_version" bigint DEFAULT 0 NOT NULL,
	"state" text DEFAULT 'active' NOT NULL,
	"purpose" text DEFAULT 'assertion' NOT NULL,
	"last_node_position" bigint DEFAULT -1 NOT NULL,
	"spoiler" integer DEFAULT 0 NOT NULL,
	"sealed_at" timestamp(3) with time zone,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "music_fact_identity_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "music_fact_spoiler_check" CHECK ("spoiler" between 0 and 2),
	CONSTRAINT "music_fact_head_version_check" CHECK ("expected_head_version" between 0 and 9007199254740990),
	CONSTRAINT "music_fact_state_check" CHECK ("state" in ('active', 'disputed', 'withdrawn', 'superseded')),
	CONSTRAINT "music_fact_purpose_check" CHECK ("purpose" in ('assertion','qualifier')),
	CONSTRAINT "music_fact_node_cursor_check" CHECK ("last_node_position" between -1 and 9007199254740991 and ("sealed_at" is null or "last_node_position" >= 0))
);

