	"source_path" text NOT NULL,
	"fact_id" uuid,
	"relation_id" uuid,
	"named_form_id" uuid,
	"identifier_id" uuid,
	"identifier_revision" bigint,
	"source_mapping_key" uuid,
	"source_correspondence_revision" bigint,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"withdrawn_at" timestamp(3) with time zone,
	CONSTRAINT "music_support_identity_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "music_support_source_correspondence_pair" CHECK (("source_mapping_key" is null) = ("source_correspondence_revision" is null)),
	CONSTRAINT "music_support_identifier_revision_check" CHECK (("identifier_id" is null) = ("identifier_revision" is null)),
	CONSTRAINT "music_support_target_check" CHECK (num_nonnulls("fact_id", "relation_id", "named_form_id", "identifier_id") = 1),
	CONSTRAINT "music_support_source_path_check" CHECK (length("source_path") > 0)
);

CREATE TABLE "music_fact_value_node" (
	"owner_id" uuid,
	"fact_id" uuid,
	"position" bigint,
	"rule_position" integer DEFAULT 0 NOT NULL,
	"parent_position" bigint,
	"parent_kind" text,
	"member_key" text,
	"kind" text NOT NULL,
	"text_value" text,
	"number_value" numeric,
	"boolean_value" boolean,
	CONSTRAINT "music_fact_node_position_key" PRIMARY KEY("owner_id","fact_id","position"),
	CONSTRAINT "music_fact_node_kind_key" UNIQUE("owner_id","fact_id","position","kind"),
	CONSTRAINT "music_fact_node_member_key" UNIQUE("owner_id","fact_id","parent_position","member_key"),
	CONSTRAINT "music_fact_node_rule_check" CHECK ("rule_position" between 0 and 127),
	CONSTRAINT "music_fact_node_kind_check" CHECK ("kind" in ('null', 'string', 'number', 'boolean', 'object', 'array')),
	CONSTRAINT "music_fact_node_position_check" CHECK ("position" between 0 and 9007199254740991 and ("parent_position" is null or "parent_position" >= 0 and "parent_position" < "position")),
	CONSTRAINT "music_fact_node_parent_check" CHECK (("position" = 0 and "parent_position" is null and "parent_kind" is null and "member_key" is null) or ("position" > 0 and "parent_position" is not null and "parent_kind" is not null and (("parent_kind" = 'object' and "member_key" is not null) or ("parent_kind" = 'array' and "member_key" is null)))),
	CONSTRAINT "music_fact_node_number_check" CHECK ("number_value" is null or "number_value"::text not in ('NaN', 'Infinity', '-Infinity')),
	CONSTRAINT "music_fact_node_value_check" CHECK (("kind" = 'string' and "text_value" is not null and "number_value" is null and "boolean_value" is null) or ("kind" = 'number' and "number_value" is not null and "text_value" is null and "boolean_value" is null) or ("kind" = 'boolean' and "boolean_value" is not null and "text_value" is null and "number_value" is null) or ("kind" in ('null', 'object', 'array') and "text_value" is null and "number_value" is null and "boolean_value" is null))
);

CREATE TABLE "music_identifier_claim" (
	"owner_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"revision" bigint DEFAULT 1 NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_by_auth_user_id" uuid,
	"namespace" text NOT NULL,
	"value" text NOT NULL,
	"normalized_value" text NOT NULL,
	"normalization_policy" text DEFAULT 'exact.1' NOT NULL,
	"validation_status" text DEFAULT 'unvalidated' NOT NULL,
	"issuer_entity_id" uuid,
	"state" text DEFAULT 'active' NOT NULL,
	CONSTRAINT "music_identifier_identity_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "music_identifier_namespace_check" CHECK ("namespace" ~ '^[a-z][a-z0-9_.:-]{0,127}$'),
	CONSTRAINT "music_identifier_value_check" CHECK (octet_length("value") between 1 and 512 and octet_length("normalized_value") between 1 and 512 and octet_length("normalization_policy") between 1 and 96),
	CONSTRAINT "music_identifier_state_check" CHECK ("state" in ('active', 'disputed', 'withdrawn', 'superseded')),
	CONSTRAINT "music_identifier_validation_check" CHECK ("validation_status" in ('unvalidated', 'valid')),
	CONSTRAINT "music_identifier_revision_check" CHECK ("revision" between 1 and 9007199254740991)
);

CREATE TABLE "music_identifier_claim_revision" (
	"owner_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"revision" bigint DEFAULT 1,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_by_auth_user_id" uuid,
	"namespace" text NOT NULL,
	"value" text NOT NULL,
	"normalized_value" text NOT NULL,
	"normalization_policy" text DEFAULT 'exact.1' NOT NULL,
	"validation_status" text DEFAULT 'unvalidated' NOT NULL,
	"issuer_entity_id" uuid,
	"state" text DEFAULT 'active' NOT NULL,
	CONSTRAINT "music_identifier_revision_key" PRIMARY KEY("owner_id","id","revision")
);

CREATE TABLE "music_identity" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"shape" text NOT NULL,
	"status" text DEFAULT 'draft' NOT NULL,
	"visibility" text DEFAULT 'private' NOT NULL,
	"content_rating" text DEFAULT 'general' NOT NULL,
	"moderation_status" text DEFAULT 'approved' NOT NULL,
	"created_by_auth_user_id" uuid,
	"post_targeting_locked" boolean DEFAULT false NOT NULL,
	"revision" bigint DEFAULT 1 NOT NULL,
	"routing_generation" integer DEFAULT 1 NOT NULL,
	"deleted_at" timestamp(3) with time zone,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "music_identity_shape_key" UNIQUE("id","shape"),
	CONSTRAINT "music_identity_shape_check" CHECK ("shape" ~ '^[a-z][a-z0-9_.-]{0,95}$'),
	CONSTRAINT "music_identity_status_check" CHECK ("status" in ('draft', 'published', 'archived')),
	CONSTRAINT "music_identity_visibility_check" CHECK ("visibility" in ('public', 'unlisted', 'private')),
	CONSTRAINT "music_identity_rating_check" CHECK ("content_rating" in ('general', 'r15', 'r18', 'r18g')),
	CONSTRAINT "music_identity_moderation_check" CHECK ("moderation_status" in ('approved', 'pending', 'removed')),
	CONSTRAINT "music_identity_revision_check" CHECK ("revision" between 1 and 9007199254740991 and "routing_generation" > 0)
);

CREATE TABLE "music_medium" (
	"release_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"position" bigint NOT NULL,
	"name" text,
	"format_revision_id" uuid,
	"source_track_count" bigint,
	CONSTRAINT "music_medium_pkey" PRIMARY KEY("release_id","id"),
	CONSTRAINT "music_medium_position_key" UNIQUE("release_id","position"),
	CONSTRAINT "music_medium_position_check" CHECK ("position" between 0 and 9007199254740991),
	CONSTRAINT "music_medium_track_count_check" CHECK ("source_track_count" is null or "source_track_count" between 0 and 9007199254740991)
);

CREATE TABLE "music_medium_attribute" (
	"release_id" uuid,
	"medium_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"definition_revision_id" uuid NOT NULL,
	"value_revision_id" uuid,
	"text_value" text,
	CONSTRAINT "music_medium_attribute_pkey" PRIMARY KEY("release_id","medium_id","id"),
	CONSTRAINT "music_medium_attribute_value_check" CHECK (("value_revision_id" is not null) <> ("text_value" is not null))
);

CREATE TABLE "music_medium_attribute_allowed_format" (
	"definition_revision_id" uuid,
	"format_revision_id" uuid,
	CONSTRAINT "music_medium_attribute_allowed_format_pkey" PRIMARY KEY("definition_revision_id","format_revision_id")
);

CREATE TABLE "music_medium_attribute_allowed_value_format" (
	"definition_revision_id" uuid,
	"value_revision_id" uuid,
	"format_revision_id" uuid,
	CONSTRAINT "music_medium_attribute_allowed_value_format_pkey" PRIMARY KEY("definition_revision_id","value_revision_id","format_revision_id")
);

CREATE TABLE "music_medium_attribute_policy" (
	"definition_revision_id" uuid PRIMARY KEY,
	"value_mode" text NOT NULL,
	CONSTRAINT "music_medium_attribute_policy_mode_check" CHECK ("value_mode" in ('text', 'vocabulary'))
);

CREATE TABLE "music_medium_identifier" (
	"release_id" uuid,
	"medium_id" uuid,
	"namespace" text,
	"value" text,
	CONSTRAINT "music_medium_identifier_pkey" PRIMARY KEY("release_id","medium_id","namespace","value"),
	CONSTRAINT "music_medium_identifier_size_check" CHECK (octet_length("namespace") between 1 and 96 and octet_length("value") between 1 and 512)
);

CREATE TABLE "music_medium_presentation" (
	"release_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"release_presentation_id" uuid NOT NULL,
	"medium_id" uuid NOT NULL,
