	CONSTRAINT "music_medium_presentation_pkey" PRIMARY KEY("release_id","id"),
	CONSTRAINT "music_medium_presentation_medium_key" UNIQUE("release_id","id","medium_id")
);

CREATE TABLE "music_medium_toc" (
	"release_id" uuid,
	"medium_id" uuid,
	"toc_id" uuid,
	CONSTRAINT "music_medium_toc_pkey" PRIMARY KEY("release_id","medium_id","toc_id")
);

CREATE TABLE "music_name_authority" (
	"owner_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"revision" bigint DEFAULT 1 NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_by_auth_user_id" uuid,
	"name_id" uuid NOT NULL,
	"name_revision" bigint NOT NULL,
	"claim" text NOT NULL,
	"review_state" text NOT NULL,
	"authorizer_entity_id" uuid,
	"role" text NOT NULL,
	"territory" text,
	"channel" text,
	"context" text,
	"valid_from" timestamp(3) with time zone,
	"valid_until" timestamp(3) with time zone,
	"source_record_id" uuid NOT NULL,
	"snapshot_id" uuid NOT NULL,
	"source_path" text NOT NULL,
	"review_source_record_id" uuid,
	"review_snapshot_id" uuid,
	"review_source_path" text,
	"state" text NOT NULL,
	CONSTRAINT "music_name_authority_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "music_name_authority_revision_check" CHECK ("revision" between 1 and 9007199254740991),
	CONSTRAINT "music_name_authority_claim_check" CHECK ("claim" in ('official', 'unofficial', 'unknown')),
	CONSTRAINT "music_name_authority_review_check" CHECK ("review_state" in ('source_claim', 'pending', 'verified', 'rejected')),
	CONSTRAINT "music_name_authority_state_check" CHECK ("state" in ('active', 'withdrawn')),
	CONSTRAINT "music_name_authority_proof_check" CHECK (("review_state" <> 'verified' or ("authorizer_entity_id" is not null and "review_snapshot_id" is not null)) and num_nonnulls("review_source_record_id","review_snapshot_id","review_source_path") in (0,3)),
	CONSTRAINT "music_name_authority_time_check" CHECK ("valid_from" is null or "valid_until" is null or "valid_until" > "valid_from"),
	CONSTRAINT "music_name_authority_scope_check" CHECK (octet_length("role") between 1 and 96 and octet_length("source_path") between 1 and 4096 and ("review_source_path" is null or octet_length("review_source_path") between 1 and 4096) and ("territory" is null or octet_length("territory") between 1 and 96) and ("channel" is null or octet_length("channel") between 1 and 96) and ("context" is null or octet_length("context") between 1 and 512))
);

CREATE TABLE "music_name_authority_revision" (
	"owner_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"revision" bigint DEFAULT 1,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_by_auth_user_id" uuid,
	"name_id" uuid NOT NULL,
	"name_revision" bigint NOT NULL,
	"claim" text NOT NULL,
	"review_state" text NOT NULL,
	"authorizer_entity_id" uuid,
	"role" text NOT NULL,
	"territory" text,
	"channel" text,
	"context" text,
	"valid_from" timestamp(3) with time zone,
	"valid_until" timestamp(3) with time zone,
	"source_record_id" uuid NOT NULL,
	"snapshot_id" uuid NOT NULL,
	"source_path" text NOT NULL,
	"review_source_record_id" uuid,
	"review_snapshot_id" uuid,
	"review_source_path" text,
	"state" text NOT NULL,
	CONSTRAINT "music_name_authority_revision_key" PRIMARY KEY("owner_id","id","revision")
);

CREATE TABLE "music_name_source_binding" (
	"owner_id" uuid,
	"source_record_id" uuid,
	"mapping_key" uuid,
	"correspondence_revision" bigint,
	"namespace" text,
	"local_key" text,
	"name_id" uuid NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "music_name_source_binding_key" PRIMARY KEY("source_record_id","mapping_key","correspondence_revision","owner_id","namespace","local_key"),
	CONSTRAINT "music_name_source_binding_owner_key" UNIQUE("owner_id","source_record_id","mapping_key","correspondence_revision","namespace","local_key","name_id"),
	CONSTRAINT "music_name_source_binding_value_check" CHECK (octet_length("namespace") between 1 and 96 and octet_length("local_key") between 1 and 512)
);

CREATE TABLE "music_name_source_occurrence" (
	"owner_id" uuid,
	"source_record_id" uuid,
	"mapping_key" uuid,
	"correspondence_revision" bigint,
	"namespace" text,
	"local_key" text,
	"name_id" uuid NOT NULL,
	"name_revision" bigint NOT NULL,
	"snapshot_id" uuid,
	"source_path" text NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "music_name_source_occurrence_key" PRIMARY KEY("source_record_id","mapping_key","correspondence_revision","owner_id","namespace","local_key","snapshot_id"),
	CONSTRAINT "music_name_source_occurrence_path_check" CHECK (octet_length("source_path") between 1 and 4096)
);

CREATE TABLE "music_named_form" (
	"owner_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"revision" bigint DEFAULT 1 NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_by_auth_user_id" uuid,
	"language_tag" text,
	"private_use_namespace" text,
	"language_policy" text,
	"kind" text NOT NULL,
	"value" text NOT NULL,
	"sort_name" text,
	"origin" text DEFAULT 'unknown' NOT NULL,
	"translation_method" text DEFAULT 'unknown' NOT NULL,
	"primary_for_language" boolean,
	"scope_owner_id" uuid,
	"territory" text,
	"context" text,
	"derivation_name_id" uuid,
	"derivation_revision" bigint,
	"begin" jsonb,
	"end" jsonb,
	"ended" boolean,
	"spoiler" integer DEFAULT 0 NOT NULL,
	"state" text DEFAULT 'active' NOT NULL,
	CONSTRAINT "music_named_form_identity_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "music_named_form_state_check" CHECK ("state" in ('active', 'disputed', 'withdrawn', 'superseded')),
	CONSTRAINT "music_named_form_revision_check" CHECK ("revision" between 1 and 9007199254740991),
	CONSTRAINT "music_named_form_kind_check" CHECK (octet_length("kind") between 1 and 96),
	CONSTRAINT "music_named_form_value_check" CHECK (octet_length("value") between 1 and 131072 and ("sort_name" is null or octet_length("sort_name") between 1 and 131072)),
	CONSTRAINT "music_named_form_language_check" CHECK (("language_tag" is null and "language_policy" is null and "private_use_namespace" is null) or ("language_tag" is not null and octet_length("language_tag") between 1 and 255 and "language_policy" is not null and ("private_use_namespace" is null or octet_length("private_use_namespace") between 1 and 512))),
	CONSTRAINT "music_named_form_origin_check" CHECK ("origin" in ('original', 'translation', 'transliteration', 'abbreviation', 'variant', 'unknown')),
	CONSTRAINT "music_named_form_method_check" CHECK ("translation_method" in ('human', 'machine', 'mixed', 'unknown', 'not_applicable')),
	CONSTRAINT "music_named_form_derivation_check" CHECK (num_nonnulls("derivation_name_id","derivation_revision") in (0,2)),
	CONSTRAINT "music_named_form_spoiler_check" CHECK ("spoiler" between 0 and 2),
	CONSTRAINT "music_named_form_scope_check" CHECK (("territory" is null or octet_length("territory") between 1 and 96) and ("context" is null or octet_length("context") between 1 and 512))
);

CREATE TABLE "music_named_form_revision" (
	"owner_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"revision" bigint DEFAULT 1,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_by_auth_user_id" uuid,
	"language_tag" text,
	"private_use_namespace" text,
	"language_policy" text,
	"kind" text NOT NULL,
	"value" text NOT NULL,
	"sort_name" text,
	"origin" text DEFAULT 'unknown' NOT NULL,
	"translation_method" text DEFAULT 'unknown' NOT NULL,
	"primary_for_language" boolean,
	"scope_owner_id" uuid,
	"territory" text,
	"context" text,
	"derivation_name_id" uuid,
	"derivation_revision" bigint,
	"begin" jsonb,
	"end" jsonb,
	"ended" boolean,
	"spoiler" integer DEFAULT 0 NOT NULL,
	"state" text DEFAULT 'active' NOT NULL,
	CONSTRAINT "music_named_form_revision_key" PRIMARY KEY("owner_id","id","revision")
);

CREATE TABLE "music_recording" (
	"id" uuid PRIMARY KEY,
	"identity_shape" text DEFAULT 'recording' NOT NULL,
	"artist_credit_id" uuid,
	"length_milliseconds" bigint,
	"video" boolean,
	CONSTRAINT "music_recording_shape_check" CHECK ("identity_shape" = 'recording'),
	CONSTRAINT "music_recording_length_check" CHECK ("length_milliseconds" is null or "length_milliseconds" between 0 and 9007199254740991)
);

CREATE TABLE "music_relation_participant" (
	"id" uuid DEFAULT uuidv7(),
	"owner_id" uuid,
	"relation_id" uuid NOT NULL,
	"role_revision_id" uuid NOT NULL,
	"position" bigint NOT NULL,
	"credited_as" text,
	"publishing_id" uuid,
	"music_id" uuid,
	"program_id" uuid,
	"software_id" uuid,
	"entity_id" uuid,
	"grouping_id" uuid,
	"reference_id" uuid,
	"distribution_id" uuid,
	CONSTRAINT "music_participant_identity_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "music_participant_position_key" UNIQUE("owner_id","relation_id","position"),
	CONSTRAINT "music_participant_target_check" CHECK (num_nonnulls("publishing_id", "music_id", "program_id", "software_id", "entity_id", "grouping_id", "reference_id", "distribution_id") = 1),
	CONSTRAINT "music_participant_position_check" CHECK ("position" between 0 and 9007199254740991)
);

CREATE TABLE "music_relation_scope" (
	"id" uuid DEFAULT uuidv7(),
	"owner_id" uuid,
	"relation_id" uuid NOT NULL,
	"definition_revision_id" uuid NOT NULL,
	"value_fact_id" uuid NOT NULL,
	CONSTRAINT "music_relation_scope_identity_key" PRIMARY KEY("owner_id","id")
);

CREATE TABLE "music_release" (
	"id" uuid PRIMARY KEY,
	"identity_shape" text DEFAULT 'release' NOT NULL,
	"release_group_id" uuid,
	"artist_credit_id" uuid,
	"status_revision_id" uuid,
	"packaging_revision_id" uuid,
	"language_tag" text,
	"script_code" text,
	"barcode" text,
	CONSTRAINT "music_release_shape_check" CHECK ("identity_shape" = 'release'),
	CONSTRAINT "music_release_language_check" CHECK ("language_tag" is null or octet_length("language_tag") between 1 and 255),
	CONSTRAINT "music_release_script_check" CHECK ("script_code" is null or "script_code" ~ '^[A-Z][a-z]{3}$')
);

CREATE TABLE "music_release_candidate" (
	"id" uuid PRIMARY KEY,
	"identity_shape" text DEFAULT 'release_candidate' NOT NULL,
	"credited_artist_text" text,
	"barcode" text,
	"comment" text,
	CONSTRAINT "music_release_candidate_shape_check" CHECK ("identity_shape" = 'release_candidate')
);

CREATE TABLE "music_release_event" (
	"release_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"area_id" uuid,
	"date_year" integer,
	"date_month" smallint,
	"date_day" smallint,
	"date_text" text,
	CONSTRAINT "music_release_event_pkey" PRIMARY KEY("release_id","id"),
	CONSTRAINT "music_release_event_date_check" CHECK (
		("date_month" is null or "date_month" between 1 and 12)
		and ("date_day" is null or "date_day" between 1 and 31)
		and ("date_month" is null or "date_day" is null or "date_day" <= case
			when "date_month" in (4, 6, 9, 11) then 30
			when "date_month" = 2 then case when "date_year" is null
				or mod("date_year", 400) = 0 or (mod("date_year", 4) = 0 and mod("date_year", 100) <> 0) then 29 else 28 end
			else 31 end))
);

CREATE TABLE "music_release_group" (
	"id" uuid PRIMARY KEY,
	"identity_shape" text DEFAULT 'release_group' NOT NULL,
	"artist_credit_id" uuid,
	"primary_type_revision_id" uuid,
	CONSTRAINT "music_release_group_shape_check" CHECK ("identity_shape" = 'release_group')
);

CREATE TABLE "music_release_group_secondary_type" (
	"release_group_id" uuid,
	"type_revision_id" uuid,
	CONSTRAINT "music_release_group_secondary_type_pkey" PRIMARY KEY("release_group_id","type_revision_id")
);

CREATE TABLE "music_release_label" (
	"release_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"label_id" uuid,
	"catalog_number" text,
	CONSTRAINT "music_release_label_pkey" PRIMARY KEY("release_id","id")
);

CREATE TABLE "music_release_presentation" (
	"release_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"name" text,
	"artist_credit_id" uuid,
	"language_tag" text,
	"script_code" text,
	"type_revision_id" uuid,
	"comment" text,
	CONSTRAINT "music_release_presentation_pkey" PRIMARY KEY("release_id","id"),
	CONSTRAINT "music_release_presentation_language_check" CHECK ("language_tag" is null or octet_length("language_tag") between 1 and 255),
	CONSTRAINT "music_release_presentation_script_check" CHECK ("script_code" is null or "script_code" ~ '^[A-Z][a-z]{3}$')
);

CREATE TABLE "music_release_source_job" (
	"source_record_id" uuid,
	"id" uuid DEFAULT gen_random_uuid(),
	"proposal_id" uuid,
	"snapshot_id" uuid NOT NULL,
	"music_id" uuid,
	"action" text NOT NULL,
	"reason" text NOT NULL,
	"authority" jsonb NOT NULL,
	"authority_auth_user_id" uuid GENERATED ALWAYS AS ((authority->'principal'->>'authUserId')::uuid) STORED NOT NULL,
	"authority_acting_entity_id" uuid GENERATED ALWAYS AS ((authority->>'actingEntityId')::uuid) STORED NOT NULL,
	"authority_grant_id" uuid GENERATED ALWAYS AS ((authority->'grant'->>'id')::uuid) STORED,
	"authority_service_principal_id" uuid GENERATED ALWAYS AS ((authority->'principal'->>'servicePrincipalId')::uuid) STORED,
	"prepared_dependency_count" integer DEFAULT 0 NOT NULL,
	"preparation_complete" boolean DEFAULT false NOT NULL,
	"next_dependency_position" integer DEFAULT 0 NOT NULL,
	"generation" bigint DEFAULT 1 NOT NULL,
	"state" text DEFAULT 'queued' NOT NULL,
	"preparation" jsonb,
	"outcome_code" text,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "music_release_source_job_pkey" PRIMARY KEY("source_record_id","id"),
