CREATE TABLE "music_track_identifier" (
	"release_id" uuid,
	"track_id" uuid,
	"namespace" text,
	"value" text,
	CONSTRAINT "music_track_identifier_pkey" PRIMARY KEY("release_id","track_id","namespace","value"),
	CONSTRAINT "music_track_identifier_size_check" CHECK (octet_length("namespace") between 1 and 96 and octet_length("value") between 1 and 512)
);

CREATE TABLE "music_track_occurrence" (
	"release_id" uuid,
	"medium_id" uuid NOT NULL,
	"id" uuid DEFAULT uuidv7(),
	"position" bigint NOT NULL,
	"number" text NOT NULL,
	"name" text,
	"recording_id" uuid,
	"artist_credit_id" uuid,
	"length_milliseconds" bigint,
	"is_data_track" boolean,
	CONSTRAINT "music_track_occurrence_pkey" PRIMARY KEY("release_id","id"),
	CONSTRAINT "music_track_occurrence_position_key" UNIQUE("release_id","medium_id","position"),
	CONSTRAINT "music_track_occurrence_medium_key" UNIQUE("release_id","id","medium_id"),
	CONSTRAINT "music_track_position_check" CHECK ("position" between 0 and 9007199254740991),
	CONSTRAINT "music_track_length_check" CHECK ("length_milliseconds" is null or "length_milliseconds" between 0 and 9007199254740991)
);

CREATE TABLE "music_track_presentation" (
	"release_id" uuid,
	"medium_presentation_id" uuid,
	"medium_id" uuid NOT NULL,
	"track_id" uuid,
	"alternative_track_id" uuid NOT NULL,
	CONSTRAINT "music_track_presentation_pkey" PRIMARY KEY("release_id","medium_presentation_id","track_id")
);

CREATE TABLE "music_work" (
	"id" uuid PRIMARY KEY,
	"identity_shape" text DEFAULT 'work' NOT NULL,
	"type_revision_id" uuid,
	CONSTRAINT "music_work_shape_check" CHECK ("identity_shape" = 'work')
);

CREATE TABLE "music_work_language" (
	"work_id" uuid,
	"language_tag" text,
	CONSTRAINT "music_work_language_pkey" PRIMARY KEY("work_id","language_tag"),
	CONSTRAINT "music_work_language_size_check" CHECK (octet_length("language_tag") between 1 and 255)
);

CREATE TABLE "notification" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"recipient_auth_user_id" uuid NOT NULL,
	"actor_profile_id" uuid,
	"kind" "notification_kind" NOT NULL,
	"subject_unit_id" uuid,
	"payload" jsonb,
	"dedupe_key" text,
	"in_app_visible" boolean DEFAULT true NOT NULL,
	"read_at" timestamp(3) with time zone,
	"email_status" "notification_email_status" DEFAULT 'not_requested'::"notification_email_status" NOT NULL,
	"emailed_at" timestamp(3) with time zone,
	"email_error" text,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"subject_unit_publishing_id" uuid,
	"subject_unit_music_id" uuid,
	"subject_unit_program_id" uuid,
	"subject_unit_software_id" uuid,
	"subject_unit_entity_id" uuid,
	"subject_unit_grouping_id" uuid,
	"subject_unit_reference_id" uuid,
	"subject_unit_distribution_id" uuid,
	"subject_unit_video_id" uuid,
	"subject_unit_audio_id" uuid,
	"subject_unit_post_id" uuid,
	"subject_unit_poll_id" uuid,
	"subject_unit_zone_id" uuid,
	"subject_unit_realm_id" uuid,
	"subject_unit_realm_rule_id" uuid,
	"subject_unit_custom_theme_id" uuid,
	"subject_unit_collection_id" uuid,
	"subject_unit_tag_id" uuid,
	"subject_unit_tag_path_id" uuid,
	"subject_unit_label_id" uuid,
	CONSTRAINT "notification_subject_unit_target_check" CHECK (num_nonnulls("subject_unit_publishing_id", "subject_unit_music_id", "subject_unit_program_id", "subject_unit_software_id", "subject_unit_entity_id", "subject_unit_grouping_id", "subject_unit_reference_id", "subject_unit_distribution_id", "subject_unit_video_id", "subject_unit_audio_id", "subject_unit_post_id", "subject_unit_poll_id", "subject_unit_zone_id", "subject_unit_realm_id", "subject_unit_realm_rule_id", "subject_unit_custom_theme_id", "subject_unit_collection_id", "subject_unit_tag_id", "subject_unit_tag_path_id", "subject_unit_label_id") between 0 and 1),
	CONSTRAINT "notification_subject_unit_id_check" CHECK ("subject_unit_id" is not distinct from coalesce("subject_unit_publishing_id", "subject_unit_music_id", "subject_unit_program_id", "subject_unit_software_id", "subject_unit_entity_id", "subject_unit_grouping_id", "subject_unit_reference_id", "subject_unit_distribution_id", "subject_unit_video_id", "subject_unit_audio_id", "subject_unit_post_id", "subject_unit_poll_id", "subject_unit_zone_id", "subject_unit_realm_id", "subject_unit_realm_rule_id", "subject_unit_custom_theme_id", "subject_unit_collection_id", "subject_unit_tag_id", "subject_unit_tag_path_id", "subject_unit_label_id")),
	CONSTRAINT "notification_read_at_check" CHECK ("read_at" is null or "read_at" >= "created_at"),
	CONSTRAINT "notification_email_state_check" CHECK (("email_status" = 'sent'::notification_email_status and "emailed_at" is not null and "email_error" is null) or ("email_status" = 'failed'::notification_email_status and "emailed_at" is null and nullif(btrim("email_error"), '') is not null) or ("email_status" in ('not_requested', 'pending') and "emailed_at" is null and "email_error" is null)),
	CONSTRAINT "notification_payload_json_object_check" CHECK ("payload" is null or jsonb_typeof("payload") = 'object')
);

CREATE TABLE "notification_preference" (
	"auth_user_id" uuid,
	"kind" "notification_kind",
	"in_app" boolean DEFAULT true NOT NULL,
	"email" boolean DEFAULT true NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "notification_preference_pkey" PRIMARY KEY("auth_user_id","kind")
);

CREATE TABLE "notification_recipient_stat" (
	"auth_user_id" uuid PRIMARY KEY,
	"unread_count" bigint DEFAULT 0 NOT NULL,
	"read_through_created_at" timestamp(3) with time zone,
	"read_through_id" uuid,
	"read_through_at" timestamp(3) with time zone,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "notification_recipient_stat_count_check" CHECK ("unread_count" >= 0),
	CONSTRAINT "notification_recipient_stat_read_through_shape_check" CHECK ((
				"read_through_created_at" is null
				and "read_through_id" is null
				and "read_through_at" is null
			) or (
				"read_through_created_at" is not null
				and "read_through_id" is not null
				and "read_through_at" is not null
			)),
	CONSTRAINT "notification_recipient_stat_read_through_time_check" CHECK ("read_through_at" is null or "read_through_at" >= "read_through_created_at")
);

CREATE TABLE "operational_application_receipt" (
	"consumer_key" text,
	"routing_bucket" integer,
	"operation_id" uuid,
	"task_operation_id" uuid,
	"request_fingerprint" text NOT NULL,
	"outcome" text NOT NULL,
	"detail" text NOT NULL,
	"completed_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "operational_application_receipt_pkey" PRIMARY KEY("routing_bucket","consumer_key","operation_id"),
	CONSTRAINT "operational_receipt_bucket_check" CHECK ("routing_bucket" between 0 and 1023),
	CONSTRAINT "operational_receipt_fields_check" CHECK ("request_fingerprint" ~ '^[a-f0-9]{64}$' and octet_length("consumer_key") between 1 and 128 and octet_length("detail") <= 512 and "outcome" in ('succeeded','cancelled','failed','superseded') and ("task_operation_id" is null or "task_operation_id" = "operation_id"))
) PARTITION BY RANGE ("routing_bucket");
