CREATE TABLE "operational_capacity" (
	"routing_bucket" integer,
	"lane" text,
	"maximum_rows" bigint NOT NULL,
	"maximum_bytes" bigint NOT NULL,
	"reserved_rows" bigint DEFAULT 0 NOT NULL,
	"reserved_bytes" bigint DEFAULT 0 NOT NULL,
	CONSTRAINT "operational_capacity_pkey" PRIMARY KEY("routing_bucket","lane"),
	CONSTRAINT "operational_capacity_bucket_check" CHECK ("routing_bucket" between 0 and 1023),
	CONSTRAINT "operational_capacity_lane_check" CHECK ("lane" in ('event-outbox', 'task-outbox', 'task-intent', 'receipt')),
	CONSTRAINT "operational_capacity_bounds_check" CHECK ("maximum_rows" between 1 and 1000000000 and "maximum_bytes" between 1 and 1000000000000000 and "reserved_rows" between 0 and "maximum_rows" and "reserved_bytes" between 0 and "maximum_bytes")
);

CREATE TABLE "operational_consumer_checkpoint" (
	"routing_bucket" integer,
	"message_class" text,
	"consumer_key" text,
	"consumer_slot" integer NOT NULL,
	"routing_epoch" bigint NOT NULL,
	"stream_created_at" text NOT NULL,
	"next_sequence" bigint NOT NULL,
	"state" text DEFAULT 'active' NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "operational_consumer_checkpoint_pkey" PRIMARY KEY("routing_bucket","message_class","consumer_key"),
	CONSTRAINT "operational_checkpoint_slot_key" UNIQUE("routing_bucket","message_class","consumer_slot"),
	CONSTRAINT "operational_checkpoint_bounds_check" CHECK ("consumer_slot" between 0 and 63 and "routing_bucket" between 0 and 1023 and "message_class" in ('event','task') and "routing_epoch" between 1 and 9007199254740991 and "next_sequence" between 1 and 9007199254740991 and "state" in ('active','replay_required') and octet_length("consumer_key") between 1 and 64 and octet_length("stream_created_at") between 1 and 64)
);

CREATE TABLE "operational_outbox" (
	"routing_bucket" integer,
	"message_id" uuid,
	"message_class" text NOT NULL,
	"kind" text NOT NULL,
	"routing_epoch" bigint NOT NULL,
	"subject" text NOT NULL,
	"aggregate_key" text NOT NULL,
	"occurred_at" timestamp with time zone NOT NULL,
	"payload" jsonb NOT NULL,
	"serialized_envelope" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "operational_outbox_pkey" PRIMARY KEY("routing_bucket","message_id"),
	CONSTRAINT "operational_outbox_bucket_check" CHECK ("routing_bucket" between 0 and 1023),
	CONSTRAINT "operational_outbox_route_check" CHECK (("routing_bucket" = mod(get_byte(sha256(convert_to(("payload"->'aggregate'->>'owner') || ':' || "aggregate_key", 'UTF8')), 0) * 256 + get_byte(sha256(convert_to(("payload"->'aggregate'->>'owner') || ':' || "aggregate_key", 'UTF8')), 1), 1024)) is true),
	CONSTRAINT "operational_outbox_fields_check" CHECK ("message_class" in ('event','task') and octet_length("kind") between 1 and 128 and "kind" ~ '^[a-z][a-z0-9_-]*(\.[a-z][a-z0-9_-]*)*$' and "routing_epoch" between 1 and 9007199254740991 and octet_length("subject") between 1 and 256 and octet_length("aggregate_key") between 1 and 1024 and "subject" = 'rezics.' || case when "message_class" = 'event' then 'events' else 'tasks' end || '.e' || "routing_epoch"::text || '.b' || "routing_bucket"::text || '.' || "kind"),
	CONSTRAINT "operational_outbox_payload_check" CHECK ((jsonb_typeof("payload") = 'object' and octet_length("serialized_envelope") <= 65536 and "serialized_envelope"::jsonb = "payload" and ("payload"->>'version') = '1' and ("payload"->>'messageId') = "message_id"::text and ("payload"->>'class') = "message_class" and ("payload"->>'kind') = "kind" and ("payload"->>'routingBucket') = "routing_bucket"::text and ("payload"->>'routingEpoch') = "routing_epoch"::text and ("payload"->'aggregate'->>'key') = "aggregate_key" and ("payload"->>'occurredAt')::timestamptz = "occurred_at") is true)
) PARTITION BY RANGE ("routing_bucket");
CREATE TABLE "operational_outbox_p00" PARTITION OF "operational_outbox" FOR VALUES FROM (0) TO (16);
CREATE TABLE "operational_outbox_p01" PARTITION OF "operational_outbox" FOR VALUES FROM (16) TO (32);
