CREATE TABLE "operational_task_intent" (
	"routing_bucket" integer,
	"operation_id" uuid,
	"consumer_key" text NOT NULL,
	"request_fingerprint" text NOT NULL,
	"origin_message_id" uuid NOT NULL,
	"state" text DEFAULT 'pending' NOT NULL,
	"fencing_generation" bigint DEFAULT 0 NOT NULL,
	"attempt_count" integer DEFAULT 0 NOT NULL,
	"maximum_attempts" integer NOT NULL,
	"deadline" timestamp with time zone NOT NULL,
	"available_at" timestamp with time zone DEFAULT now() NOT NULL,
	"lease_expires_at" timestamp with time zone,
	"last_error" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "operational_task_intent_pkey" PRIMARY KEY("routing_bucket","operation_id"),
	CONSTRAINT "operational_task_bucket_check" CHECK ("routing_bucket" between 0 and 1023),
	CONSTRAINT "operational_task_request_check" CHECK ("request_fingerprint" ~ '^[a-f0-9]{64}$' and octet_length("consumer_key") between 1 and 128 and "maximum_attempts" between 1 and 32 and "attempt_count" between 0 and "maximum_attempts" and "fencing_generation" >= 0 and "deadline" > "created_at" and "deadline" <= "created_at" + interval '7 days' and ("last_error" is null or octet_length("last_error") <= 512)),
	CONSTRAINT "operational_task_state_check" CHECK ("state" in ('pending','running','succeeded','cancelled','failed','superseded') and (("state" = 'running' and "lease_expires_at" is not null and "fencing_generation" > 0 and "attempt_count" > 0) or ("state" <> 'running' and "lease_expires_at" is null)))
) PARTITION BY RANGE ("routing_bucket");
