CREATE TABLE "organization_membership" (
	"organization_entity_id" uuid,
	"member_auth_user_id" uuid,
	"member_entity_id" uuid NOT NULL,
	"accepted_invitation_id" uuid NOT NULL,
	"revision" bigint DEFAULT 1 NOT NULL,
	"joined_at" timestamp(3) with time zone NOT NULL,
	"removed_at" timestamp(3) with time zone,
	"removed_by_auth_user_id" uuid,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "organization_membership_pkey" PRIMARY KEY("organization_entity_id","member_auth_user_id"),
	CONSTRAINT "organization_membership_revision_check" CHECK ("revision" between 1 and 9007199254740991),
	CONSTRAINT "organization_membership_removal_check" CHECK (("removed_at" is null and "removed_by_auth_user_id" is null) or ("removed_at" is not null and "removed_by_auth_user_id" is not null and "removed_at" >= "joined_at")),
	CONSTRAINT "organization_membership_time_check" CHECK ("updated_at" >= "created_at" and "updated_at" >= "joined_at" and ("removed_at" is null or "updated_at" >= "removed_at"))
);

CREATE TABLE "organization_membership_event" (
	"organization_entity_id" uuid,
	"member_auth_user_id" uuid,
	"member_entity_id" uuid NOT NULL,
	"revision" bigint,
	"operation" text NOT NULL,
	"operator_auth_user_id" uuid NOT NULL,
	"accepted_invitation_id" uuid NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "organization_membership_event_pkey" PRIMARY KEY("organization_entity_id","member_auth_user_id","revision"),
	CONSTRAINT "organization_membership_event_revision_check" CHECK ("revision" between 1 and 9007199254740991),
	CONSTRAINT "organization_membership_event_operation_check" CHECK ("operation" in ('join','remove','leave'))
);

CREATE TABLE "organization_membership_invitation" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"organization_entity_id" uuid NOT NULL,
	"organization_revision" bigint NOT NULL,
	"recipient_auth_user_id" uuid NOT NULL,
	"recipient_entity_id" uuid NOT NULL,
	"invited_by_auth_user_id" uuid NOT NULL,
	"inviter_authorization_revision" bigint NOT NULL,
	"authorization_grant_id" uuid NOT NULL,
	"authorization_grant_revision" bigint NOT NULL,
	"state" text DEFAULT 'pending' NOT NULL,
	"revision" bigint DEFAULT 1 NOT NULL,
	"expires_at" timestamp(3) with time zone NOT NULL,
	"resolved_at" timestamp(3) with time zone,
	"resolved_by_auth_user_id" uuid,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "organization_membership_invitation_state_check" CHECK ("state" in ('pending','accepted','declined','cancelled','expired','invalidated')),
	CONSTRAINT "organization_membership_invitation_revision_check" CHECK ("revision" between 1 and 9007199254740991 and "organization_revision" between 1 and 9007199254740991 and "inviter_authorization_revision" between 1 and 9007199254740991 and "authorization_grant_revision" between 1 and 9007199254740991),
	CONSTRAINT "organization_membership_invitation_expiry_check" CHECK ("expires_at" > "created_at" and "expires_at" <= "created_at" + interval '30 days'),
	CONSTRAINT "organization_membership_invitation_resolution_check" CHECK (("state" = 'pending' and "resolved_at" is null and "resolved_by_auth_user_id" is null) or ("state" <> 'pending' and "resolved_at" is not null and "resolved_at" >= "created_at" and (("state" in ('accepted','declined') and "resolved_by_auth_user_id" is not null and "resolved_by_auth_user_id" = "recipient_auth_user_id") or ("state" = 'cancelled' and "resolved_by_auth_user_id" is not null) or ("state" in ('expired','invalidated') and "resolved_by_auth_user_id" is null))))
);

CREATE TABLE "participation_grant" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"auth_user_id" uuid,
	"service_principal_id" uuid,
	"acting_entity_id" uuid NOT NULL,
	"capability" text NOT NULL,
	"proposal_source_record_id" uuid,
	"proposal_id" uuid,
	"publishing_id" uuid,
	"music_id" uuid,
	"program_id" uuid,
	"software_id" uuid,
	"entity_id" uuid,
	"grouping_id" uuid,
	"reference_id" uuid,
	"distribution_id" uuid,
	"revision" bigint DEFAULT 1 NOT NULL,
	"expires_at" timestamp(3) with time zone,
	"revoked_at" timestamp(3) with time zone,
	"created_by_auth_user_id" uuid,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "participation_grant_proposal_scope_check" CHECK (("capability" = 'proposal.adopt' and num_nonnulls("proposal_source_record_id", "proposal_id") = 2) or ("capability" <> 'proposal.adopt' and num_nonnulls("proposal_source_record_id", "proposal_id") = 0)),
	CONSTRAINT "participation_grant_principal_check" CHECK (num_nonnulls("auth_user_id", "service_principal_id") = 1),
	CONSTRAINT "participation_grant_target_check" CHECK (num_nonnulls("publishing_id", "music_id", "program_id", "software_id", "entity_id", "grouping_id", "reference_id", "distribution_id") = 1),
	CONSTRAINT "participation_grant_capability_check" CHECK ("capability" in ('catalog.read', 'catalog.edit', 'entity.publish', 'entity.membership', 'entity.security', 'proposal.adopt')),
	CONSTRAINT "participation_grant_revision_check" CHECK ("revision" between 1 and 9007199254740991)
);

CREATE TABLE "participation_grant_event" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"grant_id" uuid NOT NULL,
	"revision" bigint NOT NULL,
	"operation" text NOT NULL,
	"operator_auth_user_id" uuid,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "participation_grant_event_operation_check" CHECK ("operation" in ('grant', 'revoke'))
);

CREATE TABLE "platform_capability_grant" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"auth_user_id" uuid NOT NULL,
	"capability" "platform_capability" NOT NULL,
	"granted_by_auth_user_id" uuid NOT NULL,
	"expires_at" timestamp(3) with time zone,
	"revoked_at" timestamp(3) with time zone,
	"revoked_by_auth_user_id" uuid,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "platform_capability_grant_revocation_check" CHECK (("revoked_at" is null) = ("revoked_by_auth_user_id" is null)),
	CONSTRAINT "platform_capability_grant_expiry_check" CHECK ("expires_at" is null or "expires_at" > "created_at")
);

CREATE TABLE "poll" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"revision" bigint DEFAULT 1 NOT NULL,
	"routing_generation" integer DEFAULT 1 NOT NULL,
	"created_by_auth_user_id" uuid,
	"status" "unit_status" DEFAULT 'draft'::"unit_status" NOT NULL,
	"visibility" "resource_visibility" DEFAULT 'public'::"resource_visibility" NOT NULL,
	"content_rating" "content_rating" DEFAULT 'general'::"content_rating" NOT NULL,
	"ai_disclosure" "ai_disclosure" DEFAULT 'unknown'::"ai_disclosure" NOT NULL,
	"moderation_status" "moderation_status" DEFAULT 'approved'::"moderation_status" NOT NULL,
	"post_targeting_locked" boolean DEFAULT false NOT NULL,
	"published_at" timestamp(3) with time zone,
	"deleted_at" timestamp(3) with time zone,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"mode" "poll_mode" DEFAULT 'single'::"poll_mode" NOT NULL,
	"result_visibility" "poll_result_visibility" DEFAULT 'live'::"poll_result_visibility" NOT NULL,
	"anonymous" boolean DEFAULT false NOT NULL,
	"closes_at" timestamp(3) with time zone,
	"closed_at" timestamp(3) with time zone,
	CONSTRAINT "poll_identity_revision_check" CHECK ("revision" between 1 and 9007199254740991 and "routing_generation" between 1 and 2147483647),
	CONSTRAINT "poll_identity_publication_check" CHECK ("status" <> 'published' or "published_at" is not null),
	CONSTRAINT "poll_identity_deleted_at_check" CHECK ("deleted_at" is null or "deleted_at" >= "created_at"),
	CONSTRAINT "poll_closes_at_check" CHECK ("closes_at" is null or "closes_at" > "created_at"),
	CONSTRAINT "poll_closed_at_check" CHECK ("closed_at" is null or "closed_at" >= "created_at")
);

CREATE TABLE "poll_option" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"poll_id" uuid NOT NULL,
	"source_kind" "poll_option_source_kind" DEFAULT 'literal'::"poll_option_source_kind" NOT NULL,
	"target_unit_id" uuid,
	"target_unit_publishing_id" uuid,
	"target_unit_music_id" uuid,
	"target_unit_program_id" uuid,
