	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "poll_option_poll_id_key" UNIQUE("poll_id","id"),
	CONSTRAINT "poll_option_target_unit_target_check" CHECK (num_nonnulls("target_unit_publishing_id", "target_unit_music_id", "target_unit_program_id", "target_unit_software_id", "target_unit_entity_id", "target_unit_grouping_id", "target_unit_reference_id", "target_unit_distribution_id", "target_unit_video_id", "target_unit_audio_id", "target_unit_post_id", "target_unit_poll_id", "target_unit_zone_id", "target_unit_realm_id", "target_unit_realm_rule_id", "target_unit_custom_theme_id", "target_unit_collection_id", "target_unit_tag_id", "target_unit_tag_path_id", "target_unit_label_id") between 0 and 1),
	CONSTRAINT "poll_option_target_unit_id_check" CHECK ("target_unit_id" is not distinct from coalesce("target_unit_publishing_id", "target_unit_music_id", "target_unit_program_id", "target_unit_software_id", "target_unit_entity_id", "target_unit_grouping_id", "target_unit_reference_id", "target_unit_distribution_id", "target_unit_video_id", "target_unit_audio_id", "target_unit_post_id", "target_unit_poll_id", "target_unit_zone_id", "target_unit_realm_id", "target_unit_realm_rule_id", "target_unit_custom_theme_id", "target_unit_collection_id", "target_unit_tag_id", "target_unit_tag_path_id", "target_unit_label_id")),
	CONSTRAINT "poll_option_source_check" CHECK (("source_kind" = 'literal'::poll_option_source_kind and "target_unit_id" is null) or ("source_kind" = 'unit'::poll_option_source_kind and "target_unit_id" is not null)),
	CONSTRAINT "poll_option_deleted_at_check" CHECK ("deleted_at" is null or "deleted_at" >= "created_at")
);

CREATE TABLE "poll_option_vote_stat" (
	"option_id" uuid PRIMARY KEY,
	"vote_count" bigint DEFAULT 0 NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "poll_option_vote_stat_count_check" CHECK ("vote_count" >= 0)
);

CREATE TABLE "poll_vote" (
	"poll_id" uuid,
	"profile_id" uuid,
	"option_id" uuid,
	"realm_id" uuid,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "poll_vote_pkey" PRIMARY KEY("poll_id","profile_id","option_id")
);

CREATE TABLE "post" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"revision" bigint DEFAULT 1 NOT NULL,
	"routing_generation" integer DEFAULT 1 NOT NULL,
	"created_by_auth_user_id" uuid,
	"status" "unit_status" DEFAULT 'draft'::"unit_status" NOT NULL,
	"visibility" "resource_visibility" DEFAULT 'public'::"resource_visibility" NOT NULL,
	"content_rating" "content_rating" DEFAULT 'general'::"content_rating" NOT NULL,
	"ai_disclosure" "ai_disclosure" DEFAULT 'unknown'::"ai_disclosure" NOT NULL,
	"moderation_status" "moderation_status" DEFAULT 'approved'::"moderation_status" NOT NULL,
	"post_targeting_locked" boolean DEFAULT false NOT NULL,
	"published_at" timestamp(3) with time zone,
	"deleted_at" timestamp(3) with time zone,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"subject_unit_id" uuid,
	"subject_unit_publishing_id" uuid,
	"subject_unit_music_id" uuid,
	"subject_unit_program_id" uuid,
	"subject_unit_software_id" uuid,
	"subject_unit_entity_id" uuid,
	"subject_unit_grouping_id" uuid,
	"subject_unit_reference_id" uuid,
	"subject_unit_distribution_id" uuid,
	"subject_unit_video_id" uuid,
	"subject_unit_audio_id" uuid,
	"subject_unit_post_id" uuid,
	"subject_unit_poll_id" uuid,
	"subject_unit_zone_id" uuid,
	"subject_unit_realm_id" uuid,
	"subject_unit_realm_rule_id" uuid,
	"subject_unit_custom_theme_id" uuid,
	"subject_unit_collection_id" uuid,
	"subject_unit_tag_id" uuid,
	"subject_unit_tag_path_id" uuid,
	"subject_unit_label_id" uuid,
	"kind" "post_kind" DEFAULT 'post'::"post_kind" NOT NULL,
	CONSTRAINT "post_subject_unit_target_check" CHECK (num_nonnulls("subject_unit_publishing_id", "subject_unit_music_id", "subject_unit_program_id", "subject_unit_software_id", "subject_unit_entity_id", "subject_unit_grouping_id", "subject_unit_reference_id", "subject_unit_distribution_id", "subject_unit_video_id", "subject_unit_audio_id", "subject_unit_post_id", "subject_unit_poll_id", "subject_unit_zone_id", "subject_unit_realm_id", "subject_unit_realm_rule_id", "subject_unit_custom_theme_id", "subject_unit_collection_id", "subject_unit_tag_id", "subject_unit_tag_path_id", "subject_unit_label_id") between 0 and 1),
	CONSTRAINT "post_subject_unit_id_check" CHECK ("subject_unit_id" is not distinct from coalesce("subject_unit_publishing_id", "subject_unit_music_id", "subject_unit_program_id", "subject_unit_software_id", "subject_unit_entity_id", "subject_unit_grouping_id", "subject_unit_reference_id", "subject_unit_distribution_id", "subject_unit_video_id", "subject_unit_audio_id", "subject_unit_post_id", "subject_unit_poll_id", "subject_unit_zone_id", "subject_unit_realm_id", "subject_unit_realm_rule_id", "subject_unit_custom_theme_id", "subject_unit_collection_id", "subject_unit_tag_id", "subject_unit_tag_path_id", "subject_unit_label_id")),
	CONSTRAINT "post_identity_revision_check" CHECK ("revision" between 1 and 9007199254740991 and "routing_generation" between 1 and 2147483647),
	CONSTRAINT "post_identity_publication_check" CHECK ("status" <> 'published' or "published_at" is not null),
	CONSTRAINT "post_identity_deleted_at_check" CHECK ("deleted_at" is null or "deleted_at" >= "created_at"),
	CONSTRAINT "post_subject_not_self_check" CHECK ("subject_unit_id" is null or "subject_unit_id" <> "id"),
	CONSTRAINT "post_review_subject_check" CHECK ("kind" <> 'review'::post_kind or "subject_unit_id" is not null),
	CONSTRAINT "post_excerpt_subject_check" CHECK ("kind" <> 'excerpt'::post_kind or "subject_unit_id" is not null)
);

CREATE TABLE "post_progress_entry" (
	"post_id" uuid PRIMARY KEY,
	"progress_entry_id" uuid NOT NULL CONSTRAINT "post_progress_entry_progress_entry_key" UNIQUE,
	"position" text collate "C" NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "post_progress_entry_post_position_key" UNIQUE("post_id","position"),
	CONSTRAINT "post_progress_entry_position_byte_length_check" CHECK (octet_length("position") <= 1024)
);

CREATE TABLE "post_reply" (
	"post_id" uuid PRIMARY KEY,
	"root_post_id" uuid NOT NULL,
	"parent_post_id" uuid,
	"depth" integer NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "post_reply_post_root_key" UNIQUE("post_id","root_post_id"),
	CONSTRAINT "post_reply_not_root_check" CHECK ("post_id" <> "root_post_id"),
	CONSTRAINT "post_reply_not_self_parent_check" CHECK ("parent_post_id" is null or "parent_post_id" <> "post_id"),
	CONSTRAINT "post_reply_depth_check" CHECK ("depth" between 0 and 64)
);

CREATE TABLE "post_reply_stat" (
	"post_id" uuid PRIMARY KEY,
	"undeleted_direct_count" bigint DEFAULT 0 NOT NULL,
	"undeleted_descendant_count" bigint DEFAULT 0 NOT NULL,
	"search_reply_count" bigint DEFAULT 0 NOT NULL,
	"visible_direct_count" bigint DEFAULT 0 NOT NULL,
	"visible_descendant_count" bigint DEFAULT 0 NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "post_reply_stat_count_check" CHECK ("undeleted_direct_count" >= 0 and "undeleted_descendant_count" >= 0 and "search_reply_count" >= 0 and "visible_direct_count" >= 0 and "visible_descendant_count" >= 0)
);

CREATE TABLE "post_score" (
	"post_id" uuid,
	"score_id" uuid,
	"position" text collate "C" NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "post_score_pkey" PRIMARY KEY("post_id","score_id"),
	CONSTRAINT "post_score_post_position_key" UNIQUE("post_id","position"),
	CONSTRAINT "post_score_position_byte_length_check" CHECK (octet_length("position") <= 1024)
);

CREATE TABLE "profile_resource_participation" (
	"profile_id" uuid,
	"resource_unit_id" uuid,
	"created_resource_at" timestamp(3) with time zone,
	"first_contributed_at" timestamp(3) with time zone,
	"last_contributed_at" timestamp(3) with time zone,
	"contribution_count" bigint DEFAULT 0 NOT NULL,
	"last_participated_at" timestamp(3) with time zone NOT NULL,
	"projection_updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"resource_unit_publishing_id" uuid,
	"resource_unit_music_id" uuid,
	"resource_unit_program_id" uuid,
	"resource_unit_software_id" uuid,
	"resource_unit_entity_id" uuid,
	"resource_unit_grouping_id" uuid,
	"resource_unit_reference_id" uuid,
	"resource_unit_distribution_id" uuid,
	"resource_unit_video_id" uuid,
	"resource_unit_audio_id" uuid,
	"resource_unit_post_id" uuid,
	"resource_unit_poll_id" uuid,
	"resource_unit_zone_id" uuid,
	"resource_unit_realm_id" uuid,
	"resource_unit_realm_rule_id" uuid,
	"resource_unit_custom_theme_id" uuid,
	"resource_unit_collection_id" uuid,
	"resource_unit_tag_id" uuid,
	"resource_unit_tag_path_id" uuid,
	"resource_unit_label_id" uuid,
	CONSTRAINT "profile_resource_participation_pkey" PRIMARY KEY("profile_id","resource_unit_id"),
	CONSTRAINT "profile_resource_participation_resource_unit_target_check" CHECK (num_nonnulls("resource_unit_publishing_id", "resource_unit_music_id", "resource_unit_program_id", "resource_unit_software_id", "resource_unit_entity_id", "resource_unit_grouping_id", "resource_unit_reference_id", "resource_unit_distribution_id", "resource_unit_video_id", "resource_unit_audio_id", "resource_unit_post_id", "resource_unit_poll_id", "resource_unit_zone_id", "resource_unit_realm_id", "resource_unit_realm_rule_id", "resource_unit_custom_theme_id", "resource_unit_collection_id", "resource_unit_tag_id", "resource_unit_tag_path_id", "resource_unit_label_id") = 1),
	CONSTRAINT "profile_resource_participation_resource_unit_id_check" CHECK ("resource_unit_id" is not distinct from coalesce("resource_unit_publishing_id", "resource_unit_music_id", "resource_unit_program_id", "resource_unit_software_id", "resource_unit_entity_id", "resource_unit_grouping_id", "resource_unit_reference_id", "resource_unit_distribution_id", "resource_unit_video_id", "resource_unit_audio_id", "resource_unit_post_id", "resource_unit_poll_id", "resource_unit_zone_id", "resource_unit_realm_id", "resource_unit_realm_rule_id", "resource_unit_custom_theme_id", "resource_unit_collection_id", "resource_unit_tag_id", "resource_unit_tag_path_id", "resource_unit_label_id")),
	CONSTRAINT "profile_resource_participation_source_check" CHECK ("created_resource_at" is not null or "first_contributed_at" is not null),
	CONSTRAINT "profile_resource_participation_contribution_shape_check" CHECK ((
				"contribution_count" = 0
				and "first_contributed_at" is null
				and "last_contributed_at" is null
			) or (
				"contribution_count" > 0
				and "first_contributed_at" is not null
				and "last_contributed_at" is not null
				and "first_contributed_at" <= "last_contributed_at"
			)),
	CONSTRAINT "profile_resource_participation_last_at_check" CHECK ("last_participated_at" = greatest(
				"created_resource_at",
				"last_contributed_at"
			))
);

CREATE TABLE "program_catalog_change" (
	"id" uuid DEFAULT uuidv7(),
	"owner_id" uuid,
	"version" bigint NOT NULL,
	"actor_auth_user_id" uuid,
	"operation" text NOT NULL,
	"recorded_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"withdrawn_at" timestamp(3) with time zone,
	CONSTRAINT "program_change_identity_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "program_change_version_key" UNIQUE("owner_id","version"),
	CONSTRAINT "program_change_version_check" CHECK ("version" between 1 and 9007199254740991),
	CONSTRAINT "program_change_operation_check" CHECK (length("operation") between 1 and 96)
);

CREATE TABLE "program_catalog_relation" (
	"id" uuid DEFAULT uuidv7(),
	"owner_id" uuid,
	"definition_revision_id" uuid NOT NULL,
	"semantic_id" uuid DEFAULT uuidv7() NOT NULL,
	"expected_head_version" bigint DEFAULT 0 NOT NULL,
	"state" text DEFAULT 'active' NOT NULL,
	"revision" bigint DEFAULT 1 NOT NULL,
	"spoiler" integer DEFAULT 0 NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "program_relation_owner_id_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "program_relation_head_version_check" CHECK ("expected_head_version" between 0 and 9007199254740990),
	CONSTRAINT "program_relation_spoiler_check" CHECK ("spoiler" between 0 and 2),
	CONSTRAINT "program_relation_state_check" CHECK ("state" in ('active', 'disputed', 'withdrawn', 'superseded')),
	CONSTRAINT "program_relation_revision_check" CHECK ("revision" between 1 and 9007199254740991)
);

CREATE TABLE "program_component_head" (
	"owner_id" uuid,
	"component" text,
	"component_key" text,
	"component_sequence" bigint NOT NULL,
	"history_id" uuid NOT NULL,
	CONSTRAINT "program_component_head_pkey" PRIMARY KEY("owner_id","component","component_key"),
	CONSTRAINT "program_component_head_values" CHECK ("component_sequence" between 1 and 9007199254740991 and octet_length("component") between 1 and 96 and octet_length("component_key") between 1 and 512)
);

CREATE TABLE "program_component_revision" (
	"owner_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"component" text NOT NULL,
	"component_key" text NOT NULL,
	"component_sequence" bigint NOT NULL,
	"owner_revision" bigint NOT NULL,
	"operation" text NOT NULL,
	"value" jsonb NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "program_component_revision_pkey" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "program_component_revision_sequence_key" UNIQUE("owner_id","component","component_key","component_sequence"),
	CONSTRAINT "program_component_revision_values" CHECK ("operation" in ('INSERT','UPDATE','DELETE') and "owner_revision" between 1 and 9007199254740991 and "component_sequence" between 1 and 9007199254740991 and octet_length("component") between 1 and 96 and octet_length("component_key") between 1 and 512 and jsonb_typeof("value")='object' and octet_length("value"::text)<=1048576)
);

CREATE TABLE "program_component_source_application_change" (
	"source_record_id" uuid,
	"proposal_id" uuid,
	"action" text,
	"position" integer,
	"owner_id" uuid NOT NULL,
	"component" text NOT NULL,
	"component_key" text NOT NULL,
	"before_revision_id" uuid,
	"after_revision_id" uuid NOT NULL,
	CONSTRAINT "program_component_source_application_change_pkey" PRIMARY KEY("source_record_id","proposal_id","action","position"),
	CONSTRAINT "program_child_application_components" CHECK ("component" in ('program_episode_occurrence')),
	CONSTRAINT "program_child_application_values" CHECK ("position" between 0 and 127 and "action" in ('apply','withdraw') and octet_length("component") between 1 and 96 and octet_length("component_key")=36 and ("before_revision_id" is null or "before_revision_id"<>"after_revision_id"))
) PARTITION BY HASH ("source_record_id");
CREATE TABLE "program_component_source_application_change_p00" PARTITION OF "program_component_source_application_change" FOR VALUES WITH (MODULUS 64, REMAINDER 0);
CREATE TABLE "program_component_source_application_change_p01" PARTITION OF "program_component_source_application_change" FOR VALUES WITH (MODULUS 64, REMAINDER 1);
CREATE TABLE "program_component_source_application_change_p02" PARTITION OF "program_component_source_application_change" FOR VALUES WITH (MODULUS 64, REMAINDER 2);
CREATE TABLE "program_component_source_application_change_p03" PARTITION OF "program_component_source_application_change" FOR VALUES WITH (MODULUS 64, REMAINDER 3);
CREATE TABLE "program_component_source_application_change_p04" PARTITION OF "program_component_source_application_change" FOR VALUES WITH (MODULUS 64, REMAINDER 4);
CREATE TABLE "program_component_source_application_change_p05" PARTITION OF "program_component_source_application_change" FOR VALUES WITH (MODULUS 64, REMAINDER 5);
