CREATE TABLE "program_episode" (
	"id" uuid PRIMARY KEY,
	"identity_shape" text DEFAULT 'episode' NOT NULL,
	"program_id" uuid,
	"season_id" uuid,
	"type_revision_id" uuid,
	"sort_number" numeric,
	"episode_number" numeric,
	"disc_number" integer,
	"duration_text" text,
	"length_milliseconds" bigint,
	"date_year" integer,
	"date_month" smallint,
	"date_day" smallint,
	"date_text" text,
	CONSTRAINT "program_episode_shape_check" CHECK ("identity_shape" = 'episode'),
	CONSTRAINT "program_episode_season_owner_check" CHECK ("season_id" is null or "program_id" is not null),
	CONSTRAINT "program_episode_disc_check" CHECK ("disc_number" is null or "disc_number" >= 0),
	CONSTRAINT "program_episode_numbers_check" CHECK (("sort_number" is null or "sort_number"::text not in ('NaN', 'Infinity', '-Infinity')) and ("episode_number" is null or "episode_number"::text not in ('NaN', 'Infinity', '-Infinity'))),
	CONSTRAINT "program_episode_length_check" CHECK ("length_milliseconds" is null or "length_milliseconds" between 0 and 9007199254740991),
	CONSTRAINT "program_episode_date_check" CHECK (
		("date_month" is null or "date_month" between 1 and 12)
		and ("date_day" is null or "date_day" between 1 and 31)
		and ("date_month" is null or "date_day" is null or "date_day" <= case
			when "date_month" in (4, 6, 9, 11) then 30
			when "date_month" = 2 then case when "date_year" is null
				or mod("date_year", 400) = 0 or (mod("date_year", 4) = 0 and mod("date_year", 100) <> 0) then 29 else 28 end
			else 31 end))
);

CREATE TABLE "program_episode_occurrence" (
	"owner_id" uuid,
	"owner_shape" text NOT NULL,
	"id" uuid DEFAULT uuidv7(),
	"episode_id" uuid NOT NULL,
	"position" text collate "C" NOT NULL,
	"source_number" text,
	CONSTRAINT "program_episode_occurrence_pkey" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "program_occurrence_owner_shape_check" CHECK ("owner_shape" in ('program', 'season', 'program_version')),
	CONSTRAINT "program_occurrence_position_check" CHECK (octet_length("position") <= 1024)
);

CREATE TABLE "program_fact" (
	"id" uuid DEFAULT uuidv7(),
	"owner_id" uuid,
	"definition_revision_id" uuid NOT NULL,
	"semantic_id" uuid DEFAULT uuidv7() NOT NULL,
	"expected_head_version" bigint DEFAULT 0 NOT NULL,
	"state" text DEFAULT 'active' NOT NULL,
	"purpose" text DEFAULT 'assertion' NOT NULL,
	"last_node_position" bigint DEFAULT -1 NOT NULL,
	"spoiler" integer DEFAULT 0 NOT NULL,
	"sealed_at" timestamp(3) with time zone,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "program_fact_identity_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "program_fact_spoiler_check" CHECK ("spoiler" between 0 and 2),
	CONSTRAINT "program_fact_head_version_check" CHECK ("expected_head_version" between 0 and 9007199254740990),
	CONSTRAINT "program_fact_state_check" CHECK ("state" in ('active', 'disputed', 'withdrawn', 'superseded')),
	CONSTRAINT "program_fact_purpose_check" CHECK ("purpose" in ('assertion','qualifier')),
	CONSTRAINT "program_fact_node_cursor_check" CHECK ("last_node_position" between -1 and 9007199254740991 and ("sealed_at" is null or "last_node_position" >= 0))
);

CREATE TABLE "program_fact_support" (
	"owner_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"source_record_id" uuid NOT NULL,
	"snapshot_id" uuid NOT NULL,
	"source_path" text NOT NULL,
	"fact_id" uuid,
	"relation_id" uuid,
	"named_form_id" uuid,
	"identifier_id" uuid,
	"identifier_revision" bigint,
	"source_mapping_key" uuid,
	"source_correspondence_revision" bigint,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"withdrawn_at" timestamp(3) with time zone,
	CONSTRAINT "program_support_identity_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "program_support_source_correspondence_pair" CHECK (("source_mapping_key" is null) = ("source_correspondence_revision" is null)),
	CONSTRAINT "program_support_identifier_revision_check" CHECK (("identifier_id" is null) = ("identifier_revision" is null)),
	CONSTRAINT "program_support_target_check" CHECK (num_nonnulls("fact_id", "relation_id", "named_form_id", "identifier_id") = 1),
	CONSTRAINT "program_support_source_path_check" CHECK (length("source_path") > 0)
);

CREATE TABLE "program_fact_value_node" (
	"owner_id" uuid,
	"fact_id" uuid,
	"position" bigint,
	"rule_position" integer DEFAULT 0 NOT NULL,
	"parent_position" bigint,
	"parent_kind" text,
	"member_key" text,
	"kind" text NOT NULL,
	"text_value" text,
	"number_value" numeric,
	"boolean_value" boolean,
	CONSTRAINT "program_fact_node_position_key" PRIMARY KEY("owner_id","fact_id","position"),
	CONSTRAINT "program_fact_node_kind_key" UNIQUE("owner_id","fact_id","position","kind"),
	CONSTRAINT "program_fact_node_member_key" UNIQUE("owner_id","fact_id","parent_position","member_key"),
	CONSTRAINT "program_fact_node_rule_check" CHECK ("rule_position" between 0 and 127),
	CONSTRAINT "program_fact_node_kind_check" CHECK ("kind" in ('null', 'string', 'number', 'boolean', 'object', 'array')),
	CONSTRAINT "program_fact_node_position_check" CHECK ("position" between 0 and 9007199254740991 and ("parent_position" is null or "parent_position" >= 0 and "parent_position" < "position")),
	CONSTRAINT "program_fact_node_parent_check" CHECK (("position" = 0 and "parent_position" is null and "parent_kind" is null and "member_key" is null) or ("position" > 0 and "parent_position" is not null and "parent_kind" is not null and (("parent_kind" = 'object' and "member_key" is not null) or ("parent_kind" = 'array' and "member_key" is null)))),
	CONSTRAINT "program_fact_node_number_check" CHECK ("number_value" is null or "number_value"::text not in ('NaN', 'Infinity', '-Infinity')),
	CONSTRAINT "program_fact_node_value_check" CHECK (("kind" = 'string' and "text_value" is not null and "number_value" is null and "boolean_value" is null) or ("kind" = 'number' and "number_value" is not null and "text_value" is null and "boolean_value" is null) or ("kind" = 'boolean' and "boolean_value" is not null and "text_value" is null and "number_value" is null) or ("kind" in ('null', 'object', 'array') and "text_value" is null and "number_value" is null and "boolean_value" is null))
);

CREATE TABLE "program_identifier_claim" (
	"owner_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"revision" bigint DEFAULT 1 NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_by_auth_user_id" uuid,
	"namespace" text NOT NULL,
	"value" text NOT NULL,
	"normalized_value" text NOT NULL,
	"normalization_policy" text DEFAULT 'exact.1' NOT NULL,
	"validation_status" text DEFAULT 'unvalidated' NOT NULL,
	"issuer_entity_id" uuid,
	"state" text DEFAULT 'active' NOT NULL,
	CONSTRAINT "program_identifier_identity_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "program_identifier_namespace_check" CHECK ("namespace" ~ '^[a-z][a-z0-9_.:-]{0,127}$'),
	CONSTRAINT "program_identifier_value_check" CHECK (octet_length("value") between 1 and 512 and octet_length("normalized_value") between 1 and 512 and octet_length("normalization_policy") between 1 and 96),
	CONSTRAINT "program_identifier_state_check" CHECK ("state" in ('active', 'disputed', 'withdrawn', 'superseded')),
	CONSTRAINT "program_identifier_validation_check" CHECK ("validation_status" in ('unvalidated', 'valid')),
	CONSTRAINT "program_identifier_revision_check" CHECK ("revision" between 1 and 9007199254740991)
);

CREATE TABLE "program_identifier_claim_revision" (
	"owner_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"revision" bigint DEFAULT 1,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_by_auth_user_id" uuid,
	"namespace" text NOT NULL,
	"value" text NOT NULL,
	"normalized_value" text NOT NULL,
	"normalization_policy" text DEFAULT 'exact.1' NOT NULL,
	"validation_status" text DEFAULT 'unvalidated' NOT NULL,
	"issuer_entity_id" uuid,
	"state" text DEFAULT 'active' NOT NULL,
	CONSTRAINT "program_identifier_revision_key" PRIMARY KEY("owner_id","id","revision")
);

CREATE TABLE "program_identity" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"shape" text NOT NULL,
	"status" text DEFAULT 'draft' NOT NULL,
	"visibility" text DEFAULT 'private' NOT NULL,
	"content_rating" text DEFAULT 'general' NOT NULL,
	"moderation_status" text DEFAULT 'approved' NOT NULL,
	"created_by_auth_user_id" uuid,
	"post_targeting_locked" boolean DEFAULT false NOT NULL,
	"revision" bigint DEFAULT 1 NOT NULL,
	"routing_generation" integer DEFAULT 1 NOT NULL,
	"deleted_at" timestamp(3) with time zone,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "program_identity_shape_key" UNIQUE("id","shape"),
	CONSTRAINT "program_identity_shape_check" CHECK ("shape" ~ '^[a-z][a-z0-9_.-]{0,95}$'),
	CONSTRAINT "program_identity_status_check" CHECK ("status" in ('draft', 'published', 'archived')),
	CONSTRAINT "program_identity_visibility_check" CHECK ("visibility" in ('public', 'unlisted', 'private')),
	CONSTRAINT "program_identity_rating_check" CHECK ("content_rating" in ('general', 'r15', 'r18', 'r18g')),
	CONSTRAINT "program_identity_moderation_check" CHECK ("moderation_status" in ('approved', 'pending', 'removed')),
	CONSTRAINT "program_identity_revision_check" CHECK ("revision" between 1 and 9007199254740991 and "routing_generation" > 0)
);

CREATE TABLE "program_name_authority" (
	"owner_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"revision" bigint DEFAULT 1 NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_by_auth_user_id" uuid,
	"name_id" uuid NOT NULL,
	"name_revision" bigint NOT NULL,
	"claim" text NOT NULL,
	"review_state" text NOT NULL,
	"authorizer_entity_id" uuid,
	"role" text NOT NULL,
	"territory" text,
	"channel" text,
	"context" text,
	"valid_from" timestamp(3) with time zone,
	"valid_until" timestamp(3) with time zone,
	"source_record_id" uuid NOT NULL,
	"snapshot_id" uuid NOT NULL,
	"source_path" text NOT NULL,
	"review_source_record_id" uuid,
	"review_snapshot_id" uuid,
	"review_source_path" text,
	"state" text NOT NULL,
	CONSTRAINT "program_name_authority_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "program_name_authority_revision_check" CHECK ("revision" between 1 and 9007199254740991),
	CONSTRAINT "program_name_authority_claim_check" CHECK ("claim" in ('official', 'unofficial', 'unknown')),
	CONSTRAINT "program_name_authority_review_check" CHECK ("review_state" in ('source_claim', 'pending', 'verified', 'rejected')),
	CONSTRAINT "program_name_authority_state_check" CHECK ("state" in ('active', 'withdrawn')),
	CONSTRAINT "program_name_authority_proof_check" CHECK (("review_state" <> 'verified' or ("authorizer_entity_id" is not null and "review_snapshot_id" is not null)) and num_nonnulls("review_source_record_id","review_snapshot_id","review_source_path") in (0,3)),
	CONSTRAINT "program_name_authority_time_check" CHECK ("valid_from" is null or "valid_until" is null or "valid_until" > "valid_from"),
	CONSTRAINT "program_name_authority_scope_check" CHECK (octet_length("role") between 1 and 96 and octet_length("source_path") between 1 and 4096 and ("review_source_path" is null or octet_length("review_source_path") between 1 and 4096) and ("territory" is null or octet_length("territory") between 1 and 96) and ("channel" is null or octet_length("channel") between 1 and 96) and ("context" is null or octet_length("context") between 1 and 512))
);

CREATE TABLE "program_name_authority_revision" (
	"owner_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"revision" bigint DEFAULT 1,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_by_auth_user_id" uuid,
	"name_id" uuid NOT NULL,
	"name_revision" bigint NOT NULL,
	"claim" text NOT NULL,
	"review_state" text NOT NULL,
	"authorizer_entity_id" uuid,
	"role" text NOT NULL,
	"territory" text,
	"channel" text,
	"context" text,
	"valid_from" timestamp(3) with time zone,
	"valid_until" timestamp(3) with time zone,
	"source_record_id" uuid NOT NULL,
	"snapshot_id" uuid NOT NULL,
	"source_path" text NOT NULL,
	"review_source_record_id" uuid,
	"review_snapshot_id" uuid,
	"review_source_path" text,
	"state" text NOT NULL,
	CONSTRAINT "program_name_authority_revision_key" PRIMARY KEY("owner_id","id","revision")
);

CREATE TABLE "program_name_source_binding" (
	"owner_id" uuid,
	"source_record_id" uuid,
	"mapping_key" uuid,
	"correspondence_revision" bigint,
	"namespace" text,
	"local_key" text,
	"name_id" uuid NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "program_name_source_binding_key" PRIMARY KEY("source_record_id","mapping_key","correspondence_revision","owner_id","namespace","local_key"),
	CONSTRAINT "program_name_source_binding_owner_key" UNIQUE("owner_id","source_record_id","mapping_key","correspondence_revision","namespace","local_key","name_id"),
	CONSTRAINT "program_name_source_binding_value_check" CHECK (octet_length("namespace") between 1 and 96 and octet_length("local_key") between 1 and 512)
);

CREATE TABLE "program_name_source_occurrence" (
	"owner_id" uuid,
	"source_record_id" uuid,
	"mapping_key" uuid,
	"correspondence_revision" bigint,
	"namespace" text,
	"local_key" text,
	"name_id" uuid NOT NULL,
	"name_revision" bigint NOT NULL,
	"snapshot_id" uuid,
	"source_path" text NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "program_name_source_occurrence_key" PRIMARY KEY("source_record_id","mapping_key","correspondence_revision","owner_id","namespace","local_key","snapshot_id"),
	CONSTRAINT "program_name_source_occurrence_path_check" CHECK (octet_length("source_path") between 1 and 4096)
);

CREATE TABLE "program_named_form" (
	"owner_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"revision" bigint DEFAULT 1 NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_by_auth_user_id" uuid,
	"language_tag" text,
	"private_use_namespace" text,
	"language_policy" text,
	"kind" text NOT NULL,
	"value" text NOT NULL,
	"sort_name" text,
	"origin" text DEFAULT 'unknown' NOT NULL,
	"translation_method" text DEFAULT 'unknown' NOT NULL,
	"primary_for_language" boolean,
	"scope_owner_id" uuid,
	"territory" text,
	"context" text,
	"derivation_name_id" uuid,
	"derivation_revision" bigint,
	"begin" jsonb,
	"end" jsonb,
	"ended" boolean,
	"spoiler" integer DEFAULT 0 NOT NULL,
	"state" text DEFAULT 'active' NOT NULL,
	CONSTRAINT "program_named_form_identity_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "program_named_form_state_check" CHECK ("state" in ('active', 'disputed', 'withdrawn', 'superseded')),
	CONSTRAINT "program_named_form_revision_check" CHECK ("revision" between 1 and 9007199254740991),
	CONSTRAINT "program_named_form_kind_check" CHECK (octet_length("kind") between 1 and 96),
	CONSTRAINT "program_named_form_value_check" CHECK (octet_length("value") between 1 and 131072 and ("sort_name" is null or octet_length("sort_name") between 1 and 131072)),
	CONSTRAINT "program_named_form_language_check" CHECK (("language_tag" is null and "language_policy" is null and "private_use_namespace" is null) or ("language_tag" is not null and octet_length("language_tag") between 1 and 255 and "language_policy" is not null and ("private_use_namespace" is null or octet_length("private_use_namespace") between 1 and 512))),
	CONSTRAINT "program_named_form_origin_check" CHECK ("origin" in ('original', 'translation', 'transliteration', 'abbreviation', 'variant', 'unknown')),
	CONSTRAINT "program_named_form_method_check" CHECK ("translation_method" in ('human', 'machine', 'mixed', 'unknown', 'not_applicable')),
	CONSTRAINT "program_named_form_derivation_check" CHECK (num_nonnulls("derivation_name_id","derivation_revision") in (0,2)),
	CONSTRAINT "program_named_form_spoiler_check" CHECK ("spoiler" between 0 and 2),
	CONSTRAINT "program_named_form_scope_check" CHECK (("territory" is null or octet_length("territory") between 1 and 96) and ("context" is null or octet_length("context") between 1 and 512))
);

CREATE TABLE "program_named_form_revision" (
	"owner_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"revision" bigint DEFAULT 1,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_by_auth_user_id" uuid,
	"language_tag" text,
	"private_use_namespace" text,
	"language_policy" text,
	"kind" text NOT NULL,
	"value" text NOT NULL,
	"sort_name" text,
	"origin" text DEFAULT 'unknown' NOT NULL,
	"translation_method" text DEFAULT 'unknown' NOT NULL,
	"primary_for_language" boolean,
	"scope_owner_id" uuid,
	"territory" text,
	"context" text,
	"derivation_name_id" uuid,
	"derivation_revision" bigint,
	"begin" jsonb,
	"end" jsonb,
	"ended" boolean,
	"spoiler" integer DEFAULT 0 NOT NULL,
	"state" text DEFAULT 'active' NOT NULL,
	CONSTRAINT "program_named_form_revision_key" PRIMARY KEY("owner_id","id","revision")
);

