CREATE TABLE "program_structure_source_baseline" (
	"source_record_id" uuid,
	"mapping_key" uuid,
	"correspondence_revision" bigint,
	"mapping_owner" text NOT NULL,
	"owner_id" uuid,
	"component" text,
	"component_key" text,
	"snapshot_id" uuid NOT NULL,
	"source_path" text NOT NULL,
	"source_history_id" uuid NOT NULL,
	"current_history_id" uuid NOT NULL,
	"absent" boolean NOT NULL,
	"proposal_id" uuid NOT NULL,
	"action" text NOT NULL,
	CONSTRAINT "program_structure_source_baseline_pkey" PRIMARY KEY("source_record_id","mapping_key","correspondence_revision","owner_id","component","component_key"),
	CONSTRAINT "program_structure_baseline_owner" CHECK ("mapping_owner" in ('publishing', 'music', 'program', 'software', 'entity', 'grouping', 'reference', 'distribution')),
	CONSTRAINT "program_structure_baseline_components" CHECK ("component" in ('program_work', 'program_season', 'program_version', 'program_episode')),
	CONSTRAINT "program_structure_baseline_values" CHECK ("action" in ('apply','withdraw') and "correspondence_revision" between 1 and 9007199254740991 and octet_length("component") between 1 and 96 and "component_key"="owner_id"::text and left("source_path",1)='/' and octet_length("source_path") between 1 and 512)
) PARTITION BY HASH ("source_record_id");
