CREATE TABLE "program_version" (
	"id" uuid PRIMARY KEY,
	"identity_shape" text DEFAULT 'program_version' NOT NULL,
	"program_id" uuid,
	"version_type_revision_id" uuid,
	"length_milliseconds" bigint,
	CONSTRAINT "program_version_shape_check" CHECK ("identity_shape" = 'program_version'),
	CONSTRAINT "program_version_length_check" CHECK ("length_milliseconds" is null or "length_milliseconds" between 0 and 9007199254740991)
);

CREATE TABLE "program_work" (
	"id" uuid PRIMARY KEY,
	"identity_shape" text DEFAULT 'program' NOT NULL,
	"type_revision_id" uuid,
	"declared_main_episode_count" bigint,
	"declared_total_episode_count" bigint,
	CONSTRAINT "program_work_shape_check" CHECK ("identity_shape" = 'program'),
	CONSTRAINT "program_work_counts_check" CHECK (("declared_main_episode_count" is null or "declared_main_episode_count" between 0 and 9007199254740991) and ("declared_total_episode_count" is null or "declared_total_episode_count" between 0 and 9007199254740991))
);

CREATE TABLE "publishing_catalog_change" (
	"id" uuid DEFAULT uuidv7(),
	"owner_id" uuid,
	"version" bigint NOT NULL,
	"actor_auth_user_id" uuid,
	"operation" text NOT NULL,
	"recorded_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"withdrawn_at" timestamp(3) with time zone,
	CONSTRAINT "publishing_change_identity_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "publishing_change_version_key" UNIQUE("owner_id","version"),
	CONSTRAINT "publishing_change_version_check" CHECK ("version" between 1 and 9007199254740991),
	CONSTRAINT "publishing_change_operation_check" CHECK (length("operation") between 1 and 96)
);

CREATE TABLE "publishing_catalog_relation" (
	"id" uuid DEFAULT uuidv7(),
	"owner_id" uuid,
	"definition_revision_id" uuid NOT NULL,
	"semantic_id" uuid DEFAULT uuidv7() NOT NULL,
	"expected_head_version" bigint DEFAULT 0 NOT NULL,
	"state" text DEFAULT 'active' NOT NULL,
	"revision" bigint DEFAULT 1 NOT NULL,
	"spoiler" integer DEFAULT 0 NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "publishing_relation_owner_id_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "publishing_relation_head_version_check" CHECK ("expected_head_version" between 0 and 9007199254740990),
	CONSTRAINT "publishing_relation_spoiler_check" CHECK ("spoiler" between 0 and 2),
	CONSTRAINT "publishing_relation_state_check" CHECK ("state" in ('active', 'disputed', 'withdrawn', 'superseded')),
	CONSTRAINT "publishing_relation_revision_check" CHECK ("revision" between 1 and 9007199254740991)
);

CREATE TABLE "publishing_component_head" (
	"owner_id" uuid,
	"component" text,
	"component_key" text,
	"component_sequence" bigint NOT NULL,
	"history_id" uuid NOT NULL,
	CONSTRAINT "publishing_component_head_pkey" PRIMARY KEY("owner_id","component","component_key"),
	CONSTRAINT "publishing_component_head_values" CHECK ("component_sequence" between 1 and 9007199254740991 and octet_length("component") between 1 and 96 and octet_length("component_key") between 1 and 512)
);

CREATE TABLE "publishing_component_revision" (
	"owner_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"component" text NOT NULL,
	"component_key" text NOT NULL,
	"component_sequence" bigint NOT NULL,
	"owner_revision" bigint NOT NULL,
	"operation" text NOT NULL,
	"value" jsonb NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "publishing_component_revision_pkey" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "publishing_component_revision_sequence_key" UNIQUE("owner_id","component","component_key","component_sequence"),
	CONSTRAINT "publishing_component_revision_values" CHECK ("operation" in ('INSERT','UPDATE','DELETE') and "owner_revision" between 1 and 9007199254740991 and "component_sequence" between 1 and 9007199254740991 and octet_length("component") between 1 and 96 and octet_length("component_key") between 1 and 512 and jsonb_typeof("value")='object' and octet_length("value"::text)<=1048576)
);

CREATE TABLE "publishing_component_source_application_change" (
	"source_record_id" uuid,
	"proposal_id" uuid,
	"action" text,
	"position" integer,
	"owner_id" uuid NOT NULL,
	"component" text NOT NULL,
	"component_key" text NOT NULL,
	"before_revision_id" uuid,
	"after_revision_id" uuid NOT NULL,
	CONSTRAINT "publishing_component_source_application_change_pkey" PRIMARY KEY("source_record_id","proposal_id","action","position"),
	CONSTRAINT "publishing_child_application_components" CHECK ("component" in ('publishing_text_work', 'publishing_publication_text', 'publishing_publication_work', 'publishing_publication_facet', 'publishing_release_event', 'publishing_installment')),
	CONSTRAINT "publishing_child_application_values" CHECK ("position" between 0 and 127 and "action" in ('apply','withdraw') and octet_length("component") between 1 and 96 and octet_length("component_key")=36 and ("before_revision_id" is null or "before_revision_id"<>"after_revision_id"))
) PARTITION BY HASH ("source_record_id");
