CREATE TABLE "publishing_component_source_occurrence" (
	"source_record_id" uuid,
	"mapping_key" uuid,
	"correspondence_revision" bigint,
	"mapping_owner" text NOT NULL,
	"snapshot_id" uuid,
	"owner_id" uuid,
	"component" text,
	"component_key" text,
	"source_path" text NOT NULL,
	"history_id" uuid NOT NULL,
	"source_value" jsonb NOT NULL,
	"observed_fields" text[] NOT NULL,
	"source_target_id" uuid GENERATED ALWAYS AS ((source_value->'fields'->>'targetId')::uuid) STORED,
	"source_publisher_id" uuid GENERATED ALWAYS AS ((source_value->'fields'->>'publisherEntityId')::uuid) STORED,
	"source_area_id" uuid GENERATED ALWAYS AS ((source_value->'fields'->>'areaId')::uuid) STORED,
	"source_definition_revision_id" uuid GENERATED ALWAYS AS (coalesce(source_value->'fields'->>'definitionRevisionId',source_value->'fields'->>'kindRevisionId')::uuid) STORED,
	"source_parent_component" text GENERATED ALWAYS AS (case when source_value->'fields'->>'parentId' is not null then 'publishing_installment' else null end) STORED,
	"source_parent_key" text GENERATED ALWAYS AS (source_value->'fields'->>'parentId') STORED,
	CONSTRAINT "publishing_component_source_occurrence_pkey" PRIMARY KEY("source_record_id","mapping_key","correspondence_revision","snapshot_id","owner_id","component","component_key"),
	CONSTRAINT "publishing_component_source_owner" CHECK ("mapping_owner" in ('publishing', 'music', 'program', 'software', 'entity', 'grouping', 'reference', 'distribution')),
	CONSTRAINT "publishing_component_source_components" CHECK ("component" in ('publishing_text_work', 'publishing_publication_text', 'publishing_publication_work', 'publishing_publication_facet', 'publishing_release_event', 'publishing_installment')),
	CONSTRAINT "publishing_component_source_values" CHECK ("correspondence_revision" between 1 and 9007199254740991 and octet_length("component") between 1 and 96 and octet_length("component_key")=36 and left("source_path",1)='/' and octet_length("source_path") between 1 and 512 and jsonb_typeof("source_value")='object' and "source_value" ?& array['kind','fields'] and "source_value"-'kind'-'fields'='{}'::jsonb and jsonb_typeof("source_value"->'kind')='string' and jsonb_typeof("source_value"->'fields')='object' and octet_length("source_value"::text)<=1048576 and cardinality("observed_fields") between 0 and 32)
) PARTITION BY HASH ("source_record_id");
