CREATE TABLE "publishing_editorial" (
	"owner_id" uuid,
	"language" text,
	"revision" bigint NOT NULL,
	"state" text NOT NULL,
	"summary" text,
	"description" jsonb,
	"avatar_type" text,
	"avatar_asset_id" uuid,
	"avatar_emoji" text,
	"avatar_icon_prefix" text,
	"avatar_icon_name" text,
	"banner_asset_id" uuid,
	"cover_asset_id" uuid,
	"operator_auth_user_id" uuid NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "publishing_editorial_pkey" PRIMARY KEY("owner_id","language"),
	CONSTRAINT "publishing_editorial_revision_check" CHECK ("revision" between 1 and 9007199254740991),
	CONSTRAINT "publishing_editorial_language_check" CHECK (octet_length("language") between 1 and 255),
	CONSTRAINT "publishing_editorial_state_check" CHECK ("state" in ('active','withdrawn')),
	CONSTRAINT "publishing_editorial_summary_check" CHECK ("summary" is null or char_length("summary") <= 500),
	CONSTRAINT "publishing_editorial_description_check" CHECK ("description" is null or (jsonb_typeof("description")='object' and octet_length("description"::text) <= 1048576)),
	CONSTRAINT "publishing_editorial_avatar_check" CHECK (
		 ("avatar_type" is null and num_nonnulls("avatar_asset_id","avatar_emoji","avatar_icon_prefix","avatar_icon_name")=0)
		 or ("avatar_type"='image' and "avatar_asset_id" is not null and num_nonnulls("avatar_emoji","avatar_icon_prefix","avatar_icon_name")=0)
		 or ("avatar_type"='emoji' and char_length("avatar_emoji") between 1 and 64 and "avatar_emoji" is not null and num_nonnulls("avatar_asset_id","avatar_icon_prefix","avatar_icon_name")=0)
		 or ("avatar_type"='icon' and "avatar_icon_prefix" in ('fas','fab') and "avatar_icon_prefix" is not null and "avatar_icon_name" is not null and "avatar_icon_name" ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length("avatar_icon_name") <= 128 and num_nonnulls("avatar_asset_id","avatar_emoji")=0))
) PARTITION BY HASH ("owner_id");
CREATE TABLE "publishing_editorial_p00" PARTITION OF "publishing_editorial" FOR VALUES WITH (MODULUS 64, REMAINDER 0);
CREATE TABLE "publishing_editorial_p01" PARTITION OF "publishing_editorial" FOR VALUES WITH (MODULUS 64, REMAINDER 1);
CREATE TABLE "publishing_editorial_p02" PARTITION OF "publishing_editorial" FOR VALUES WITH (MODULUS 64, REMAINDER 2);
CREATE TABLE "publishing_editorial_p03" PARTITION OF "publishing_editorial" FOR VALUES WITH (MODULUS 64, REMAINDER 3);
