CREATE TABLE "publishing_fact" (
	"id" uuid DEFAULT uuidv7(),
	"owner_id" uuid,
	"definition_revision_id" uuid NOT NULL,
	"semantic_id" uuid DEFAULT uuidv7() NOT NULL,
	"expected_head_version" bigint DEFAULT 0 NOT NULL,
	"state" text DEFAULT 'active' NOT NULL,
	"purpose" text DEFAULT 'assertion' NOT NULL,
	"last_node_position" bigint DEFAULT -1 NOT NULL,
	"spoiler" integer DEFAULT 0 NOT NULL,
	"sealed_at" timestamp(3) with time zone,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "publishing_fact_identity_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "publishing_fact_spoiler_check" CHECK ("spoiler" between 0 and 2),
	CONSTRAINT "publishing_fact_head_version_check" CHECK ("expected_head_version" between 0 and 9007199254740990),
	CONSTRAINT "publishing_fact_state_check" CHECK ("state" in ('active', 'disputed', 'withdrawn', 'superseded')),
	CONSTRAINT "publishing_fact_purpose_check" CHECK ("purpose" in ('assertion','qualifier')),
	CONSTRAINT "publishing_fact_node_cursor_check" CHECK ("last_node_position" between -1 and 9007199254740991 and ("sealed_at" is null or "last_node_position" >= 0))
);

CREATE TABLE "publishing_fact_support" (
	"owner_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"source_record_id" uuid NOT NULL,
	"snapshot_id" uuid NOT NULL,
	"source_path" text NOT NULL,
	"fact_id" uuid,
	"relation_id" uuid,
	"named_form_id" uuid,
	"identifier_id" uuid,
	"identifier_revision" bigint,
	"source_mapping_key" uuid,
	"source_correspondence_revision" bigint,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"withdrawn_at" timestamp(3) with time zone,
	CONSTRAINT "publishing_support_identity_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "publishing_support_source_correspondence_pair" CHECK (("source_mapping_key" is null) = ("source_correspondence_revision" is null)),
	CONSTRAINT "publishing_support_identifier_revision_check" CHECK (("identifier_id" is null) = ("identifier_revision" is null)),
	CONSTRAINT "publishing_support_target_check" CHECK (num_nonnulls("fact_id", "relation_id", "named_form_id", "identifier_id") = 1),
	CONSTRAINT "publishing_support_source_path_check" CHECK (length("source_path") > 0)
);

CREATE TABLE "publishing_fact_value_node" (
	"owner_id" uuid,
	"fact_id" uuid,
	"position" bigint,
	"rule_position" integer DEFAULT 0 NOT NULL,
	"parent_position" bigint,
	"parent_kind" text,
	"member_key" text,
	"kind" text NOT NULL,
	"text_value" text,
	"number_value" numeric,
	"boolean_value" boolean,
	CONSTRAINT "publishing_fact_node_position_key" PRIMARY KEY("owner_id","fact_id","position"),
	CONSTRAINT "publishing_fact_node_kind_key" UNIQUE("owner_id","fact_id","position","kind"),
	CONSTRAINT "publishing_fact_node_member_key" UNIQUE("owner_id","fact_id","parent_position","member_key"),
	CONSTRAINT "publishing_fact_node_rule_check" CHECK ("rule_position" between 0 and 127),
	CONSTRAINT "publishing_fact_node_kind_check" CHECK ("kind" in ('null', 'string', 'number', 'boolean', 'object', 'array')),
	CONSTRAINT "publishing_fact_node_position_check" CHECK ("position" between 0 and 9007199254740991 and ("parent_position" is null or "parent_position" >= 0 and "parent_position" < "position")),
	CONSTRAINT "publishing_fact_node_parent_check" CHECK (("position" = 0 and "parent_position" is null and "parent_kind" is null and "member_key" is null) or ("position" > 0 and "parent_position" is not null and "parent_kind" is not null and (("parent_kind" = 'object' and "member_key" is not null) or ("parent_kind" = 'array' and "member_key" is null)))),
	CONSTRAINT "publishing_fact_node_number_check" CHECK ("number_value" is null or "number_value"::text not in ('NaN', 'Infinity', '-Infinity')),
	CONSTRAINT "publishing_fact_node_value_check" CHECK (("kind" = 'string' and "text_value" is not null and "number_value" is null and "boolean_value" is null) or ("kind" = 'number' and "number_value" is not null and "text_value" is null and "boolean_value" is null) or ("kind" = 'boolean' and "boolean_value" is not null and "text_value" is null and "number_value" is null) or ("kind" in ('null', 'object', 'array') and "text_value" is null and "number_value" is null and "boolean_value" is null))
);

CREATE TABLE "publishing_identifier_claim" (
	"owner_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"revision" bigint DEFAULT 1 NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_by_auth_user_id" uuid,
	"namespace" text NOT NULL,
	"value" text NOT NULL,
	"normalized_value" text NOT NULL,
	"normalization_policy" text DEFAULT 'exact.1' NOT NULL,
	"validation_status" text DEFAULT 'unvalidated' NOT NULL,
	"issuer_entity_id" uuid,
	"state" text DEFAULT 'active' NOT NULL,
	CONSTRAINT "publishing_identifier_identity_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "publishing_identifier_namespace_check" CHECK ("namespace" ~ '^[a-z][a-z0-9_.:-]{0,127}$'),
	CONSTRAINT "publishing_identifier_value_check" CHECK (octet_length("value") between 1 and 512 and octet_length("normalized_value") between 1 and 512 and octet_length("normalization_policy") between 1 and 96),
	CONSTRAINT "publishing_identifier_state_check" CHECK ("state" in ('active', 'disputed', 'withdrawn', 'superseded')),
	CONSTRAINT "publishing_identifier_validation_check" CHECK ("validation_status" in ('unvalidated', 'valid')),
	CONSTRAINT "publishing_identifier_revision_check" CHECK ("revision" between 1 and 9007199254740991)
);

CREATE TABLE "publishing_identifier_claim_revision" (
	"owner_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"revision" bigint DEFAULT 1,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_by_auth_user_id" uuid,
	"namespace" text NOT NULL,
	"value" text NOT NULL,
	"normalized_value" text NOT NULL,
	"normalization_policy" text DEFAULT 'exact.1' NOT NULL,
	"validation_status" text DEFAULT 'unvalidated' NOT NULL,
	"issuer_entity_id" uuid,
	"state" text DEFAULT 'active' NOT NULL,
	CONSTRAINT "publishing_identifier_revision_key" PRIMARY KEY("owner_id","id","revision")
);

CREATE TABLE "publishing_identity" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"shape" text NOT NULL,
	"status" text DEFAULT 'draft' NOT NULL,
	"visibility" text DEFAULT 'private' NOT NULL,
	"content_rating" text DEFAULT 'general' NOT NULL,
	"moderation_status" text DEFAULT 'approved' NOT NULL,
	"created_by_auth_user_id" uuid,
	"post_targeting_locked" boolean DEFAULT false NOT NULL,
	"revision" bigint DEFAULT 1 NOT NULL,
	"routing_generation" integer DEFAULT 1 NOT NULL,
	"deleted_at" timestamp(3) with time zone,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "publishing_identity_shape_key" UNIQUE("id","shape"),
	CONSTRAINT "publishing_identity_shape_check" CHECK ("shape" ~ '^[a-z][a-z0-9_.-]{0,95}$'),
	CONSTRAINT "publishing_identity_status_check" CHECK ("status" in ('draft', 'published', 'archived')),
	CONSTRAINT "publishing_identity_visibility_check" CHECK ("visibility" in ('public', 'unlisted', 'private')),
	CONSTRAINT "publishing_identity_rating_check" CHECK ("content_rating" in ('general', 'r15', 'r18', 'r18g')),
	CONSTRAINT "publishing_identity_moderation_check" CHECK ("moderation_status" in ('approved', 'pending', 'removed')),
	CONSTRAINT "publishing_identity_revision_check" CHECK ("revision" between 1 and 9007199254740991 and "routing_generation" > 0)
);

CREATE TABLE "publishing_installment" (
	"serialization_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"parent_id" uuid,
	"position" text collate "C" NOT NULL,
	"label" text,
	"kind_revision_id" uuid NOT NULL,
	"date_year" integer,
	"date_month" smallint,
	"date_day" smallint,
	"date_text" text,
	CONSTRAINT "publishing_installment_pkey" PRIMARY KEY("serialization_id","id"),
	CONSTRAINT "publishing_installment_position_check" CHECK (octet_length("position") <= 1024),
	CONSTRAINT "publishing_installment_parent_check" CHECK ("parent_id" is null or "parent_id" <> "id"),
	CONSTRAINT "publishing_installment_date_check" CHECK (
		("date_month" is null or "date_month" between 1 and 12)
		and ("date_day" is null or "date_day" between 1 and 31)
		and ("date_month" is null or "date_day" is null or "date_day" <= case
			when "date_month" in (4, 6, 9, 11) then 30
			when "date_month" = 2 then case when "date_year" is null
				or mod("date_year", 400) = 0 or (mod("date_year", 4) = 0 and mod("date_year", 100) <> 0) then 29 else 28 end
			else 31 end))
);

CREATE TABLE "publishing_name_authority" (
	"owner_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"revision" bigint DEFAULT 1 NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_by_auth_user_id" uuid,
	"name_id" uuid NOT NULL,
	"name_revision" bigint NOT NULL,
	"claim" text NOT NULL,
	"review_state" text NOT NULL,
	"authorizer_entity_id" uuid,
	"role" text NOT NULL,
	"territory" text,
	"channel" text,
	"context" text,
	"valid_from" timestamp(3) with time zone,
	"valid_until" timestamp(3) with time zone,
	"source_record_id" uuid NOT NULL,
	"snapshot_id" uuid NOT NULL,
	"source_path" text NOT NULL,
	"review_source_record_id" uuid,
	"review_snapshot_id" uuid,
	"review_source_path" text,
	"state" text NOT NULL,
	CONSTRAINT "publishing_name_authority_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "publishing_name_authority_revision_check" CHECK ("revision" between 1 and 9007199254740991),
	CONSTRAINT "publishing_name_authority_claim_check" CHECK ("claim" in ('official', 'unofficial', 'unknown')),
	CONSTRAINT "publishing_name_authority_review_check" CHECK ("review_state" in ('source_claim', 'pending', 'verified', 'rejected')),
	CONSTRAINT "publishing_name_authority_state_check" CHECK ("state" in ('active', 'withdrawn')),
	CONSTRAINT "publishing_name_authority_proof_check" CHECK (("review_state" <> 'verified' or ("authorizer_entity_id" is not null and "review_snapshot_id" is not null)) and num_nonnulls("review_source_record_id","review_snapshot_id","review_source_path") in (0,3)),
	CONSTRAINT "publishing_name_authority_time_check" CHECK ("valid_from" is null or "valid_until" is null or "valid_until" > "valid_from"),
	CONSTRAINT "publishing_name_authority_scope_check" CHECK (octet_length("role") between 1 and 96 and octet_length("source_path") between 1 and 4096 and ("review_source_path" is null or octet_length("review_source_path") between 1 and 4096) and ("territory" is null or octet_length("territory") between 1 and 96) and ("channel" is null or octet_length("channel") between 1 and 96) and ("context" is null or octet_length("context") between 1 and 512))
);

CREATE TABLE "publishing_name_authority_revision" (
	"owner_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"revision" bigint DEFAULT 1,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_by_auth_user_id" uuid,
	"name_id" uuid NOT NULL,
	"name_revision" bigint NOT NULL,
	"claim" text NOT NULL,
	"review_state" text NOT NULL,
	"authorizer_entity_id" uuid,
	"role" text NOT NULL,
	"territory" text,
	"channel" text,
	"context" text,
	"valid_from" timestamp(3) with time zone,
	"valid_until" timestamp(3) with time zone,
	"source_record_id" uuid NOT NULL,
	"snapshot_id" uuid NOT NULL,
	"source_path" text NOT NULL,
	"review_source_record_id" uuid,
	"review_snapshot_id" uuid,
	"review_source_path" text,
	"state" text NOT NULL,
	CONSTRAINT "publishing_name_authority_revision_key" PRIMARY KEY("owner_id","id","revision")
);

CREATE TABLE "publishing_name_source_binding" (
	"owner_id" uuid,
