CREATE TABLE "publishing_source_owned_baseline" (
	"source_record_id" uuid,
	"mapping_owner" text NOT NULL,
	"mapping_key" uuid,
	"correspondence_revision" bigint,
	"owner_id" uuid,
	"source_snapshot_id" uuid NOT NULL,
	"source_path" text NOT NULL,
	"source_revision" bigint NOT NULL,
	"current_revision" bigint NOT NULL,
	"absent" boolean DEFAULT false NOT NULL,
	"last_proposal_id" uuid NOT NULL,
	"last_action" text NOT NULL,
	"kind" text,
	"component_key" uuid,
	"semantic_id" uuid,
	"name_id" uuid,
	"authority_id" uuid,
	"identifier_id" uuid,
	CONSTRAINT "publishing_source_owned_baseline_pkey" PRIMARY KEY("source_record_id","mapping_key","correspondence_revision","owner_id","kind","component_key"),
	CONSTRAINT "publishing_source_owned_base_owner" CHECK ("mapping_owner" in ('publishing', 'music', 'program', 'software', 'entity', 'grouping', 'reference', 'distribution')),
	CONSTRAINT "publishing_source_owned_base_values" CHECK (octet_length("source_path") between 1 and 512 and "source_revision" between 1 and 9007199254740991 and "current_revision" between 1 and 9007199254740991),
	CONSTRAINT "publishing_source_owned_base_kind" CHECK (num_nonnulls("semantic_id","name_id","authority_id","identifier_id") = 1 and (("kind" = 'catalog-semantic' and "component_key" = "semantic_id") or ("kind" = 'catalog-name' and "component_key" = "name_id") or ("kind" = 'catalog-name-authority' and "component_key" = "authority_id") or ("kind" = 'catalog-identifier' and "component_key" = "identifier_id")))
) PARTITION BY HASH ("source_record_id");
