CREATE TABLE "publishing_structure_source_occurrence" (
	"source_record_id" uuid,
	"mapping_key" uuid,
	"correspondence_revision" bigint,
	"mapping_owner" text NOT NULL,
	"snapshot_id" uuid,
	"owner_id" uuid,
	"component" text,
	"component_key" text,
	"source_path" text NOT NULL,
	"history_id" uuid NOT NULL,
	"source_value" jsonb NOT NULL,
	"observed_fields" text[] NOT NULL,
	"source_parent_id" uuid GENERATED ALWAYS AS ((source_value->'fields'->>'textVersionId')::uuid) STORED,
	"source_secondary_parent_id" uuid GENERATED ALWAYS AS (null::uuid) STORED,
	"source_type_revision_id" uuid GENERATED ALWAYS AS ((source_value->'fields'->>'statusRevisionId')::uuid) STORED,
	"source_method_revision_id" uuid GENERATED ALWAYS AS ((source_value->'fields'->>'methodRevisionId')::uuid) STORED,
	CONSTRAINT "publishing_structure_source_occurrence_pkey" PRIMARY KEY("source_record_id","mapping_key","correspondence_revision","snapshot_id","owner_id","component","component_key"),
	CONSTRAINT "publishing_structure_source_owner" CHECK ("mapping_owner" in ('publishing', 'music', 'program', 'software', 'entity', 'grouping', 'reference', 'distribution')),
	CONSTRAINT "publishing_structure_source_components" CHECK ("component" in ('publishing_work', 'publishing_text_version', 'publishing_publication', 'publishing_serialization')),
	CONSTRAINT "publishing_structure_source_values" CHECK ("correspondence_revision" between 1 and 9007199254740991 and octet_length("component") between 1 and 96 and "component_key"="owner_id"::text and left("source_path",1)='/' and octet_length("source_path") between 1 and 512 and jsonb_typeof("source_value")='object' and "source_value" ?& array['shape','fields'] and "source_value"-'shape'-'fields'='{}'::jsonb and jsonb_typeof("source_value"->'shape')='string' and jsonb_typeof("source_value"->'fields')='object' and octet_length("source_value"::text)<=1048576 and cardinality("observed_fields") between 0 and 32)
) PARTITION BY HASH ("source_record_id");
CREATE TABLE "publishing_structure_source_occurrence_p00" PARTITION OF "publishing_structure_source_occurrence" FOR VALUES WITH (MODULUS 64, REMAINDER 0);
