CREATE TABLE "publishing_text_version" (
	"id" uuid PRIMARY KEY,
	"identity_shape" text DEFAULT 'text_version' NOT NULL,
	"language_tag" text,
	"method_revision_id" uuid,
	CONSTRAINT "publishing_text_version_shape_check" CHECK ("identity_shape" = 'text_version'),
	CONSTRAINT "publishing_text_language_check" CHECK ("language_tag" is null or octet_length("language_tag") between 1 and 255)
);

CREATE TABLE "publishing_text_work" (
	"text_version_id" uuid,
	"work_id" uuid,
	"position" bigint NOT NULL,
	"coverage_text" text,
	CONSTRAINT "publishing_text_work_pkey" PRIMARY KEY("text_version_id","work_id"),
	CONSTRAINT "publishing_text_work_position_check" CHECK ("position" between 0 and 9007199254740991)
);

CREATE TABLE "publishing_work" (
	"id" uuid PRIMARY KEY,
	"identity_shape" text DEFAULT 'work' NOT NULL,
	CONSTRAINT "publishing_work_shape_check" CHECK ("identity_shape" = 'work')
);

CREATE TABLE "realm" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"revision" bigint DEFAULT 1 NOT NULL,
	"routing_generation" integer DEFAULT 1 NOT NULL,
	"created_by_auth_user_id" uuid,
	"status" "unit_status" DEFAULT 'draft'::"unit_status" NOT NULL,
	"visibility" "resource_visibility" DEFAULT 'public'::"resource_visibility" NOT NULL,
	"content_rating" "content_rating" DEFAULT 'general'::"content_rating" NOT NULL,
	"ai_disclosure" "ai_disclosure" DEFAULT 'unknown'::"ai_disclosure" NOT NULL,
	"moderation_status" "moderation_status" DEFAULT 'approved'::"moderation_status" NOT NULL,
	"post_targeting_locked" boolean DEFAULT false NOT NULL,
	"published_at" timestamp(3) with time zone,
	"deleted_at" timestamp(3) with time zone,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"join_policy" "realm_join_policy" DEFAULT 'open'::"realm_join_policy" NOT NULL,
	"realm_tag_voting_enabled" boolean DEFAULT false NOT NULL,
	"tag_fit_fallback_policy" "realm_tag_fallback_policy" DEFAULT 'inherit'::"realm_tag_fallback_policy" NOT NULL,
	"tag_spoiler_fallback_policy" "realm_tag_fallback_policy" DEFAULT 'inherit'::"realm_tag_fallback_policy" NOT NULL,
	"enabled_pages" "realm_page_kind"[] DEFAULT array['main']::"realm_page_kind"[] NOT NULL,
	CONSTRAINT "realm_identity_revision_check" CHECK ("revision" between 1 and 9007199254740991 and "routing_generation" between 1 and 2147483647),
	CONSTRAINT "realm_identity_publication_check" CHECK ("status" <> 'published' or "published_at" is not null),
	CONSTRAINT "realm_identity_deleted_at_check" CHECK ("deleted_at" is null or "deleted_at" >= "created_at"),
	CONSTRAINT "realm_enabled_pages_cardinality_check" CHECK (cardinality("enabled_pages") between 1 and 3),
	CONSTRAINT "realm_enabled_pages_main_check" CHECK (cardinality(array_positions("enabled_pages", 'main'::realm_page_kind)) = 1),
	CONSTRAINT "realm_enabled_pages_no_null_check" CHECK (array_position("enabled_pages", null) is null),
	CONSTRAINT "realm_enabled_pages_tags_unique_check" CHECK (cardinality(array_positions("enabled_pages", 'tags'::realm_page_kind)) <= 1),
	CONSTRAINT "realm_enabled_pages_wiki_unique_check" CHECK (cardinality(array_positions("enabled_pages", 'wiki'::realm_page_kind)) <= 1)
);

CREATE TABLE "realm_member" (
	"realm_id" uuid,
	"profile_id" uuid,
	"state" "realm_member_state" DEFAULT 'active'::"realm_member_state" NOT NULL,
	"joined_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "realm_member_pkey" PRIMARY KEY("realm_id","profile_id")
);

CREATE TABLE "realm_pin" (
	"realm_id" uuid,
	"unit_id" uuid,
	"unit_publishing_id" uuid,
	"unit_music_id" uuid,
	"unit_program_id" uuid,
	"unit_software_id" uuid,
	"unit_entity_id" uuid,
	"unit_grouping_id" uuid,
	"unit_reference_id" uuid,
	"unit_distribution_id" uuid,
	"unit_video_id" uuid,
	"unit_audio_id" uuid,
	"unit_post_id" uuid,
	"unit_poll_id" uuid,
	"unit_zone_id" uuid,
	"unit_realm_id" uuid,
	"unit_realm_rule_id" uuid,
	"unit_custom_theme_id" uuid,
	"unit_collection_id" uuid,
	"unit_tag_id" uuid,
	"unit_tag_path_id" uuid,
	"unit_label_id" uuid,
	"kind" "realm_pin_kind" DEFAULT 'pinned'::"realm_pin_kind" NOT NULL,
	"position" text collate "C" DEFAULT 'a0' NOT NULL,
	"created_by_profile_id" uuid,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "realm_pin_pkey" PRIMARY KEY("realm_id","unit_id"),
	CONSTRAINT "realm_pin_unit_target_check" CHECK (num_nonnulls("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id") = 1),
	CONSTRAINT "realm_pin_unit_id_check" CHECK ("unit_id" is not distinct from coalesce("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id")),
	CONSTRAINT "realm_pin_not_self_check" CHECK ("realm_id" <> "unit_id"),
	CONSTRAINT "realm_pin_position_byte_length_check" CHECK (octet_length("position") <= 1024)
);

CREATE TABLE "realm_rule" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"revision" bigint DEFAULT 1 NOT NULL,
	"routing_generation" integer DEFAULT 1 NOT NULL,
	"created_by_auth_user_id" uuid,
	"status" "unit_status" DEFAULT 'draft'::"unit_status" NOT NULL,
	"visibility" "resource_visibility" DEFAULT 'public'::"resource_visibility" NOT NULL,
	"content_rating" "content_rating" DEFAULT 'general'::"content_rating" NOT NULL,
	"ai_disclosure" "ai_disclosure" DEFAULT 'unknown'::"ai_disclosure" NOT NULL,
	"moderation_status" "moderation_status" DEFAULT 'approved'::"moderation_status" NOT NULL,
	"post_targeting_locked" boolean DEFAULT false NOT NULL,
	"published_at" timestamp(3) with time zone,
	"deleted_at" timestamp(3) with time zone,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"revision_id" uuid NOT NULL,
	"position" integer NOT NULL,
	CONSTRAINT "realm_rule_id_revision_key" UNIQUE("id","revision_id"),
	CONSTRAINT "realm_rule_identity_revision_check" CHECK ("revision" between 1 and 9007199254740991 and "routing_generation" between 1 and 2147483647),
	CONSTRAINT "realm_rule_identity_publication_check" CHECK ("status" <> 'published' or "published_at" is not null),
	CONSTRAINT "realm_rule_identity_deleted_at_check" CHECK ("deleted_at" is null or "deleted_at" >= "created_at")
);

CREATE TABLE "realm_rule_acceptance" (
	"revision_id" uuid,
	"profile_id" uuid,
	"language" text,
	"accepted_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "realm_rule_acceptance_pkey" PRIMARY KEY("revision_id","profile_id"),
	CONSTRAINT "realm_rule_acceptance_language_check" CHECK ("language" is null or "language" in ('zh', 'en', 'ja', 'ko', 'de', 'fr', 'es'))
);

CREATE TABLE "realm_rule_revision" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"realm_id" uuid NOT NULL,
	"version" integer NOT NULL,
	"acknowledgement_mode" "realm_rule_acknowledgement_mode" DEFAULT 'explicit'::"realm_rule_acknowledgement_mode" NOT NULL,
	"require_on_join" boolean DEFAULT false NOT NULL,
	"require_on_post" boolean DEFAULT false NOT NULL,
	"created_by_profile_id" uuid,
	"published_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "realm_rule_revision_realm_version_key" UNIQUE("realm_id","version"),
	CONSTRAINT "realm_rule_revision_realm_id_key" UNIQUE("realm_id","id"),
	CONSTRAINT "realm_rule_revision_version_check" CHECK ("version" > 0)
);

CREATE TABLE "realm_score_context" (
	"realm_id" uuid PRIMARY KEY,
	"context_post_id" uuid NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "realm_stat" (
	"realm_id" uuid PRIMARY KEY,
	"active_member_count" bigint DEFAULT 0 NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "realm_stat_count_check" CHECK ("active_member_count" >= 0)
);

CREATE TABLE "realm_tag_context" (
	"realm_id" uuid,
	"tag_id" uuid,
	"context_post_id" uuid NOT NULL,
	"created_by_profile_id" uuid,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "realm_tag_context_pkey" PRIMARY KEY("realm_id","tag_id")
);

CREATE TABLE "realm_tag_judgment" (
	"realm_id" uuid,
	"unit_id" uuid,
	"unit_publishing_id" uuid,
	"unit_music_id" uuid,
	"unit_program_id" uuid,
	"unit_software_id" uuid,
	"unit_entity_id" uuid,
	"unit_grouping_id" uuid,
	"unit_reference_id" uuid,
	"unit_distribution_id" uuid,
	"unit_video_id" uuid,
	"unit_audio_id" uuid,
	"unit_post_id" uuid,
	"unit_poll_id" uuid,
	"unit_zone_id" uuid,
	"unit_realm_id" uuid,
	"unit_realm_rule_id" uuid,
	"unit_custom_theme_id" uuid,
	"unit_collection_id" uuid,
	"unit_tag_id" uuid,
	"unit_tag_path_id" uuid,
	"unit_label_id" uuid,
	"tag_id" uuid,
	"profile_id" uuid,
	"fit_vote" integer,
	"spoiler_level" smallint,
	"fit_updated_at" timestamp(3) with time zone,
	"spoiler_updated_at" timestamp(3) with time zone,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "realm_tag_judgment_pkey" PRIMARY KEY("realm_id","unit_id","tag_id","profile_id"),
	CONSTRAINT "realm_tag_judgment_unit_target_check" CHECK (num_nonnulls("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id") = 1),
	CONSTRAINT "realm_tag_judgment_unit_id_check" CHECK ("unit_id" is not distinct from coalesce("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id")),
	CONSTRAINT "realm_tag_judgment_not_self_check" CHECK ("unit_id" <> "tag_id"),
	CONSTRAINT "realm_tag_judgment_fit_vote_check" CHECK ("fit_vote" is null or "fit_vote" in (-1, 1)),
	CONSTRAINT "realm_tag_judgment_spoiler_level_check" CHECK ("spoiler_level" is null or "spoiler_level" between 0 and 2),
	CONSTRAINT "realm_tag_judgment_sparse_check" CHECK ("fit_vote" is not null or "spoiler_level" is not null),
	CONSTRAINT "realm_tag_judgment_fit_timestamp_check" CHECK (("fit_vote" is null) = ("fit_updated_at" is null)),
	CONSTRAINT "realm_tag_judgment_spoiler_timestamp_check" CHECK (("spoiler_level" is null) = ("spoiler_updated_at" is null))
);

