	CONSTRAINT "realm_tag_judgment_stat_pkey" PRIMARY KEY("realm_id","unit_id","tag_id"),
	CONSTRAINT "realm_tag_judgment_stat_unit_target_check" CHECK (num_nonnulls("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id") = 1),
	CONSTRAINT "realm_tag_judgment_stat_unit_id_check" CHECK ("unit_id" is not distinct from coalesce("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id")),
	CONSTRAINT "realm_tag_judgment_stat_count_check" CHECK ("vote_count" >= 0),
	CONSTRAINT "realm_tag_judgment_stat_score_check" CHECK (abs("score") <= "vote_count"),
	CONSTRAINT "realm_tag_judgment_stat_parity_check" CHECK (("vote_count" + "score") % 2 = 0),
	CONSTRAINT "realm_tag_judgment_stat_spoiler_nonnegative_check" CHECK ("spoiler_vote_count" >= 0
				and "spoiler_none_count" >= 0
				and "spoiler_minor_count" >= 0
				and "spoiler_major_count" >= 0),
	CONSTRAINT "realm_tag_judgment_stat_spoiler_count_check" CHECK ("spoiler_vote_count" =
				"spoiler_none_count" + "spoiler_minor_count" + "spoiler_major_count")
);

