	"spoiler_major_count" bigint DEFAULT 0 NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "realm_unit_tag_path_application_judgment_stat_count_check" CHECK ("vote_count" >= 0),
	CONSTRAINT "realm_unit_tag_path_application_judgment_stat_score_check" CHECK (abs("score") <= "vote_count"),
	CONSTRAINT "realm_unit_tag_path_application_judgment_stat_parity_check" CHECK (("vote_count" + "score") % 2 = 0),
	CONSTRAINT "realm_unit_tag_path_application_judgment_stat_spoiler_nonnegative_check" CHECK ("spoiler_vote_count" >= 0
				and "spoiler_none_count" >= 0
				and "spoiler_minor_count" >= 0
				and "spoiler_major_count" >= 0),
	CONSTRAINT "realm_unit_tag_path_application_judgment_stat_spoiler_count_check" CHECK ("spoiler_vote_count" =
				"spoiler_none_count" + "spoiler_minor_count" + "spoiler_major_count")
