CREATE TABLE "recommendation_metric_daily" (
	"day" date,
	"shard" smallint,
	"surface" "recommendation_surface",
	"policy_version" text,
	"impressions" bigint DEFAULT 0 NOT NULL,
	"opens" bigint DEFAULT 0 NOT NULL,
	"dwell_30s" bigint DEFAULT 0 NOT NULL,
	"not_interested" bigint DEFAULT 0 NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "recommendation_metric_daily_pkey" PRIMARY KEY("day","surface","policy_version","shard"),
	CONSTRAINT "recommendation_metric_daily_shard_check" CHECK ("shard" between 0 and 127),
	CONSTRAINT "recommendation_metric_daily_policy_version_not_blank" CHECK (btrim("policy_version") <> ''),
	CONSTRAINT "recommendation_metric_daily_counts_check" CHECK ("impressions" >= 0 and "opens" >= 0 and "dwell_30s" >= 0 and "not_interested" >= 0)
);

CREATE TABLE "recommendation_snapshot" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"policy_version" text NOT NULL,
	"state" "recommendation_snapshot_state" DEFAULT 'building'::"recommendation_snapshot_state" NOT NULL,
	"active" boolean DEFAULT false NOT NULL,
	"source_watermark" timestamp(3) with time zone,
	"started_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"completed_at" timestamp(3) with time zone,
	"error" text,
	CONSTRAINT "recommendation_snapshot_policy_watermark_key" UNIQUE("policy_version","source_watermark"),
	CONSTRAINT "recommendation_snapshot_policy_version_not_blank" CHECK (btrim("policy_version") <> ''),
	CONSTRAINT "recommendation_snapshot_active_ready_check" CHECK (not "active" or ("state" = 'ready'::recommendation_snapshot_state and "completed_at" is not null)),
	CONSTRAINT "recommendation_snapshot_completion_check" CHECK (("state" = 'building'::recommendation_snapshot_state and "completed_at" is null) or ("state" <> 'building'::recommendation_snapshot_state and "completed_at" is not null))
);

CREATE TABLE "recommendation_snapshot_partition" (
	"snapshot_id" uuid,
	"bucket" smallint,
	"state" text DEFAULT 'pending' NOT NULL,
	"generation" bigint DEFAULT 0 NOT NULL,
	"lease_token" uuid,
	"lease_expires_at" timestamp(3) with time zone,
	"after_bucket_start" timestamp(3) with time zone,
	"after_unit_id" uuid,
	"after_kind" text,
	"scanned_rows" bigint DEFAULT 0 NOT NULL,
	"failures" smallint DEFAULT 0 NOT NULL,
	"next_attempt_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"error" text,
	CONSTRAINT "recommendation_snapshot_partition_pkey" PRIMARY KEY("snapshot_id","bucket"),
	CONSTRAINT "recommendation_snapshot_partition_values" CHECK ("bucket" between 0 and 63 and "state" in ('pending','working','done','failed') and "generation" between 0 and 9007199254740991 and "scanned_rows">=0 and "failures" between 0 and 12 and ("error" is null or octet_length("error")<=2048)),
	CONSTRAINT "recommendation_snapshot_partition_lease" CHECK (("state"='working') = ("lease_token" is not null and "lease_expires_at" is not null) and num_nonnulls("lease_token","lease_expires_at") in (0,2)),
	CONSTRAINT "recommendation_snapshot_partition_cursor" CHECK (num_nonnulls("after_bucket_start","after_unit_id","after_kind") in (0,3))
);

CREATE TABLE "recommendation_unit_signal_hourly" (
	"unit_id" uuid,
	"bucket_start" timestamp(3) with time zone,
