CREATE TABLE "reference_area" (
	"id" uuid PRIMARY KEY,
	"identity_shape" text DEFAULT 'area' NOT NULL,
	"date_year" integer,
	"date_month" smallint,
	"date_day" smallint,
	"date_text" text,
	"end_year" integer,
	"end_month" smallint,
	"end_day" smallint,
	"end_text" text,
	"ended" boolean,
	"type_revision_id" uuid,
	CONSTRAINT "reference_area_shape_check" CHECK ("identity_shape" = 'area'),
	CONSTRAINT "reference_area_begin_check" CHECK (
		("date_month" is null or "date_month" between 1 and 12)
		and ("date_day" is null or "date_day" between 1 and 31)
		and ("date_month" is null or "date_day" is null or "date_day" <= case
			when "date_month" in (4, 6, 9, 11) then 30
			when "date_month" = 2 then case when "date_year" is null
				or mod("date_year", 400) = 0 or (mod("date_year", 4) = 0 and mod("date_year", 100) <> 0) then 29 else 28 end
			else 31 end)),
	CONSTRAINT "reference_area_end_check" CHECK (
		("end_month" is null or "end_month" between 1 and 12)
		and ("end_day" is null or "end_day" between 1 and 31)
		and ("end_month" is null or "end_day" is null or "end_day" <= case
			when "end_month" in (4, 6, 9, 11) then 30
			when "end_month" = 2 then case when "end_year" is null
				or mod("end_year", 400) = 0 or (mod("end_year", 4) = 0 and mod("end_year", 100) <> 0) then 29 else 28 end
			else 31 end))
);

CREATE TABLE "reference_area_code" (
	"area_id" uuid,
	"namespace" text,
	"code" text,
	CONSTRAINT "reference_area_code_pkey" PRIMARY KEY("area_id","namespace","code"),
	CONSTRAINT "reference_area_code_size_check" CHECK (octet_length("namespace") between 1 and 64 and octet_length("code") between 1 and 128)
);

CREATE TABLE "reference_catalog_change" (
	"id" uuid DEFAULT uuidv7(),
	"owner_id" uuid,
	"version" bigint NOT NULL,
	"actor_auth_user_id" uuid,
	"operation" text NOT NULL,
	"recorded_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"withdrawn_at" timestamp(3) with time zone,
	CONSTRAINT "reference_change_identity_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "reference_change_version_key" UNIQUE("owner_id","version"),
	CONSTRAINT "reference_change_version_check" CHECK ("version" between 1 and 9007199254740991),
	CONSTRAINT "reference_change_operation_check" CHECK (length("operation") between 1 and 96)
);

CREATE TABLE "reference_catalog_profile_revision" (
	"owner_id" uuid,
	"revision" bigint,
	"removed" boolean DEFAULT false NOT NULL,
	"snapshot" jsonb NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "reference_catalog_profile_revision_pkey" PRIMARY KEY("owner_id","revision"),
	CONSTRAINT "reference_catalog_profile_revision_number_check" CHECK ("revision" between 1 and 9007199254740991),
	CONSTRAINT "reference_catalog_profile_revision_snapshot_check" CHECK (jsonb_typeof("snapshot") = 'object' and octet_length("snapshot"::text) <= 131072)
);

CREATE TABLE "reference_catalog_relation" (
	"id" uuid DEFAULT uuidv7(),
	"owner_id" uuid,
	"definition_revision_id" uuid NOT NULL,
	"semantic_id" uuid DEFAULT uuidv7() NOT NULL,
	"expected_head_version" bigint DEFAULT 0 NOT NULL,
	"state" text DEFAULT 'active' NOT NULL,
	"revision" bigint DEFAULT 1 NOT NULL,
	"spoiler" integer DEFAULT 0 NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "reference_relation_owner_id_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "reference_relation_head_version_check" CHECK ("expected_head_version" between 0 and 9007199254740990),
	CONSTRAINT "reference_relation_spoiler_check" CHECK ("spoiler" between 0 and 2),
	CONSTRAINT "reference_relation_state_check" CHECK ("state" in ('active', 'disputed', 'withdrawn', 'superseded')),
	CONSTRAINT "reference_relation_revision_check" CHECK ("revision" between 1 and 9007199254740991)
);

CREATE TABLE "reference_concept" (
	"id" uuid PRIMARY KEY,
	"identity_shape" text DEFAULT 'concept' NOT NULL,
	"type_revision_id" uuid,
	CONSTRAINT "reference_concept_shape_check" CHECK ("identity_shape" = 'concept')
);

CREATE TABLE "reference_editorial" (
	"owner_id" uuid,
	"language" text,
	"revision" bigint NOT NULL,
	"state" text NOT NULL,
	"summary" text,
	"description" jsonb,
	"avatar_type" text,
	"avatar_asset_id" uuid,
	"avatar_emoji" text,
	"avatar_icon_prefix" text,
	"avatar_icon_name" text,
	"banner_asset_id" uuid,
	"cover_asset_id" uuid,
	"operator_auth_user_id" uuid NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "reference_editorial_pkey" PRIMARY KEY("owner_id","language"),
	CONSTRAINT "reference_editorial_revision_check" CHECK ("revision" between 1 and 9007199254740991),
	CONSTRAINT "reference_editorial_language_check" CHECK (octet_length("language") between 1 and 255),
	CONSTRAINT "reference_editorial_state_check" CHECK ("state" in ('active','withdrawn')),
	CONSTRAINT "reference_editorial_summary_check" CHECK ("summary" is null or char_length("summary") <= 500),
	CONSTRAINT "reference_editorial_description_check" CHECK ("description" is null or (jsonb_typeof("description")='object' and octet_length("description"::text) <= 1048576)),
	CONSTRAINT "reference_editorial_avatar_check" CHECK (
		 ("avatar_type" is null and num_nonnulls("avatar_asset_id","avatar_emoji","avatar_icon_prefix","avatar_icon_name")=0)
		 or ("avatar_type"='image' and "avatar_asset_id" is not null and num_nonnulls("avatar_emoji","avatar_icon_prefix","avatar_icon_name")=0)
		 or ("avatar_type"='emoji' and char_length("avatar_emoji") between 1 and 64 and "avatar_emoji" is not null and num_nonnulls("avatar_asset_id","avatar_icon_prefix","avatar_icon_name")=0)
		 or ("avatar_type"='icon' and "avatar_icon_prefix" in ('fas','fab') and "avatar_icon_prefix" is not null and "avatar_icon_name" is not null and "avatar_icon_name" ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length("avatar_icon_name") <= 128 and num_nonnulls("avatar_asset_id","avatar_emoji")=0))
) PARTITION BY HASH ("owner_id");
