	CONSTRAINT "reference_name_source_occurrence_path_check" CHECK (octet_length("source_path") between 1 and 4096)
);

CREATE TABLE "reference_named_form" (
	"owner_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"revision" bigint DEFAULT 1 NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_by_auth_user_id" uuid,
	"language_tag" text,
	"private_use_namespace" text,
	"language_policy" text,
	"kind" text NOT NULL,
	"value" text NOT NULL,
	"sort_name" text,
	"origin" text DEFAULT 'unknown' NOT NULL,
	"translation_method" text DEFAULT 'unknown' NOT NULL,
	"primary_for_language" boolean,
	"scope_owner_id" uuid,
	"territory" text,
	"context" text,
	"derivation_name_id" uuid,
	"derivation_revision" bigint,
	"begin" jsonb,
	"end" jsonb,
	"ended" boolean,
	"spoiler" integer DEFAULT 0 NOT NULL,
	"state" text DEFAULT 'active' NOT NULL,
	CONSTRAINT "reference_named_form_identity_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "reference_named_form_state_check" CHECK ("state" in ('active', 'disputed', 'withdrawn', 'superseded')),
	CONSTRAINT "reference_named_form_revision_check" CHECK ("revision" between 1 and 9007199254740991),
	CONSTRAINT "reference_named_form_kind_check" CHECK (octet_length("kind") between 1 and 96),
	CONSTRAINT "reference_named_form_value_check" CHECK (octet_length("value") between 1 and 131072 and ("sort_name" is null or octet_length("sort_name") between 1 and 131072)),
	CONSTRAINT "reference_named_form_language_check" CHECK (("language_tag" is null and "language_policy" is null and "private_use_namespace" is null) or ("language_tag" is not null and octet_length("language_tag") between 1 and 255 and "language_policy" is not null and ("private_use_namespace" is null or octet_length("private_use_namespace") between 1 and 512))),
	CONSTRAINT "reference_named_form_origin_check" CHECK ("origin" in ('original', 'translation', 'transliteration', 'abbreviation', 'variant', 'unknown')),
	CONSTRAINT "reference_named_form_method_check" CHECK ("translation_method" in ('human', 'machine', 'mixed', 'unknown', 'not_applicable')),
	CONSTRAINT "reference_named_form_derivation_check" CHECK (num_nonnulls("derivation_name_id","derivation_revision") in (0,2)),
	CONSTRAINT "reference_named_form_spoiler_check" CHECK ("spoiler" between 0 and 2),
	CONSTRAINT "reference_named_form_scope_check" CHECK (("territory" is null or octet_length("territory") between 1 and 96) and ("context" is null or octet_length("context") between 1 and 512))
);

CREATE TABLE "reference_named_form_revision" (
	"owner_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"revision" bigint DEFAULT 1,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"recorded_by_auth_user_id" uuid,
	"language_tag" text,
	"private_use_namespace" text,
	"language_policy" text,
	"kind" text NOT NULL,
	"value" text NOT NULL,
	"sort_name" text,
	"origin" text DEFAULT 'unknown' NOT NULL,
	"translation_method" text DEFAULT 'unknown' NOT NULL,
	"primary_for_language" boolean,
	"scope_owner_id" uuid,
	"territory" text,
	"context" text,
	"derivation_name_id" uuid,
	"derivation_revision" bigint,
	"begin" jsonb,
	"end" jsonb,
	"ended" boolean,
	"spoiler" integer DEFAULT 0 NOT NULL,
	"state" text DEFAULT 'active' NOT NULL,
	CONSTRAINT "reference_named_form_revision_key" PRIMARY KEY("owner_id","id","revision")
);

CREATE TABLE "reference_place" (
	"id" uuid PRIMARY KEY,
	"identity_shape" text DEFAULT 'place' NOT NULL,
	"date_year" integer,
	"date_month" smallint,
	"date_day" smallint,
	"date_text" text,
	"end_year" integer,
	"end_month" smallint,
	"end_day" smallint,
	"end_text" text,
	"ended" boolean,
	"area_id" uuid,
	"type_revision_id" uuid,
	"address" text,
	"latitude" numeric,
	"longitude" numeric,
	CONSTRAINT "reference_place_shape_check" CHECK ("identity_shape" = 'place'),
	CONSTRAINT "reference_place_begin_check" CHECK (
		("date_month" is null or "date_month" between 1 and 12)
		and ("date_day" is null or "date_day" between 1 and 31)
		and ("date_month" is null or "date_day" is null or "date_day" <= case
			when "date_month" in (4, 6, 9, 11) then 30
			when "date_month" = 2 then case when "date_year" is null
				or mod("date_year", 400) = 0 or (mod("date_year", 4) = 0 and mod("date_year", 100) <> 0) then 29 else 28 end
			else 31 end)),
	CONSTRAINT "reference_place_end_check" CHECK (
		("end_month" is null or "end_month" between 1 and 12)
		and ("end_day" is null or "end_day" between 1 and 31)
		and ("end_month" is null or "end_day" is null or "end_day" <= case
			when "end_month" in (4, 6, 9, 11) then 30
			when "end_month" = 2 then case when "end_year" is null
				or mod("end_year", 400) = 0 or (mod("end_year", 4) = 0 and mod("end_year", 100) <> 0) then 29 else 28 end
			else 31 end)),
	CONSTRAINT "reference_place_coordinates_check" CHECK (("latitude" is null or "latitude" between -90 and 90) and ("longitude" is null or "longitude" between -180 and 180) and (("latitude" is null) = ("longitude" is null)))
);

CREATE TABLE "reference_profile_source_occurrence" (
	"source_record_id" uuid,
	"mapping_key" uuid,
	"correspondence_revision" bigint,
