CREATE TABLE "reference_web_resource" (
	"id" uuid PRIMARY KEY,
	"identity_shape" text DEFAULT 'web_resource' NOT NULL,
	"url" text NOT NULL,
	CONSTRAINT "reference_web_resource_shape_check" CHECK ("identity_shape" = 'web_resource'),
	CONSTRAINT "reference_web_resource_url_check" CHECK (octet_length("url") between 1 and 8192 and "url" ~ '^[A-Za-z][A-Za-z0-9+.-]*:')
);

CREATE TABLE "revision_content" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"model" text NOT NULL,
	"sha256" text NOT NULL,
	"byte_size" integer NOT NULL,
	"encoding" text DEFAULT 'full' NOT NULL,
	"base_content_id" uuid,
	"delta_depth" integer DEFAULT 0 NOT NULL,
	"payload" jsonb NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "revision_content_model_sha256_key" UNIQUE("model","sha256"),
	CONSTRAINT "revision_content_model_not_blank" CHECK (btrim("model") <> ''),
	CONSTRAINT "revision_content_sha256_check" CHECK ("sha256" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "revision_content_byte_size_check" CHECK ("byte_size" >= 0),
	CONSTRAINT "revision_content_encoding_check" CHECK ("encoding" in ('full', 'delta')),
	CONSTRAINT "revision_content_delta_shape_check" CHECK ((
				"encoding" = 'full'
				and "base_content_id" is null
				and "delta_depth" = 0
			) or (
				"encoding" = 'delta'
				and "base_content_id" is not null
				and "delta_depth" > 0
			)),
	CONSTRAINT "revision_content_payload_check" CHECK (jsonb_typeof("payload") in ('object', 'array'))
);

CREATE TABLE "score" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"profile_id" uuid NOT NULL,
	"unit_id" uuid NOT NULL,
	"realm_id" uuid NOT NULL,
	"value" integer NOT NULL,
	"visibility" "resource_visibility" DEFAULT 'public'::"resource_visibility" NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"unit_publishing_id" uuid,
	"unit_music_id" uuid,
	"unit_program_id" uuid,
	"unit_software_id" uuid,
	"unit_entity_id" uuid,
	"unit_grouping_id" uuid,
	"unit_reference_id" uuid,
	"unit_distribution_id" uuid,
	"unit_video_id" uuid,
	"unit_audio_id" uuid,
	"unit_post_id" uuid,
	"unit_poll_id" uuid,
	"unit_zone_id" uuid,
	"unit_realm_id" uuid,
	"unit_realm_rule_id" uuid,
	"unit_custom_theme_id" uuid,
	"unit_collection_id" uuid,
	"unit_tag_id" uuid,
	"unit_tag_path_id" uuid,
	"unit_label_id" uuid,
	CONSTRAINT "score_profile_unit_realm_key" UNIQUE("profile_id","unit_id","realm_id"),
	CONSTRAINT "score_unit_target_check" CHECK (num_nonnulls("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id") = 1),
	CONSTRAINT "score_unit_id_check" CHECK ("unit_id" is not distinct from coalesce("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id")),
	CONSTRAINT "score_value_check" CHECK ("value" between 1 and 10)
);

CREATE TABLE "score_stat" (
	"unit_id" uuid,
	"realm_id" uuid,
	"total_count" bigint DEFAULT 0 NOT NULL,
	"total_score" bigint DEFAULT 0 NOT NULL,
	"score_1_count" bigint DEFAULT 0 NOT NULL,
	"score_2_count" bigint DEFAULT 0 NOT NULL,
	"score_3_count" bigint DEFAULT 0 NOT NULL,
	"score_4_count" bigint DEFAULT 0 NOT NULL,
	"score_5_count" bigint DEFAULT 0 NOT NULL,
	"score_6_count" bigint DEFAULT 0 NOT NULL,
	"score_7_count" bigint DEFAULT 0 NOT NULL,
	"score_8_count" bigint DEFAULT 0 NOT NULL,
	"score_9_count" bigint DEFAULT 0 NOT NULL,
	"score_10_count" bigint DEFAULT 0 NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"unit_publishing_id" uuid,
	"unit_music_id" uuid,
	"unit_program_id" uuid,
	"unit_software_id" uuid,
	"unit_entity_id" uuid,
	"unit_grouping_id" uuid,
	"unit_reference_id" uuid,
	"unit_distribution_id" uuid,
	"unit_video_id" uuid,
	"unit_audio_id" uuid,
	"unit_post_id" uuid,
	"unit_poll_id" uuid,
	"unit_zone_id" uuid,
	"unit_realm_id" uuid,
	"unit_realm_rule_id" uuid,
	"unit_custom_theme_id" uuid,
	"unit_collection_id" uuid,
	"unit_tag_id" uuid,
	"unit_tag_path_id" uuid,
	"unit_label_id" uuid,
	CONSTRAINT "score_stat_pkey" PRIMARY KEY("unit_id","realm_id"),
	CONSTRAINT "score_stat_unit_target_check" CHECK (num_nonnulls("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id") = 1),
	CONSTRAINT "score_stat_unit_id_check" CHECK ("unit_id" is not distinct from coalesce("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id")),
	CONSTRAINT "score_stat_nonnegative_check" CHECK ("total_count" >= 0 and "total_score" >= 0 and "score_1_count" >= 0 and "score_2_count" >= 0 and "score_3_count" >= 0 and "score_4_count" >= 0 and "score_5_count" >= 0 and "score_6_count" >= 0 and "score_7_count" >= 0 and "score_8_count" >= 0 and "score_9_count" >= 0 and "score_10_count" >= 0),
	CONSTRAINT "score_stat_total_count_check" CHECK ("total_count" = "score_1_count" + "score_2_count" + "score_3_count" + "score_4_count" + "score_5_count" + "score_6_count" + "score_7_count" + "score_8_count" + "score_9_count" + "score_10_count"),
	CONSTRAINT "score_stat_total_score_check" CHECK ("total_score" = "score_1_count" + 2 * "score_2_count" + 3 * "score_3_count" + 4 * "score_4_count" + 5 * "score_5_count" + 6 * "score_6_count" + 7 * "score_7_count" + 8 * "score_8_count" + 9 * "score_9_count" + 10 * "score_10_count")
);

CREATE TABLE "service_principal" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"auth_user_id" uuid NOT NULL,
	"entity_id" uuid NOT NULL,
	"name" text NOT NULL,
	"credential_digest" text NOT NULL,
	"created_by_auth_user_id" uuid,
	"revision" bigint DEFAULT 1 NOT NULL,
	"revoked_at" timestamp(3) with time zone,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "service_principal_credential_digest_check" CHECK ("credential_digest" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "service_principal_name_check" CHECK (length(btrim("name")) between 1 and 160),
	CONSTRAINT "service_principal_revision_check" CHECK ("revision" between 1 and 9007199254740991)
);

CREATE TABLE "sessions" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"expires_at" timestamp(3) with time zone NOT NULL,
	"token" text NOT NULL UNIQUE,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"ip_address" text,
	"user_agent" text,
	"user_id" uuid NOT NULL
);

CREATE TABLE "shared_search_query" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"document" jsonb NOT NULL,
	"created_by_profile_id" uuid NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "shared_search_query_document_check" CHECK (jsonb_typeof("document") = 'object')
);

CREATE TABLE "slug_namespace" (
	"id" uuid PRIMARY KEY,
	"name" text NOT NULL UNIQUE,
	CONSTRAINT "slug_namespace_registered_check" CHECK (("id"='019b76da-a800-7000-8000-000000000001'::uuid and "name"='users') or ("id"='019b76da-a800-7000-8000-000000000002'::uuid and "name"='realms') or ("id"='019b76da-a800-7000-8000-000000000003'::uuid and "name"='tags') or ("id"='019b76da-a800-7000-8000-000000000004'::uuid and "name"='zones') or ("id"='019b76da-a800-7000-8000-000000000005'::uuid and "name"='entities'))
);

CREATE TABLE "software_catalog_change" (
	"id" uuid DEFAULT uuidv7(),
	"owner_id" uuid,
	"version" bigint NOT NULL,
	"actor_auth_user_id" uuid,
	"operation" text NOT NULL,
	"recorded_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"withdrawn_at" timestamp(3) with time zone,
	CONSTRAINT "software_change_identity_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "software_change_version_key" UNIQUE("owner_id","version"),
	CONSTRAINT "software_change_version_check" CHECK ("version" between 1 and 9007199254740991),
	CONSTRAINT "software_change_operation_check" CHECK (length("operation") between 1 and 96)
);

CREATE TABLE "software_catalog_relation" (
	"id" uuid DEFAULT uuidv7(),
	"owner_id" uuid,
	"definition_revision_id" uuid NOT NULL,
	"semantic_id" uuid DEFAULT uuidv7() NOT NULL,
	"expected_head_version" bigint DEFAULT 0 NOT NULL,
	"state" text DEFAULT 'active' NOT NULL,
	"revision" bigint DEFAULT 1 NOT NULL,
	"spoiler" integer DEFAULT 0 NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "software_relation_owner_id_key" PRIMARY KEY("owner_id","id"),
	CONSTRAINT "software_relation_head_version_check" CHECK ("expected_head_version" between 0 and 9007199254740990),
	CONSTRAINT "software_relation_spoiler_check" CHECK ("spoiler" between 0 and 2),
	CONSTRAINT "software_relation_state_check" CHECK ("state" in ('active', 'disputed', 'withdrawn', 'superseded')),
	CONSTRAINT "software_relation_revision_check" CHECK ("revision" between 1 and 9007199254740991)
);

CREATE TABLE "software_component_revision" (
	"release_id" uuid,
	"kind" text,
	"component_id" text,
	"revision" bigint,
	"operation" text NOT NULL,
	"value" jsonb NOT NULL,
	CONSTRAINT "software_component_revision_pkey" PRIMARY KEY("release_id","kind","component_id","revision"),
	CONSTRAINT "software_component_revision_check" CHECK ("revision" between 1 and 9007199254740991 and "kind" in ('content', 'platform', 'medium', 'language', 'event', 'patch_target', 'animation') and octet_length("component_id") between 1 and 96 and "operation" in ('put', 'remove') and jsonb_typeof("value") = 'object' and octet_length("value"::text) <= 524288)
);

