	CONSTRAINT "software_context_occurrence_label_check" CHECK (octet_length("source_label") <= 4096),
	CONSTRAINT "software_context_occurrence_language_check" CHECK (("source_language" is null and "source_language_tag" is null) or ("source_language" is not null and "source_language_tag" is not null and octet_length("source_language") between 1 and 255 and octet_length("source_language_tag") between 1 and 255))
