CREATE TABLE "software_record_revision" (
	"owner_id" uuid,
	"revision" bigint,
	"shape" text NOT NULL,
	"value" jsonb NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "software_record_revision_pkey" PRIMARY KEY("owner_id","revision"),
	CONSTRAINT "software_record_revision_check" CHECK ("revision" between 1 and 9007199254740991 and "shape" in ('content', 'version', 'release') and jsonb_typeof("value") = 'object' and octet_length("value"::text) <= 1048576)
);

CREATE TABLE "software_record_source_occurrence" (
	"source_record_id" uuid,
	"mapping_key" uuid,
	"correspondence_revision" bigint,
	"snapshot_id" uuid,
	"owner_id" uuid,
	"revision" bigint NOT NULL,
	"source_shape" text NOT NULL,
	"source_value" jsonb NOT NULL,
	"source_path" text NOT NULL,
	CONSTRAINT "software_record_source_occurrence_pkey" PRIMARY KEY("source_record_id","mapping_key","correspondence_revision","snapshot_id","owner_id"),
	CONSTRAINT "software_record_source_value_check" CHECK ("source_shape" in ('content','release') and jsonb_typeof("source_value") = 'object' and octet_length("source_value"::text) <= 2097152),
	CONSTRAINT "software_record_source_value_shape_check" CHECK (case "source_shape" when 'content' then
				"source_value" ?& array['originalLanguageTag','developmentStatus','description'] and "source_value" - array['originalLanguageTag','developmentStatus','description'] = '{}'::jsonb
				and jsonb_typeof("source_value"->'originalLanguageTag') in ('null','string') and jsonb_typeof("source_value"->'description') in ('null','string')
				and (jsonb_typeof("source_value"->'developmentStatus') = 'null' or "source_value"->>'developmentStatus' in ('finished','in_development','cancelled'))
			when 'release' then
				"source_value" ?& array['typeRevisionId','isPatch','freeware','uncensored','hasEroticContent','minimumAge','resolution','engine','voicing','notes','gtin','catalogNumber','date']
				and "source_value" - array['typeRevisionId','isPatch','freeware','uncensored','hasEroticContent','minimumAge','resolution','engine','voicing','notes','gtin','catalogNumber','date'] = '{}'::jsonb
				and jsonb_typeof("source_value"->'typeRevisionId') in ('null','string') and jsonb_typeof("source_value"->'engine') in ('null','string')
				and jsonb_typeof("source_value"->'notes') in ('null','string') and jsonb_typeof("source_value"->'gtin') in ('null','string') and jsonb_typeof("source_value"->'catalogNumber') in ('null','string')
				and jsonb_typeof("source_value"->'isPatch') in ('null','boolean') and jsonb_typeof("source_value"->'freeware') in ('null','boolean')
				and jsonb_typeof("source_value"->'uncensored') in ('null','boolean') and jsonb_typeof("source_value"->'hasEroticContent') in ('null','boolean')
				and jsonb_typeof("source_value"->'minimumAge') in ('null','number') and jsonb_typeof("source_value"->'resolution') in ('null','object') and jsonb_typeof("source_value"->'date') = 'object'
				and (jsonb_typeof("source_value"->'voicing') = 'null' or "source_value"->>'voicing' in ('none','erotic_only','partial','full'))
			else false end),
	CONSTRAINT "software_record_source_path_check" CHECK (octet_length("source_path") between 1 and 512 and left("source_path",1) = '/')
) PARTITION BY HASH ("source_record_id");
