CREATE TABLE "software_release" (
	"id" uuid PRIMARY KEY,
	"identity_shape" text DEFAULT 'release' NOT NULL,
	"type_revision_id" uuid,
	"is_patch" boolean,
	"freeware" boolean,
	"uncensored" boolean,
	"has_erotic_content" boolean,
	"minimum_age" integer,
	"resolution_kind" text,
	"resolution_width" integer,
	"resolution_height" integer,
	"engine" text,
	"voicing" text,
	"notes" text,
	"gtin" text,
	"catalog_number" text,
	"date_year" integer,
	"date_month" smallint,
	"date_day" smallint,
	"date_text" text,
	CONSTRAINT "software_release_shape_check" CHECK ("identity_shape" = 'release'),
	CONSTRAINT "software_release_age_check" CHECK ("minimum_age" is null or "minimum_age" between 0 and 255),
	CONSTRAINT "software_release_date_check" CHECK (
		("date_month" is null or "date_month" between 1 and 12)
		and ("date_day" is null or "date_day" between 1 and 31)
		and ("date_month" is null or "date_day" is null or "date_day" <= case
			when "date_month" in (4, 6, 9, 11) then 30
			when "date_month" = 2 then case when "date_year" is null
				or mod("date_year", 400) = 0 or (mod("date_year", 4) = 0 and mod("date_year", 100) <> 0) then 29 else 28 end
			else 31 end)),
	CONSTRAINT "software_release_resolution_check" CHECK ((("resolution_kind" is null and "resolution_width" is null and "resolution_height" is null) or ("resolution_kind" = 'non_standard' and "resolution_width" is null and "resolution_height" is null) or ("resolution_kind" = 'pixels' and "resolution_width" is not null and "resolution_height" is not null and "resolution_width" between 1 and 2147483647 and "resolution_height" between 1 and 2147483647)) is true),
	CONSTRAINT "software_release_voicing_check" CHECK ("voicing" is null or "voicing" in ('none', 'erotic_only', 'partial', 'full')),
	CONSTRAINT "software_release_text_budget_check" CHECK (("engine" is null or octet_length("engine") <= 4096) and ("notes" is null or octet_length("notes") <= 524288) and ("gtin" is null or octet_length("gtin") <= 128) and ("catalog_number" is null or octet_length("catalog_number") <= 4096))
);

CREATE TABLE "software_release_animation" (
	"release_id" uuid,
	"context" text,
	"state" text NOT NULL,
	"hand_drawn" boolean DEFAULT false NOT NULL,
	"vectorial" boolean DEFAULT false NOT NULL,
	"three_dimensional" boolean DEFAULT false NOT NULL,
	"live_action" boolean DEFAULT false NOT NULL,
	"frequency" text DEFAULT 'unknown' NOT NULL,
	CONSTRAINT "software_release_animation_pkey" PRIMARY KEY("release_id","context"),
	CONSTRAINT "software_animation_context_check" CHECK ("context" in ('story_sprite','story_scene','cutscene','erotic_sprite','erotic_scene')),
	CONSTRAINT "software_animation_state_check" CHECK ("state" in ('unknown','none','not_applicable','animated') and "frequency" in ('unknown','some','all')),
	CONSTRAINT "software_animation_technique_check" CHECK (("state" = 'animated' and ("hand_drawn" or "vectorial" or "three_dimensional" or "live_action")) or ("state" <> 'animated' and not ("hand_drawn" or "vectorial" or "three_dimensional" or "live_action") and "frequency" = 'unknown')),
	CONSTRAINT "software_animation_cutscene_check" CHECK ("context" <> 'cutscene' or ("state" <> 'none' and "frequency" = 'unknown'))
);

CREATE TABLE "software_release_content" (
	"release_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"content_id" uuid NOT NULL,
	"release_type_revision_id" uuid,
	"version_id" uuid,
	CONSTRAINT "software_release_content_pkey" PRIMARY KEY("release_id","id")
);

CREATE TABLE "software_release_event" (
	"release_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"area_id" uuid,
	"date_year" integer,
	"date_month" smallint,
	"date_day" smallint,
	"date_text" text,
	CONSTRAINT "software_release_event_pkey" PRIMARY KEY("release_id","id"),
	CONSTRAINT "software_release_event_date_check" CHECK (
		("date_month" is null or "date_month" between 1 and 12)
		and ("date_day" is null or "date_day" between 1 and 31)
		and ("date_month" is null or "date_day" is null or "date_day" <= case
			when "date_month" in (4, 6, 9, 11) then 30
			when "date_month" = 2 then case when "date_year" is null
				or mod("date_year", 400) = 0 or (mod("date_year", 4) = 0 and mod("date_year", 100) <> 0) then 29 else 28 end
			else 31 end))
);

CREATE TABLE "software_release_language" (
	"release_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"language_tag" text NOT NULL,
	"channel_revision_id" uuid,
	"machine_translated" boolean,
	"main" boolean,
	"title" text,
	"transliterated_title" text,
	CONSTRAINT "software_release_language_pkey" PRIMARY KEY("release_id","id"),
	CONSTRAINT "software_release_language_tag_check" CHECK (octet_length("language_tag") between 1 and 255),
	CONSTRAINT "software_release_language_title_check" CHECK (("title" is null or octet_length("title") <= 131072) and ("transliterated_title" is null or octet_length("transliterated_title") <= 131072))
);

CREATE TABLE "software_release_medium" (
	"release_id" uuid,
	"id" uuid DEFAULT uuidv7(),
	"medium_type_revision_id" uuid NOT NULL,
	"quantity" bigint,
	CONSTRAINT "software_release_medium_pkey" PRIMARY KEY("release_id","id"),
	CONSTRAINT "software_release_medium_quantity_check" CHECK ("quantity" is null or "quantity" between 0 and 9007199254740991)
);

CREATE TABLE "software_release_platform" (
	"release_id" uuid,
	"platform_revision_id" uuid,
	CONSTRAINT "software_release_platform_pkey" PRIMARY KEY("release_id","platform_revision_id")
);

CREATE TABLE "software_semantic_head" (
	"owner_id" uuid,
	"semantic_id" uuid,
	"version" bigint NOT NULL,
	CONSTRAINT "software_semantic_head_key" PRIMARY KEY("owner_id","semantic_id")
);

CREATE TABLE "software_semantic_revision" (
	"owner_id" uuid,
	"semantic_id" uuid,
	"version" bigint,
	"fact_id" uuid,
	"relation_id" uuid,
	"state" text DEFAULT 'active' NOT NULL,
	"actor_auth_user_id" uuid,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "software_semantic_revision_key" PRIMARY KEY("owner_id","semantic_id","version"),
	CONSTRAINT "software_semantic_revision_target_check" CHECK (num_nonnulls("fact_id","relation_id") = 1),
	CONSTRAINT "software_semantic_revision_state_check" CHECK ("state" in ('active', 'disputed', 'withdrawn', 'superseded')),
	CONSTRAINT "software_semantic_revision_version_check" CHECK ("version" between 1 and 9007199254740991)
);

