CREATE TABLE "software_version" (
	"id" uuid PRIMARY KEY,
	"identity_shape" text DEFAULT 'version' NOT NULL,
	"content_id" uuid NOT NULL,
	"kind" text NOT NULL,
	"version_label" text,
	"language_tag" text,
	"distinguishing_evidence" text NOT NULL,
	CONSTRAINT "software_version_content_id_unique" UNIQUE("content_id","id"),
	CONSTRAINT "software_version_shape_check" CHECK ("identity_shape" = 'version'),
	CONSTRAINT "software_version_kind_check" CHECK ("kind" in ('revision', 'translation', 'localization', 'port', 'variant')),
	CONSTRAINT "software_version_evidence_check" CHECK (octet_length("distinguishing_evidence") between 1 and 16384),
	CONSTRAINT "software_version_label_check" CHECK ("version_label" is null or octet_length("version_label") between 1 and 4096),
	CONSTRAINT "software_version_language_check" CHECK ("language_tag" is null or octet_length("language_tag") between 1 and 255)
);

CREATE TABLE "software_visual_novel" (
	"id" uuid PRIMARY KEY
);

CREATE TABLE "studio_auth_editor_candidate" (
	"auth_user_id" uuid,
	"unit_id" uuid,
	"owner_since" timestamp(3) with time zone,
	"catalog_creator_since" timestamp(3) with time zone,
	"direct_grant_since" timestamp(3) with time zone,
	"direct_grant_last_at" timestamp(3) with time zone,
	"relevant_at" timestamp(3) with time zone NOT NULL,
	"valid_until" timestamp(3) with time zone,
	"projection_updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"unit_publishing_id" uuid,
	"unit_music_id" uuid,
	"unit_program_id" uuid,
	"unit_software_id" uuid,
	"unit_entity_id" uuid,
	"unit_grouping_id" uuid,
	"unit_reference_id" uuid,
	"unit_distribution_id" uuid,
	"unit_video_id" uuid,
	"unit_audio_id" uuid,
	"unit_post_id" uuid,
	"unit_poll_id" uuid,
	"unit_zone_id" uuid,
	"unit_realm_id" uuid,
	"unit_realm_rule_id" uuid,
	"unit_custom_theme_id" uuid,
	"unit_collection_id" uuid,
	"unit_tag_id" uuid,
	"unit_tag_path_id" uuid,
	"unit_label_id" uuid,
	CONSTRAINT "studio_auth_editor_candidate_pkey" PRIMARY KEY("auth_user_id","unit_id"),
	CONSTRAINT "studio_auth_editor_candidate_unit_target_check" CHECK (num_nonnulls("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id") = 1),
	CONSTRAINT "studio_auth_editor_candidate_unit_id_check" CHECK ("unit_id" is not distinct from coalesce("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id")),
	CONSTRAINT "studio_auth_editor_candidate_catalog_creator_owner_check" CHECK ("catalog_creator_since" is null or num_nonnulls("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id") = 1),
	CONSTRAINT "studio_auth_editor_candidate_source_check" CHECK ("owner_since" is not null or "direct_grant_since" is not null or "catalog_creator_since" is not null),
	CONSTRAINT "studio_auth_editor_candidate_relevant_at_check" CHECK ("relevant_at" = greatest("owner_since", "direct_grant_last_at", "catalog_creator_since")),
	CONSTRAINT "studio_auth_editor_candidate_direct_grant_time_check" CHECK ((
				"direct_grant_since" is null
				and "direct_grant_last_at" is null
			) or (
				"direct_grant_since" is not null
				and "direct_grant_last_at" is not null
				and "direct_grant_since" <= "direct_grant_last_at"
			)),
	CONSTRAINT "studio_auth_editor_candidate_validity_check" CHECK ("valid_until" is null or "direct_grant_since" is not null)
);

CREATE TABLE "studio_realm_editor_candidate" (
	"realm_id" uuid,
	"realm_relation" "realm_access_subject_relation",
	"unit_id" uuid,
	"grant_since" timestamp(3) with time zone NOT NULL,
