	"unit_distribution_id" uuid,
	"unit_video_id" uuid,
	"unit_audio_id" uuid,
	"unit_post_id" uuid,
	"unit_poll_id" uuid,
	"unit_zone_id" uuid,
	"unit_realm_id" uuid,
	"unit_realm_rule_id" uuid,
	"unit_custom_theme_id" uuid,
	"unit_collection_id" uuid,
	"unit_tag_id" uuid,
	"unit_tag_path_id" uuid,
	"unit_label_id" uuid,
	CONSTRAINT "studio_realm_editor_candidate_pkey" PRIMARY KEY("realm_id","realm_relation","unit_id"),
	CONSTRAINT "studio_realm_editor_candidate_unit_target_check" CHECK (num_nonnulls("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id") = 1),
	CONSTRAINT "studio_realm_editor_candidate_unit_id_check" CHECK ("unit_id" is not distinct from coalesce("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id")),
	CONSTRAINT "studio_realm_editor_candidate_time_check" CHECK ("grant_since" <= "relevant_at")
);

CREATE TABLE "studio_resource_visit" (
