	CONSTRAINT "studio_resource_visit_resource_unit_id_check" CHECK ("resource_unit_id" is not distinct from coalesce("resource_unit_publishing_id", "resource_unit_music_id", "resource_unit_program_id", "resource_unit_software_id", "resource_unit_entity_id", "resource_unit_grouping_id", "resource_unit_reference_id", "resource_unit_distribution_id", "resource_unit_video_id", "resource_unit_audio_id", "resource_unit_post_id", "resource_unit_poll_id", "resource_unit_zone_id", "resource_unit_realm_id", "resource_unit_realm_rule_id", "resource_unit_custom_theme_id", "resource_unit_collection_id", "resource_unit_tag_id", "resource_unit_tag_path_id", "resource_unit_label_id"))
);

CREATE TABLE "subject_association" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"unit_id" uuid NOT NULL,
	"entity_id" uuid NOT NULL,
	"context_post_id" uuid,
	"role" text NOT NULL,
	"position" text collate "C" DEFAULT 'a0' NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"unit_publishing_id" uuid,
	"unit_music_id" uuid,
	"unit_program_id" uuid,
	"unit_software_id" uuid,
	"unit_entity_id" uuid,
	"unit_grouping_id" uuid,
	"unit_reference_id" uuid,
	"unit_distribution_id" uuid,
	"unit_video_id" uuid,
	"unit_audio_id" uuid,
	"unit_post_id" uuid,
	"unit_poll_id" uuid,
	"unit_zone_id" uuid,
	"unit_realm_id" uuid,
	"unit_realm_rule_id" uuid,
	"unit_custom_theme_id" uuid,
	"unit_collection_id" uuid,
	"unit_tag_id" uuid,
	"unit_tag_path_id" uuid,
	"unit_label_id" uuid,
	CONSTRAINT "subject_association_unit_entity_role_key" UNIQUE("unit_id","entity_id","role"),
	CONSTRAINT "subject_association_unit_target_check" CHECK (num_nonnulls("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id") = 1),
	CONSTRAINT "subject_association_unit_id_check" CHECK ("unit_id" is not distinct from coalesce("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id")),
	CONSTRAINT "subject_association_role_check" CHECK ("role" in ('primary_character', 'featured_character', 'appears', 'about', 'setting', 'source_work', 'canonical_wiki_page', 'related_subject')),
	CONSTRAINT "subject_association_not_self_check" CHECK ("unit_id" <> "entity_id"),
	CONSTRAINT "subject_association_position_byte_length_check" CHECK (octet_length("position") <= 1024)
);

CREATE TABLE "subject_association_judgment" (
	"association_id" uuid,
	"profile_id" uuid,
	"spoiler_level" smallint NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "subject_association_judgment_pkey" PRIMARY KEY("association_id","profile_id"),
	CONSTRAINT "subject_association_judgment_spoiler_level_check" CHECK ("spoiler_level" between 0 and 2)
);

CREATE TABLE "subject_association_judgment_stat" (
	"association_id" uuid PRIMARY KEY,
	"spoiler_vote_count" bigint DEFAULT 0 NOT NULL,
	"spoiler_none_count" bigint DEFAULT 0 NOT NULL,
	"spoiler_minor_count" bigint DEFAULT 0 NOT NULL,
	"spoiler_major_count" bigint DEFAULT 0 NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "subject_association_judgment_stat_spoiler_nonnegative_check" CHECK ("spoiler_vote_count" >= 0
				and "spoiler_none_count" >= 0
				and "spoiler_minor_count" >= 0
				and "spoiler_major_count" >= 0),
	CONSTRAINT "subject_association_judgment_stat_spoiler_count_check" CHECK ("spoiler_vote_count" =
				"spoiler_none_count" + "spoiler_minor_count" + "spoiler_major_count")
);

CREATE TABLE "tag" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"revision" bigint DEFAULT 1 NOT NULL,
	"routing_generation" integer DEFAULT 1 NOT NULL,
	"created_by_auth_user_id" uuid,
	"status" "unit_status" DEFAULT 'draft'::"unit_status" NOT NULL,
	"visibility" "resource_visibility" DEFAULT 'public'::"resource_visibility" NOT NULL,
	"content_rating" "content_rating" DEFAULT 'general'::"content_rating" NOT NULL,
	"ai_disclosure" "ai_disclosure" DEFAULT 'unknown'::"ai_disclosure" NOT NULL,
	"moderation_status" "moderation_status" DEFAULT 'approved'::"moderation_status" NOT NULL,
	"post_targeting_locked" boolean DEFAULT false NOT NULL,
	"published_at" timestamp(3) with time zone,
	"deleted_at" timestamp(3) with time zone,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"node_kind" text DEFAULT 'concept' NOT NULL,
	"directly_applicable" boolean DEFAULT true NOT NULL,
	"default_spoiler_level" smallint,
	CONSTRAINT "tag_identity_revision_check" CHECK ("revision" between 1 and 9007199254740991 and "routing_generation" between 1 and 2147483647),
	CONSTRAINT "tag_identity_publication_check" CHECK ("status" <> 'published' or "published_at" is not null),
	CONSTRAINT "tag_identity_deleted_at_check" CHECK ("deleted_at" is null or "deleted_at" >= "created_at"),
	CONSTRAINT "tag_node_kind_check" CHECK ("node_kind" = 'concept'),
	CONSTRAINT "tag_default_spoiler_level_check" CHECK ("default_spoiler_level" is null or "default_spoiler_level" between 0 and 2)
);

CREATE TABLE "tag_expression" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"expression_kind" text NOT NULL,
	"canonical_claim_key" text NOT NULL CONSTRAINT "tag_expression_claim_key" UNIQUE,
	"focus_tag_id" uuid NOT NULL,
	"status" text DEFAULT 'active' NOT NULL,
	"created_by_profile_id" uuid,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"sealed_at" timestamp(3) with time zone,
	"retired_at" timestamp(3) with time zone,
	CONSTRAINT "tag_expression_kind_check" CHECK ("expression_kind" in ('simple', 'facet_value', 'relation')),
	CONSTRAINT "tag_expression_status_check" CHECK ("status" in ('active', 'retired')),
	CONSTRAINT "tag_expression_claim_key_check" CHECK (btrim("canonical_claim_key") <> '' and octet_length("canonical_claim_key") <= 2048),
	CONSTRAINT "tag_expression_retirement_check" CHECK (("status" = 'active' and "retired_at" is null)
				or ("status" = 'retired' and "retired_at" is not null))
);

CREATE TABLE "tag_expression_argument" (
	"expression_id" uuid,
	"role" text,
	"ordinal" integer DEFAULT 0,
	"tag_id" uuid NOT NULL,
	CONSTRAINT "tag_expression_argument_pkey" PRIMARY KEY("expression_id","role","ordinal"),
	CONSTRAINT "tag_expression_argument_role_tag_key" UNIQUE("expression_id","role","tag_id"),
	CONSTRAINT "tag_expression_argument_role_check" CHECK ("role" in ('predicate', 'slot', 'value', 'focus', 'qualifier')),
	CONSTRAINT "tag_expression_argument_ordinal_check" CHECK ("ordinal" >= 0)
);

CREATE TABLE "tag_expression_effective_tag" (
	"expression_id" uuid,
	"tag_id" uuid,
	"evidence_kind" text,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "tag_expression_effective_tag_pkey" PRIMARY KEY("expression_id","tag_id","evidence_kind"),
	CONSTRAINT "tag_expression_effective_tag_kind_check" CHECK ("evidence_kind" in ('primary', 'entailed', 'retrieval_only'))
);

CREATE TABLE "tag_expression_group_key" (
	"presentation_revision_id" uuid PRIMARY KEY,
	"tag_id" uuid NOT NULL,
	"semantic_role" text NOT NULL,
	CONSTRAINT "tag_expression_group_key_role_check" CHECK ("semantic_role" in ('predicate', 'slot', 'value', 'focus', 'qualifier'))
);

CREATE TABLE "tag_expression_inference_rule" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"source_expression_id" uuid NOT NULL,
	"target_tag_id" uuid,
	"target_expression_id" uuid,
	"inference_kind" text NOT NULL,
	"revision" integer DEFAULT 1 NOT NULL,
	"status" text DEFAULT 'active' NOT NULL,
	"provenance" jsonb,
	"created_by_profile_id" uuid,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"retired_at" timestamp(3) with time zone,
	CONSTRAINT "tag_expression_inference_rule_kind_check" CHECK ("inference_kind" in ('entailed', 'retrieval_only')),
	CONSTRAINT "tag_expression_inference_rule_revision_check" CHECK ("revision" >= 1),
	CONSTRAINT "tag_expression_inference_rule_status_check" CHECK ("status" in ('active', 'retired')),
	CONSTRAINT "tag_expression_inference_rule_target_check" CHECK (num_nonnulls("target_tag_id", "target_expression_id") = 1),
	CONSTRAINT "tag_expression_inference_rule_not_self_check" CHECK ("target_expression_id" is null or "source_expression_id" <> "target_expression_id"),
	CONSTRAINT "tag_expression_inference_rule_retirement_check" CHECK (("status" = 'active' and "retired_at" is null)
				or ("status" = 'retired' and "retired_at" is not null)),
	CONSTRAINT "tag_expression_inference_rule_provenance_object_check" CHECK ("provenance" is null or jsonb_typeof("provenance") = 'object')
);

CREATE TABLE "tag_expression_label_component" (
	"presentation_revision_id" uuid,
	"ordinal" integer,
	"tag_id" uuid NOT NULL,
	"semantic_role" text NOT NULL,
	"component_kind" text DEFAULT 'required' NOT NULL,
	CONSTRAINT "tag_expression_label_component_pkey" PRIMARY KEY("presentation_revision_id","ordinal"),
	CONSTRAINT "tag_expression_label_component_semantic_key" UNIQUE("presentation_revision_id","tag_id","semantic_role","component_kind"),
	CONSTRAINT "tag_expression_label_component_ordinal_check" CHECK ("ordinal" >= 0),
	CONSTRAINT "tag_expression_label_component_role_check" CHECK ("semantic_role" in ('predicate', 'slot', 'value', 'focus', 'qualifier')),
	CONSTRAINT "tag_expression_label_component_kind_check" CHECK ("component_kind" in ('required', 'fallback'))
);

CREATE TABLE "tag_expression_presentation_revision" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"expression_id" uuid NOT NULL,
	"revision" integer DEFAULT 1 NOT NULL,
	"status" text DEFAULT 'active' NOT NULL,
	"created_by_profile_id" uuid,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"sealed_at" timestamp(3) with time zone,
	"retired_at" timestamp(3) with time zone,
	CONSTRAINT "tag_expression_presentation_revision_key" UNIQUE("expression_id","revision"),
	CONSTRAINT "tag_expression_presentation_revision_check" CHECK ("revision" >= 1),
	CONSTRAINT "tag_expression_presentation_status_check" CHECK ("status" in ('active', 'retired')),
	CONSTRAINT "tag_expression_presentation_retirement_check" CHECK (("status" = 'active' and "retired_at" is null)
				or ("status" = 'retired' and "retired_at" is not null))
);

CREATE TABLE "tag_expression_projection_rebuild" (
	"expression_id" uuid PRIMARY KEY,
	"global_cursor_unit_id" uuid,
	"global_complete" boolean DEFAULT false NOT NULL,
	"realm_cursor_realm_id" uuid,
	"realm_cursor_unit_id" uuid,
	"realm_complete" boolean DEFAULT false NOT NULL,
	"attempt_count" integer DEFAULT 0 NOT NULL,
	"available_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"last_error_message" text,
	"requested_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "tag_expression_projection_rebuild_realm_cursor_check" CHECK (("realm_cursor_realm_id" is null) = ("realm_cursor_unit_id" is null)),
	CONSTRAINT "tag_expression_projection_rebuild_attempt_check" CHECK ("attempt_count" >= 0),
	CONSTRAINT "tag_expression_projection_rebuild_incomplete_check" CHECK (not ("global_complete" and "realm_complete"))
);

CREATE TABLE "tag_path" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"revision" bigint DEFAULT 1 NOT NULL,
	"routing_generation" integer DEFAULT 1 NOT NULL,
	"created_by_auth_user_id" uuid,
	"status" "unit_status" DEFAULT 'draft'::"unit_status" NOT NULL,
	"visibility" "resource_visibility" DEFAULT 'public'::"resource_visibility" NOT NULL,
	"content_rating" "content_rating" DEFAULT 'general'::"content_rating" NOT NULL,
	"ai_disclosure" "ai_disclosure" DEFAULT 'unknown'::"ai_disclosure" NOT NULL,
	"moderation_status" "moderation_status" DEFAULT 'approved'::"moderation_status" NOT NULL,
	"post_targeting_locked" boolean DEFAULT false NOT NULL,
	"published_at" timestamp(3) with time zone,
	"deleted_at" timestamp(3) with time zone,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"member_node_ids" uuid[] NOT NULL,
	"relation_ids" uuid[] NOT NULL,
	"structural_identity_hash" text NOT NULL CONSTRAINT "tag_path_structural_identity_hash_key" UNIQUE,
	"terminal_node_id" uuid NOT NULL,
	"created_by_profile_id" uuid NOT NULL,
	CONSTRAINT "tag_path_structure_key" UNIQUE("member_node_ids","relation_ids"),
	CONSTRAINT "tag_path_identity_revision_check" CHECK ("revision" between 1 and 9007199254740991 and "routing_generation" between 1 and 2147483647),
	CONSTRAINT "tag_path_identity_publication_check" CHECK ("status" <> 'published' or "published_at" is not null),
	CONSTRAINT "tag_path_identity_deleted_at_check" CHECK ("deleted_at" is null or "deleted_at" >= "created_at"),
	CONSTRAINT "tag_path_member_count_check" CHECK (cardinality("member_node_ids") between 2 and 16),
	CONSTRAINT "tag_path_relation_count_check" CHECK (cardinality("relation_ids") = cardinality("member_node_ids") - 1),
	CONSTRAINT "tag_path_member_null_check" CHECK (array_position("member_node_ids", null) is null),
	CONSTRAINT "tag_path_relation_null_check" CHECK (array_position("relation_ids", null) is null),
	CONSTRAINT "tag_path_terminal_check" CHECK ("terminal_node_id" = "member_node_ids"[cardinality("member_node_ids")]),
	CONSTRAINT "tag_path_not_self_check" CHECK (not ("id" = any("member_node_ids"))),
	CONSTRAINT "tag_path_structural_identity_hash_check" CHECK ("structural_identity_hash" ~ '^[0-9a-f]{64}$')
);

CREATE TABLE "tag_path_member" (
	"path_id" uuid,
	"ordinal" integer,
	"node_id" uuid NOT NULL,
	"incoming_relation_id" uuid,
	CONSTRAINT "tag_path_member_pkey" PRIMARY KEY("path_id","ordinal"),
	CONSTRAINT "tag_path_member_path_node_key" UNIQUE("path_id","node_id"),
	CONSTRAINT "tag_path_member_ordinal_check" CHECK ("ordinal" >= 0),
	CONSTRAINT "tag_path_member_incoming_relation_check" CHECK (("ordinal" = 0 and "incoming_relation_id" is null)
				or ("ordinal" > 0 and "incoming_relation_id" is not null))
);

CREATE TABLE "tag_path_merge" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"source_path_id" uuid NOT NULL,
	"target_path_id" uuid NOT NULL,
	"status" text DEFAULT 'proposed' NOT NULL,
	"reason" text NOT NULL,
	"proposal_source_kind" text DEFAULT 'human' NOT NULL,
	"proposal_provenance" jsonb,
	"proposed_by_profile_id" uuid NOT NULL,
	"resolved_by_profile_id" uuid,
	"resolved_at" timestamp(3) with time zone,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "tag_path_merge_status_check" CHECK ("status" in ('proposed', 'accepted', 'rejected', 'reversed')),
	CONSTRAINT "tag_path_merge_proposal_source_kind_check" CHECK ("proposal_source_kind" in ('human', 'assisted')),
	CONSTRAINT "tag_path_merge_proposal_provenance_object_check" CHECK ("proposal_provenance" is null or jsonb_typeof("proposal_provenance") = 'object'),
	CONSTRAINT "tag_path_merge_proposal_provenance_check" CHECK ("proposal_source_kind" = 'human' and "proposal_provenance" is null
			or (
				"proposal_source_kind" = 'assisted'
				and "proposal_provenance"->>'kind' = 'assisted'
				and jsonb_typeof("proposal_provenance"->'system') = 'string'
				and btrim("proposal_provenance"->>'system') <> ''
				and jsonb_typeof("proposal_provenance"->'runId') = 'string'
				and btrim("proposal_provenance"->>'runId') <> ''
				and (
					not ("proposal_provenance" ? 'model')
					or jsonb_typeof("proposal_provenance"->'model') = 'string'
				)
				and (
					not ("proposal_provenance" ? 'confidence')
					or (
						jsonb_typeof("proposal_provenance"->'confidence') = 'number'
						and ("proposal_provenance"->>'confidence')::numeric between 0 and 1
					)
				)
			)),
	CONSTRAINT "tag_path_merge_distinct_check" CHECK ("source_path_id" <> "target_path_id"),
	CONSTRAINT "tag_path_merge_reason_check" CHECK (btrim("reason") <> ''),
	CONSTRAINT "tag_path_merge_resolution_check" CHECK (("status" = 'proposed') = ("resolved_at" is null and "resolved_by_profile_id" is null))
);

CREATE TABLE "tag_path_sense" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"path_id" uuid NOT NULL,
	"expression_id" uuid NOT NULL,
	"scope" text DEFAULT 'global' NOT NULL,
	"realm_id" uuid,
	"binding_signature" text NOT NULL,
	"status" text DEFAULT 'active' NOT NULL,
	"provenance" jsonb,
	"created_by_profile_id" uuid NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"sealed_at" timestamp(3) with time zone,
	"retired_at" timestamp(3) with time zone,
	CONSTRAINT "tag_path_sense_id_path_key" UNIQUE("id","path_id"),
	CONSTRAINT "tag_path_sense_scope_check" CHECK ("scope" in ('global', 'realm')),
	CONSTRAINT "tag_path_sense_status_check" CHECK ("status" in ('active', 'retired')),
	CONSTRAINT "tag_path_sense_authority_check" CHECK (("scope" = 'global' and "realm_id" is null)
				or ("scope" = 'realm' and "realm_id" is not null)),
	CONSTRAINT "tag_path_sense_binding_signature_check" CHECK (btrim("binding_signature") <> '' and octet_length("binding_signature") <= 2048),
	CONSTRAINT "tag_path_sense_retirement_check" CHECK (("status" = 'active' and "retired_at" is null)
				or ("status" = 'retired' and "retired_at" is not null)),
	CONSTRAINT "tag_path_sense_provenance_object_check" CHECK ("provenance" is null or jsonb_typeof("provenance") = 'object')
);

CREATE TABLE "tag_path_sense_binding" (
	"sense_id" uuid,
	"member_ordinal" integer,
	"argument_role" text,
	"argument_ordinal" integer DEFAULT 0,
	CONSTRAINT "tag_path_sense_binding_pkey" PRIMARY KEY("sense_id","member_ordinal","argument_role","argument_ordinal"),
	CONSTRAINT "tag_path_sense_binding_argument_key" UNIQUE("sense_id","argument_role","argument_ordinal"),
	CONSTRAINT "tag_path_sense_binding_role_check" CHECK ("argument_role" in ('predicate', 'slot', 'value', 'focus', 'qualifier')),
	CONSTRAINT "tag_path_sense_binding_member_ordinal_check" CHECK ("member_ordinal" >= 0),
	CONSTRAINT "tag_path_sense_binding_argument_ordinal_check" CHECK ("argument_ordinal" >= 0)
);

CREATE TABLE "tag_path_vote" (
	"path_id" uuid,
	"profile_id" uuid,
	"value" integer NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "tag_path_vote_pkey" PRIMARY KEY("path_id","profile_id"),
	CONSTRAINT "tag_path_vote_value_check" CHECK ("value" in (-1, 1))
);

CREATE TABLE "tag_path_vote_stat" (
	"path_id" uuid PRIMARY KEY,
	"terminal_node_id" uuid NOT NULL,
	"score" bigint DEFAULT 0 NOT NULL,
	"vote_count" bigint DEFAULT 0 NOT NULL,
	"usage_count" bigint DEFAULT 0 NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "tag_path_vote_stat_count_check" CHECK ("vote_count" >= 0),
	CONSTRAINT "tag_path_vote_stat_usage_count_check" CHECK ("usage_count" >= 0),
	CONSTRAINT "tag_path_vote_stat_score_check" CHECK (abs("score") <= "vote_count"),
	CONSTRAINT "tag_path_vote_stat_parity_check" CHECK (("vote_count" + "score") % 2 = 0)
);

CREATE TABLE "tag_public_position_stat" (
	"tag_id" uuid PRIMARY KEY,
	"public_position_count" bigint DEFAULT 0 NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "tag_public_position_stat_count_check" CHECK ("public_position_count" >= 0)
);

CREATE TABLE "tag_relation" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"parent_node_id" uuid NOT NULL,
	"child_node_id" uuid NOT NULL,
	"relation_kind" text NOT NULL,
	"revision" integer DEFAULT 1 NOT NULL,
	"status" text DEFAULT 'active' NOT NULL,
	"provenance" jsonb,
	"created_by_profile_id" uuid,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"retired_at" timestamp(3) with time zone,
	CONSTRAINT "tag_relation_revision_key" UNIQUE("parent_node_id","child_node_id","relation_kind","revision"),
	CONSTRAINT "tag_relation_kind_check" CHECK ("relation_kind" in ('generic', 'partitive', 'instance', 'organizational', 'facet_value')),
	CONSTRAINT "tag_relation_status_check" CHECK ("status" in ('active', 'retired')),
	CONSTRAINT "tag_relation_revision_check" CHECK ("revision" >= 1),
	CONSTRAINT "tag_relation_distinct_check" CHECK ("parent_node_id" <> "child_node_id"),
	CONSTRAINT "tag_relation_retirement_check" CHECK (("status" = 'active' and "retired_at" is null)
				or ("status" = 'retired' and "retired_at" is not null)),
	CONSTRAINT "tag_relation_provenance_object_check" CHECK ("provenance" is null or jsonb_typeof("provenance") = 'object')
);

CREATE TABLE "unit_access_grant" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"unit_id" uuid NOT NULL,
	"subject_kind" "unit_access_subject_kind" NOT NULL,
	"auth_user_id" uuid,
	"realm_id" uuid,
	"realm_relation" "realm_access_subject_relation",
	"permission" "unit_permission" NOT NULL,
	"scope" text[] DEFAULT array[]::text[] NOT NULL,
	"granted_by_auth_user_id" uuid,
	"expires_at" timestamp(3) with time zone,
	"revoked_at" timestamp(3) with time zone,
	"revoked_by_auth_user_id" uuid,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"unit_publishing_id" uuid,
	"unit_music_id" uuid,
	"unit_program_id" uuid,
	"unit_software_id" uuid,
	"unit_entity_id" uuid,
	"unit_grouping_id" uuid,
	"unit_reference_id" uuid,
	"unit_distribution_id" uuid,
	"unit_video_id" uuid,
	"unit_audio_id" uuid,
	"unit_post_id" uuid,
	"unit_poll_id" uuid,
	"unit_zone_id" uuid,
	"unit_realm_id" uuid,
	"unit_realm_rule_id" uuid,
	"unit_custom_theme_id" uuid,
	"unit_collection_id" uuid,
	"unit_tag_id" uuid,
	"unit_tag_path_id" uuid,
	"unit_label_id" uuid,
	CONSTRAINT "unit_access_grant_unit_target_check" CHECK (num_nonnulls("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id") = 1),
	CONSTRAINT "unit_access_grant_unit_id_check" CHECK ("unit_id" is not distinct from coalesce("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id")),
	CONSTRAINT "unit_access_grant_subject_shape_check" CHECK ((
				"subject_kind" = 'auth' and "auth_user_id" is not null and "realm_id" is null and "realm_relation" is null
			) or (
				"subject_kind" = 'realm' and "auth_user_id" is null and "realm_id" is not null and "realm_relation" is not null
			) or (
				"subject_kind" = 'authenticated' and "auth_user_id" is null and "realm_id" is null and "realm_relation" is null
			)),
	CONSTRAINT "unit_access_grant_scope_check" CHECK (cardinality("scope") <= 8 and (
		cardinality("scope") = 0 or
		array_to_string("scope", '/') ~ '^[a-z0-9][a-z0-9-]*(/[a-z0-9][a-z0-9-]*)*$'
	)),
	CONSTRAINT "unit_access_grant_permission_delegable_check" CHECK ("permission" not in (
				'unit.ownership.transfer'::unit_permission,
				'unit.delete'::unit_permission
			)),
	CONSTRAINT "unit_access_grant_expiry_check" CHECK ("expires_at" is null or "expires_at" > "created_at"),
	CONSTRAINT "unit_access_grant_revocation_shape_check" CHECK (("revoked_at" is null) = ("revoked_by_auth_user_id" is null))
);

CREATE TABLE "unit_access_invitation" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"unit_id" uuid NOT NULL,
	"invited_auth_user_id" uuid NOT NULL,
	"permissions" "unit_permission"[] NOT NULL,
	"scope" text[] DEFAULT array[]::text[] NOT NULL,
	"invited_by_auth_user_id" uuid NOT NULL,
	"expires_at" timestamp(3) with time zone NOT NULL,
	"access_expires_at" timestamp(3) with time zone,
	"resolution" "unit_access_invitation_resolution",
	"resolved_at" timestamp(3) with time zone,
	"resolved_by_auth_user_id" uuid,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"unit_publishing_id" uuid,
	"unit_music_id" uuid,
	"unit_program_id" uuid,
	"unit_software_id" uuid,
	"unit_entity_id" uuid,
	"unit_grouping_id" uuid,
	"unit_reference_id" uuid,
	"unit_distribution_id" uuid,
	"unit_video_id" uuid,
	"unit_audio_id" uuid,
	"unit_post_id" uuid,
	"unit_poll_id" uuid,
	"unit_zone_id" uuid,
	"unit_realm_id" uuid,
	"unit_realm_rule_id" uuid,
	"unit_custom_theme_id" uuid,
	"unit_collection_id" uuid,
	"unit_tag_id" uuid,
	"unit_tag_path_id" uuid,
	"unit_label_id" uuid,
	CONSTRAINT "unit_access_invitation_unit_target_check" CHECK (num_nonnulls("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id") = 1),
	CONSTRAINT "unit_access_invitation_unit_id_check" CHECK ("unit_id" is not distinct from coalesce("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id")),
	CONSTRAINT "unit_access_invitation_scope_check" CHECK (cardinality("scope") <= 8 and (
		cardinality("scope") = 0 or
		array_to_string("scope", '/') ~ '^[a-z0-9][a-z0-9-]*(/[a-z0-9][a-z0-9-]*)*$'
	)),
	CONSTRAINT "unit_access_invitation_permissions_check" CHECK (cardinality("permissions") between 1 and 28
				and array_position("permissions", 'unit.ownership.transfer'::unit_permission) is null
				and array_position("permissions", 'unit.delete'::unit_permission) is null),
	CONSTRAINT "unit_access_invitation_accounts_differ_check" CHECK ("invited_auth_user_id" <> "invited_by_auth_user_id"),
	CONSTRAINT "unit_access_invitation_expiry_check" CHECK ("expires_at" > "created_at" and ("access_expires_at" is null or "access_expires_at" > "created_at")),
	CONSTRAINT "unit_access_invitation_resolution_shape_check" CHECK ((
				"resolution" is null and "resolved_at" is null and "resolved_by_auth_user_id" is null
			) or (
				"resolution" is not null and "resolved_at" is not null and "resolved_by_auth_user_id" is not null
			))
);

