CREATE TABLE "unit_alias" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"unit_id" uuid NOT NULL,
	"term" text NOT NULL,
	"normalized_term" text NOT NULL,
	"language" text,
	"kind" "alias_kind" DEFAULT 'common'::"alias_kind" NOT NULL,
	"created_by_profile_id" uuid,
	"withdrawn_at" timestamp(3) with time zone,
	"pinned" boolean DEFAULT false NOT NULL,
	"position" text collate "C",
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"unit_publishing_id" uuid,
	"unit_music_id" uuid,
	"unit_program_id" uuid,
	"unit_software_id" uuid,
	"unit_entity_id" uuid,
	"unit_grouping_id" uuid,
	"unit_reference_id" uuid,
	"unit_distribution_id" uuid,
	"unit_video_id" uuid,
	"unit_audio_id" uuid,
	"unit_post_id" uuid,
	"unit_poll_id" uuid,
	"unit_zone_id" uuid,
	"unit_realm_id" uuid,
	"unit_realm_rule_id" uuid,
	"unit_custom_theme_id" uuid,
	"unit_collection_id" uuid,
	"unit_tag_id" uuid,
	"unit_tag_path_id" uuid,
	"unit_label_id" uuid,
	CONSTRAINT "unit_alias_unit_language_normalized_key" UNIQUE NULLS NOT DISTINCT("unit_id","language","normalized_term"),
	CONSTRAINT "unit_alias_unit_target_check" CHECK (num_nonnulls("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id") = 1),
	CONSTRAINT "unit_alias_unit_id_check" CHECK ("unit_id" is not distinct from coalesce("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id")),
	CONSTRAINT "unit_alias_term_not_blank" CHECK (btrim("term") <> '' and btrim("normalized_term") <> ''),
	CONSTRAINT "unit_alias_language_check" CHECK ("language" is null or "language" in ('zh', 'en', 'ja', 'ko', 'de', 'fr', 'es')),
	CONSTRAINT "unit_alias_pinned_position_check" CHECK (("pinned" and "position" is not null)
					or (not "pinned" and "position" is null)),
	CONSTRAINT "unit_alias_withdrawn_curation_check" CHECK ("withdrawn_at" is null or (not "pinned" and "position" is null)),
	CONSTRAINT "unit_alias_position_byte_length_check" CHECK (octet_length("position") <= 1024)
);

CREATE TABLE "unit_alias_vote" (
	"alias_id" uuid,
