	"target_unit_tag_path_id" uuid,
	"target_unit_label_id" uuid,
	CONSTRAINT "unit_association_proposal_source_unit_target_check" CHECK (num_nonnulls("source_unit_publishing_id", "source_unit_music_id", "source_unit_program_id", "source_unit_software_id", "source_unit_entity_id", "source_unit_grouping_id", "source_unit_reference_id", "source_unit_distribution_id", "source_unit_video_id", "source_unit_audio_id", "source_unit_post_id", "source_unit_poll_id", "source_unit_zone_id", "source_unit_realm_id", "source_unit_realm_rule_id", "source_unit_custom_theme_id", "source_unit_collection_id", "source_unit_tag_id", "source_unit_tag_path_id", "source_unit_label_id") = 1),
	CONSTRAINT "unit_association_proposal_source_unit_id_check" CHECK ("source_unit_id" is not distinct from coalesce("source_unit_publishing_id", "source_unit_music_id", "source_unit_program_id", "source_unit_software_id", "source_unit_entity_id", "source_unit_grouping_id", "source_unit_reference_id", "source_unit_distribution_id", "source_unit_video_id", "source_unit_audio_id", "source_unit_post_id", "source_unit_poll_id", "source_unit_zone_id", "source_unit_realm_id", "source_unit_realm_rule_id", "source_unit_custom_theme_id", "source_unit_collection_id", "source_unit_tag_id", "source_unit_tag_path_id", "source_unit_label_id")),
