	CONSTRAINT "unit_association_proposal_target_unit_id_check" CHECK ("target_unit_id" is not distinct from coalesce("target_unit_publishing_id", "target_unit_music_id", "target_unit_program_id", "target_unit_software_id", "target_unit_entity_id", "target_unit_grouping_id", "target_unit_reference_id", "target_unit_distribution_id", "target_unit_video_id", "target_unit_audio_id", "target_unit_post_id", "target_unit_poll_id", "target_unit_zone_id", "target_unit_realm_id", "target_unit_realm_rule_id", "target_unit_custom_theme_id", "target_unit_collection_id", "target_unit_tag_id", "target_unit_tag_path_id", "target_unit_label_id")),
	CONSTRAINT "unit_association_proposal_authority_shape_check" CHECK (jsonb_typeof("creator_authority")='object' and octet_length("creator_authority"::text)<=4096),
	CONSTRAINT "unit_association_proposal_role_not_blank" CHECK (btrim("role") <> ''),
	CONSTRAINT "unit_association_proposal_role_check" CHECK ((
				"kind" = 'credit' and "role" in ('author', 'co-author', 'translator', 'illustrator', 'editor', 'publisher', 'letterer', 'colorist', 'developer', 'composer', 'designer', 'director', 'producer', 'writer', 'actor', 'narrator', 'studio', 'distributor')
			) or (
				"kind" = 'subject' and "role" in ('primary_character', 'featured_character', 'appears', 'about', 'setting', 'source_work', 'canonical_wiki_page', 'related_subject')
			)),
	CONSTRAINT "unit_association_proposal_context_post_shape_check" CHECK ((
				"kind" = 'credit' and "context_post_id" is null
			) or (
				"kind" = 'subject'
			)),
	CONSTRAINT "unit_association_proposal_not_self_check" CHECK ("source_unit_id" <> "target_unit_id"),
	CONSTRAINT "unit_association_proposal_expiry_check" CHECK ("expires_at" > "created_at"),
	CONSTRAINT "unit_association_proposal_resolution_shape_check" CHECK ((
				"resolution" is null and "resolved_at" is null and "resolved_by_profile_id" is null and "resolved_by_auth_user_id" is null
			) or (
				"resolution" is not null and "resolved_at" is not null and "resolved_by_profile_id" is not null and "resolved_by_auth_user_id" is not null
			))
);

