CREATE TABLE "unit_effective_tag" (
	"unit_id" uuid,
	"tag_id" uuid,
	"direct" boolean DEFAULT false NOT NULL,
	"primary_expression_count" bigint DEFAULT 0 NOT NULL,
	"entailed_expression_count" bigint DEFAULT 0 NOT NULL,
	"retrieval_expression_count" bigint DEFAULT 0 NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"unit_publishing_id" uuid,
	"unit_music_id" uuid,
	"unit_program_id" uuid,
	"unit_software_id" uuid,
	"unit_entity_id" uuid,
	"unit_grouping_id" uuid,
	"unit_reference_id" uuid,
	"unit_distribution_id" uuid,
	"unit_video_id" uuid,
	"unit_audio_id" uuid,
	"unit_post_id" uuid,
	"unit_poll_id" uuid,
	"unit_zone_id" uuid,
	"unit_realm_id" uuid,
	"unit_realm_rule_id" uuid,
	"unit_custom_theme_id" uuid,
	"unit_collection_id" uuid,
	"unit_tag_id" uuid,
	"unit_tag_path_id" uuid,
	"unit_label_id" uuid,
	CONSTRAINT "unit_effective_tag_pkey" PRIMARY KEY("unit_id","tag_id"),
	CONSTRAINT "unit_effective_tag_unit_target_check" CHECK (num_nonnulls("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id") = 1),
	CONSTRAINT "unit_effective_tag_unit_id_check" CHECK ("unit_id" is not distinct from coalesce("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id")),
	CONSTRAINT "unit_effective_tag_source_check" CHECK ("direct"
				or "primary_expression_count" > 0
				or "entailed_expression_count" > 0
				or "retrieval_expression_count" > 0),
	CONSTRAINT "unit_effective_tag_not_self_check" CHECK ("unit_id" <> "tag_id"),
	CONSTRAINT "unit_effective_tag_count_check" CHECK ("primary_expression_count" >= 0
				and "entailed_expression_count" >= 0
				and "retrieval_expression_count" >= 0)
);

