	CONSTRAINT "unit_external_link_hash_check" CHECK ("normalized_url_hash" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "unit_external_link_pinned_position_check" CHECK (("pinned" and "position" is not null)
