	CONSTRAINT "unit_license_grant_unit_id_check" CHECK ("unit_id" is not distinct from coalesce("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id")),
	CONSTRAINT "unit_license_grant_license_id_check" CHECK ("license_id" in ('cc-by-nc-sa-4.0', 'cc-by-sa-4.0', 'cc-by-sa-3.0', 'all-rights-reserved', 'cc-by-nc-4.0', 'cc-by-4.0', 'cc0-1.0', 'pdm-1.0', 'rezics-unit-content-license-v1-1')),
