			))
);

CREATE TABLE "unit_localization" (
	"unit_id" uuid,
	"language" text,
	"position" text collate "C" DEFAULT ('a0' || replace(uuidv7()::text, '-', '') || 'V') NOT NULL,
	"avatar_type" text,
	"avatar_asset_id" uuid,
	"avatar_emoji" text,
	"avatar_icon_prefix" text,
	"avatar_icon_name" text,
	"banner_asset_id" uuid,
	"cover_asset_id" uuid,
	"title" text,
	"summary" text,
	"description" jsonb,
	"content" jsonb,
	"content_status" "content_status",
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"unit_publishing_id" uuid,
	"unit_music_id" uuid,
	"unit_program_id" uuid,
	"unit_software_id" uuid,
	"unit_entity_id" uuid,
	"unit_grouping_id" uuid,
	"unit_reference_id" uuid,
	"unit_distribution_id" uuid,
	"unit_video_id" uuid,
	"unit_audio_id" uuid,
	"unit_post_id" uuid,
	"unit_poll_id" uuid,
	"unit_zone_id" uuid,
	"unit_realm_id" uuid,
	"unit_realm_rule_id" uuid,
	"unit_custom_theme_id" uuid,
	"unit_collection_id" uuid,
	"unit_tag_id" uuid,
	"unit_tag_path_id" uuid,
	"unit_label_id" uuid,
	CONSTRAINT "unit_localization_pkey" PRIMARY KEY("unit_id","language"),
	CONSTRAINT "unit_localization_unit_position_key" UNIQUE("unit_id","position"),
	CONSTRAINT "unit_localization_unit_target_check" CHECK (num_nonnulls("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id") = 1),
	CONSTRAINT "unit_localization_unit_id_check" CHECK ("unit_id" is not distinct from coalesce("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id")),
	CONSTRAINT "unit_localization_language_check" CHECK ("language" in ('zh', 'en', 'ja', 'ko', 'de', 'fr', 'es')),
	CONSTRAINT "unit_localization_avatar_type_check" CHECK ("avatar_type" in ('image', 'emoji', 'icon')),
	CONSTRAINT "unit_localization_avatar_value_check" CHECK ((
				"avatar_type" is null
				and "avatar_asset_id" is null
				and "avatar_emoji" is null
				and "avatar_icon_prefix" is null
				and "avatar_icon_name" is null
			) or (
				"avatar_type" = 'image'
				and "avatar_asset_id" is not null
				and "avatar_emoji" is null
				and "avatar_icon_prefix" is null
				and "avatar_icon_name" is null
			) or (
				"avatar_type" = 'emoji'
				and "avatar_asset_id" is null
				and "avatar_emoji" is not null
				and char_length("avatar_emoji") <= 64
				and "avatar_icon_prefix" is null
				and "avatar_icon_name" is null
			) or (
				"avatar_type" = 'icon'
				and "avatar_asset_id" is null
				and "avatar_emoji" is null
				and "avatar_icon_prefix" is not null
				and "avatar_icon_prefix" in ('fas', 'fab')
				and "avatar_icon_name" is not null
				and "avatar_icon_name" ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'
				and char_length("avatar_icon_name") <= 128
			)),
	CONSTRAINT "unit_localization_value_check" CHECK ("avatar_type" is not null or "banner_asset_id" is not null or "cover_asset_id" is not null or "title" is not null or "summary" is not null or "description" is not null or "content" is not null),
	CONSTRAINT "unit_localization_content_state_check" CHECK (("content" is null) = ("content_status" is null)),
	CONSTRAINT "unit_localization_position_byte_length_check" CHECK (octet_length("position") <= 1024)
);

CREATE TABLE "unit_localization_content_metric" (
	"unit_id" uuid,
	"language" text,
	"word_count" integer NOT NULL,
	"character_count" integer NOT NULL,
	"algorithm_version" integer NOT NULL,
	"source_sha256" text NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "unit_localization_content_metric_pkey" PRIMARY KEY("unit_id","language"),
	CONSTRAINT "unit_localization_content_metric_language_check" CHECK ("language" in ('zh', 'en', 'ja', 'ko', 'de', 'fr', 'es')),
	CONSTRAINT "unit_localization_content_metric_word_count_check" CHECK ("word_count" >= 0),
	CONSTRAINT "unit_localization_content_metric_character_count_check" CHECK ("character_count" >= 0),
	CONSTRAINT "unit_localization_content_metric_algorithm_version_check" CHECK ("algorithm_version" > 0),
	CONSTRAINT "unit_localization_content_metric_source_sha256_check" CHECK ("source_sha256" ~ '^[0-9a-f]{64}$')
);

