CREATE TABLE "unit_merge_operation" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"request_id" uuid NOT NULL CONSTRAINT "unit_merge_operation_request_key" UNIQUE,
	"source_unit_id" uuid NOT NULL,
	"target_unit_id" uuid NOT NULL,
	"owner" text NOT NULL,
	"shard" smallint NOT NULL,
	"state" "unit_merge_operation_state" DEFAULT 'pending'::"unit_merge_operation_state" NOT NULL,
	"phase" "unit_merge_operation_phase" DEFAULT 'canonicalize'::"unit_merge_operation_phase" NOT NULL,
	"cursor_id" uuid,
	"cursor_secondary_id" uuid,
	"executor_auth_user_id" uuid NOT NULL,
	"executor_profile_id" uuid NOT NULL,
	"executor_authority" jsonb NOT NULL,
	"attempt_count" integer DEFAULT 0 NOT NULL,
	"processed_rows" bigint DEFAULT 0 NOT NULL,
	"total_items" bigint DEFAULT 0 NOT NULL,
	"resolved_items" bigint DEFAULT 0 NOT NULL,
	"available_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"lease_token" uuid,
	"lease_expires_at" timestamp(3) with time zone,
	"last_error_code" text,
	"last_error_message" text,
	"started_at" timestamp(3) with time zone,
	"completed_at" timestamp(3) with time zone,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "unit_merge_operation_shard_check" CHECK ("shard" between 0 and 63),
	CONSTRAINT "unit_merge_operation_counters_check" CHECK ("processed_rows" between 0 and 9007199254740991 and "total_items" between 0 and 9007199254740991 and "resolved_items" between 0 and "total_items" and "attempt_count">=0),
	CONSTRAINT "unit_merge_operation_lease_check" CHECK (("state"='processing')=("lease_token" is not null and "lease_expires_at" is not null)),
	CONSTRAINT "unit_merge_operation_error_check" CHECK (("last_error_code" is null)=("last_error_message" is null) and ("last_error_message" is null or octet_length("last_error_message")<=2048)),
	CONSTRAINT "unit_merge_operation_authority_check" CHECK (jsonb_typeof("executor_authority")='object' and octet_length("executor_authority"::text)<=4096 and "executor_authority"->'principal'->>'kind'='auth' and ("executor_authority"->'principal'->>'authUserId')::uuid="executor_auth_user_id")
);

