	"source_distribution_owner_id" uuid GENERATED ALWAYS AS (case when owner='distribution' then source_unit_id end) STORED,
	"target_publishing_owner_id" uuid GENERATED ALWAYS AS (case when owner='publishing' then target_unit_id end) STORED,
