	"target_unit_collection_id" uuid,
	"target_unit_tag_id" uuid,
	"target_unit_tag_path_id" uuid,
	"target_unit_label_id" uuid,
	CONSTRAINT "unit_merge_reconciliation_item_pkey" PRIMARY KEY("request_id","id"),
	CONSTRAINT "unit_merge_item_source_key" UNIQUE("request_id","kind","source_key"),
	CONSTRAINT "unit_merge_reconciliation_item_source_unit_target_check" CHECK (num_nonnulls("source_unit_publishing_id", "source_unit_music_id", "source_unit_program_id", "source_unit_software_id", "source_unit_entity_id", "source_unit_grouping_id", "source_unit_reference_id", "source_unit_distribution_id", "source_unit_video_id", "source_unit_audio_id", "source_unit_post_id", "source_unit_poll_id", "source_unit_zone_id", "source_unit_realm_id", "source_unit_realm_rule_id", "source_unit_custom_theme_id", "source_unit_collection_id", "source_unit_tag_id", "source_unit_tag_path_id", "source_unit_label_id") = 1),
	CONSTRAINT "unit_merge_reconciliation_item_source_unit_id_check" CHECK ("source_unit_id" is not distinct from coalesce("source_unit_publishing_id", "source_unit_music_id", "source_unit_program_id", "source_unit_software_id", "source_unit_entity_id", "source_unit_grouping_id", "source_unit_reference_id", "source_unit_distribution_id", "source_unit_video_id", "source_unit_audio_id", "source_unit_post_id", "source_unit_poll_id", "source_unit_zone_id", "source_unit_realm_id", "source_unit_realm_rule_id", "source_unit_custom_theme_id", "source_unit_collection_id", "source_unit_tag_id", "source_unit_tag_path_id", "source_unit_label_id")),
	CONSTRAINT "unit_merge_reconciliation_item_target_unit_target_check" CHECK (num_nonnulls("target_unit_publishing_id", "target_unit_music_id", "target_unit_program_id", "target_unit_software_id", "target_unit_entity_id", "target_unit_grouping_id", "target_unit_reference_id", "target_unit_distribution_id", "target_unit_video_id", "target_unit_audio_id", "target_unit_post_id", "target_unit_poll_id", "target_unit_zone_id", "target_unit_realm_id", "target_unit_realm_rule_id", "target_unit_custom_theme_id", "target_unit_collection_id", "target_unit_tag_id", "target_unit_tag_path_id", "target_unit_label_id") = 1),
	CONSTRAINT "unit_merge_reconciliation_item_target_unit_id_check" CHECK ("target_unit_id" is not distinct from coalesce("target_unit_publishing_id", "target_unit_music_id", "target_unit_program_id", "target_unit_software_id", "target_unit_entity_id", "target_unit_grouping_id", "target_unit_reference_id", "target_unit_distribution_id", "target_unit_video_id", "target_unit_audio_id", "target_unit_post_id", "target_unit_poll_id", "target_unit_zone_id", "target_unit_realm_id", "target_unit_realm_rule_id", "target_unit_custom_theme_id", "target_unit_collection_id", "target_unit_tag_id", "target_unit_tag_path_id", "target_unit_label_id")),
	CONSTRAINT "unit_merge_item_kind_check" CHECK ("kind" in ('name', 'identifier', 'semantic', 'source_binding', 'structure')),
	CONSTRAINT "unit_merge_item_state_check" CHECK ("state" in ('pending', 'applied', 'retained', 'action_required')),
	CONSTRAINT "unit_merge_item_key_check" CHECK (octet_length("source_key") between 1 and 256),
	CONSTRAINT "unit_merge_item_root_revision_check" CHECK ("source_owner_revision" between 1 and 9007199254740991 and ("target_owner_revision" is null or "target_owner_revision" between 1 and 9007199254740991)),
	CONSTRAINT "unit_merge_item_history_shape_check" CHECK (case "kind" when 'name' then "source_name_id" is not null and "source_name_revision">0 and num_nonnulls("source_identifier_id","source_semantic_id","source_record_id")=0 when 'identifier' then "source_identifier_id" is not null and "source_identifier_revision">0 and num_nonnulls("source_name_id","source_semantic_id","source_record_id")=0 when 'semantic' then "source_semantic_id" is not null and "source_semantic_version">0 and num_nonnulls("source_name_id","source_identifier_id","source_record_id")=0 when 'source_binding' then "source_record_id" is not null and "mapping_key" is not null and "source_binding_revision">0 and num_nonnulls("source_name_id","source_identifier_id","source_semantic_id")=0 when 'structure' then num_nonnulls("source_name_id","source_identifier_id","source_semantic_id","source_record_id")=0 else false end),
	CONSTRAINT "unit_merge_item_target_shape_check" CHECK (num_nonnulls("target_name_id","target_name_revision") in (0,2) and num_nonnulls("target_identifier_id","target_identifier_revision") in (0,2)),
	CONSTRAINT "unit_merge_item_resolution_check" CHECK (("state" in ('applied','retained'))=("resolved_at" is not null and "resolved_by_auth_user_id" is not null and "decision" is not null))
) PARTITION BY HASH ("request_id");
