	"target_updated_at" timestamp(3) with time zone NOT NULL,
	"status_at_request" text NOT NULL,
	"visibility_at_request" text NOT NULL,
	"source_title" text,
	"target_title" text,
	"proposer_profile_id" uuid NOT NULL,
	"proposer_auth_user_id" uuid NOT NULL,
	"proposer_authority" jsonb NOT NULL,
	"idempotency_key" text NOT NULL,
	"decision_id" uuid NOT NULL,
	"request_fingerprint" text NOT NULL,
	"plan" jsonb NOT NULL,
	"note" text,
	"policy_version" smallint DEFAULT 1 NOT NULL,
	"required_approvals" smallint DEFAULT 2 NOT NULL,
	"veto_enabled" boolean DEFAULT true NOT NULL,
	"self_review_forbidden" boolean DEFAULT true NOT NULL,
	"state" "unit_merge_request_state" DEFAULT 'pending_review'::"unit_merge_request_state" NOT NULL,
	"expires_at" timestamp(3) with time zone NOT NULL,
	"accepted_at" timestamp(3) with time zone,
	"canonicalized_at" timestamp(3) with time zone,
	"completed_at" timestamp(3) with time zone,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"source_unit_publishing_id" uuid,
	"source_unit_music_id" uuid,
	"source_unit_program_id" uuid,
	"source_unit_software_id" uuid,
	"source_unit_entity_id" uuid,
	"source_unit_grouping_id" uuid,
	"source_unit_reference_id" uuid,
	"source_unit_distribution_id" uuid,
	"source_unit_video_id" uuid,
	"source_unit_audio_id" uuid,
	"source_unit_post_id" uuid,
	"source_unit_poll_id" uuid,
	"source_unit_zone_id" uuid,
	"source_unit_realm_id" uuid,
	"source_unit_realm_rule_id" uuid,
	"source_unit_custom_theme_id" uuid,
	"source_unit_collection_id" uuid,
	"source_unit_tag_id" uuid,
	"source_unit_tag_path_id" uuid,
	"source_unit_label_id" uuid,
	"target_unit_publishing_id" uuid,
	"target_unit_music_id" uuid,
	"target_unit_program_id" uuid,
	"target_unit_software_id" uuid,
	"target_unit_entity_id" uuid,
	"target_unit_grouping_id" uuid,
	"target_unit_reference_id" uuid,
	"target_unit_distribution_id" uuid,
	"target_unit_video_id" uuid,
	"target_unit_audio_id" uuid,
	"target_unit_post_id" uuid,
	"target_unit_poll_id" uuid,
	"target_unit_zone_id" uuid,
	"target_unit_realm_id" uuid,
	"target_unit_realm_rule_id" uuid,
	"target_unit_custom_theme_id" uuid,
	"target_unit_collection_id" uuid,
	"target_unit_tag_id" uuid,
	"target_unit_tag_path_id" uuid,
	"target_unit_label_id" uuid,
	CONSTRAINT "unit_merge_request_pair_key" UNIQUE("id","owner","source_unit_id","target_unit_id"),
	CONSTRAINT "unit_merge_request_actor_idempotency_key" UNIQUE("proposer_auth_user_id","idempotency_key"),
	CONSTRAINT "unit_merge_request_source_unit_target_check" CHECK (num_nonnulls("source_unit_publishing_id", "source_unit_music_id", "source_unit_program_id", "source_unit_software_id", "source_unit_entity_id", "source_unit_grouping_id", "source_unit_reference_id", "source_unit_distribution_id", "source_unit_video_id", "source_unit_audio_id", "source_unit_post_id", "source_unit_poll_id", "source_unit_zone_id", "source_unit_realm_id", "source_unit_realm_rule_id", "source_unit_custom_theme_id", "source_unit_collection_id", "source_unit_tag_id", "source_unit_tag_path_id", "source_unit_label_id") = 1),
	CONSTRAINT "unit_merge_request_source_unit_id_check" CHECK ("source_unit_id" is not distinct from coalesce("source_unit_publishing_id", "source_unit_music_id", "source_unit_program_id", "source_unit_software_id", "source_unit_entity_id", "source_unit_grouping_id", "source_unit_reference_id", "source_unit_distribution_id", "source_unit_video_id", "source_unit_audio_id", "source_unit_post_id", "source_unit_poll_id", "source_unit_zone_id", "source_unit_realm_id", "source_unit_realm_rule_id", "source_unit_custom_theme_id", "source_unit_collection_id", "source_unit_tag_id", "source_unit_tag_path_id", "source_unit_label_id")),
	CONSTRAINT "unit_merge_request_target_unit_target_check" CHECK (num_nonnulls("target_unit_publishing_id", "target_unit_music_id", "target_unit_program_id", "target_unit_software_id", "target_unit_entity_id", "target_unit_grouping_id", "target_unit_reference_id", "target_unit_distribution_id", "target_unit_video_id", "target_unit_audio_id", "target_unit_post_id", "target_unit_poll_id", "target_unit_zone_id", "target_unit_realm_id", "target_unit_realm_rule_id", "target_unit_custom_theme_id", "target_unit_collection_id", "target_unit_tag_id", "target_unit_tag_path_id", "target_unit_label_id") = 1),
	CONSTRAINT "unit_merge_request_target_unit_id_check" CHECK ("target_unit_id" is not distinct from coalesce("target_unit_publishing_id", "target_unit_music_id", "target_unit_program_id", "target_unit_software_id", "target_unit_entity_id", "target_unit_grouping_id", "target_unit_reference_id", "target_unit_distribution_id", "target_unit_video_id", "target_unit_audio_id", "target_unit_post_id", "target_unit_poll_id", "target_unit_zone_id", "target_unit_realm_id", "target_unit_realm_rule_id", "target_unit_custom_theme_id", "target_unit_collection_id", "target_unit_tag_id", "target_unit_tag_path_id", "target_unit_label_id")),
	CONSTRAINT "unit_merge_request_owner_check" CHECK ("owner" in ('publishing', 'music', 'program', 'software', 'entity', 'grouping', 'reference', 'distribution')),
	CONSTRAINT "unit_merge_request_native_pair_check" CHECK (coalesce((case "owner" when 'publishing' then "source_unit_publishing_id" when 'music' then "source_unit_music_id" when 'program' then "source_unit_program_id" when 'software' then "source_unit_software_id" when 'entity' then "source_unit_entity_id" when 'grouping' then "source_unit_grouping_id" when 'reference' then "source_unit_reference_id" when 'distribution' then "source_unit_distribution_id" end)="source_unit_id" and (case "owner" when 'publishing' then "target_unit_publishing_id" when 'music' then "target_unit_music_id" when 'program' then "target_unit_program_id" when 'software' then "target_unit_software_id" when 'entity' then "target_unit_entity_id" when 'grouping' then "target_unit_grouping_id" when 'reference' then "target_unit_reference_id" when 'distribution' then "target_unit_distribution_id" end)="target_unit_id",false)),
	CONSTRAINT "unit_merge_request_not_self_check" CHECK ("source_unit_id"<>"target_unit_id"),
	CONSTRAINT "unit_merge_request_revision_check" CHECK ("source_revision" between 1 and 9007199254740991 and "target_revision" between 1 and 9007199254740991),
	CONSTRAINT "unit_merge_request_shape_check" CHECK ("shape"~'^[a-z][a-z0-9_.-]{0,95}$'),
	CONSTRAINT "unit_merge_request_lifecycle_check" CHECK ("status_at_request" in ('draft','published','archived') and "visibility_at_request" in ('public','unlisted','private')),
	CONSTRAINT "unit_merge_request_review_policy_check" CHECK ("policy_version"=1 and "required_approvals"=2 and "veto_enabled" and "self_review_forbidden"),
	CONSTRAINT "unit_merge_request_fingerprint_check" CHECK ("request_fingerprint"~'^[a-f0-9]{64}$'),
	CONSTRAINT "unit_merge_request_size_check" CHECK (octet_length("idempotency_key") between 1 and 200 and ("note" is null or octet_length("note")<=8000) and ("source_title" is null or char_length("source_title")<=500) and ("target_title" is null or char_length("target_title")<=500)),
	CONSTRAINT "unit_merge_request_authority_check" CHECK (jsonb_typeof("proposer_authority")='object' and octet_length("proposer_authority"::text)<=4096 and "proposer_authority"->'principal'->>'kind'='auth' and ("proposer_authority"->'principal'->>'authUserId')::uuid="proposer_auth_user_id"),
	CONSTRAINT "unit_merge_request_plan_check" CHECK (jsonb_typeof("plan")='object' and octet_length("plan"::text)<=1024 and "plan"->>'names' in ('copy_alternates','retain_source') and "plan"->>'identifiers' in ('copy_claims','retain_source') and "plan"->>'semantics'='retain_source' and "plan"->>'structure'='retain_source' and "plan"->>'bindings' in ('rebind_paused','pause_at_source') and "plan"->>'retainedAccess'='target_readers')
);

CREATE TABLE "unit_merge_review" (
