CREATE TABLE "unit_progress" (
	"auth_user_id" uuid,
	"unit_id" uuid,
	"progress" double precision DEFAULT 0 NOT NULL,
	"status" "progress_status" DEFAULT 'backlog'::"progress_status" NOT NULL,
	"completed_count" integer DEFAULT 0 NOT NULL,
	"total_time_ms" bigint DEFAULT 0 NOT NULL,
	"first_seen_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"last_seen_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"last_content_structure_node_id" uuid,
	"current_entry_id" uuid,
	"current_basis" text,
	"visibility" "resource_visibility" DEFAULT 'public'::"resource_visibility" NOT NULL,
	"deleted_at" timestamp(3) with time zone,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"unit_publishing_id" uuid,
	"unit_music_id" uuid,
	"unit_program_id" uuid,
	"unit_software_id" uuid,
	"unit_entity_id" uuid,
	"unit_grouping_id" uuid,
	"unit_reference_id" uuid,
	"unit_distribution_id" uuid,
	"unit_video_id" uuid,
	"unit_audio_id" uuid,
	"unit_post_id" uuid,
	"unit_poll_id" uuid,
	"unit_zone_id" uuid,
	"unit_realm_id" uuid,
	"unit_realm_rule_id" uuid,
	"unit_custom_theme_id" uuid,
	"unit_collection_id" uuid,
	"unit_tag_id" uuid,
	"unit_tag_path_id" uuid,
	"unit_label_id" uuid,
	CONSTRAINT "unit_progress_pkey" PRIMARY KEY("auth_user_id","unit_id"),
	CONSTRAINT "unit_progress_unit_target_check" CHECK (num_nonnulls("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id") = 1),
	CONSTRAINT "unit_progress_unit_id_check" CHECK ("unit_id" is not distinct from coalesce("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id")),
	CONSTRAINT "unit_progress_current_basis_check" CHECK ("current_basis" is null or "current_basis" in ('journal', 'reading')),
	CONSTRAINT "unit_progress_current_basis_shape_check" CHECK (case
				when "current_basis" is null then "current_entry_id" is null
				when "current_basis" = 'journal' then "current_entry_id" is not null
				when "current_basis" = 'reading' then "current_entry_id" is null
				else false
			end),
	CONSTRAINT "unit_progress_value_check" CHECK ("progress" between 0 and 1),
	CONSTRAINT "unit_progress_count_check" CHECK ("completed_count" >= 0 and "total_time_ms" >= 0),
	CONSTRAINT "unit_progress_seen_check" CHECK ("last_seen_at" >= "first_seen_at"),
	CONSTRAINT "unit_progress_deleted_at_check" CHECK ("deleted_at" is null or "deleted_at" >= "created_at")
);

