	CONSTRAINT "unit_tag_unit_id_check" CHECK ("unit_id" is not distinct from coalesce("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id")),
	CONSTRAINT "unit_tag_pinned_position_check" CHECK (("pinned" and "position" is not null)
				or (not "pinned" and "position" is null)),
	CONSTRAINT "unit_tag_not_self_check" CHECK ("unit_id" <> "tag_id"),
	CONSTRAINT "unit_tag_position_byte_length_check" CHECK (octet_length("position") <= 1024)
);

CREATE TABLE "unit_tag_judgment" (
	"unit_id" uuid,
	"unit_publishing_id" uuid,
	"unit_music_id" uuid,
	"unit_program_id" uuid,
	"unit_software_id" uuid,
	"unit_entity_id" uuid,
	"unit_grouping_id" uuid,
	"unit_reference_id" uuid,
	"unit_distribution_id" uuid,
	"unit_video_id" uuid,
	"unit_audio_id" uuid,
	"unit_post_id" uuid,
	"unit_poll_id" uuid,
	"unit_zone_id" uuid,
	"unit_realm_id" uuid,
	"unit_realm_rule_id" uuid,
	"unit_custom_theme_id" uuid,
	"unit_collection_id" uuid,
	"unit_tag_id" uuid,
	"unit_tag_path_id" uuid,
	"unit_label_id" uuid,
	"tag_id" uuid,
	"profile_id" uuid,
	"fit_vote" integer,
	"spoiler_level" smallint,
	"fit_updated_at" timestamp(3) with time zone,
	"spoiler_updated_at" timestamp(3) with time zone,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "unit_tag_judgment_pkey" PRIMARY KEY("unit_id","tag_id","profile_id"),
	CONSTRAINT "unit_tag_judgment_unit_target_check" CHECK (num_nonnulls("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id") = 1),
	CONSTRAINT "unit_tag_judgment_unit_id_check" CHECK ("unit_id" is not distinct from coalesce("unit_publishing_id", "unit_music_id", "unit_program_id", "unit_software_id", "unit_entity_id", "unit_grouping_id", "unit_reference_id", "unit_distribution_id", "unit_video_id", "unit_audio_id", "unit_post_id", "unit_poll_id", "unit_zone_id", "unit_realm_id", "unit_realm_rule_id", "unit_custom_theme_id", "unit_collection_id", "unit_tag_id", "unit_tag_path_id", "unit_label_id")),
	CONSTRAINT "unit_tag_judgment_not_self_check" CHECK ("unit_id" <> "tag_id"),
	CONSTRAINT "unit_tag_judgment_fit_vote_check" CHECK ("fit_vote" is null or "fit_vote" in (-1, 1)),
	CONSTRAINT "unit_tag_judgment_spoiler_level_check" CHECK ("spoiler_level" is null or "spoiler_level" between 0 and 2),
	CONSTRAINT "unit_tag_judgment_sparse_check" CHECK ("fit_vote" is not null or "spoiler_level" is not null),
	CONSTRAINT "unit_tag_judgment_fit_timestamp_check" CHECK (("fit_vote" is null) = ("fit_updated_at" is null)),
	CONSTRAINT "unit_tag_judgment_spoiler_timestamp_check" CHECK (("spoiler_level" is null) = ("spoiler_updated_at" is null))
);

CREATE TABLE "unit_tag_judgment_stat" (
	"unit_id" uuid,
	"tag_id" uuid,
	"score" bigint DEFAULT 0 NOT NULL,
	"vote_count" bigint DEFAULT 0 NOT NULL,
	"spoiler_vote_count" bigint DEFAULT 0 NOT NULL,
	"spoiler_none_count" bigint DEFAULT 0 NOT NULL,
	"spoiler_minor_count" bigint DEFAULT 0 NOT NULL,
	"spoiler_major_count" bigint DEFAULT 0 NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "unit_tag_judgment_stat_pkey" PRIMARY KEY("unit_id","tag_id"),
	CONSTRAINT "unit_tag_judgment_stat_count_check" CHECK ("vote_count" >= 0),
	CONSTRAINT "unit_tag_judgment_stat_score_check" CHECK (abs("score") <= "vote_count"),
	CONSTRAINT "unit_tag_judgment_stat_parity_check" CHECK (("vote_count" + "score") % 2 = 0),
	CONSTRAINT "unit_tag_judgment_stat_spoiler_nonnegative_check" CHECK ("spoiler_vote_count" >= 0
				and "spoiler_none_count" >= 0
				and "spoiler_minor_count" >= 0
				and "spoiler_major_count" >= 0),
	CONSTRAINT "unit_tag_judgment_stat_spoiler_count_check" CHECK ("spoiler_vote_count" =
				"spoiler_none_count" + "spoiler_minor_count" + "spoiler_major_count")
);

