CREATE TABLE "user_account_state" (
	"user_id" uuid PRIMARY KEY,
	"state" "user_account_state_value" DEFAULT 'active'::"user_account_state_value" NOT NULL,
	"decision_id" uuid,
	"note" text,
	"expires_at" timestamp(3) with time zone,
	"updated_by_auth_user_id" uuid NOT NULL,
	"revision" integer DEFAULT 1 NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "user_account_state_revision_check" CHECK ("revision" > 0),
	CONSTRAINT "user_account_state_shape_check" CHECK ((
				"state" = 'active'::user_account_state_value
				and "note" is null
				and "expires_at" is null
			) or (
				"state" = 'suspended'::user_account_state_value
			) or (
				"state" = 'closed'::user_account_state_value
				and "expires_at" is null
			))
);

CREATE TABLE "users" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"principal_kind" text DEFAULT 'human' NOT NULL,
	"erased_at" timestamp(3) with time zone,
	"name" text NOT NULL,
	"email" text NOT NULL UNIQUE,
	"email_verified" boolean DEFAULT false NOT NULL,
	"image" text,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"registration_content_language" text DEFAULT 'en' NOT NULL,
	CONSTRAINT "users_principal_kind_check" CHECK ("principal_kind" in ('human', 'service')),
	CONSTRAINT "users_registration_content_language_check" CHECK ("registration_content_language" in ('zh', 'en', 'ja', 'ko', 'de', 'fr', 'es'))
);

CREATE TABLE "verifications" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"identifier" text NOT NULL,
	"value" text NOT NULL,
	"expires_at" timestamp(3) with time zone NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "video" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"revision" bigint DEFAULT 1 NOT NULL,
	"routing_generation" integer DEFAULT 1 NOT NULL,
	"created_by_auth_user_id" uuid,
	"status" "unit_status" DEFAULT 'draft'::"unit_status" NOT NULL,
	"visibility" "resource_visibility" DEFAULT 'public'::"resource_visibility" NOT NULL,
	"content_rating" "content_rating" DEFAULT 'general'::"content_rating" NOT NULL,
	"ai_disclosure" "ai_disclosure" DEFAULT 'unknown'::"ai_disclosure" NOT NULL,
	"moderation_status" "moderation_status" DEFAULT 'approved'::"moderation_status" NOT NULL,
	"post_targeting_locked" boolean DEFAULT false NOT NULL,
	"published_at" timestamp(3) with time zone,
	"deleted_at" timestamp(3) with time zone,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"duration_seconds" integer,
	CONSTRAINT "video_identity_revision_check" CHECK ("revision" between 1 and 9007199254740991 and "routing_generation" between 1 and 2147483647),
	CONSTRAINT "video_identity_publication_check" CHECK ("status" <> 'published' or "published_at" is not null),
	CONSTRAINT "video_identity_deleted_at_check" CHECK ("deleted_at" is null or "deleted_at" >= "created_at"),
	CONSTRAINT "video_duration_seconds_check" CHECK ("duration_seconds" is null or "duration_seconds" > 0)
);

CREATE TABLE "video_audio_track" (
	"video_unit_id" uuid,
	"audio_unit_id" uuid,
	CONSTRAINT "video_audio_track_video_audio_pkey" PRIMARY KEY("video_unit_id","audio_unit_id"),
	CONSTRAINT "video_audio_track_not_self_check" CHECK ("video_unit_id" <> "audio_unit_id")
);

CREATE TABLE "vocabulary_node" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"kind" text NOT NULL,
	"status" text DEFAULT 'active' NOT NULL,
	"created_by_profile_id" uuid,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"retired_at" timestamp(3) with time zone,
	CONSTRAINT "vocabulary_node_id_kind_key" UNIQUE("id","kind"),
	CONSTRAINT "vocabulary_node_kind_check" CHECK ("kind" in ('concept', 'guide')),
	CONSTRAINT "vocabulary_node_status_check" CHECK ("status" in ('active', 'retired')),
	CONSTRAINT "vocabulary_node_retirement_check" CHECK (("status" = 'active' and "retired_at" is null)
				or ("status" = 'retired' and "retired_at" is not null))
);

CREATE TABLE "zone" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"revision" bigint DEFAULT 1 NOT NULL,
	"routing_generation" integer DEFAULT 1 NOT NULL,
	"created_by_auth_user_id" uuid,
	"status" "unit_status" DEFAULT 'draft'::"unit_status" NOT NULL,
	"visibility" "resource_visibility" DEFAULT 'public'::"resource_visibility" NOT NULL,
	"content_rating" "content_rating" DEFAULT 'general'::"content_rating" NOT NULL,
	"ai_disclosure" "ai_disclosure" DEFAULT 'unknown'::"ai_disclosure" NOT NULL,
	"moderation_status" "moderation_status" DEFAULT 'approved'::"moderation_status" NOT NULL,
	"post_targeting_locked" boolean DEFAULT false NOT NULL,
	"published_at" timestamp(3) with time zone,
	"deleted_at" timestamp(3) with time zone,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"filter_document" jsonb NOT NULL,
	"appearance_document" jsonb NOT NULL,
	"starts_at" timestamp(3) with time zone,
	"ends_at" timestamp(3) with time zone,
	"local_rule_realm_id" uuid,
	CONSTRAINT "zone_identity_revision_check" CHECK ("revision" between 1 and 9007199254740991 and "routing_generation" between 1 and 2147483647),
	CONSTRAINT "zone_identity_publication_check" CHECK ("status" <> 'published' or "published_at" is not null),
	CONSTRAINT "zone_identity_deleted_at_check" CHECK ("deleted_at" is null or "deleted_at" >= "created_at"),
	CONSTRAINT "zone_time_range_check" CHECK ("ends_at" is null or "starts_at" is null or "ends_at" > "starts_at")
);

CREATE TABLE "zone_page" (
	"id" uuid PRIMARY KEY,
	"zone_id" uuid NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL
);

