-- Two-sided consent retains the private authority admitted by the initiating request.
CREATE OR REPLACE FUNCTION public.association_proposal_guard_authority()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$
DECLARE creator_auth uuid;
BEGIN
 IF TG_OP='UPDATE' AND (NEW.source_unit_id,NEW.target_unit_id,NEW.context_post_id,NEW.kind,NEW.role,NEW.direction,NEW.created_by_profile_id,NEW.creator_authority,NEW.expires_at,NEW.created_at) IS DISTINCT FROM
 (OLD.source_unit_id,OLD.target_unit_id,OLD.context_post_id,OLD.kind,OLD.role,OLD.direction,OLD.created_by_profile_id,OLD.creator_authority,OLD.expires_at,OLD.created_at) THEN
  RAISE EXCEPTION 'Association proposal admission and scope are immutable' USING ERRCODE='23514';
 END IF;
 IF TG_OP='INSERT' THEN
  -- Stored generated FK columns are not available to BEFORE triggers; validate the authoritative JSON.
  creator_auth := (NEW.creator_authority->'principal'->>'authUserId')::uuid;
  PERFORM 1 FROM public.auth_entity a JOIN public.users u ON u.id=a.auth_user_id
   WHERE a.auth_user_id=creator_auth AND a.entity_id=NEW.created_by_profile_id AND a.state='active' AND u.erased_at IS NULL FOR SHARE OF a,u;
  IF NOT FOUND THEN RAISE EXCEPTION 'Association creator must be the admitted account self identity' USING ERRCODE='23514'; END IF;
 END IF;
 IF NEW.resolution IS NOT NULL THEN
  IF TG_OP='UPDATE' AND OLD.resolution IS NOT NULL THEN RAISE EXCEPTION 'Association resolution is immutable' USING ERRCODE='23514'; END IF;
  PERFORM 1 FROM public.auth_entity a JOIN public.users u ON u.id=a.auth_user_id
   WHERE a.auth_user_id=NEW.resolved_by_auth_user_id AND a.entity_id=NEW.resolved_by_profile_id AND a.state='active' AND u.erased_at IS NULL FOR SHARE OF a,u;
  IF NOT FOUND THEN RAISE EXCEPTION 'Association resolver must be an active account self identity' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS association_proposal_authority_guard ON public.unit_association_proposal;
CREATE TRIGGER association_proposal_authority_guard BEFORE INSERT OR UPDATE ON public.unit_association_proposal FOR EACH ROW EXECUTE FUNCTION public.association_proposal_guard_authority();


-- Persisted queue authority remains a concrete account/entity/grant fact, not an opaque JSON assertion.
CREATE OR REPLACE FUNCTION public.music_release_source_job_guard()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$
DECLARE a uuid; e uuid; g uuid; s uuid; r bigint; gr bigint; principal_kind text;
BEGIN
 IF TG_OP='UPDATE' THEN
  IF (NEW.source_record_id,NEW.id,NEW.proposal_id,NEW.snapshot_id,NEW.action,NEW.reason,NEW.created_at) IS DISTINCT FROM
     (OLD.source_record_id,OLD.id,OLD.proposal_id,OLD.snapshot_id,OLD.action,OLD.reason,OLD.created_at) THEN
   RAISE EXCEPTION 'Release job admission is immutable' USING ERRCODE='23514';
  END IF;
  IF NEW.generation < OLD.generation OR NEW.generation > OLD.generation+1 THEN
   RAISE EXCEPTION 'Release job generation must remain current or advance once' USING ERRCODE='23514';
  END IF;
  IF NEW.authority IS DISTINCT FROM OLD.authority AND NOT
     (NEW.generation=OLD.generation+1 AND (NEW.state='paused' OR (OLD.state IN ('paused','failed') AND NEW.state IN ('queued','prepared')))) THEN
   RAISE EXCEPTION 'Release job authority changes only during an explicit control generation' USING ERRCODE='23514';
  END IF;
  IF OLD.preparation IS NOT NULL AND NEW.preparation IS DISTINCT FROM OLD.preparation THEN
   RAISE EXCEPTION 'Prepared release evidence is immutable' USING ERRCODE='23514';
  END IF;
  IF NEW.prepared_dependency_count < OLD.prepared_dependency_count OR NEW.next_dependency_position < OLD.next_dependency_position OR (OLD.preparation_complete AND NOT NEW.preparation_complete) THEN
   RAISE EXCEPTION 'Release preparation progress is monotone' USING ERRCODE='23514';
  END IF;
  IF OLD.music_id IS NOT NULL AND NEW.music_id IS DISTINCT FROM OLD.music_id THEN
   RAISE EXCEPTION 'Release job native target is immutable' USING ERRCODE='23514';
  END IF;
 END IF;
 IF TG_OP='INSERT' OR NEW.authority IS DISTINCT FROM OLD.authority THEN
  a := (NEW.authority->'principal'->>'authUserId')::uuid;
  e := (NEW.authority->>'actingEntityId')::uuid;
  g := (NEW.authority->'grant'->>'id')::uuid;
  s := (NEW.authority->'principal'->>'servicePrincipalId')::uuid;
  r := (NEW.authority->>'authorizationRevision')::bigint;
  gr := (NEW.authority->'grant'->>'revision')::bigint;
  principal_kind := NEW.authority->'principal'->>'kind';
  IF a IS NULL OR e IS NULL OR r IS NULL OR r<1 OR principal_kind NOT IN ('auth','service') THEN
   RAISE EXCEPTION 'Invalid release job authority' USING ERRCODE='23514';
  END IF;
  PERFORM 1 FROM public.users u JOIN public.entity_participation p ON p.entity_id=e
   WHERE u.id=a AND u.erased_at IS NULL AND p.state='active' FOR SHARE OF u,p;
  IF NOT FOUND THEN RAISE EXCEPTION 'Release job authority is unavailable' USING ERRCODE='23514'; END IF;
  IF principal_kind='auth' THEN
   PERFORM 1 FROM public.auth_entity x WHERE x.auth_user_id=a AND x.state='active' AND x.revision=r
    AND (g IS NOT NULL OR x.entity_id=e) FOR SHARE;
   IF NOT FOUND OR s IS NOT NULL THEN RAISE EXCEPTION 'Release job account authority differs' USING ERRCODE='23514'; END IF;
  ELSE
   PERFORM 1 FROM public.service_principal x WHERE x.id=s AND x.auth_user_id=a AND x.entity_id=e AND x.revision=r AND x.revoked_at IS NULL FOR SHARE;
   IF NOT FOUND OR g IS NULL THEN RAISE EXCEPTION 'Release job service authority differs' USING ERRCODE='23514'; END IF;
  END IF;
  IF g IS NOT NULL THEN
   PERFORM 1 FROM public.participation_grant x WHERE x.id=g AND x.revision=gr AND x.acting_entity_id=e
    AND ((principal_kind='auth' AND x.auth_user_id=a) OR (principal_kind='service' AND x.service_principal_id=s))
    AND x.capability='proposal.adopt' AND x.proposal_source_record_id=NEW.source_record_id AND x.proposal_id=NEW.proposal_id
    AND x.music_id=NEW.music_id AND x.revoked_at IS NULL AND (x.expires_at IS NULL OR x.expires_at>clock_timestamp()) FOR SHARE;
   IF NOT FOUND THEN RAISE EXCEPTION 'Release job proposal grant differs' USING ERRCODE='23514'; END IF;
  END IF;
  IF NEW.action='initialize' AND (principal_kind<>'auth' OR g IS NOT NULL) THEN
   RAISE EXCEPTION 'Release intake requires direct account authority' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS music_release_source_job_guard_trigger ON public.music_release_source_job;
CREATE TRIGGER music_release_source_job_guard_trigger BEFORE INSERT OR UPDATE ON public.music_release_source_job FOR EACH ROW EXECUTE FUNCTION public.music_release_source_job_guard();


CREATE OR REPLACE FUNCTION public.catalog_definition_review_guard()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$
BEGIN
 IF TG_OP <> 'INSERT' THEN
  RAISE EXCEPTION 'Definition review is immutable' USING ERRCODE='55000';
 END IF;
 PERFORM 1 FROM public.platform_capability_grant g
 WHERE g.id=NEW.grant_id AND g.auth_user_id=NEW.auth_user_id
 AND g.capability='catalog.definition.manage' AND g.revoked_at IS NULL
 AND (g.expires_at IS NULL OR g.expires_at>clock_timestamp()) FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Definition review requires its current exact platform grant' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS catalog_definition_review_guard_trigger ON public.catalog_definition_review;
CREATE TRIGGER catalog_definition_review_guard_trigger BEFORE INSERT OR UPDATE OR DELETE ON public.catalog_definition_review
FOR EACH ROW EXECUTE FUNCTION public.catalog_definition_review_guard();
DROP TRIGGER IF EXISTS catalog_definition_label_immutable ON public.catalog_definition_label;
CREATE TRIGGER catalog_definition_label_immutable BEFORE UPDATE OR DELETE ON public.catalog_definition_label
FOR EACH ROW EXECUTE FUNCTION public.reject_immutable_history_mutation();


CREATE OR REPLACE FUNCTION public.recommendation_partition_guard()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$
BEGIN
 IF TG_OP='UPDATE' THEN
  IF (NEW.snapshot_id,NEW.bucket) IS DISTINCT FROM (OLD.snapshot_id,OLD.bucket)
   OR NEW.generation<OLD.generation OR NEW.generation>OLD.generation+1
   OR NEW.scanned_rows<OLD.scanned_rows THEN
   RAISE EXCEPTION 'Recommendation partition identity and progress are monotone' USING ERRCODE='23514';
  END IF;
  IF OLD.after_bucket_start IS NOT NULL AND (NEW.after_bucket_start IS NULL OR
   (NEW.after_bucket_start,NEW.after_unit_id,NEW.after_kind::recommendation_signal_kind)<
   (OLD.after_bucket_start,OLD.after_unit_id,OLD.after_kind::recommendation_signal_kind)) THEN
   RAISE EXCEPTION 'Recommendation cursor cannot move backwards' USING ERRCODE='23514';
  END IF;
  IF OLD.state IN ('done','failed') AND NEW IS DISTINCT FROM OLD THEN
   RAISE EXCEPTION 'Recommendation partition is terminal' USING ERRCODE='23514';
  END IF;
  IF NEW.generation>OLD.generation AND NOT(NEW.state='working' AND NEW.lease_token IS NOT NULL AND NEW.lease_token IS DISTINCT FROM OLD.lease_token) THEN
   RAISE EXCEPTION 'Recommendation generation advances only when claiming a lease' USING ERRCODE='23514';
  END IF;
  IF NEW.generation=OLD.generation AND NEW.lease_token IS NOT NULL AND NEW.lease_token IS DISTINCT FROM OLD.lease_token THEN
   RAISE EXCEPTION 'Recommendation token requires a new generation' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS recommendation_snapshot_partition_guard ON public.recommendation_snapshot_partition;
CREATE TRIGGER recommendation_snapshot_partition_guard BEFORE UPDATE ON public.recommendation_snapshot_partition
FOR EACH ROW EXECUTE FUNCTION public.recommendation_partition_guard();

CREATE OR REPLACE FUNCTION public.recommendation_snapshot_guard()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$
DECLARE completed integer;
BEGIN
 IF TG_OP='INSERT' AND (NEW.state<>'building' OR NEW.active OR NEW.source_watermark IS NULL) THEN
  RAISE EXCEPTION 'Recommendation snapshots begin as private builds' USING ERRCODE='23514';
 END IF;
 IF TG_OP='UPDATE' THEN
  IF (NEW.id,NEW.policy_version,NEW.source_watermark,NEW.started_at) IS DISTINCT FROM
     (OLD.id,OLD.policy_version,OLD.source_watermark,OLD.started_at) THEN
   RAISE EXCEPTION 'Recommendation snapshot input is immutable' USING ERRCODE='23514';
  END IF;
  IF OLD.state<>'building' AND (NEW.state,NEW.completed_at,NEW.error) IS DISTINCT FROM (OLD.state,OLD.completed_at,OLD.error) THEN
   RAISE EXCEPTION 'Recommendation snapshot is terminal' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NEW.state='ready' AND (TG_OP='INSERT' OR OLD.state IS DISTINCT FROM NEW.state) THEN
  SELECT count(*) INTO completed FROM public.recommendation_snapshot_partition WHERE snapshot_id=NEW.id AND state='done';
  IF completed<>64 THEN RAISE EXCEPTION 'All recommendation partitions must finish before activation' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS recommendation_snapshot_build_guard ON public.recommendation_snapshot;
CREATE TRIGGER recommendation_snapshot_build_guard BEFORE INSERT OR UPDATE ON public.recommendation_snapshot
FOR EACH ROW EXECUTE FUNCTION public.recommendation_snapshot_guard();

CREATE OR REPLACE FUNCTION public.recommendation_score_build_guard()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$
BEGIN
 PERFORM 1 FROM public.recommendation_snapshot WHERE id=NEW.snapshot_id AND state='building' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Only a building snapshot accepts recommendation scores' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS unit_best_score_build_guard ON public.unit_best_score;
CREATE TRIGGER unit_best_score_build_guard BEFORE INSERT OR UPDATE ON public.unit_best_score
FOR EACH ROW EXECUTE FUNCTION public.recommendation_score_build_guard();


-- Bounded slot domains plus uniqueness are the concurrency-safe capacity proof.
-- Advisory locks avoid routine conflicts; the UNIQUE constraints still reject oversubscription under a stale repeatable-read snapshot.
CREATE OR REPLACE FUNCTION public.assign_content_structure_slots() RETURNS trigger
LANGUAGE plpgsql SET search_path TO pg_catalog, public AS $function$
BEGIN
 IF NEW.deleted_at IS NOT NULL THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND OLD.deleted_at IS NULL
  AND OLD.structure_id=NEW.structure_id AND OLD.content_unit_id=NEW.content_unit_id THEN
  NEW.live_structure_slot:=OLD.live_structure_slot;
  NEW.live_content_slot:=OLD.live_content_slot;
  RETURN NEW;
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('content-structure-slots:'||NEW.structure_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('content-placement-slots:'||NEW.content_unit_id::text,0));
 SELECT candidate::smallint INTO NEW.live_structure_slot FROM generate_series(0,2047) candidate
 WHERE NOT EXISTS(SELECT 1 FROM public.content_structure_node n WHERE n.structure_id=NEW.structure_id AND n.live_structure_slot=candidate AND n.deleted_at IS NULL AND n.id<>NEW.id)
 ORDER BY candidate LIMIT 1;
 IF NEW.live_structure_slot IS NULL THEN RAISE EXCEPTION 'Content structure admits at most 2048 live nodes' USING ERRCODE='23514'; END IF;
 SELECT candidate::smallint INTO NEW.live_content_slot FROM generate_series(0,63) candidate
 WHERE NOT EXISTS(SELECT 1 FROM public.content_structure_node n WHERE n.content_unit_id=NEW.content_unit_id AND n.live_content_slot=candidate AND n.deleted_at IS NULL AND n.id<>NEW.id)
 ORDER BY candidate LIMIT 1;
 IF NEW.live_content_slot IS NULL THEN RAISE EXCEPTION 'Content admits at most 64 live placements' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS content_structure_slots_assign ON public.content_structure_node;
CREATE TRIGGER content_structure_slots_assign BEFORE INSERT OR UPDATE ON public.content_structure_node
FOR EACH ROW EXECUTE FUNCTION public.assign_content_structure_slots();


-- One exact latest state-changing governance action per Realm publication.
CREATE OR REPLACE FUNCTION public.realm_publication_guard_governance_pointer()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE chosen public.content_governance_action%ROWTYPE; prior public.content_governance_action%ROWTYPE;
BEGIN
 IF TG_OP='UPDATE' AND (NEW.realm_id,NEW.unit_id) IS DISTINCT FROM (OLD.realm_id,OLD.unit_id) THEN
  RAISE EXCEPTION 'Realm publication identity is immutable' USING ERRCODE='23514';
 END IF;
 IF TG_OP='UPDATE' AND NEW.latest_governance_action_id IS NOT DISTINCT FROM OLD.latest_governance_action_id THEN RETURN NEW; END IF;
 IF NEW.latest_governance_action_id IS NULL THEN
  IF TG_OP='UPDATE' AND OLD.latest_governance_action_id IS NOT NULL THEN RAISE EXCEPTION 'Latest Realm governance cannot be cleared' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 SELECT a.* INTO chosen FROM public.content_governance_action a JOIN public.content_review_case c ON c.id=a.case_id
 WHERE a.id=NEW.latest_governance_action_id AND c.authority='realm' AND c.realm_id=NEW.realm_id AND c.target_unit_id=NEW.unit_id AND a.resulting_state IS NOT NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'Latest governance action must address the exact Realm publication state' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' AND OLD.latest_governance_action_id IS NOT NULL THEN
  SELECT * INTO STRICT prior FROM public.content_governance_action WHERE id=OLD.latest_governance_action_id;
  IF (chosen.created_at,chosen.id)<=(prior.created_at,prior.id) THEN RAISE EXCEPTION 'Latest governance pointer cannot move backward' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION public.realm_publication_project_governance_action()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE context public.content_review_case%ROWTYPE;
BEGIN
 IF NEW.resulting_state IS NULL THEN RETURN NEW; END IF;
 SELECT * INTO STRICT context FROM public.content_review_case WHERE id=NEW.case_id;
 IF context.authority<>'realm' THEN RETURN NEW; END IF;
 PERFORM 1 FROM public.realm_unit WHERE realm_id=context.realm_id AND unit_id=context.target_unit_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Realm state action requires its publication' USING ERRCODE='23514'; END IF;
 -- The UPDATE locks the one publication row; PostgreSQL rechecks this predicate after concurrent writers.
 UPDATE public.realm_unit r SET latest_governance_action_id=NEW.id
 WHERE r.realm_id=context.realm_id AND r.unit_id=context.target_unit_id
 AND (r.latest_governance_action_id IS NULL OR
  (SELECT (a.created_at,a.id)<(NEW.created_at,NEW.id) FROM public.content_governance_action a WHERE a.id=r.latest_governance_action_id));
 RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION public.realm_publication_guard_governance_evidence()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
BEGIN
 IF TG_TABLE_NAME='content_governance_action' THEN
  IF TG_OP='DELETE' OR NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'Governance action evidence is immutable' USING ERRCODE='23514'; END IF;
 ELSE
  IF (NEW.authority,NEW.realm_id,NEW.target_unit_id) IS DISTINCT FROM (OLD.authority,OLD.realm_id,OLD.target_unit_id) THEN
   RAISE EXCEPTION 'Governance case authority and target are immutable' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS realm_publication_governance_pointer_guard ON public.realm_unit;
CREATE TRIGGER realm_publication_governance_pointer_guard BEFORE INSERT OR UPDATE ON public.realm_unit FOR EACH ROW EXECUTE FUNCTION public.realm_publication_guard_governance_pointer();
DROP TRIGGER IF EXISTS realm_publication_governance_project ON public.content_governance_action;
CREATE TRIGGER realm_publication_governance_project AFTER INSERT ON public.content_governance_action FOR EACH ROW EXECUTE FUNCTION public.realm_publication_project_governance_action();
DROP TRIGGER IF EXISTS realm_publication_governance_evidence_guard ON public.content_governance_action;
CREATE TRIGGER realm_publication_governance_evidence_guard BEFORE UPDATE OR DELETE ON public.content_governance_action FOR EACH ROW EXECUTE FUNCTION public.realm_publication_guard_governance_evidence();
DROP TRIGGER IF EXISTS realm_publication_governance_scope_guard ON public.content_review_case;
CREATE TRIGGER realm_publication_governance_scope_guard BEFORE UPDATE ON public.content_review_case FOR EACH ROW EXECUTE FUNCTION public.realm_publication_guard_governance_evidence();


-- Native owner integrity and derived state. This file is the canonical forward-maintained source.
CREATE OR REPLACE FUNCTION public.refresh_book_localized_content_metric_stat(p_book_unit_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO pg_catalog, public
AS $function$
BEGIN
    DELETE FROM public.book_localized_content_metric_stat
    WHERE book_unit_id = p_book_unit_id;

    INSERT INTO public.book_localized_content_metric_stat (
        book_unit_id, language, chapter_count, word_count, character_count
    )
    SELECT p_book_unit_id, metric.language, count(*), sum(metric.word_count),
        sum(metric.character_count)
    FROM public.content_structure_node AS node
    JOIN public.content_structure AS structure
        ON structure.id = node.structure_id
        AND structure.owner_unit_id = node.owner_unit_id
    JOIN public.post AS content_post ON content_post.id = node.content_unit_id

    JOIN public.unit_localization AS localization ON localization.unit_id = node.content_unit_id
    JOIN public.unit_localization_content_metric AS metric
        ON metric.unit_id = node.content_unit_id
        AND metric.language = localization.language
    WHERE structure.owner_unit_id = p_book_unit_id
      AND structure.kind = 'book.contents'
      AND structure.deleted_at IS NULL
      AND node.deleted_at IS NULL
      AND content_post.kind = 'chapter'
      AND content_post.deleted_at IS NULL
      AND content_post.status = 'published'
      AND content_post.visibility IN ('public', 'unlisted')
      AND localization.content_status = 'published'
    GROUP BY metric.language;
END
$function$;

CREATE OR REPLACE FUNCTION public.refresh_book_metric_from_content_unit()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO pg_catalog, public
AS $function$
DECLARE
    book_id uuid;
BEGIN
    FOR book_id IN
        SELECT DISTINCT node.owner_unit_id
        FROM public.content_structure_node AS node
        JOIN public.content_structure AS structure ON structure.id = node.structure_id
        WHERE node.content_unit_id = coalesce(NEW.id, OLD.id)
          AND structure.kind = 'book.contents'
    LOOP
        PERFORM public.refresh_book_localized_content_metric_stat(book_id);
    END LOOP;
    RETURN NULL;
END
$function$;

CREATE OR REPLACE FUNCTION public.refresh_book_metric_from_localization()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO pg_catalog, public
AS $function$
DECLARE
    book_id uuid;
    p_content_unit_id uuid := coalesce(NEW.unit_id, OLD.unit_id);
BEGIN
    FOR book_id IN
        SELECT DISTINCT node.owner_unit_id
        FROM public.content_structure_node AS node
        JOIN public.content_structure AS structure ON structure.id = node.structure_id
        WHERE node.content_unit_id = p_content_unit_id
          AND structure.kind = 'book.contents'
    LOOP
        PERFORM public.refresh_book_localized_content_metric_stat(book_id);
    END LOOP;
    RETURN NULL;
END
$function$;

CREATE OR REPLACE FUNCTION public.refresh_book_metric_from_node()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO pg_catalog, public
AS $function$
BEGIN
    IF TG_OP <> 'INSERT' THEN
        PERFORM public.refresh_book_localized_content_metric_stat(OLD.owner_unit_id);
    END IF;
    IF TG_OP <> 'DELETE' AND (
        TG_OP = 'INSERT' OR NEW.owner_unit_id IS DISTINCT FROM OLD.owner_unit_id
    ) THEN
        PERFORM public.refresh_book_localized_content_metric_stat(NEW.owner_unit_id);
    END IF;
    RETURN NULL;
END
$function$;

CREATE OR REPLACE FUNCTION public.refresh_book_metric_from_structure()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO pg_catalog, public
AS $function$
BEGIN
    IF TG_OP <> 'INSERT' THEN
        PERFORM public.refresh_book_localized_content_metric_stat(OLD.owner_unit_id);
    END IF;
    IF TG_OP <> 'DELETE' AND (
        TG_OP = 'INSERT' OR NEW.owner_unit_id IS DISTINCT FROM OLD.owner_unit_id
    ) THEN
        PERFORM public.refresh_book_localized_content_metric_stat(NEW.owner_unit_id);
    END IF;
    RETURN NULL;
END
$function$;

DROP TRIGGER IF EXISTS book_localized_metric_structure_refresh ON public.content_structure;
CREATE TRIGGER book_localized_metric_structure_refresh AFTER INSERT OR DELETE OR UPDATE OF owner_unit_id, kind, deleted_at ON public.content_structure FOR EACH ROW EXECUTE FUNCTION public.refresh_book_metric_from_structure();

DROP TRIGGER IF EXISTS book_localized_metric_node_refresh ON public.content_structure_node;
CREATE TRIGGER book_localized_metric_node_refresh AFTER INSERT OR DELETE OR UPDATE OF structure_id, owner_unit_id, content_unit_id, deleted_at ON public.content_structure_node FOR EACH ROW EXECUTE FUNCTION public.refresh_book_metric_from_node();

DROP TRIGGER IF EXISTS book_localized_metric_post_refresh ON public.post;
