CREATE TRIGGER music_track_identifier_record_revision AFTER INSERT OR UPDATE OR DELETE ON public.music_track_identifier
  FOR EACH ROW EXECUTE FUNCTION public.catalog_record_music_component('release_id','track_id','namespace','value');

CREATE OR REPLACE FUNCTION public.catalog_check_music_source_occurrence()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE native_value jsonb; normalized_value jsonb; component_table regclass; invalid boolean; checks text;
BEGIN
  SELECT value INTO native_value FROM public.music_component_revision
    WHERE owner_id = NEW.owner_id AND id = NEW.history_id AND component = NEW.component
      AND component_key = NEW.component_key AND operation <> 'DELETE';
  IF native_value IS NULL THEN
    RAISE EXCEPTION 'Music source occurrence must reference the exact native component revision'
      USING ERRCODE = '23514', CONSTRAINT = 'music_source_occurrence_exact_history';
  END IF;
  IF jsonb_typeof(NEW.source_value) IS DISTINCT FROM 'object'
    OR ARRAY(SELECT jsonb_object_keys(NEW.source_value) ORDER BY 1) IS DISTINCT FROM ARRAY(SELECT jsonb_object_keys(native_value) ORDER BY 1)
  THEN RAISE EXCEPTION 'Music interpretation must contain exactly the native component fields' USING ERRCODE='23514'; END IF;
  component_table := to_regclass(format('public.%I',NEW.component));
  EXECUTE format('SELECT to_jsonb(v) FROM jsonb_populate_record(NULL::public.%I,$1) v',NEW.component) INTO normalized_value USING NEW.source_value;
  IF normalized_value IS DISTINCT FROM NEW.source_value THEN
    RAISE EXCEPTION 'Music interpretation has invalid native field types' USING ERRCODE='23514';
  END IF;
  SELECT EXISTS(SELECT 1 FROM pg_attribute a WHERE a.attrelid=component_table AND a.attnum>0 AND NOT a.attisdropped AND a.attnotnull AND NEW.source_value->a.attname='null'::jsonb)
    OR EXISTS(SELECT 1 FROM pg_index i JOIN pg_attribute a ON a.attrelid=i.indrelid AND a.attnum=ANY(i.indkey)
      WHERE i.indrelid=component_table AND i.indisprimary AND NEW.source_value->a.attname IS DISTINCT FROM native_value->a.attname)
    INTO invalid;
  IF invalid THEN RAISE EXCEPTION 'Music interpretation changes native identity or required fields' USING ERRCODE='23514'; END IF;
  SELECT string_agg('(' || pg_get_expr(c.conbin,c.conrelid) || ')',' AND ') INTO checks
    FROM pg_constraint c WHERE c.conrelid=component_table AND c.contype='c';
  IF checks IS NOT NULL THEN
    EXECUTE format('SELECT NOT coalesce((%s),true) FROM jsonb_populate_record(NULL::public.%I,$1)', checks, NEW.component) INTO invalid USING NEW.source_value;
    IF invalid THEN RAISE EXCEPTION 'Music interpretation violates native component constraints' USING ERRCODE='23514'; END IF;
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS music_component_source_occurrence_exact_history ON public.music_component_source_occurrence;
CREATE TRIGGER music_component_source_occurrence_exact_history BEFORE INSERT ON public.music_component_source_occurrence
  FOR EACH ROW EXECUTE FUNCTION public.catalog_check_music_source_occurrence();
DROP TRIGGER IF EXISTS music_component_source_occurrence_immutable ON public.music_component_source_occurrence;
CREATE TRIGGER music_component_source_occurrence_immutable BEFORE UPDATE OR DELETE ON public.music_component_source_occurrence
  FOR EACH ROW EXECUTE FUNCTION public.catalog_guard_music_history();


CREATE OR REPLACE FUNCTION public.catalog_guard_music_component_head()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
BEGIN
  IF TG_OP='DELETE' OR pg_trigger_depth()<2 THEN
    RAISE EXCEPTION 'Music component heads are maintained by native history capture' USING ERRCODE='23514';
  END IF;
  IF TG_OP='INSERT' AND NEW.component_sequence<>1 THEN
    RAISE EXCEPTION 'Music component history must start at sequence one' USING ERRCODE='23514';
  END IF;
  IF TG_OP='UPDATE' AND ((OLD.owner_id,OLD.component,OLD.component_key) IS DISTINCT FROM (NEW.owner_id,NEW.component,NEW.component_key)
    OR NEW.component_sequence<>OLD.component_sequence+1) THEN
    RAISE EXCEPTION 'Music component sequence must advance exactly once' USING ERRCODE='23514';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.music_component_revision WHERE owner_id=NEW.owner_id AND id=NEW.history_id
    AND component=NEW.component AND component_key=NEW.component_key AND component_sequence=NEW.component_sequence) THEN
    RAISE EXCEPTION 'Music component head requires its exact immutable revision' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS music_component_head_maintained ON public.music_component_head;
CREATE TRIGGER music_component_head_maintained BEFORE INSERT OR UPDATE OR DELETE ON public.music_component_head
  FOR EACH ROW EXECUTE FUNCTION public.catalog_guard_music_component_head();

CREATE OR REPLACE FUNCTION public.catalog_guard_music_revision_insert()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
BEGIN
  IF pg_trigger_depth()<2 THEN
    RAISE EXCEPTION 'Music history is captured from native rows, not caller-supplied snapshots' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS music_component_revision_capture_only ON public.music_component_revision;
CREATE TRIGGER music_component_revision_capture_only BEFORE INSERT ON public.music_component_revision
  FOR EACH ROW EXECUTE FUNCTION public.catalog_guard_music_revision_insert();

CREATE OR REPLACE FUNCTION public.catalog_check_music_source_baseline()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE native public.music_component_revision%ROWTYPE;
BEGIN
  IF TG_OP = 'UPDATE' AND (OLD.source_record_id, OLD.mapping_key, OLD.correspondence_revision, OLD.owner_id, OLD.component, OLD.component_key)
    IS DISTINCT FROM (NEW.source_record_id, NEW.mapping_key, NEW.correspondence_revision, NEW.owner_id, NEW.component, NEW.component_key) THEN
    RAISE EXCEPTION 'Music source baseline identity is immutable' USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.music_component_source_occurrence
    WHERE source_record_id=NEW.source_record_id AND mapping_key=NEW.mapping_key AND correspondence_revision=NEW.correspondence_revision AND snapshot_id=NEW.snapshot_id AND owner_id=NEW.owner_id
      AND component=NEW.component AND component_key=NEW.component_key AND source_path=NEW.source_path AND history_id=NEW.source_history_id) THEN
    RAISE EXCEPTION 'Music source baseline requires exact original source support' USING ERRCODE = '23514';
  END IF;
  SELECT * INTO STRICT native FROM public.music_component_revision WHERE owner_id=NEW.owner_id AND id=NEW.current_history_id;
  IF native.component <> NEW.component OR native.component_key <> NEW.component_key OR (native.operation='DELETE') <> NEW.absent THEN
    RAISE EXCEPTION 'Music source baseline current component differs' USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.music_source_application_change change
    JOIN public.catalog_source_adoption_proposal proposal ON proposal.source_record_id=change.source_record_id AND proposal.id=change.proposal_id
    WHERE change.source_record_id=NEW.source_record_id AND change.proposal_id=NEW.proposal_id AND change.action=NEW.action
      AND proposal.mapping_key=NEW.mapping_key AND change.owner_id=NEW.owner_id AND change.component=NEW.component
      AND change.component_key=NEW.component_key AND change.after_revision_id=NEW.current_history_id) THEN
    RAISE EXCEPTION 'Music source baseline requires exact native application proof' USING ERRCODE = '23514';
  END IF;
  IF NOT public.catalog_source_application_includes_epoch(NEW.source_record_id,NEW.proposal_id,NEW.mapping_key,NEW.correspondence_revision) OR NOT EXISTS (
    SELECT 1 FROM public.catalog_source_binding_revision r WHERE r.source_record_id=NEW.source_record_id AND r.mapping_key=NEW.mapping_key AND r.revision=NEW.correspondence_revision AND r.owner=NEW.mapping_owner)
  THEN RAISE EXCEPTION 'Music baseline requires its proposal owner correspondence epoch' USING ERRCODE='23514'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.music_component_head h WHERE h.owner_id=NEW.owner_id AND h.component=NEW.component AND h.component_key=NEW.component_key AND h.history_id=NEW.current_history_id)
  THEN RAISE EXCEPTION 'Music baseline must identify its exact current native head' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS music_source_baseline_proof ON public.music_component_source_baseline;
CREATE TRIGGER music_source_baseline_proof BEFORE INSERT OR UPDATE ON public.music_component_source_baseline
  FOR EACH ROW EXECUTE FUNCTION public.catalog_check_music_source_baseline();

-- Shared alternate text/credit values are replaced through exact occurrence revisions.
DROP TRIGGER IF EXISTS music_alternative_track_immutable ON public.music_alternative_track;
CREATE TRIGGER music_alternative_track_immutable BEFORE UPDATE OR DELETE ON public.music_alternative_track
  FOR EACH ROW EXECUTE FUNCTION public.catalog_guard_music_history();

CREATE OR REPLACE FUNCTION public.catalog_check_music_definition_scope()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE revision_id uuid; policy jsonb;
BEGIN
  revision_id := (to_jsonb(NEW)->>TG_ARGV[0])::uuid;
  IF revision_id IS NULL THEN RETURN NEW; END IF;
  SELECT revision.constraints INTO policy FROM public.catalog_definition_revision revision
    JOIN public.catalog_definition definition ON definition.id=revision.definition_id
    WHERE revision.id=revision_id AND definition.kind='vocabulary';
  IF policy IS NULL OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(policy->'targets','[]'::jsonb)) target
    WHERE target->>'owner'='music' AND coalesce(target->'shapes','[]'::jsonb) ? TG_ARGV[1])
    OR NOT (coalesce(policy->'slots','[]'::jsonb) ? TG_ARGV[2]) THEN
    RAISE EXCEPTION 'Music vocabulary is outside its governed native target or slot'
      USING ERRCODE='23514', CONSTRAINT='music_definition_target_scope';
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS music_release_status_scope ON public.music_release;
CREATE TRIGGER music_release_status_scope BEFORE INSERT OR UPDATE ON public.music_release
  FOR EACH ROW EXECUTE FUNCTION public.catalog_check_music_definition_scope('status_revision_id','release','music_release.status_revision_id');
DROP TRIGGER IF EXISTS music_release_packaging_scope ON public.music_release;
CREATE TRIGGER music_release_packaging_scope BEFORE INSERT OR UPDATE ON public.music_release
  FOR EACH ROW EXECUTE FUNCTION public.catalog_check_music_definition_scope('packaging_revision_id','release','music_release.packaging_revision_id');
DROP TRIGGER IF EXISTS music_medium_format_scope ON public.music_medium;
CREATE TRIGGER music_medium_format_scope BEFORE INSERT OR UPDATE ON public.music_medium
  FOR EACH ROW EXECUTE FUNCTION public.catalog_check_music_definition_scope('format_revision_id','release','music_medium.format_revision_id');
DROP TRIGGER IF EXISTS music_work_type_scope ON public.music_work;
CREATE TRIGGER music_work_type_scope BEFORE INSERT OR UPDATE ON public.music_work
  FOR EACH ROW EXECUTE FUNCTION public.catalog_check_music_definition_scope('type_revision_id','work','music_work.type_revision_id');
DROP TRIGGER IF EXISTS music_release_group_primary_scope ON public.music_release_group;
CREATE TRIGGER music_release_group_primary_scope BEFORE INSERT OR UPDATE ON public.music_release_group
  FOR EACH ROW EXECUTE FUNCTION public.catalog_check_music_definition_scope('primary_type_revision_id','release_group','music_release_group.primary_type_revision_id');
DROP TRIGGER IF EXISTS music_release_group_secondary_scope ON public.music_release_group_secondary_type;
CREATE TRIGGER music_release_group_secondary_scope BEFORE INSERT OR UPDATE ON public.music_release_group_secondary_type
  FOR EACH ROW EXECUTE FUNCTION public.catalog_check_music_definition_scope('type_revision_id','release_group','music_release_group_secondary_type.type_revision_id');
DROP TRIGGER IF EXISTS music_release_presentation_type_scope ON public.music_release_presentation;
CREATE TRIGGER music_release_presentation_type_scope BEFORE INSERT OR UPDATE ON public.music_release_presentation
  FOR EACH ROW EXECUTE FUNCTION public.catalog_check_music_definition_scope('type_revision_id','release','music_release_presentation.type_revision_id');


CREATE OR REPLACE FUNCTION public.catalog_valid_name_date(value jsonb)
RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path = pg_catalog, public AS $$
DECLARE y integer; m integer; d integer; maximum integer;
BEGIN
 IF value IS NULL THEN RETURN TRUE; END IF;
 IF jsonb_typeof(value) <> 'object' THEN RETURN FALSE; END IF;
 IF NOT value ?& ARRAY['year','month','day'] OR
    (SELECT count(*) FROM jsonb_object_keys(value)) <> 3 THEN RETURN FALSE; END IF;
 IF EXISTS (SELECT 1 FROM jsonb_each(value) item WHERE item.value <> 'null'::jsonb AND
    (jsonb_typeof(item.value) <> 'number' OR NOT pg_input_is_valid(item.value::text, 'integer'))) THEN RETURN FALSE; END IF;
 y := (value->>'year')::integer; m := (value->>'month')::integer; d := (value->>'day')::integer;
 IF (m IS NOT NULL AND m NOT BETWEEN 1 AND 12) OR (d IS NOT NULL AND d NOT BETWEEN 1 AND 31) THEN RETURN FALSE; END IF;
 IF m IS NULL OR d IS NULL THEN RETURN TRUE; END IF;
 maximum := CASE WHEN m = 2 THEN CASE WHEN y IS NULL OR y % 400 = 0 OR (y % 4 = 0 AND y % 100 <> 0) THEN 29 ELSE 28 END WHEN m IN (4,6,9,11) THEN 30 ELSE 31 END;
 RETURN d <= maximum;
END;
$$;

CREATE OR REPLACE FUNCTION public.catalog_guard_named_head()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
BEGIN
 IF TG_OP = 'DELETE' THEN
  RAISE EXCEPTION 'Named facts retain identity and revision history' USING ERRCODE = '23514';
 END IF;
 IF TG_TABLE_NAME LIKE '%\_named_form' ESCAPE '\' THEN
  IF NOT public.catalog_valid_name_date(NEW."begin") OR NOT public.catalog_valid_name_date(NEW."end") THEN
   RAISE EXCEPTION 'Named-form dates must preserve valid known calendar components' USING ERRCODE = '23514';
  END IF;
 END IF;
 IF (TG_OP = 'INSERT' AND NEW.revision <> 1) OR
    (TG_OP = 'UPDATE' AND (NEW.owner_id <> OLD.owner_id OR NEW.id <> OLD.id OR NEW.created_at <> OLD.created_at OR NEW.revision <> OLD.revision + 1)) THEN
  RAISE EXCEPTION 'Named fact identity is immutable and revisions must advance by one' USING ERRCODE = '23514';
 END IF;
 RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.catalog_snapshot_named_head()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
BEGIN
 -- ALTER TABLE preserves old physical column order; history must match names, not positions.
 EXECUTE format('INSERT INTO public.%I SELECT (jsonb_populate_record(NULL::public.%I, to_jsonb($1))).*',
   TG_TABLE_NAME || '_revision', TG_TABLE_NAME || '_revision') USING NEW;
 RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.catalog_guard_named_history()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE head_value jsonb;
BEGIN
 IF TG_OP <> 'INSERT' THEN
  RAISE EXCEPTION 'Named fact revision history is immutable' USING ERRCODE = '23514';
 END IF;
 EXECUTE format('SELECT to_jsonb(t) FROM public.%I t WHERE owner_id = $1 AND id = $2', TG_ARGV[0])
 INTO head_value USING NEW.owner_id, NEW.id;
 IF head_value IS DISTINCT FROM to_jsonb(NEW) THEN
  RAISE EXCEPTION 'History must be the exact complete current revision' USING ERRCODE = '23514';
 END IF;
 RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.catalog_guard_name_source_identity()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
BEGIN
 RAISE EXCEPTION 'Named-form source bindings and observations are immutable' USING ERRCODE = '23514';
END;
$$;

DO $$
DECLARE owner text; suffix text; head_name text;
BEGIN
 FOREACH owner IN ARRAY ARRAY['publishing','music','program','software','entity','grouping','reference','distribution'] LOOP
  FOREACH suffix IN ARRAY ARRAY['named_form','identifier_claim','name_authority'] LOOP
   head_name := owner || '_' || suffix;
   EXECUTE format('DROP TRIGGER IF EXISTS catalog_named_head_guard ON public.%I', head_name);
   EXECUTE format('CREATE TRIGGER catalog_named_head_guard BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.catalog_guard_named_head()', head_name);
   EXECUTE format('DROP TRIGGER IF EXISTS catalog_named_head_snapshot ON public.%I', head_name);
   EXECUTE format('CREATE TRIGGER catalog_named_head_snapshot AFTER INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.catalog_snapshot_named_head()', head_name);
   EXECUTE format('DROP TRIGGER IF EXISTS catalog_named_history_guard ON public.%I', head_name || '_revision');
   EXECUTE format('CREATE TRIGGER catalog_named_history_guard BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.catalog_guard_named_history(%L)', head_name || '_revision', head_name);
  END LOOP;
  FOREACH suffix IN ARRAY ARRAY['name_source_binding','name_source_occurrence'] LOOP
   head_name := owner || '_' || suffix;
   EXECUTE format('DROP TRIGGER IF EXISTS catalog_name_source_guard ON public.%I', head_name);
   EXECUTE format('CREATE TRIGGER catalog_name_source_guard BEFORE UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.catalog_guard_name_source_identity()', head_name);
  END LOOP;
 END LOOP;
END;
$$;


-- Native catalog names remain independently indexed rows. Editing one name never
-- concatenates every alias into an identity-wide document or rewrites its siblings.
CREATE OR REPLACE FUNCTION public.search_catalog_name_candidates(
 p_owner text, p_queries text[], p_languages text[], p_shapes text[],
 p_after_updated_at_micros bigint, p_after_unit_id uuid,
 p_estimated_postings_limit integer, p_limit integer
) RETURNS TABLE(unit_id uuid, unit_updated_at_micros bigint, search_matched boolean)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE
 expanded_query text; index_column text; keyword text; estimate jsonb;
 estimated_postings bigint := 0; index_name text; candidates uuid[];
BEGIN
 IF p_owner IS NULL OR NOT p_owner=ANY(ARRAY['publishing','music','program','software','entity','grouping','reference','distribution'])
 OR p_queries IS NULL OR cardinality(p_queries) NOT BETWEEN 1 AND 3
 OR EXISTS(SELECT 1 FROM unnest(p_queries) q WHERE q IS NULL OR btrim(q)='' OR char_length(q)>512)
 OR p_languages IS NULL OR cardinality(p_languages)>50
 OR p_shapes IS NULL OR cardinality(p_shapes)>50
 OR p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 4097
 OR p_estimated_postings_limit IS NULL OR p_estimated_postings_limit NOT BETWEEN 1 AND 50000
 OR num_nonnulls(p_after_updated_at_micros,p_after_unit_id) NOT IN (0,2)
 OR p_after_updated_at_micros<0 THEN
  RAISE EXCEPTION 'invalid native name search input' USING ERRCODE='22023';
 END IF;
 SELECT string_agg('('||public.pgroonga_query_escape(q)||')',' OR ' ORDER BY n)
 INTO expanded_query FROM unnest(p_queries) WITH ORDINALITY v(q,n);
 index_name := p_owner||'_named_form_search_idx';
 index_column := public.pgroonga_index_column_name(index_name::cstring,'value');
 FOREACH keyword IN ARRAY public.pgroonga_query_extract_keywords(expanded_query) LOOP
  estimate := public.pgroonga_command('table_tokenize',ARRAY[
   'table',split_part(index_column,'.',1),'string',keyword,
   'index_column',split_part(index_column,'.',2),'mode','GET'])::jsonb;
  IF (estimate #>> '{0,0}')::integer IS DISTINCT FROM 0 THEN
   RAISE EXCEPTION 'native name posting estimate failed';
  END IF;
  SELECT estimated_postings+coalesce(sum((token->>'estimated_size')::bigint),0)
  INTO estimated_postings FROM jsonb_array_elements(coalesce(estimate #> '{1}','[]'::jsonb)) token;
  EXIT WHEN estimated_postings>p_estimated_postings_limit;
 END LOOP;
 IF estimated_postings<=p_estimated_postings_limit THEN
  -- LIMIT is before DISTINCT, identity joins and sorting. A stale underestimate
  -- is detected by the extra row and switches to the same bounded scan fallback.
  EXECUTE format('SELECT array_agg(owner_id) FROM (
   SELECT owner_id FROM public.%I WHERE state=''active'' AND spoiler=0 AND scope_owner_id IS NULL
    AND value &@~ $1 AND (cardinality($2)=0 OR split_part(lower(language_tag),''-'',1)=ANY($2))
   LIMIT $3) hits',p_owner||'_named_form')
   INTO candidates USING expanded_query,p_languages,p_estimated_postings_limit+1;
  IF coalesce(cardinality(candidates),0)<=p_estimated_postings_limit THEN
   RETURN QUERY EXECUTE format('SELECT identity.id,(extract(epoch FROM identity.updated_at)*1000000)::bigint,true
    FROM (SELECT DISTINCT id FROM unnest($1) ids(id)) matches JOIN public.%I identity ON identity.id=matches.id
    WHERE identity.status=''published'' AND identity.visibility=''public'' AND identity.moderation_status=''approved'' AND identity.deleted_at IS NULL
     AND (cardinality($2)=0 OR identity.shape=ANY($2))
     AND ($3 IS NULL OR (identity.updated_at,identity.id)<(to_timestamp($4::numeric/1000000),$3))
    ORDER BY identity.updated_at DESC,identity.id DESC LIMIT $5',p_owner||'_identity')
    USING coalesce(candidates,ARRAY[]::uuid[]),p_shapes,p_after_unit_id,p_after_updated_at_micros,p_limit;
   RETURN;
  END IF;
 END IF;
 RETURN QUERY EXECUTE format('SELECT identity.id,(extract(epoch FROM identity.updated_at)*1000000)::bigint,false
  FROM public.%I identity WHERE identity.status=''published'' AND identity.visibility=''public''
   AND identity.moderation_status=''approved'' AND identity.deleted_at IS NULL
   AND (cardinality($1)=0 OR identity.shape=ANY($1))
   AND ($2 IS NULL OR (identity.updated_at,identity.id)<(to_timestamp($3::numeric/1000000),$2))
  ORDER BY identity.updated_at DESC,identity.id DESC LIMIT $4',p_owner||'_identity')
  USING p_shapes,p_after_unit_id,p_after_updated_at_micros,p_limit;
END;
$$;
REVOKE ALL ON FUNCTION public.search_catalog_name_candidates(text,text[],text[],text[],bigint,uuid,integer,integer) FROM PUBLIC;

CREATE OR REPLACE FUNCTION public.catalog_name_matches(p_id uuid,p_queries text[],p_languages text[])
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE v_owner text; matched boolean; query text; inspected integer; candidate_ids uuid[]; name_bytes bigint;
BEGIN
 SELECT owner INTO v_owner FROM public.catalog_unit_locator WHERE id=p_id;
 IF v_owner IS NULL OR NOT v_owner=ANY(ARRAY['publishing','music','program','software','entity','grouping','reference','distribution']) THEN RETURN false; END IF;
 IF p_queries IS NULL OR cardinality(p_queries) NOT BETWEEN 1 AND 3
  OR EXISTS(SELECT 1 FROM unnest(p_queries) q WHERE q IS NULL OR btrim(q)='' OR char_length(q)>512)
  OR p_languages IS NULL OR cardinality(p_languages)>50 THEN
  RAISE EXCEPTION 'invalid bounded name search input' USING ERRCODE='22023';
 END IF;
 SELECT string_agg('('||public.pgroonga_query_escape(q)||')',' OR ' ORDER BY n)
 INTO query FROM unnest(p_queries) WITH ORDINALITY v(q,n);
 -- Rare-term postings still cover all names. A broad residual has a fixed count and byte budget;
 -- exceeded budgets report unavailable instead of silently treating unexamined aliases as non-matches.
 EXECUTE format('SELECT array_agg(id),coalesce(sum(bytes),0),count(*)::integer FROM (
  SELECT id,octet_length(value) bytes FROM public.%I WHERE owner_id=$1 AND state=''active'' AND spoiler=0 AND scope_owner_id IS NULL
  AND (cardinality($2)=0 OR split_part(lower(language_tag),''-'',1)=ANY($2)) LIMIT 513
 ) bounded',v_owner||'_named_form') INTO candidate_ids,name_bytes,inspected USING p_id,p_languages;
 IF inspected>512 OR name_bytes>65536 THEN RAISE EXCEPTION 'Native name residual budget exceeded; refine the query' USING ERRCODE='54000'; END IF;
 EXECUTE format('WITH bounded AS MATERIALIZED (SELECT value FROM public.%I WHERE owner_id=$1 AND id=ANY($2))
  SELECT coalesce(bool_or(value &@~ $3),false) FROM bounded',v_owner||'_named_form')
 INTO matched USING p_id,coalesce(candidate_ids,ARRAY[]::uuid[]),query;
 RETURN matched;
END;
$$;
REVOKE ALL ON FUNCTION public.catalog_name_matches(uuid,text[],text[]) FROM PUBLIC;

CREATE OR REPLACE FUNCTION public.catalog_name_has_languages(p_id uuid,p_languages text[],p_all boolean)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE v_owner text; matched boolean;
BEGIN
 IF p_languages IS NULL OR cardinality(p_languages) NOT BETWEEN 1 AND 50 OR p_all IS NULL THEN
  RAISE EXCEPTION 'invalid name language boundary' USING ERRCODE='22023';
 END IF;
 SELECT owner INTO v_owner FROM public.catalog_unit_locator WHERE id=p_id;
 IF v_owner IS NULL OR NOT v_owner=ANY(ARRAY['publishing','music','program','software','entity','grouping','reference','distribution']) THEN RETURN false; END IF;
 IF p_all THEN
  EXECUTE format('SELECT NOT EXISTS(SELECT 1 FROM unnest($2) requested(language) WHERE NOT EXISTS(
   SELECT 1 FROM public.%I WHERE owner_id=$1 AND state=''active'' AND spoiler=0 AND scope_owner_id IS NULL
   AND split_part(lower(language_tag),''-'',1)=requested.language))',v_owner||'_named_form') INTO matched USING p_id,p_languages;
 ELSE
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE owner_id=$1 AND state=''active'' AND spoiler=0 AND scope_owner_id IS NULL
   AND split_part(lower(language_tag),''-'',1)=ANY($2))',v_owner||'_named_form') INTO matched USING p_id,p_languages;
 END IF;
 RETURN matched;
END;
$$;
REVOKE ALL ON FUNCTION public.catalog_name_has_languages(uuid,text[],boolean) FROM PUBLIC;


CREATE OR REPLACE FUNCTION public.catalog_guard_semantic_immutable()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
BEGIN
 RAISE EXCEPTION 'Semantic revisions and their participants are immutable' USING ERRCODE='23514', CONSTRAINT='catalog_semantic_revision_immutable';
END;
$$;

CREATE OR REPLACE FUNCTION public.catalog_guard_governed_value()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE definition jsonb; expected_kind text; rule jsonb; parent_rule integer; vocabulary jsonb;
BEGIN
 EXECUTE format('SELECT d.constraints,d.value_kind FROM public.%I f JOIN public.catalog_definition_revision d ON d.id=f.definition_revision_id WHERE f.owner_id=$1 AND f.id=$2',TG_ARGV[0]||'_fact') INTO definition,expected_kind USING NEW.owner_id,NEW.fact_id;
 IF definition ? 'rules' THEN
  rule:=definition->'rules'->NEW.rule_position;
  IF rule IS NULL OR (rule->>'position')::integer <> NEW.rule_position THEN RAISE EXCEPTION 'Unknown value rule' USING ERRCODE='23514'; END IF;
  expected_kind:=rule->>'kind';
  IF NEW.position=0 THEN
   IF NEW.rule_position<>0 THEN RAISE EXCEPTION 'Invalid root rule' USING ERRCODE='23514'; END IF;
  ELSE
   EXECUTE format('SELECT rule_position FROM public.%I WHERE owner_id=$1 AND fact_id=$2 AND position=$3',TG_ARGV[0]||'_fact_value_node') INTO parent_rule USING NEW.owner_id,NEW.fact_id,NEW.parent_position;
   IF parent_rule IS NULL OR (rule->>'parent')::integer IS DISTINCT FROM parent_rule OR rule->>'memberKey' IS DISTINCT FROM NEW.member_key THEN RAISE EXCEPTION 'Undeclared value member' USING ERRCODE='23514'; END IF;
  END IF;
 ELSE
  rule:=definition;
  IF NEW.position<>0 THEN RAISE EXCEPTION 'Scalar definition cannot accept descendants' USING ERRCODE='23514'; END IF;
 END IF;
 IF NEW.kind='null' AND coalesce((rule->>'nullable')::boolean,false) THEN RETURN NEW; END IF;
 IF NEW.kind IS DISTINCT FROM expected_kind THEN RAISE EXCEPTION 'Wrong governed value type' USING ERRCODE='23514'; END IF;
 IF NEW.kind='number' AND ((rule ? 'minimum' AND NEW.number_value<(rule->>'minimum')::numeric) OR (rule ? 'maximum' AND NEW.number_value>(rule->>'maximum')::numeric) OR (coalesce((rule->>'integer')::boolean,false) AND (trunc(NEW.number_value)<>NEW.number_value OR abs(NEW.number_value)>9007199254740991))) THEN RAISE EXCEPTION 'Governed numeric bound violated' USING ERRCODE='23514'; END IF;
 IF NEW.kind='string' AND ((rule ? 'minLength' AND length(NEW.text_value)<(rule->>'minLength')::integer) OR (rule ? 'maxLength' AND length(NEW.text_value)>(rule->>'maxLength')::integer)) THEN RAISE EXCEPTION 'Governed text bound violated' USING ERRCODE='23514'; END IF;
 IF rule ? 'allowedValues' AND NOT (rule->'allowedValues' @> jsonb_build_array(CASE NEW.kind WHEN 'string' THEN to_jsonb(NEW.text_value) WHEN 'number' THEN to_jsonb(NEW.number_value) WHEN 'boolean' THEN to_jsonb(NEW.boolean_value) ELSE 'null'::jsonb END)) THEN RAISE EXCEPTION 'Value is not a governed member' USING ERRCODE='23514'; END IF;
 IF rule ? 'vocabularyRevisionId' THEN
  SELECT constraints INTO vocabulary FROM public.catalog_definition_revision WHERE id=(rule->>'vocabularyRevisionId')::uuid;
  IF NEW.kind<>'string' OR NOT (coalesce(vocabulary->'memberRevisionIds','[]'::jsonb) ? NEW.text_value) THEN RAISE EXCEPTION 'Value is not in the exact vocabulary revision' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.catalog_guard_sealed_semantic()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE published boolean;
BEGIN
 IF TG_ARGV[1]='fact' THEN
  IF OLD.sealed_at IS NOT NULL AND (TG_OP='DELETE' OR NEW IS DISTINCT FROM OLD) THEN RAISE EXCEPTION 'Sealed facts are immutable' USING ERRCODE='23514', CONSTRAINT='catalog_fact_value_immutable'; END IF;
  IF TG_OP='UPDATE' AND (NEW.semantic_id<>OLD.semantic_id OR NEW.expected_head_version<>OLD.expected_head_version OR NEW.spoiler<>OLD.spoiler OR NEW.purpose<>OLD.purpose) THEN RAISE EXCEPTION 'Staged fact identity and purpose are immutable' USING ERRCODE='23514', CONSTRAINT='catalog_fact_identity_immutable'; END IF;
  RETURN NEW;
 END IF;
 EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE owner_id=$1 AND relation_id=$2)',TG_ARGV[0]||'_semantic_revision') INTO published USING NEW.owner_id,NEW.relation_id;
 IF published THEN RAISE EXCEPTION 'Published relation cannot gain participants or qualifiers' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.catalog_guard_semantic_revision()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE current_version bigint; target record; prior record; predicate jsonb; role jsonb; participant record; target_owner text; target_id uuid; target_shape text; role_count integer; total integer;
BEGIN
 EXECUTE format('SELECT id FROM public.%I WHERE id=$1 FOR UPDATE',TG_ARGV[0]||'_identity') USING NEW.owner_id;
 EXECUTE format('SELECT version FROM public.%I WHERE owner_id=$1 AND semantic_id=$2 FOR UPDATE',TG_ARGV[0]||'_semantic_head') INTO current_version USING NEW.owner_id,NEW.semantic_id;
 IF NEW.version<>coalesce(current_version,0)+1 THEN RAISE EXCEPTION 'Semantic head version conflict' USING ERRCODE='40001'; END IF;
 IF NEW.fact_id IS NOT NULL THEN
  EXECUTE format('SELECT semantic_id,sealed_at,purpose FROM public.%I WHERE owner_id=$1 AND id=$2',TG_ARGV[0]||'_fact') INTO target USING NEW.owner_id,NEW.fact_id;
  IF target.semantic_id IS DISTINCT FROM NEW.semantic_id OR target.sealed_at IS NULL THEN RAISE EXCEPTION 'Unsealed or wrong semantic fact' USING ERRCODE='23514'; END IF;
  IF current_version IS NOT NULL THEN
   EXECUTE format('SELECT r.fact_id,f.purpose FROM public.%I r LEFT JOIN public.%I f ON f.owner_id=r.owner_id AND f.id=r.fact_id WHERE r.owner_id=$1 AND r.semantic_id=$2 AND r.version=$3',TG_ARGV[0]||'_semantic_revision',TG_ARGV[0]||'_fact') INTO prior USING NEW.owner_id,NEW.semantic_id,current_version;
   IF prior.fact_id IS NULL OR prior.purpose IS DISTINCT FROM target.purpose THEN RAISE EXCEPTION 'Semantic fact purpose cannot change across revisions' USING ERRCODE='23514',CONSTRAINT='catalog_semantic_fact_purpose_immutable'; END IF;
  END IF;
 ELSE
  IF current_version IS NOT NULL THEN
   EXECUTE format('SELECT fact_id FROM public.%I WHERE owner_id=$1 AND semantic_id=$2 AND version=$3',TG_ARGV[0]||'_semantic_revision') INTO prior USING NEW.owner_id,NEW.semantic_id,current_version;
   IF prior.fact_id IS NOT NULL THEN RAISE EXCEPTION 'A fact semantic cannot become a relation' USING ERRCODE='23514',CONSTRAINT='catalog_semantic_fact_purpose_immutable'; END IF;
  END IF;
  EXECUTE format('SELECT r.semantic_id,d.constraints FROM public.%I r JOIN public.catalog_definition_revision d ON d.id=r.definition_revision_id WHERE r.owner_id=$1 AND r.id=$2',TG_ARGV[0]||'_catalog_relation') INTO target USING NEW.owner_id,NEW.relation_id;
  IF target.semantic_id IS DISTINCT FROM NEW.semantic_id THEN RAISE EXCEPTION 'Wrong semantic relation' USING ERRCODE='23514'; END IF;
  predicate:=target.constraints;
  IF jsonb_array_length(coalesce(predicate->'roles','[]'::jsonb))=0 THEN RAISE EXCEPTION 'Predicate roles missing' USING ERRCODE='23514'; END IF;
  EXECUTE format('SELECT count(*) FROM (SELECT 1 FROM public.%I WHERE owner_id=$1 AND relation_id=$2 LIMIT 129) p',TG_ARGV[0]||'_relation_participant') INTO total USING NEW.owner_id,NEW.relation_id;
  IF total>128 THEN RAISE EXCEPTION 'Relation participant budget exceeded' USING ERRCODE='23514'; END IF;
  FOR role IN SELECT value FROM jsonb_array_elements(predicate->'roles') LOOP
   EXECUTE format('SELECT count(*) FROM public.%I WHERE owner_id=$1 AND relation_id=$2 AND role_revision_id=$3',TG_ARGV[0]||'_relation_participant') INTO role_count USING NEW.owner_id,NEW.relation_id,(role->>'roleRevisionId')::uuid;
   IF role_count<(role->>'min')::integer OR role_count>(role->>'max')::integer THEN RAISE EXCEPTION 'Predicate cardinality violated' USING ERRCODE='23514'; END IF;
  END LOOP;
  FOR participant IN EXECUTE format('SELECT to_jsonb(p) AS data FROM public.%I p WHERE owner_id=$1 AND relation_id=$2 LIMIT 129',TG_ARGV[0]||'_relation_participant') USING NEW.owner_id,NEW.relation_id LOOP
   SELECT value INTO role FROM jsonb_array_elements(predicate->'roles') WHERE value->>'roleRevisionId'=participant.data->>'role_revision_id';
   IF role IS NULL THEN RAISE EXCEPTION 'Undeclared predicate role' USING ERRCODE='23514'; END IF;
   FOREACH target_owner IN ARRAY ARRAY['publishing','music','program','software','entity','grouping','reference','distribution'] LOOP
    target_id:=(participant.data->>(target_owner||'_id'))::uuid;
    IF target_id IS NOT NULL THEN
     EXECUTE format('SELECT shape FROM public.%I WHERE id=$1',target_owner||'_identity') INTO target_shape USING target_id;
     IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(role->'targets') t WHERE t->>'owner'=target_owner AND t->'shapes' ? target_shape) THEN RAISE EXCEPTION 'Predicate target shape violated' USING ERRCODE='23514'; END IF;
    END IF;
   END LOOP;
  END LOOP;
  EXECUTE format('SELECT count(*) FROM (SELECT 1 FROM public.%I WHERE owner_id=$1 AND relation_id=$2 LIMIT 65) q',TG_ARGV[0]||'_relation_scope') INTO total USING NEW.owner_id,NEW.relation_id;
  IF total>64 THEN RAISE EXCEPTION 'Relation qualifier budget exceeded' USING ERRCODE='23514'; END IF;
  FOR target IN EXECUTE format('SELECT q.definition_revision_id,f.definition_revision_id AS fact_definition,f.sealed_at FROM public.%I q JOIN public.%I f ON f.owner_id=q.owner_id AND f.id=q.value_fact_id WHERE q.owner_id=$1 AND q.relation_id=$2 LIMIT 65',TG_ARGV[0]||'_relation_scope',TG_ARGV[0]||'_fact') USING NEW.owner_id,NEW.relation_id LOOP
   IF NOT (coalesce(predicate->'qualifierRevisionIds','[]'::jsonb) ? target.definition_revision_id::text) OR target.fact_definition<>target.definition_revision_id OR target.sealed_at IS NULL THEN RAISE EXCEPTION 'Undeclared or unsealed relation qualifier' USING ERRCODE='23514'; END IF;
  END LOOP;
 END IF;
 RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.catalog_require_semantic_head()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE current_version bigint;
BEGIN
 EXECUTE format('SELECT version FROM public.%I WHERE owner_id=$1 AND semantic_id=$2',TG_ARGV[0]||'_semantic_head') INTO current_version USING NEW.owner_id,NEW.semantic_id;
 IF current_version IS NULL OR current_version<NEW.version THEN RAISE EXCEPTION 'Immutable semantic revision must publish an atomic head' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END;
$$;

