CREATE OR REPLACE FUNCTION public.catalog_guard_definition_constraints()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE kind text; rule jsonb; role jsonb; reference_id text; reference_kind text; rule_position integer:=0; parent_rule jsonb;
BEGIN
 SELECT d.kind INTO kind FROM public.catalog_definition d WHERE d.id=NEW.definition_id;
 IF kind='predicate' AND (jsonb_typeof(NEW.constraints->'roles') IS DISTINCT FROM 'array' OR jsonb_array_length(NEW.constraints->'roles') NOT BETWEEN 1 AND 32) THEN RAISE EXCEPTION 'Predicate needs bounded roles' USING ERRCODE='23514'; END IF;
 IF NEW.value_kind IN ('object','array') AND (jsonb_typeof(NEW.constraints->'rules') IS DISTINCT FROM 'array' OR jsonb_array_length(NEW.constraints->'rules') NOT BETWEEN 1 AND 128) THEN RAISE EXCEPTION 'Structured property needs bounded grammar' USING ERRCODE='23514'; END IF;
 FOR rule IN SELECT value FROM jsonb_array_elements(coalesce(NEW.constraints->'rules','[]'::jsonb)) LOOP
  IF (rule->>'position')::integer IS DISTINCT FROM rule_position OR (rule_position=0 AND (rule->>'parent' IS NOT NULL OR rule->>'memberKey' IS NOT NULL OR rule->>'kind'<>NEW.value_kind)) OR (rule_position>0 AND ((rule->>'parent')::integer IS NULL OR (rule->>'parent')::integer NOT BETWEEN 0 AND rule_position-1)) THEN RAISE EXCEPTION 'Invalid governed grammar order' USING ERRCODE='23514'; END IF;
  IF rule_position>0 THEN
   parent_rule:=NEW.constraints->'rules'->((rule->>'parent')::integer);
   IF parent_rule->>'kind' NOT IN ('object','array') OR (parent_rule->>'kind'='array')<>(rule->>'memberKey' IS NULL) THEN RAISE EXCEPTION 'Governed grammar parent mismatch' USING ERRCODE='23514'; END IF;
  END IF;
  rule_position:=rule_position+1;
 END LOOP;
 FOR role IN SELECT value FROM jsonb_array_elements(coalesce(NEW.constraints->'roles','[]'::jsonb)) LOOP
  SELECT d.kind INTO reference_kind FROM public.catalog_definition_revision r JOIN public.catalog_definition d ON d.id=r.definition_id WHERE r.id=(role->>'roleRevisionId')::uuid;
  IF reference_kind IS DISTINCT FROM 'role' OR role->>'min' IS NULL OR role->>'max' IS NULL OR (role->>'min')::integer NOT BETWEEN 0 AND 128 OR (role->>'max')::integer NOT BETWEEN 1 AND 128 OR (role->>'min')::integer>(role->>'max')::integer THEN RAISE EXCEPTION 'Invalid governed predicate role' USING ERRCODE='23514'; END IF;
 END LOOP;
 FOR reference_id IN SELECT value FROM jsonb_array_elements_text(coalesce(NEW.constraints->'qualifierRevisionIds','[]'::jsonb)) LOOP
  SELECT d.kind INTO reference_kind FROM public.catalog_definition_revision r JOIN public.catalog_definition d ON d.id=r.definition_id WHERE r.id=reference_id::uuid;
  IF reference_kind IS DISTINCT FROM 'property' THEN RAISE EXCEPTION 'Qualifier must name a property revision' USING ERRCODE='23514'; END IF;
 END LOOP;
 FOR reference_id IN SELECT value FROM jsonb_array_elements_text(coalesce(NEW.constraints->'memberRevisionIds','[]'::jsonb)) LOOP
  SELECT d.kind INTO reference_kind FROM public.catalog_definition_revision r JOIN public.catalog_definition d ON d.id=r.definition_id WHERE r.id=reference_id::uuid;
  IF reference_kind IS NULL OR reference_kind NOT IN ('class','vocabulary') THEN RAISE EXCEPTION 'Vocabulary member must exist as a governed meaning' USING ERRCODE='23514'; END IF;
 END LOOP;
 FOR reference_id IN SELECT v FROM (SELECT NEW.constraints->>'vocabularyRevisionId' AS v UNION SELECT value->>'vocabularyRevisionId' FROM jsonb_array_elements(coalesce(NEW.constraints->'rules','[]'::jsonb))) q WHERE v IS NOT NULL LOOP
  SELECT d.kind INTO reference_kind FROM public.catalog_definition_revision r JOIN public.catalog_definition d ON d.id=r.definition_id WHERE r.id=reference_id::uuid;
  IF reference_kind IS DISTINCT FROM 'vocabulary' THEN RAISE EXCEPTION 'Vocabulary reference must name a vocabulary revision' USING ERRCODE='23514'; END IF;
 END LOOP;
 RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS catalog_definition_revision_governance ON public.catalog_definition_revision;
CREATE TRIGGER catalog_definition_revision_governance BEFORE INSERT ON public.catalog_definition_revision FOR EACH ROW EXECUTE FUNCTION public.catalog_guard_definition_constraints();


-- Software state is constrained in native columns before its immutable history is captured.
CREATE OR REPLACE FUNCTION public.capture_software_record_revision() RETURNS trigger
LANGUAGE plpgsql SET search_path = public AS $$
DECLARE owner_revision bigint;
BEGIN
  IF TG_OP = 'UPDATE' AND (NEW.id IS DISTINCT FROM OLD.id OR NEW.identity_shape IS DISTINCT FROM OLD.identity_shape OR (TG_TABLE_NAME = 'software_version' AND to_jsonb(NEW)->'content_id' IS DISTINCT FROM to_jsonb(OLD)->'content_id')) THEN
    RAISE EXCEPTION 'software identity and content ownership are immutable' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'UPDATE' AND to_jsonb(NEW) = to_jsonb(OLD) THEN RETURN NEW; END IF;
  SELECT revision INTO STRICT owner_revision FROM public.software_identity WHERE id = NEW.id FOR UPDATE;
  INSERT INTO public.software_record_revision(owner_id, revision, shape, value)
  VALUES (NEW.id, owner_revision, NEW.identity_shape, to_jsonb(NEW));
  RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION public.reject_software_revision_mutation() RETURNS trigger
LANGUAGE plpgsql SET search_path = public AS $$
BEGIN
  IF TG_OP = 'INSERT' AND pg_trigger_depth() > 1 THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'software history is written only by native capture triggers' USING ERRCODE = '23514';
END $$;

DROP TRIGGER IF EXISTS software_content_history ON public.software_content;
CREATE TRIGGER software_content_history AFTER INSERT OR UPDATE ON public.software_content
FOR EACH ROW EXECUTE FUNCTION public.capture_software_record_revision();
DROP TRIGGER IF EXISTS software_version_history ON public.software_version;
CREATE TRIGGER software_version_history AFTER INSERT OR UPDATE ON public.software_version
FOR EACH ROW EXECUTE FUNCTION public.capture_software_record_revision();
DROP TRIGGER IF EXISTS software_release_history ON public.software_release;
CREATE TRIGGER software_release_history AFTER INSERT OR UPDATE ON public.software_release
FOR EACH ROW EXECUTE FUNCTION public.capture_software_record_revision();
DROP TRIGGER IF EXISTS software_record_revision_immutable ON public.software_record_revision;
CREATE TRIGGER software_record_revision_immutable BEFORE INSERT OR UPDATE OR DELETE ON public.software_record_revision
FOR EACH ROW EXECUTE FUNCTION public.reject_software_revision_mutation();

CREATE OR REPLACE FUNCTION public.capture_software_component_revision() RETURNS trigger
LANGUAGE plpgsql SET search_path = public AS $$
DECLARE v jsonb; owner_revision bigint; component_id text;
BEGIN
  IF TG_OP = 'UPDATE' AND to_jsonb(NEW) = to_jsonb(OLD) THEN RETURN NEW; END IF;
  v := CASE WHEN TG_OP = 'DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
  component_id := v ->> TG_ARGV[1];
  SELECT revision INTO STRICT owner_revision FROM public.software_identity WHERE id = (v ->> 'release_id')::uuid FOR UPDATE;
  INSERT INTO public.software_component_revision(release_id, kind, component_id, revision, operation, value)
  VALUES ((v ->> 'release_id')::uuid, TG_ARGV[0], component_id, owner_revision, CASE WHEN TG_OP = 'DELETE' THEN 'remove' ELSE 'put' END, v);
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $$;

DROP TRIGGER IF EXISTS software_component_revision_immutable ON public.software_component_revision;
CREATE TRIGGER software_component_revision_immutable BEFORE INSERT OR UPDATE OR DELETE ON public.software_component_revision
FOR EACH ROW EXECUTE FUNCTION public.reject_software_revision_mutation();
DO $$
DECLARE entry text[];
BEGIN
  FOREACH entry SLICE 1 IN ARRAY ARRAY[
    ['software_release_content','content','id'], ['software_release_platform','platform','platform_revision_id'],
    ['software_release_medium','medium','id'], ['software_release_language','language','id'],
    ['software_release_event','event','id'], ['software_patch_target','patch_target','base_release_id'],
    ['software_release_animation','animation','context']
  ] LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS software_component_history ON public.%I', entry[1]);
    EXECUTE format('CREATE TRIGGER software_component_history AFTER INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.capture_software_component_revision(%L,%L)', entry[1], entry[2], entry[3]);
  END LOOP;
END $$;

CREATE OR REPLACE FUNCTION public.enforce_software_patch_target() RETURNS trigger
LANGUAGE plpgsql SET search_path = public AS $$
BEGIN
  IF TG_TABLE_NAME = 'software_patch_target' THEN
    IF NOT EXISTS (SELECT 1 FROM public.software_release WHERE id = NEW.release_id AND is_patch IS TRUE FOR SHARE) THEN
      RAISE EXCEPTION 'only a patch can declare applicable base releases' USING ERRCODE = '23514';
    END IF;
  ELSIF NEW.is_patch IS DISTINCT FROM TRUE AND EXISTS (SELECT 1 FROM public.software_patch_target WHERE release_id = NEW.id LIMIT 1) THEN
    RAISE EXCEPTION 'release with patch targets must remain a patch' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS software_patch_target_kind ON public.software_patch_target;
CREATE TRIGGER software_patch_target_kind BEFORE INSERT OR UPDATE ON public.software_patch_target
FOR EACH ROW EXECUTE FUNCTION public.enforce_software_patch_target();
DROP TRIGGER IF EXISTS software_release_patch_kind ON public.software_release;
CREATE TRIGGER software_release_patch_kind BEFORE UPDATE OF is_patch ON public.software_release
FOR EACH ROW EXECUTE FUNCTION public.enforce_software_patch_target();


CREATE OR REPLACE FUNCTION public.catalog_guard_software_participation()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
BEGIN
  IF TG_OP = 'DELETE' OR (TG_OP = 'UPDATE' AND
      (NEW.content_id <> OLD.content_id OR NEW.id <> OLD.id OR
       NEW.current_revision IS NULL OR
       NEW.current_revision <> coalesce(OLD.current_revision, 0) + 1)) THEN
    RAISE EXCEPTION 'Participation identity is immutable and its head must advance by one'
      USING ERRCODE = '23514', CONSTRAINT = 'software_participation_transition_check';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.catalog_require_software_participation_head()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.software_participation
             WHERE content_id = NEW.content_id AND id = NEW.id AND current_revision IS NULL) THEN
    RAISE EXCEPTION 'Participation must have a current revision at commit'
      USING ERRCODE = '23514', CONSTRAINT = 'software_participation_committed_head_check';
  END IF;
  RETURN NULL;
END;
$$;

CREATE OR REPLACE FUNCTION public.catalog_guard_software_participation_revision()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE current_head bigint;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'Participation revisions and source occurrences are immutable'
      USING ERRCODE = '23514', CONSTRAINT = 'software_participation_history_immutable';
  END IF;
  SELECT current_revision INTO current_head FROM public.software_participation
    WHERE content_id = NEW.content_id AND id = NEW.participation_id FOR UPDATE;
  IF FOUND AND NEW.revision <> coalesce(current_head, 0) + 1 THEN
    RAISE EXCEPTION 'Participation revisions must append at the current head'
      USING ERRCODE = '23514', CONSTRAINT = 'software_participation_revision_sequence_check';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS software_participation_guard ON public.software_participation;
CREATE TRIGGER software_participation_guard BEFORE UPDATE OR DELETE ON public.software_participation
FOR EACH ROW EXECUTE FUNCTION public.catalog_guard_software_participation();

DROP TRIGGER IF EXISTS software_participation_head_required ON public.software_participation;
CREATE CONSTRAINT TRIGGER software_participation_head_required AFTER INSERT OR UPDATE ON public.software_participation
DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.catalog_require_software_participation_head();

DROP TRIGGER IF EXISTS software_participation_revision_guard ON public.software_participation_revision;
CREATE TRIGGER software_participation_revision_guard BEFORE INSERT OR UPDATE OR DELETE ON public.software_participation_revision
FOR EACH ROW EXECUTE FUNCTION public.catalog_guard_software_participation_revision();

DROP TRIGGER IF EXISTS software_participation_occurrence_guard ON public.software_participation_credit_source_occurrence;
CREATE TRIGGER software_participation_occurrence_guard BEFORE UPDATE OR DELETE ON public.software_participation_credit_source_occurrence
FOR EACH ROW EXECUTE FUNCTION public.catalog_guard_software_participation_revision();

CREATE OR REPLACE FUNCTION public.catalog_require_software_participation_revision_head()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.software_participation
             WHERE content_id = NEW.content_id AND id = NEW.participation_id
             AND (current_revision IS NULL OR current_revision < NEW.revision)) THEN
    RAISE EXCEPTION 'Participation appended revision must become current in its transaction'
      USING ERRCODE = '23514', CONSTRAINT = 'software_participation_appended_head_check';
  END IF;
  RETURN NULL;
END;
$$;

DROP TRIGGER IF EXISTS software_participation_revision_head_required ON public.software_participation_revision;
CREATE CONSTRAINT TRIGGER software_participation_revision_head_required AFTER INSERT ON public.software_participation_revision
DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.catalog_require_software_participation_revision_head();

CREATE OR REPLACE FUNCTION public.catalog_validate_software_participation() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.entity_identity WHERE id = NEW.entity_id AND shape IN ('person','organization','collective','unresolved','label')) THEN
    RAISE EXCEPTION 'Participation actor must be a person, organization or collective' USING ERRCODE = '23514';
  END IF;
  IF NEW.character_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.entity_identity WHERE id = NEW.character_id AND shape = 'character') THEN
    RAISE EXCEPTION 'Voice participation requires a Character' USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.catalog_definition_revision r JOIN public.catalog_definition d ON d.id = r.definition_id WHERE r.id = NEW.role_revision_id AND d.kind = 'vocabulary') THEN
    RAISE EXCEPTION 'Participation role requires a vocabulary revision' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS software_participation_values ON public.software_participation_revision;
CREATE TRIGGER software_participation_values BEFORE INSERT ON public.software_participation_revision
FOR EACH ROW EXECUTE FUNCTION public.catalog_validate_software_participation();


CREATE OR REPLACE FUNCTION public.catalog_source_guard_record()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
BEGIN
  IF TG_OP = 'DELETE' OR (TG_OP = 'UPDATE' AND
    (NEW.id <> OLD.id OR NEW.source <> OLD.source OR NEW.object_type <> OLD.object_type OR
     NEW.external_id <> OLD.external_id OR NEW.acquisition_generation < OLD.acquisition_generation OR
     NEW.accepted_generation < OLD.accepted_generation)) THEN
    RAISE EXCEPTION 'Source natural identity is immutable and acquisition generations cannot regress'
      USING ERRCODE = '23514', CONSTRAINT = 'catalog_source_identity_immutable';
  END IF;
  IF NEW.head_snapshot_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.catalog_source_snapshot WHERE source_record_id = NEW.id AND id = NEW.head_snapshot_id
  ) THEN
    RAISE EXCEPTION 'Source head must reference its own immutable snapshot'
      USING ERRCODE = '23503', CONSTRAINT = 'catalog_source_exact_head';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.catalog_source_guard_immutable_evidence()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
BEGIN
  RAISE EXCEPTION 'Source snapshots, binding revisions and completed check receipts are immutable'
    USING ERRCODE = '23514', CONSTRAINT = 'catalog_source_evidence_immutable';
END;
$$;

CREATE OR REPLACE FUNCTION public.catalog_source_guard_mapping()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
BEGIN
  IF TG_OP = 'DELETE' OR (TG_OP = 'UPDATE' AND
    (NEW.source_record_id <> OLD.source_record_id OR NEW.path <> OLD.path OR
     NEW.mapping_key <> OLD.mapping_key OR NEW.owner <> OLD.owner OR
     NEW.binding_revision < OLD.binding_revision OR NEW.binding_revision > OLD.binding_revision + 1 OR
     NEW.policy_revision < OLD.policy_revision OR
     NEW.correspondence_revision < OLD.correspondence_revision OR
     (NEW.correspondence_revision <> OLD.correspondence_revision AND NEW.binding_revision <> OLD.binding_revision + 1) OR
     (NEW.mapping_version <> OLD.mapping_version AND NEW.binding_revision <> OLD.binding_revision + 1) OR
     ((NEW.state <> OLD.state OR NEW.policy_revision <> OLD.policy_revision) AND NEW.binding_revision <> OLD.binding_revision + 1))) THEN
    RAISE EXCEPTION 'Source mapping identity is immutable and authority edits require the next revision'
      USING ERRCODE = '23514', CONSTRAINT = 'catalog_source_mapping_transition';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.catalog_source_require_binding_head()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE claim public.catalog_source_mapping_claim%ROWTYPE; binding_row public.catalog_source_binding_revision%ROWTYPE; native_target uuid;
BEGIN
  SELECT * INTO claim FROM public.catalog_source_mapping_claim
    WHERE source_record_id = NEW.source_record_id AND mapping_key = NEW.mapping_key;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF to_jsonb(NEW) ? 'revision' AND (to_jsonb(NEW)->>'revision')::bigint > claim.binding_revision THEN
    RAISE EXCEPTION 'An appended source binding revision must be published in its transaction'
      USING ERRCODE = '23514', CONSTRAINT = 'catalog_source_binding_revision_published';
  END IF;
  SELECT r.* INTO binding_row FROM public.catalog_source_binding_revision r
    WHERE r.source_record_id = claim.source_record_id AND r.mapping_key = claim.mapping_key AND r.revision = claim.binding_revision;
  IF NOT FOUND OR binding_row.owner <> claim.owner OR binding_row.policy_revision <> claim.policy_revision OR binding_row.state <> claim.state OR binding_row.mapping_version <> claim.mapping_version OR binding_row.correspondence_revision <> claim.correspondence_revision THEN
    RAISE EXCEPTION 'Source mapping must commit its exact immutable binding and policy revision'
      USING ERRCODE = '23514', CONSTRAINT = 'catalog_source_binding_head_required';
  END IF;
  IF claim.applied_correspondence_revision IS NOT NULL AND (claim.observed_snapshot_id IS NULL OR NOT EXISTS(
    SELECT 1 FROM public.catalog_source_binding_revision a WHERE a.source_record_id=claim.source_record_id AND a.mapping_key=claim.mapping_key AND a.revision=claim.applied_correspondence_revision AND a.correspondence_revision=a.revision AND a.owner=claim.owner
  )) THEN RAISE EXCEPTION 'Applied source correspondence must retain an exact observed snapshot and epoch anchor' USING ERRCODE='23514'; END IF;
  EXECUTE format('SELECT owner_id FROM public.%I WHERE source_record_id = $1 AND mapping_key = $2', claim.owner || '_source_binding')
    INTO native_target USING claim.source_record_id, claim.mapping_key;
  IF native_target IS NULL OR native_target IS DISTINCT FROM (to_jsonb(binding_row)->>(claim.owner || '_id'))::uuid THEN
    RAISE EXCEPTION 'Source binding target must equal its committed revision target'
      USING ERRCODE = '23514', CONSTRAINT = 'catalog_source_binding_exact_target';
  END IF;
  RETURN NULL;
END;
$$;

DROP TRIGGER IF EXISTS catalog_source_record_guard ON public.catalog_source_record;
CREATE TRIGGER catalog_source_record_guard BEFORE INSERT OR UPDATE OR DELETE ON public.catalog_source_record
FOR EACH ROW EXECUTE FUNCTION public.catalog_source_guard_record();
DROP TRIGGER IF EXISTS catalog_source_mapping_guard ON public.catalog_source_mapping_claim;
CREATE TRIGGER catalog_source_mapping_guard BEFORE UPDATE OR DELETE ON public.catalog_source_mapping_claim
FOR EACH ROW EXECUTE FUNCTION public.catalog_source_guard_mapping();

DO $$
DECLARE relation_name text; physical record;
BEGIN
  FOREACH relation_name IN ARRAY ARRAY['catalog_source_snapshot', 'catalog_source_binding_revision', 'catalog_source_check_receipt'] LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS catalog_source_evidence_guard ON public.%I', relation_name);
    EXECUTE format('CREATE TRIGGER catalog_source_evidence_guard BEFORE UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.catalog_source_guard_immutable_evidence()', relation_name);
  END LOOP;
  -- Constraint triggers are installed on concrete leaves, including an unpartitioned fresh target.
  FOR physical IN
    WITH RECURSIVE roots AS (
      SELECT c.oid FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
      WHERE n.nspname='public' AND c.relname IN ('catalog_source_mapping_claim','catalog_source_binding_revision','publishing_source_binding','music_source_binding','program_source_binding','software_source_binding','entity_source_binding','grouping_source_binding','reference_source_binding','distribution_source_binding')
      UNION ALL SELECT i.inhrelid FROM pg_inherits i JOIN roots r ON r.oid=i.inhparent
    ) SELECT c.oid::regclass AS name FROM roots r JOIN pg_class c ON c.oid=r.oid WHERE c.relkind='r'
  LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS catalog_source_binding_head_required ON %s', physical.name);
    EXECUTE format('CREATE CONSTRAINT TRIGGER catalog_source_binding_head_required AFTER INSERT OR UPDATE ON %s DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.catalog_source_require_binding_head()', physical.name);
  END LOOP;
END;
$$;


CREATE OR REPLACE FUNCTION public.catalog_structure_source_projection_valid(component_name text, source_value jsonb, observed_fields text[])
RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path = pg_catalog, public AS $$
DECLARE shape_name text; allowed text[]; uuids text[] := '{}'; integers text[] := '{}'; numbers text[] := '{}'; strings text[] := '{}'; fields jsonb; field_name text; scalar jsonb; numeric_value numeric; yr numeric; mon numeric; dy numeric; maximum_day integer;
BEGIN
  CASE component_name
    WHEN 'program_work' THEN shape_name:='program'; uuids:=ARRAY['typeRevisionId']; integers:=ARRAY['declaredMainEpisodeCount','declaredTotalEpisodeCount'];
    WHEN 'program_season' THEN shape_name:='season'; uuids:=ARRAY['programId']; strings:=ARRAY['number'];
    WHEN 'program_version' THEN shape_name:='program_version'; uuids:=ARRAY['programId','versionTypeRevisionId']; integers:=ARRAY['lengthMilliseconds'];
    WHEN 'program_episode' THEN shape_name:='episode'; uuids:=ARRAY['programId','seasonId','typeRevisionId']; integers:=ARRAY['discNumber','lengthMilliseconds']; numbers:=ARRAY['sortNumber','episodeNumber']; strings:=ARRAY['durationText','dateText'];
    WHEN 'publishing_work' THEN shape_name:='work';
    WHEN 'publishing_text_version' THEN shape_name:='text_version'; uuids:=ARRAY['methodRevisionId']; strings:=ARRAY['languageTag'];
    WHEN 'publishing_publication' THEN shape_name:='publication'; integers:=ARRAY['pageCount']; strings:=ARRAY['paginationText'];
    WHEN 'publishing_serialization' THEN shape_name:='serialization'; uuids:=ARRAY['textVersionId','statusRevisionId'];
    ELSE RETURN false;
  END CASE;
  IF source_value IS NULL OR jsonb_typeof(source_value) IS DISTINCT FROM 'object' OR source_value->>'shape' IS DISTINCT FROM shape_name
    OR source_value-'shape'-'fields'<>'{}'::jsonb OR jsonb_typeof(source_value->'fields') IS DISTINCT FROM 'object' THEN RETURN false; END IF;
  fields:=source_value->'fields'; allowed:=uuids||integers||numbers||strings;
  IF component_name='program_episode' THEN allowed:=allowed||ARRAY['date']; END IF;
  IF NOT fields ?& allowed OR fields-allowed<>'{}'::jsonb OR observed_fields IS NULL OR cardinality(observed_fields)>32
    OR NOT observed_fields<@allowed OR (SELECT count(*)<>count(DISTINCT k) FROM unnest(observed_fields) k) THEN RETURN false; END IF;
  IF component_name='program_episode' AND fields->'seasonId'<>'null'::jsonb AND fields->'programId'='null'::jsonb THEN RETURN false; END IF;
  FOREACH field_name IN ARRAY allowed LOOP
    scalar:=fields->field_name;
    IF NOT field_name=ANY(observed_fields) THEN
      IF field_name='date' THEN
        IF scalar<>'{"year":null,"month":null,"day":null}'::jsonb THEN RETURN false; END IF;
      ELSIF scalar<>'null'::jsonb THEN RETURN false; END IF;
    END IF;
    IF scalar='null'::jsonb THEN
      IF field_name='date' THEN RETURN false; END IF;
      CONTINUE;
    END IF;
    IF field_name=ANY(uuids) THEN
      IF jsonb_typeof(scalar)<>'string' OR fields->>field_name !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RETURN false; END IF;
    ELSIF field_name=ANY(integers) OR field_name=ANY(numbers) THEN
      IF jsonb_typeof(scalar)<>'number' THEN RETURN false; END IF;
      numeric_value:=(fields->>field_name)::numeric;
      IF field_name=ANY(integers) AND (numeric_value<0 OR numeric_value>9007199254740991 OR trunc(numeric_value)<>numeric_value) THEN RETURN false; END IF;
      IF field_name='discNumber' AND numeric_value>2147483647 THEN RETURN false; END IF;
      IF abs(numeric_value)>1.7976931348623157e308::numeric THEN RETURN false; END IF;
    ELSIF field_name=ANY(strings) THEN
      IF jsonb_typeof(scalar)<>'string' OR char_length(fields->>field_name)>(CASE WHEN field_name IN('number','durationText','dateText') THEN 4096 WHEN field_name='languageTag' THEN 255 ELSE 131072 END) THEN RETURN false; END IF;
    ELSE
      IF jsonb_typeof(scalar)<>'object' OR NOT scalar ?& ARRAY['year','month','day'] OR scalar-'year'-'month'-'day'<>'{}'::jsonb THEN RETURN false; END IF;
      IF EXISTS(SELECT 1 FROM jsonb_each(scalar) f WHERE jsonb_typeof(f.value) NOT IN ('number','null')) THEN RETURN false; END IF;
      yr:=(scalar->>'year')::numeric; mon:=(scalar->>'month')::numeric; dy:=(scalar->>'day')::numeric;
      IF yr IS NOT NULL AND (yr<>trunc(yr) OR yr NOT BETWEEN -2147483648 AND 2147483647) THEN RETURN false; END IF;
      IF mon IS NOT NULL AND (mon<>trunc(mon) OR mon NOT BETWEEN 1 AND 12) THEN RETURN false; END IF;
      IF dy IS NOT NULL AND (dy<>trunc(dy) OR dy NOT BETWEEN 1 AND 31) THEN RETURN false; END IF;
      IF mon IS NOT NULL AND dy IS NOT NULL THEN
        maximum_day:=CASE WHEN mon=2 THEN CASE WHEN yr IS NULL OR mod(yr,400)=0 OR (mod(yr,4)=0 AND mod(yr,100)<>0) THEN 29 ELSE 28 END WHEN mon IN(4,6,9,11) THEN 30 ELSE 31 END;
        IF dy>maximum_day THEN RETURN false; END IF;
      END IF;
    END IF;
  END LOOP;
  RETURN true;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN false;
END $$;

CREATE OR REPLACE FUNCTION public.catalog_structure_source_guard_occurrence()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE root public.catalog_source_binding_revision%ROWTYPE; native record; shape_name text; parent_id uuid; source_definition_id uuid; field_name text; expected_shape text;
BEGIN
  IF TG_ARGV[0] NOT IN ('program','publishing') OR NEW.component NOT LIKE TG_ARGV[0]||'_%' OR NEW.component_key<>NEW.owner_id::text
    OR NOT public.catalog_structure_source_projection_valid(NEW.component,NEW.source_value,NEW.observed_fields) THEN
    RAISE EXCEPTION 'Structure source projection must contain only typed observed values' USING ERRCODE='23514';
  END IF;
  SELECT * INTO STRICT root FROM public.catalog_source_binding_revision WHERE source_record_id=NEW.source_record_id AND mapping_key=NEW.mapping_key AND revision=NEW.correspondence_revision;
  IF root.correspondence_revision<>root.revision OR root.owner<>NEW.mapping_owner THEN RAISE EXCEPTION 'Structure source requires its exact root correspondence epoch' USING ERRCODE='23514'; END IF;
  EXECUTE format('SELECT component,component_key,operation FROM public.%I WHERE owner_id=$1 AND id=$2',TG_ARGV[0]||'_component_revision') INTO STRICT native USING NEW.owner_id,NEW.history_id;
  IF native.component<>NEW.component OR native.component_key<>NEW.component_key OR native.operation='DELETE' THEN RAISE EXCEPTION 'Structure source history belongs to another native component' USING ERRCODE='23514'; END IF;
  FOREACH field_name IN ARRAY (CASE WHEN TG_ARGV[0]='program' THEN ARRAY['programId','seasonId'] ELSE ARRAY['textVersionId'] END) LOOP
    parent_id:=(NEW.source_value->'fields'->>field_name)::uuid;
    IF parent_id IS NULL THEN CONTINUE; END IF;
    expected_shape:=CASE field_name WHEN 'programId' THEN 'program' WHEN 'seasonId' THEN 'season' ELSE 'text_version' END;
    EXECUTE format('SELECT shape FROM public.%I WHERE id=$1',TG_ARGV[0]||'_identity') INTO STRICT shape_name USING parent_id;
    IF shape_name<>expected_shape THEN RAISE EXCEPTION 'Structure source parent has another native shape' USING ERRCODE='23514'; END IF;
  END LOOP;
  FOREACH field_name IN ARRAY ARRAY['typeRevisionId','versionTypeRevisionId','methodRevisionId','statusRevisionId'] LOOP
    source_definition_id:=(NEW.source_value->'fields'->>field_name)::uuid;
    IF source_definition_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.catalog_definition_revision r JOIN public.catalog_definition d ON d.id=r.definition_id WHERE r.id=source_definition_id AND d.kind='vocabulary') THEN
      RAISE EXCEPTION 'Structure source type or method requires an exact vocabulary revision' USING ERRCODE='23514';
    END IF;
  END LOOP;
  RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION public.catalog_structure_source_guard_application()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE application public.catalog_source_application%ROWTYPE; proposal_state text; before_row record; after_row record; current_id uuid;
BEGIN
  IF TG_ARGV[0] NOT IN ('program','publishing') OR NEW.component NOT LIKE TG_ARGV[0]||'_%' OR NEW.component_key<>NEW.owner_id::text THEN RAISE EXCEPTION 'Structure application owner differs' USING ERRCODE='23514'; END IF;
  SELECT * INTO STRICT application FROM public.catalog_source_application WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action;
  SELECT state INTO STRICT proposal_state FROM public.catalog_source_adoption_proposal WHERE source_record_id=NEW.source_record_id AND id=NEW.proposal_id;
  IF NEW.position>=application.change_count OR (NEW.action='apply' AND proposal_state<>'pending') OR (NEW.action='withdraw' AND proposal_state<>'applied') THEN RAISE EXCEPTION 'Structure change requires its in-progress source application' USING ERRCODE='23514'; END IF;
  EXECUTE format('SELECT component,component_key,component_sequence FROM public.%I WHERE owner_id=$1 AND id=$2',TG_ARGV[0]||'_component_revision') INTO STRICT after_row USING NEW.owner_id,NEW.after_revision_id;
  IF after_row.component<>NEW.component OR after_row.component_key<>NEW.component_key THEN RAISE EXCEPTION 'Structure application after history differs' USING ERRCODE='23514'; END IF;
  IF NEW.before_revision_id IS NOT NULL THEN
    EXECUTE format('SELECT component,component_key,component_sequence FROM public.%I WHERE owner_id=$1 AND id=$2',TG_ARGV[0]||'_component_revision') INTO STRICT before_row USING NEW.owner_id,NEW.before_revision_id;
    IF before_row.component<>NEW.component OR before_row.component_key<>NEW.component_key OR before_row.component_sequence>=after_row.component_sequence THEN RAISE EXCEPTION 'Structure application history order differs' USING ERRCODE='23514'; END IF;
  END IF;
  EXECUTE format('SELECT history_id FROM public.%I WHERE owner_id=$1 AND component=$2 AND component_key=$3',TG_ARGV[0]||'_component_head') INTO STRICT current_id USING NEW.owner_id,NEW.component,NEW.component_key;
  IF current_id<>NEW.after_revision_id THEN RAISE EXCEPTION 'Structure application does not identify the current child head' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION public.catalog_structure_source_guard_baseline()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE source_row record; native record; previous_sequence bigint; root public.catalog_source_binding_revision%ROWTYPE; matched boolean;
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Structure source baselines are retained evidence' USING ERRCODE='23514'; END IF;
  IF TG_OP='UPDATE' AND (NEW.source_record_id,NEW.mapping_key,NEW.correspondence_revision,NEW.mapping_owner,NEW.owner_id,NEW.component,NEW.component_key) IS DISTINCT FROM (OLD.source_record_id,OLD.mapping_key,OLD.correspondence_revision,OLD.mapping_owner,OLD.owner_id,OLD.component,OLD.component_key) THEN RAISE EXCEPTION 'Structure baseline identity is immutable' USING ERRCODE='23514'; END IF;
  SELECT * INTO STRICT root FROM public.catalog_source_binding_revision WHERE source_record_id=NEW.source_record_id AND mapping_key=NEW.mapping_key AND revision=NEW.correspondence_revision;
  IF root.correspondence_revision<>root.revision OR root.owner<>NEW.mapping_owner OR NOT public.catalog_source_application_includes_epoch(NEW.source_record_id,NEW.proposal_id,NEW.mapping_key,NEW.correspondence_revision) THEN RAISE EXCEPTION 'Structure baseline requires an admitted application epoch' USING ERRCODE='23514'; END IF;
  EXECUTE format('SELECT history_id,source_path FROM public.%I WHERE source_record_id=$1 AND mapping_key=$2 AND correspondence_revision=$3 AND snapshot_id=$4 AND owner_id=$5 AND component=$6 AND component_key=$7',TG_ARGV[0]||'_structure_source_occurrence') INTO STRICT source_row USING NEW.source_record_id,NEW.mapping_key,NEW.correspondence_revision,NEW.snapshot_id,NEW.owner_id,NEW.component,NEW.component_key;
  IF source_row.history_id<>NEW.source_history_id OR source_row.source_path<>NEW.source_path THEN RAISE EXCEPTION 'Structure baseline source occurrence differs' USING ERRCODE='23514'; END IF;
  EXECUTE format('SELECT h.id,h.component,h.component_key,h.component_sequence FROM public.%I head JOIN public.%I h ON h.owner_id=head.owner_id AND h.id=head.history_id WHERE head.owner_id=$1 AND head.component=$2 AND head.component_key=$3',TG_ARGV[0]||'_component_head',TG_ARGV[0]||'_component_revision') INTO STRICT native USING NEW.owner_id,NEW.component,NEW.component_key;
  IF native.id<>NEW.current_history_id THEN RAISE EXCEPTION 'Structure baseline current history is stale' USING ERRCODE='23514'; END IF;
  IF TG_OP='UPDATE' THEN
    EXECUTE format('SELECT component_sequence FROM public.%I WHERE owner_id=$1 AND id=$2',TG_ARGV[0]||'_component_revision') INTO STRICT previous_sequence USING OLD.owner_id,OLD.current_history_id;
    IF native.component_sequence<=previous_sequence THEN RAISE EXCEPTION 'Structure baseline history must advance' USING ERRCODE='23514'; END IF;
  END IF;
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE source_record_id=$1 AND proposal_id=$2 AND action=$3 AND owner_id=$4 AND component=$5 AND component_key=$6 AND after_revision_id=$7)',TG_ARGV[0]||'_structure_source_application_change') INTO matched USING NEW.source_record_id,NEW.proposal_id,NEW.action,NEW.owner_id,NEW.component,NEW.component_key,NEW.current_history_id;
  IF NOT matched THEN RAISE EXCEPTION 'Structure baseline current history lacks its exact application' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;

DO $$
DECLARE owner_name text; table_name text;
BEGIN
  FOREACH owner_name IN ARRAY ARRAY['program','publishing'] LOOP
    FOREACH table_name IN ARRAY ARRAY[owner_name||'_structure_source_occurrence',owner_name||'_structure_source_application_change'] LOOP
      EXECUTE format('DROP TRIGGER IF EXISTS catalog_structure_source_immutable ON public.%I',table_name);
      EXECUTE format('CREATE TRIGGER catalog_structure_source_immutable BEFORE UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.catalog_source_guard_immutable_evidence()',table_name);
    END LOOP;
    EXECUTE format('DROP TRIGGER IF EXISTS catalog_structure_source_occurrence_guard ON public.%I',owner_name||'_structure_source_occurrence');
    EXECUTE format('CREATE TRIGGER catalog_structure_source_occurrence_guard BEFORE INSERT ON public.%I FOR EACH ROW EXECUTE FUNCTION public.catalog_structure_source_guard_occurrence(%L)',owner_name||'_structure_source_occurrence',owner_name);
    EXECUTE format('DROP TRIGGER IF EXISTS catalog_structure_source_application_guard ON public.%I',owner_name||'_structure_source_application_change');
    EXECUTE format('CREATE TRIGGER catalog_structure_source_application_guard BEFORE INSERT ON public.%I FOR EACH ROW EXECUTE FUNCTION public.catalog_structure_source_guard_application(%L)',owner_name||'_structure_source_application_change',owner_name);
    EXECUTE format('DROP TRIGGER IF EXISTS catalog_structure_source_baseline_guard ON public.%I',owner_name||'_structure_source_baseline');
    EXECUTE format('CREATE TRIGGER catalog_structure_source_baseline_guard BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.catalog_structure_source_guard_baseline(%L)',owner_name||'_structure_source_baseline',owner_name);
  END LOOP;
END $$;


CREATE OR REPLACE FUNCTION public.catalog_source_guard_binding_correspondence()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE previous public.catalog_source_binding_revision%ROWTYPE; anchor public.catalog_source_binding_revision%ROWTYPE; same_meaning boolean;
BEGIN
  IF NEW.revision=1 THEN
    IF NEW.correspondence_revision<>1 THEN RAISE EXCEPTION 'Initial source correspondence must anchor itself' USING ERRCODE='23514'; END IF;
  ELSE
    SELECT * INTO previous FROM public.catalog_source_binding_revision WHERE source_record_id=NEW.source_record_id AND mapping_key=NEW.mapping_key AND revision=NEW.revision-1;
    IF NOT FOUND THEN RAISE EXCEPTION 'Source binding revisions must be contiguous' USING ERRCODE='23514'; END IF;
    same_meaning := (NEW.owner,NEW.mapping_version,NEW.publishing_id,NEW.music_id,NEW.program_id,NEW.software_id,NEW.entity_id,NEW.grouping_id,NEW.reference_id,NEW.distribution_id)
      IS NOT DISTINCT FROM (previous.owner,previous.mapping_version,previous.publishing_id,previous.music_id,previous.program_id,previous.software_id,previous.entity_id,previous.grouping_id,previous.reference_id,previous.distribution_id);
    IF NEW.correspondence_revision <> (CASE WHEN same_meaning THEN previous.correspondence_revision ELSE NEW.revision END) THEN
      RAISE EXCEPTION 'Correspondence changes only with native target or mapping meaning' USING ERRCODE='23514';
    END IF;
  END IF;
  IF NEW.correspondence_revision<>NEW.revision THEN
    SELECT * INTO anchor FROM public.catalog_source_binding_revision WHERE source_record_id=NEW.source_record_id AND mapping_key=NEW.mapping_key AND revision=NEW.correspondence_revision;
    IF NOT FOUND OR anchor.correspondence_revision<>anchor.revision OR
      (NEW.owner,NEW.mapping_version,NEW.publishing_id,NEW.music_id,NEW.program_id,NEW.software_id,NEW.entity_id,NEW.grouping_id,NEW.reference_id,NEW.distribution_id)
      IS DISTINCT FROM (anchor.owner,anchor.mapping_version,anchor.publishing_id,anchor.music_id,anchor.program_id,anchor.software_id,anchor.entity_id,anchor.grouping_id,anchor.reference_id,anchor.distribution_id) THEN
      RAISE EXCEPTION 'Correspondence requires the exact self-anchored target and mapping meaning' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS catalog_source_binding_correspondence_guard ON public.catalog_source_binding_revision;
CREATE TRIGGER catalog_source_binding_correspondence_guard BEFORE INSERT ON public.catalog_source_binding_revision
FOR EACH ROW EXECUTE FUNCTION public.catalog_source_guard_binding_correspondence();

CREATE OR REPLACE FUNCTION public.catalog_source_guard_child_correspondence()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE anchor public.catalog_source_binding_revision%ROWTYPE; source_mapping uuid; source_epoch bigint; native_shape text;
BEGIN
  IF TG_ARGV[0]='source-support' THEN
    source_mapping := NEW.source_mapping_key; source_epoch := NEW.source_correspondence_revision;
    IF source_mapping IS NULL AND source_epoch IS NULL THEN RETURN NEW; END IF;
  ELSE
    source_mapping := NEW.mapping_key; source_epoch := NEW.correspondence_revision;
  END IF;
  SELECT * INTO anchor FROM public.catalog_source_binding_revision WHERE source_record_id=NEW.source_record_id AND mapping_key=source_mapping AND revision=source_epoch;
  IF NOT FOUND OR anchor.correspondence_revision<>anchor.revision THEN RAISE EXCEPTION 'Source child correspondence requires its exact epoch anchor' USING ERRCODE='23514'; END IF;
  IF TG_ARGV[0]='software-context' THEN
    IF anchor.owner<>'software' OR anchor.software_id IS DISTINCT FROM NEW.content_id THEN
      RAISE EXCEPTION 'Source context correspondence must target its exact software content' USING ERRCODE='23514';
    END IF;
  END IF;
  IF TG_ARGV[0] IN ('software-owner','software-record') THEN
    IF anchor.owner<>'software' OR anchor.software_id IS DISTINCT FROM NEW.owner_id THEN
      RAISE EXCEPTION 'Source scalar or component correspondence must target its exact software owner' USING ERRCODE='23514';
    END IF;
  END IF;
  IF TG_ARGV[0]='software-record' THEN
    SELECT shape INTO STRICT native_shape FROM public.software_record_revision WHERE owner_id=NEW.owner_id AND revision=NEW.revision;
    IF native_shape IS DISTINCT FROM NEW.source_shape THEN RAISE EXCEPTION 'Source scalar interpretation must match its exact native history shape' USING ERRCODE='23514'; END IF;
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS software_context_correspondence_guard ON public.software_participation_source_occurrence;
CREATE TRIGGER software_context_correspondence_guard BEFORE INSERT ON public.software_participation_source_occurrence
FOR EACH ROW EXECUTE FUNCTION public.catalog_source_guard_child_correspondence('software-context');
DROP TRIGGER IF EXISTS software_credit_correspondence_guard ON public.software_participation_credit_source_occurrence;
CREATE TRIGGER software_credit_correspondence_guard BEFORE INSERT ON public.software_participation_credit_source_occurrence
FOR EACH ROW EXECUTE FUNCTION public.catalog_source_guard_child_correspondence('software-context');
DROP TRIGGER IF EXISTS software_record_correspondence_guard ON public.software_record_source_occurrence;
CREATE TRIGGER software_record_correspondence_guard BEFORE INSERT ON public.software_record_source_occurrence
FOR EACH ROW EXECUTE FUNCTION public.catalog_source_guard_child_correspondence('software-record');
DROP TRIGGER IF EXISTS software_component_correspondence_guard ON public.software_component_source_occurrence;
CREATE TRIGGER software_component_correspondence_guard BEFORE INSERT ON public.software_component_source_occurrence
FOR EACH ROW EXECUTE FUNCTION public.catalog_source_guard_child_correspondence('software-owner');
DO $$ DECLARE owner_name text; family text;
BEGIN
  FOREACH owner_name IN ARRAY ARRAY['publishing','music','program','software','entity','grouping','reference','distribution'] LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS catalog_support_correspondence_guard ON public.%I',owner_name || '_fact_support');
    EXECUTE format('CREATE TRIGGER catalog_support_correspondence_guard BEFORE INSERT ON public.%I FOR EACH ROW EXECUTE FUNCTION public.catalog_source_guard_child_correspondence(%L)',owner_name || '_fact_support','source-support');
    FOREACH family IN ARRAY ARRAY['name_source_binding','name_source_occurrence'] LOOP
      EXECUTE format('DROP TRIGGER IF EXISTS catalog_name_correspondence_guard ON public.%I',owner_name || '_' || family);
      EXECUTE format('CREATE TRIGGER catalog_name_correspondence_guard BEFORE INSERT ON public.%I FOR EACH ROW EXECUTE FUNCTION public.catalog_source_guard_child_correspondence(%L)',owner_name || '_' || family,'name');
    END LOOP;
  END LOOP;
  FOREACH owner_name IN ARRAY ARRAY['entity','reference'] LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS catalog_profile_correspondence_guard ON public.%I',owner_name || '_profile_source_occurrence');
    EXECUTE format('CREATE TRIGGER catalog_profile_correspondence_guard BEFORE INSERT ON public.%I FOR EACH ROW EXECUTE FUNCTION public.catalog_source_guard_child_correspondence(%L)',owner_name || '_profile_source_occurrence','profile');
  END LOOP;
END $$;


CREATE OR REPLACE FUNCTION public.catalog_guard_source_support()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Source occurrence history cannot be deleted' USING ERRCODE = '23514';
  END IF;
  IF (to_jsonb(NEW) - 'withdrawn_at') IS DISTINCT FROM (to_jsonb(OLD) - 'withdrawn_at')
    OR (OLD.withdrawn_at IS NOT NULL AND NEW.withdrawn_at IS DISTINCT FROM OLD.withdrawn_at) THEN
    RAISE EXCEPTION 'Source occurrence target, revision, epoch and evidence are immutable' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;

DO $$
DECLARE owner_name text;
BEGIN
  FOREACH owner_name IN ARRAY ARRAY['publishing','music','program','software','entity','grouping','reference','distribution'] LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS catalog_source_support_guard ON public.%I', owner_name || '_fact_support');
    EXECUTE format('CREATE TRIGGER catalog_source_support_guard BEFORE UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.catalog_guard_source_support()', owner_name || '_fact_support');
  END LOOP;
END $$;


CREATE OR REPLACE FUNCTION public.catalog_source_guard_dependency()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE proposal public.catalog_source_adoption_proposal%ROWTYPE; binding public.catalog_source_binding_revision%ROWTYPE; root_claim public.catalog_source_mapping_claim%ROWTYPE;
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Source dependency evidence is retained' USING ERRCODE='23514'; END IF;
  IF TG_OP='UPDATE' THEN
    IF (to_jsonb(NEW)-'revoked_at'-'prepared_by_auth_user_id') IS DISTINCT FROM (to_jsonb(OLD)-'revoked_at'-'prepared_by_auth_user_id')
      OR (OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS DISTINCT FROM OLD.revoked_at)
      OR (NEW.prepared_by_auth_user_id IS DISTINCT FROM OLD.prepared_by_auth_user_id AND NEW.prepared_by_auth_user_id IS NOT NULL) THEN
      RAISE EXCEPTION 'Source dependency target and evidence are immutable' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  SELECT * INTO STRICT proposal FROM public.catalog_source_adoption_proposal WHERE source_record_id=NEW.source_record_id AND id=NEW.proposal_id FOR SHARE;
  SELECT * INTO STRICT root_claim FROM public.catalog_source_mapping_claim WHERE source_record_id=proposal.source_record_id AND mapping_key=proposal.mapping_key FOR SHARE;
  IF proposal.state<>'pending' OR proposal.expected_binding_revision<>root_claim.binding_revision THEN RAISE EXCEPTION 'Dependency must be prepared for its pending proposal exact binding' USING ERRCODE='23514'; END IF;
  IF NEW.snapshot_id<>proposal.snapshot_id AND (NEW.snapshot_id IS DISTINCT FROM root_claim.observed_snapshot_id OR root_claim.applied_correspondence_revision IS DISTINCT FROM root_claim.correspondence_revision) THEN
    RAISE EXCEPTION 'Previous dependency evidence requires the same root correspondence and exact adopted snapshot' USING ERRCODE='23514';
  END IF;
  SELECT * INTO STRICT binding FROM public.catalog_source_binding_revision WHERE source_record_id=NEW.dependency_source_record_id AND mapping_key=NEW.dependency_mapping_key AND revision=NEW.dependency_binding_revision;
  IF (NEW.publishing_id,NEW.music_id,NEW.program_id,NEW.software_id,NEW.entity_id,NEW.grouping_id,NEW.reference_id,NEW.distribution_id)
    IS DISTINCT FROM (binding.publishing_id,binding.music_id,binding.program_id,binding.software_id,binding.entity_id,binding.grouping_id,binding.reference_id,binding.distribution_id) THEN
    RAISE EXCEPTION 'Dependency target must match its exact source binding' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS catalog_source_dependency_guard ON public.catalog_source_proposal_dependency;
CREATE TRIGGER catalog_source_dependency_guard BEFORE INSERT OR UPDATE OR DELETE ON public.catalog_source_proposal_dependency
FOR EACH ROW EXECUTE FUNCTION public.catalog_source_guard_dependency();


CREATE OR REPLACE FUNCTION public.catalog_guard_definition_term()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'Exact definition terms and their source evidence are immutable' USING ERRCODE = '23514';
  END IF;
  IF TG_TABLE_NAME = 'catalog_definition_term' AND NOT EXISTS (
    SELECT 1 FROM public.catalog_definition_revision r
    JOIN public.catalog_definition d ON d.id = r.definition_id
    WHERE r.id = NEW.definition_revision_id AND d.kind IN ('class', 'vocabulary')
  ) THEN
    RAISE EXCEPTION 'Only governed classes and vocabularies designate definition terms' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS catalog_definition_term_guard ON public.catalog_definition_term;
CREATE TRIGGER catalog_definition_term_guard BEFORE INSERT OR UPDATE OR DELETE ON public.catalog_definition_term
FOR EACH ROW EXECUTE FUNCTION public.catalog_guard_definition_term();

DROP TRIGGER IF EXISTS catalog_definition_term_support_guard ON public.catalog_definition_term_support;
CREATE TRIGGER catalog_definition_term_support_guard BEFORE UPDATE OR DELETE ON public.catalog_definition_term_support
FOR EACH ROW EXECUTE FUNCTION public.catalog_guard_definition_term();


CREATE OR REPLACE FUNCTION public.catalog_source_application_includes_epoch(source_id uuid, requested_proposal_id uuid, mapping_id uuid, epoch_revision bigint)
RETURNS boolean LANGUAGE sql STABLE SET search_path = pg_catalog, public AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.catalog_source_adoption_proposal p
    JOIN public.catalog_source_binding_revision r ON r.source_record_id=p.source_record_id AND r.mapping_key=p.mapping_key AND r.revision=p.expected_binding_revision
    WHERE p.source_record_id=source_id AND p.id=requested_proposal_id AND p.mapping_key=mapping_id AND r.correspondence_revision=epoch_revision
    UNION ALL
    SELECT 1 FROM public.catalog_source_application a
    WHERE a.source_record_id=source_id AND a.proposal_id=requested_proposal_id
      AND a.mapping_key=mapping_id AND a.action='apply' AND a.previous_correspondence_revision=epoch_revision
      AND a.previous_observed_snapshot_id IS NOT NULL
  )
$$;

CREATE OR REPLACE FUNCTION public.catalog_source_validate_application_change()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE history public.music_component_revision%ROWTYPE; application public.catalog_source_application%ROWTYPE; proposal_state text; after_sequence bigint;
BEGIN
  SELECT * INTO STRICT application FROM public.catalog_source_application WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action;
  SELECT state INTO STRICT proposal_state FROM public.catalog_source_adoption_proposal WHERE source_record_id=NEW.source_record_id AND id=NEW.proposal_id;
  IF NEW.position >= application.change_count OR (NEW.action='apply' AND proposal_state <> 'pending') OR (NEW.action='withdraw' AND proposal_state <> 'applied') THEN
    RAISE EXCEPTION 'Native change must belong to its in-progress application' USING ERRCODE = '23514';
  END IF;
  IF TG_ARGV[0] = 'music' THEN
    SELECT * INTO STRICT history FROM public.music_component_revision WHERE owner_id = NEW.owner_id AND id = NEW.after_revision_id;
    IF history.component <> NEW.component OR history.component_key <> NEW.component_key THEN
      RAISE EXCEPTION 'Music application history has a different component key' USING ERRCODE = '23514';
    END IF;
    after_sequence := history.component_sequence;
    IF NEW.before_revision_id IS NOT NULL THEN
      SELECT * INTO STRICT history FROM public.music_component_revision WHERE owner_id = NEW.owner_id AND id = NEW.before_revision_id;
      IF history.component <> NEW.component OR history.component_key <> NEW.component_key OR history.component_sequence >= after_sequence THEN
        RAISE EXCEPTION 'Music application before history has a different component or order' USING ERRCODE = '23514';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION public.catalog_source_require_application_complete()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE application public.catalog_source_application%ROWTYPE; proposal public.catalog_source_adoption_proposal%ROWTYPE;
  actual_count integer; unique_positions integer; first_position integer; last_position integer;
BEGIN
  SELECT * INTO STRICT application FROM public.catalog_source_application
    WHERE source_record_id = NEW.source_record_id AND proposal_id = NEW.proposal_id AND action = NEW.action;
  SELECT * INTO STRICT proposal FROM public.catalog_source_adoption_proposal
    WHERE source_record_id = NEW.source_record_id AND id = NEW.proposal_id;
  IF application.mapping_key <> proposal.mapping_key THEN RAISE EXCEPTION 'Native application must retain the exact proposal mapping' USING ERRCODE='23514'; END IF;
  IF application.previous_correspondence_revision IS NOT NULL AND NOT EXISTS(
    SELECT 1 FROM public.catalog_source_binding_revision b WHERE b.source_record_id=application.source_record_id AND b.mapping_key=application.mapping_key AND b.revision=application.previous_correspondence_revision AND b.correspondence_revision=b.revision
  ) THEN RAISE EXCEPTION 'Previous native source correspondence must reference an epoch anchor' USING ERRCODE='23514'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.catalog_source_binding_revision b WHERE b.source_record_id=proposal.source_record_id AND b.mapping_key=proposal.mapping_key AND b.revision=proposal.expected_binding_revision AND
    application.previous_snapshot_id IS NOT DISTINCT FROM CASE WHEN application.previous_correspondence_revision=b.correspondence_revision THEN application.previous_observed_snapshot_id ELSE NULL END
  ) THEN RAISE EXCEPTION 'Effective previous source snapshot must match the proposal correspondence epoch' USING ERRCODE='23514'; END IF;
  IF (application.action = 'apply' AND proposal.state NOT IN ('applied','withdrawn'))
    OR (application.action = 'withdraw' AND proposal.state <> 'withdrawn') THEN
    RAISE EXCEPTION 'Native application must commit its corresponding proposal decision' USING ERRCODE = '23514';
  END IF;
  SELECT count(*), count(DISTINCT position), min(position), max(position)
    INTO actual_count, unique_positions, first_position, last_position FROM (
      SELECT position FROM public.music_source_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.program_component_source_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.publishing_component_source_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.program_structure_source_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.publishing_structure_source_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.software_source_component_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.software_source_record_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.publishing_source_semantic_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.publishing_source_name_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.publishing_source_authority_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.music_source_semantic_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.music_source_name_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.music_source_authority_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.program_source_semantic_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.program_source_name_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.program_source_authority_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.software_source_semantic_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.software_source_name_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.software_source_authority_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.entity_source_semantic_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.entity_source_name_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.entity_source_authority_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.grouping_source_semantic_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.grouping_source_name_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.grouping_source_authority_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.reference_source_semantic_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.reference_source_name_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.reference_source_authority_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.distribution_source_semantic_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.distribution_source_name_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.distribution_source_authority_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.software_source_context_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.software_source_participation_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.entity_source_profile_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.reference_source_profile_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.publishing_source_identifier_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.music_source_identifier_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.program_source_identifier_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.software_source_identifier_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.entity_source_identifier_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.grouping_source_identifier_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.reference_source_identifier_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
      UNION ALL SELECT position FROM public.distribution_source_identifier_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action
    ) changes;
  IF actual_count <> application.change_count OR unique_positions <> actual_count
    OR (actual_count > 0 AND (first_position <> 0 OR last_position <> actual_count - 1)) THEN
    RAISE EXCEPTION 'Native application requires a complete contiguous change manifest' USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END $$;

DO $$
DECLARE relation_name text; physical record;
BEGIN
  FOREACH relation_name IN ARRAY ARRAY['catalog_source_application','music_source_application_change','software_source_component_application_change','software_source_record_application_change','publishing_source_semantic_application_change','publishing_source_name_application_change','publishing_source_authority_application_change','publishing_source_identifier_application_change','music_source_semantic_application_change','music_source_name_application_change','music_source_authority_application_change','music_source_identifier_application_change','program_source_semantic_application_change','program_source_name_application_change','program_source_authority_application_change','program_source_identifier_application_change','software_source_semantic_application_change','software_source_name_application_change','software_source_authority_application_change','software_source_identifier_application_change','entity_source_semantic_application_change','entity_source_name_application_change','entity_source_authority_application_change','entity_source_identifier_application_change','grouping_source_semantic_application_change','grouping_source_name_application_change','grouping_source_authority_application_change','grouping_source_identifier_application_change','reference_source_semantic_application_change','reference_source_name_application_change','reference_source_authority_application_change','reference_source_identifier_application_change','distribution_source_semantic_application_change','distribution_source_name_application_change','distribution_source_authority_application_change','distribution_source_identifier_application_change','software_source_context_application_change','software_source_participation_application_change','entity_source_profile_application_change','reference_source_profile_application_change'] LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS catalog_source_application_immutable ON public.%I', relation_name);
    EXECUTE format('CREATE TRIGGER catalog_source_application_immutable BEFORE UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.catalog_source_guard_immutable_evidence()', relation_name);
    IF relation_name NOT IN ('catalog_source_application','music_source_application_change') THEN
      EXECUTE format('DROP TRIGGER IF EXISTS catalog_source_application_change_guard ON public.%I', relation_name);
      EXECUTE format('CREATE TRIGGER catalog_source_application_change_guard BEFORE INSERT ON public.%I FOR EACH ROW EXECUTE FUNCTION public.catalog_source_validate_application_change()', relation_name);
    END IF;
  END LOOP;
  FOR physical IN
    WITH RECURSIVE roots AS (
      SELECT c.oid FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
      WHERE n.nspname='public' AND c.relname IN ('catalog_source_application','music_source_application_change','software_source_component_application_change','software_source_record_application_change','publishing_source_semantic_application_change','publishing_source_name_application_change','publishing_source_authority_application_change','publishing_source_identifier_application_change','music_source_semantic_application_change','music_source_name_application_change','music_source_authority_application_change','music_source_identifier_application_change','program_source_semantic_application_change','program_source_name_application_change','program_source_authority_application_change','program_source_identifier_application_change','software_source_semantic_application_change','software_source_name_application_change','software_source_authority_application_change','software_source_identifier_application_change','entity_source_semantic_application_change','entity_source_name_application_change','entity_source_authority_application_change','entity_source_identifier_application_change','grouping_source_semantic_application_change','grouping_source_name_application_change','grouping_source_authority_application_change','grouping_source_identifier_application_change','reference_source_semantic_application_change','reference_source_name_application_change','reference_source_authority_application_change','reference_source_identifier_application_change','distribution_source_semantic_application_change','distribution_source_name_application_change','distribution_source_authority_application_change','distribution_source_identifier_application_change','software_source_context_application_change','software_source_participation_application_change','entity_source_profile_application_change','reference_source_profile_application_change')
      UNION ALL SELECT i.inhrelid FROM pg_inherits i JOIN roots r ON r.oid=i.inhparent
    ) SELECT c.oid::regclass AS name, c.relname AS local_name FROM roots r JOIN pg_class c ON c.oid=r.oid WHERE c.relkind='r'
  LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS catalog_source_application_complete ON %s', physical.name);
    IF physical.local_name LIKE 'catalog_source_application%' THEN
      EXECUTE format('CREATE CONSTRAINT TRIGGER catalog_source_application_complete AFTER INSERT ON %s DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.catalog_source_require_application_complete()', physical.name);
    END IF;
  END LOOP;
END $$;
DROP TRIGGER IF EXISTS music_source_application_exact_component ON public.music_source_application_change;
CREATE TRIGGER music_source_application_exact_component BEFORE INSERT ON public.music_source_application_change
  FOR EACH ROW EXECUTE FUNCTION public.catalog_source_validate_application_change('music');

CREATE OR REPLACE FUNCTION public.catalog_source_guard_proposal()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Source proposal decisions are retained evidence' USING ERRCODE='23514'; END IF;
  IF (NEW.source_record_id,NEW.id,NEW.snapshot_id,NEW.mapping_key,NEW.mapping_owner,NEW.mapping_version,NEW.expected_target_revision,NEW.expected_binding_revision,NEW.expected_policy_revision,NEW.created_at)
    IS DISTINCT FROM (OLD.source_record_id,OLD.id,OLD.snapshot_id,OLD.mapping_key,OLD.mapping_owner,OLD.mapping_version,OLD.expected_target_revision,OLD.expected_binding_revision,OLD.expected_policy_revision,OLD.created_at)
    OR (NEW.proposer_auth_user_id IS DISTINCT FROM OLD.proposer_auth_user_id AND NEW.proposer_auth_user_id IS NOT NULL) THEN
    RAISE EXCEPTION 'Source proposal scope and preconditions are immutable' USING ERRCODE='23514';
  END IF;
  IF NEW.state = OLD.state THEN
    IF (NEW.decided_at,NEW.decision_reason,NEW.applied_target_revision) IS DISTINCT FROM (OLD.decided_at,OLD.decision_reason,OLD.applied_target_revision) THEN
      RAISE EXCEPTION 'Source proposal decisions are immutable without an allowed transition' USING ERRCODE='23514';
    END IF;
  ELSIF NOT ((OLD.state='pending' AND NEW.state IN ('applied','rejected','superseded')) OR (OLD.state='applied' AND NEW.state='withdrawn')) THEN
    RAISE EXCEPTION 'Source proposal transition is not allowed' USING ERRCODE='23514';
  END IF;
  IF NEW.state IN ('applied','withdrawn') AND NOT EXISTS (
    SELECT 1 FROM public.catalog_source_application WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.id
      AND action=CASE WHEN NEW.state='applied' THEN 'apply' ELSE 'withdraw' END AND after_revision=NEW.applied_target_revision
  ) THEN
    RAISE EXCEPTION 'Source proposal decision requires its exact native application' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS catalog_source_proposal_guard ON public.catalog_source_adoption_proposal;
CREATE TRIGGER catalog_source_proposal_guard BEFORE UPDATE OR DELETE ON public.catalog_source_adoption_proposal
  FOR EACH ROW EXECUTE FUNCTION public.catalog_source_guard_proposal();


-- A multipart snapshot is never accepted with a missing, duplicate or differently sized part set.
CREATE OR REPLACE FUNCTION public.catalog_source_bundle_check_parts()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$
DECLARE expected_count integer; expected_bytes integer; actual_count integer; actual_bytes integer; maximum_position integer; native_views integer;
BEGIN
 SELECT part_count,total_bytes INTO expected_count,expected_bytes FROM public.catalog_source_snapshot_bundle
  WHERE source_record_id=NEW.source_record_id AND snapshot_id=NEW.snapshot_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Multipart snapshot header is missing' USING ERRCODE='23514'; END IF;
 SELECT count(*),sum(byte_length),max(position),count(*) FILTER(WHERE kind='derived_view' AND key='native_view')
 INTO actual_count,actual_bytes,maximum_position,native_views FROM public.catalog_source_snapshot_part
  WHERE source_record_id=NEW.source_record_id AND snapshot_id=NEW.snapshot_id;
 IF actual_count<>expected_count OR actual_bytes<>expected_bytes OR maximum_position<>actual_count-1 OR native_views<>1 THEN
  RAISE EXCEPTION 'Multipart snapshot part set is incomplete' USING ERRCODE='23514';
 END IF;
 RETURN NULL;
END $$;
CREATE OR REPLACE FUNCTION public.catalog_source_bundle_immutable()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$
BEGIN RAISE EXCEPTION 'Archived multipart source evidence is immutable' USING ERRCODE='23514'; END $$;
DROP TRIGGER IF EXISTS catalog_source_bundle_parts_check ON public.catalog_source_snapshot_bundle;
CREATE CONSTRAINT TRIGGER catalog_source_bundle_parts_check AFTER INSERT ON public.catalog_source_snapshot_bundle DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.catalog_source_bundle_check_parts();
DROP TRIGGER IF EXISTS catalog_source_part_set_check ON public.catalog_source_snapshot_part;
CREATE CONSTRAINT TRIGGER catalog_source_part_set_check AFTER INSERT ON public.catalog_source_snapshot_part DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.catalog_source_bundle_check_parts();
DROP TRIGGER IF EXISTS catalog_source_bundle_immutable ON public.catalog_source_snapshot_bundle;
CREATE TRIGGER catalog_source_bundle_immutable BEFORE UPDATE OR DELETE ON public.catalog_source_snapshot_bundle FOR EACH ROW EXECUTE FUNCTION public.catalog_source_bundle_immutable();
DROP TRIGGER IF EXISTS catalog_source_part_immutable ON public.catalog_source_snapshot_part;
CREATE TRIGGER catalog_source_part_immutable BEFORE UPDATE OR DELETE ON public.catalog_source_snapshot_part FOR EACH ROW EXECUTE FUNCTION public.catalog_source_bundle_immutable();


CREATE OR REPLACE FUNCTION public.catalog_source_guard_owned_baseline() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE matched boolean; source_matched boolean; native_head bigint; source_epoch bigint;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Source/native baselines require reviewed retention, not ad hoc deletion' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'UPDATE' AND (NEW.source_record_id <> OLD.source_record_id OR NEW.mapping_key <> OLD.mapping_key OR NEW.correspondence_revision <> OLD.correspondence_revision OR NEW.owner_id <> OLD.owner_id OR to_jsonb(NEW)->'component_key' IS DISTINCT FROM to_jsonb(OLD)->'component_key' OR to_jsonb(NEW)->'component' IS DISTINCT FROM to_jsonb(OLD)->'component' OR to_jsonb(NEW)->'kind' IS DISTINCT FROM to_jsonb(OLD)->'kind') THEN
    RAISE EXCEPTION 'Source/native baseline identity is immutable' USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.catalog_source_adoption_proposal WHERE source_record_id=NEW.source_record_id AND id=NEW.last_proposal_id AND mapping_key=NEW.mapping_key) THEN
    RAISE EXCEPTION 'Baseline application belongs to another mapping' USING ERRCODE = '23514';
  END IF;
  SELECT r.correspondence_revision INTO STRICT source_epoch
  FROM public.catalog_source_adoption_proposal p JOIN public.catalog_source_binding_revision r
    ON r.source_record_id=p.source_record_id AND r.mapping_key=p.mapping_key AND r.revision=p.expected_binding_revision
  WHERE p.source_record_id=NEW.source_record_id AND p.id=NEW.last_proposal_id;
  IF NOT public.catalog_source_application_includes_epoch(NEW.source_record_id,NEW.last_proposal_id,NEW.mapping_key,NEW.correspondence_revision) OR NOT EXISTS (
    SELECT 1 FROM public.catalog_source_binding_revision WHERE source_record_id=NEW.source_record_id
      AND mapping_key=NEW.mapping_key AND revision=NEW.correspondence_revision AND owner=NEW.mapping_owner
  ) THEN RAISE EXCEPTION 'Baseline requires the proposal exact owner correspondence epoch' USING ERRCODE='23514'; END IF;
  source_epoch := NEW.correspondence_revision;
  IF TG_OP = 'UPDATE' AND NEW.current_revision <= OLD.current_revision THEN
    RAISE EXCEPTION 'Baseline native history must advance' USING ERRCODE = '23514';
  END IF;
  IF TG_ARGV[0] = 'owned' THEN
    EXECUTE format('SELECT EXISTS (SELECT 1 FROM public.%I WHERE source_record_id=$1 AND proposal_id=$2 AND action=$3 AND owner_id=$4 AND component_key=$5 AND after_revision=$6)', TG_ARGV[1] || CASE NEW.kind WHEN 'catalog-semantic' THEN '_source_semantic_application_change' WHEN 'catalog-name' THEN '_source_name_application_change' WHEN 'catalog-name-authority' THEN '_source_authority_application_change' WHEN 'catalog-identifier' THEN '_source_identifier_application_change' END)
      INTO matched USING NEW.source_record_id, NEW.last_proposal_id, NEW.last_action, NEW.owner_id, NEW.component_key, NEW.current_revision;
  ELSIF TG_ARGV[0] = 'record' THEN
    SELECT EXISTS (SELECT 1 FROM public.software_source_record_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.last_proposal_id AND action=NEW.last_action AND owner_id=NEW.owner_id AND after_revision=NEW.current_revision) INTO matched;
  ELSIF TG_ARGV[0] = 'component' THEN
    SELECT EXISTS (SELECT 1 FROM public.software_source_component_application_change WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.last_proposal_id AND action=NEW.last_action AND owner_id=NEW.owner_id AND component=NEW.component AND component_key=NEW.component_key AND after_revision=NEW.current_revision) INTO matched;
  ELSE
    EXECUTE format('SELECT EXISTS (SELECT 1 FROM public.%I WHERE source_record_id=$1 AND proposal_id=$2 AND action=$3 AND owner_id=$4 AND component_key=$5 AND after_revision=$6)', 'software_source_' || TG_ARGV[0] || '_application_change')
      INTO matched USING NEW.source_record_id, NEW.last_proposal_id, NEW.last_action, NEW.owner_id, NEW.component_key, NEW.current_revision;
  END IF;
  IF NOT matched THEN RAISE EXCEPTION 'Baseline current head is not backed by its exact native application' USING ERRCODE = '23514'; END IF;
  IF TG_ARGV[0] = 'owned' THEN
    IF NEW.kind = 'catalog-name' THEN
    EXECUTE format('SELECT EXISTS (SELECT 1 FROM public.%I WHERE source_record_id=$1 AND snapshot_id=$2 AND owner_id=$3 AND name_id=$4 AND name_revision=$5 AND source_path=$6 AND mapping_key=$7 AND correspondence_revision=$8)', TG_ARGV[1] || '_name_source_occurrence') INTO source_matched USING NEW.source_record_id,NEW.source_snapshot_id,NEW.owner_id,NEW.component_key,NEW.source_revision,NEW.source_path,NEW.mapping_key,source_epoch;
    ELSIF NEW.kind = 'catalog-identifier' THEN
    EXECUTE format('SELECT EXISTS (SELECT 1 FROM public.%I WHERE source_record_id=$1 AND snapshot_id=$2 AND owner_id=$3 AND identifier_id=$4 AND identifier_revision=$5 AND source_path=$6 AND source_mapping_key=$7 AND source_correspondence_revision=$8)', TG_ARGV[1] || '_fact_support') INTO source_matched USING NEW.source_record_id,NEW.source_snapshot_id,NEW.owner_id,NEW.component_key,NEW.source_revision,NEW.source_path,NEW.mapping_key,source_epoch;
    ELSIF NEW.kind = 'catalog-name-authority' THEN
    EXECUTE format('SELECT EXISTS (SELECT 1 FROM public.%I a JOIN public.%I b ON b.owner_id=a.owner_id AND b.name_id=a.name_id WHERE a.source_record_id=$1 AND a.snapshot_id=$2 AND a.owner_id=$3 AND a.id=$4 AND a.revision=$5 AND a.source_path=$6 AND b.source_record_id=$1 AND b.mapping_key=$7 AND b.correspondence_revision=$8)', TG_ARGV[1] || '_name_authority_revision', TG_ARGV[1] || '_name_source_binding') INTO source_matched USING NEW.source_record_id,NEW.source_snapshot_id,NEW.owner_id,NEW.component_key,NEW.source_revision,NEW.source_path,NEW.mapping_key,source_epoch;
    ELSE
    EXECUTE format('SELECT EXISTS (SELECT 1 FROM public.%I s JOIN public.%I v ON v.owner_id=s.owner_id AND v.id=s.fact_id WHERE s.source_record_id=$1 AND s.snapshot_id=$2 AND s.owner_id=$3 AND v.semantic_id=$4 AND v.expected_head_version+1=$5 AND s.source_path=$6 AND s.source_mapping_key=$7 AND s.source_correspondence_revision=$8 UNION ALL SELECT 1 FROM public.%I s JOIN public.%I v ON v.owner_id=s.owner_id AND v.id=s.relation_id WHERE s.source_record_id=$1 AND s.snapshot_id=$2 AND s.owner_id=$3 AND v.semantic_id=$4 AND v.expected_head_version+1=$5 AND s.source_path=$6 AND s.source_mapping_key=$7 AND s.source_correspondence_revision=$8)', TG_ARGV[1] || '_fact_support',TG_ARGV[1] || '_fact',TG_ARGV[1] || '_fact_support',TG_ARGV[1] || '_catalog_relation') INTO source_matched USING NEW.source_record_id,NEW.source_snapshot_id,NEW.owner_id,NEW.component_key,NEW.source_revision,NEW.source_path,NEW.mapping_key,source_epoch;
    END IF;
  ELSIF TG_ARGV[0] = 'record' THEN
    SELECT EXISTS (SELECT 1 FROM public.software_record_source_occurrence WHERE source_record_id=NEW.source_record_id AND snapshot_id=NEW.source_snapshot_id AND owner_id=NEW.owner_id AND revision=NEW.source_revision AND source_path=NEW.source_path AND mapping_key=NEW.mapping_key AND correspondence_revision=source_epoch) INTO source_matched;
  ELSIF TG_ARGV[0] = 'component' THEN
    SELECT EXISTS (SELECT 1 FROM public.software_component_source_occurrence WHERE source_record_id=NEW.source_record_id AND snapshot_id=NEW.source_snapshot_id AND owner_id=NEW.owner_id AND component=NEW.component AND component_key=NEW.component_key AND revision=NEW.source_revision AND source_path=NEW.source_path AND mapping_key=NEW.mapping_key AND correspondence_revision=source_epoch) INTO source_matched;
  ELSIF TG_ARGV[0] = 'context' THEN
    SELECT EXISTS (SELECT 1 FROM public.software_participation_source_occurrence WHERE source_record_id=NEW.source_record_id AND snapshot_id=NEW.source_snapshot_id AND content_id=NEW.owner_id AND context_id=NEW.component_key AND context_revision=NEW.source_revision AND source_pointer=NEW.source_path AND mapping_key=NEW.mapping_key AND correspondence_revision=source_epoch) INTO source_matched;
  ELSE
    SELECT EXISTS (SELECT 1 FROM public.software_participation_credit_source_occurrence WHERE source_record_id=NEW.source_record_id AND snapshot_id=NEW.source_snapshot_id AND content_id=NEW.owner_id AND participation_id=NEW.component_key AND participation_revision=NEW.source_revision AND source_path=NEW.source_path AND mapping_key=NEW.mapping_key AND correspondence_revision=source_epoch) INTO source_matched;
  END IF;
  IF NOT source_matched THEN RAISE EXCEPTION 'Baseline originating history is not backed by its exact source occurrence' USING ERRCODE = '23514'; END IF;
  IF TG_ARGV[0] = 'owned' THEN
    EXECUTE format('SELECT %I FROM public.%I WHERE owner_id=$1 AND %I=$2', CASE NEW.kind WHEN 'catalog-semantic' THEN 'version' ELSE 'revision' END, TG_ARGV[1] || CASE NEW.kind WHEN 'catalog-semantic' THEN '_semantic_head' WHEN 'catalog-name' THEN '_named_form' WHEN 'catalog-name-authority' THEN '_name_authority' WHEN 'catalog-identifier' THEN '_identifier_claim' END, CASE NEW.kind WHEN 'catalog-semantic' THEN 'semantic_id' ELSE 'id' END) INTO native_head USING NEW.owner_id,NEW.component_key;
  ELSIF TG_ARGV[0] = 'component' THEN
    SELECT revision INTO native_head FROM public.software_component_revision WHERE release_id=NEW.owner_id AND kind=NEW.component AND component_id=NEW.component_key ORDER BY revision DESC LIMIT 1;
  ELSIF TG_ARGV[0] = 'record' THEN
    SELECT revision INTO native_head FROM public.software_record_revision WHERE owner_id=NEW.owner_id ORDER BY revision DESC LIMIT 1;
  ELSE
    EXECUTE format('SELECT current_revision FROM public.%I WHERE content_id=$1 AND id=$2', CASE TG_ARGV[0] WHEN 'context' THEN 'software_participation_context' ELSE 'software_participation' END) INTO native_head USING NEW.owner_id,NEW.component_key;
  END IF;
  IF native_head IS DISTINCT FROM NEW.current_revision THEN RAISE EXCEPTION 'Baseline native history is no longer current' USING ERRCODE = '23514'; END IF;
  RETURN NEW;
END $$;
DO $$
DECLARE owner_name text; child text;
BEGIN
  FOREACH owner_name IN ARRAY ARRAY['publishing','music','program','software','entity','grouping','reference','distribution'] LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS catalog_source_baseline_guard ON public.%I', owner_name || '_source_owned_baseline');
    EXECUTE format('CREATE TRIGGER catalog_source_baseline_guard BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.catalog_source_guard_owned_baseline(%L,%L)', owner_name || '_source_owned_baseline', 'owned', owner_name);
  END LOOP;
  FOREACH child IN ARRAY ARRAY['record','component','context','participation'] LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS catalog_source_baseline_guard ON public.%I', 'software_source_' || child || '_baseline');
    EXECUTE format('CREATE TRIGGER catalog_source_baseline_guard BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.catalog_source_guard_owned_baseline(%L)', 'software_source_' || child || '_baseline', child);
  END LOOP;
  FOREACH child IN ARRAY ARRAY['software_component_source_occurrence','software_record_source_occurrence'] LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS software_source_occurrence_immutable ON public.%I', child);
    EXECUTE format('CREATE TRIGGER software_source_occurrence_immutable BEFORE UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.catalog_source_guard_immutable_evidence()', child);
  END LOOP;
END $$;


CREATE OR REPLACE FUNCTION public.catalog_validate_profile_source()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE native_snapshot jsonb; expected_keys text[]; field_name text; field_value jsonb; date_part text; date_year integer; date_month integer; date_day integer; maximum_day integer;
BEGIN
  EXECUTE format('SELECT snapshot FROM public.%I WHERE owner_id=$1 AND revision=$2 AND NOT removed',TG_ARGV[0] || '_catalog_profile_revision') INTO native_snapshot USING NEW.owner_id,NEW.revision;
  IF native_snapshot IS NULL THEN RAISE EXCEPTION 'Profile source occurrence requires exact present native history' USING ERRCODE='23514'; END IF;
  IF TG_ARGV[0]='entity' THEN
    expected_keys := ARRAY['typeRevisionId','genderRevisionId','areaId','beginAreaId','endAreaId','begin','end','ended'];
  ELSE
    IF NEW.source_profile->>'shape' IS DISTINCT FROM native_snapshot->>'shape' THEN
      RAISE EXCEPTION 'Source profile cannot reclassify its native history' USING ERRCODE='23514';
    END IF;
    expected_keys := CASE NEW.source_profile->>'shape'
      WHEN 'concept' THEN ARRAY['shape','typeRevisionId']
      WHEN 'instrument' THEN ARRAY['shape','typeRevisionId']
      WHEN 'web_resource' THEN ARRAY['shape','url']
      WHEN 'area' THEN ARRAY['shape','typeRevisionId','begin','end','ended']
      WHEN 'place' THEN ARRAY['shape','typeRevisionId','begin','end','ended','areaId','address','latitude','longitude']
      WHEN 'event' THEN ARRAY['shape','typeRevisionId','placeId','begin','end','localTime','cancelled','ended','setlist']
      ELSE NULL END;
  END IF;
  IF expected_keys IS NULL OR jsonb_typeof(NEW.source_profile) IS DISTINCT FROM 'object'
    OR NOT (NEW.source_profile ?& expected_keys) OR NEW.source_profile - expected_keys <> '{}'::jsonb
    OR array_position(NEW.observed_fields,NULL) IS NOT NULL
    OR coalesce(array_ndims(NEW.observed_fields),1) <> 1
    OR cardinality(NEW.observed_fields) <> (SELECT count(DISTINCT f) FROM unnest(NEW.observed_fields) f)
    OR NOT (NEW.observed_fields <@ expected_keys)
  THEN RAISE EXCEPTION 'Source profile has an unknown shape, field or observation scope' USING ERRCODE='23514'; END IF;
  FOR field_name,field_value IN SELECT key,value FROM jsonb_each(NEW.source_profile) LOOP
    IF field_name <> 'shape' AND NOT (field_name=ANY(NEW.observed_fields)) AND field_value<>'null'::jsonb THEN
      RAISE EXCEPTION 'Unobserved profile fields cannot retain native or human values' USING ERRCODE='23514';
    END IF;
    IF field_value='null'::jsonb THEN
      IF field_name IN ('shape','url') THEN RAISE EXCEPTION 'Source profile requires its native discriminator/resource' USING ERRCODE='23514'; END IF;
      CONTINUE;
    END IF;
    IF field_name ~ 'Id$' THEN
      IF jsonb_typeof(field_value)<>'string' THEN RAISE EXCEPTION 'Source profile reference must be a UUID' USING ERRCODE='23514'; END IF;
      PERFORM (field_value #>> '{}')::uuid;
    ELSIF field_name IN ('ended','cancelled') THEN
      IF jsonb_typeof(field_value)<>'boolean' THEN RAISE EXCEPTION 'Source profile flag must be boolean' USING ERRCODE='23514'; END IF;
    ELSIF field_name IN ('latitude','longitude') THEN
      IF jsonb_typeof(field_value)<>'number' OR abs((field_value #>> '{}')::numeric) > (CASE field_name WHEN 'latitude' THEN 90 ELSE 180 END) THEN
        RAISE EXCEPTION 'Source profile coordinate is invalid' USING ERRCODE='23514';
      END IF;
    ELSIF field_name IN ('begin','end') THEN
      IF jsonb_typeof(field_value)<>'object' OR NOT (field_value ?& ARRAY['year','month','day','text']) OR field_value - ARRAY['year','month','day','text'] <> '{}'::jsonb
        OR jsonb_typeof(field_value->'text') NOT IN ('null','string') THEN
        RAISE EXCEPTION 'Source profile partial date is invalid' USING ERRCODE='23514';
      END IF;
      FOREACH date_part IN ARRAY ARRAY['year','month','day'] LOOP
        IF field_value->date_part <> 'null'::jsonb AND (jsonb_typeof(field_value->date_part)<>'number' OR (field_value->>date_part)::numeric <> trunc((field_value->>date_part)::numeric)) THEN
          RAISE EXCEPTION 'Source profile date part must be an integer' USING ERRCODE='23514';
        END IF;
      END LOOP;
      date_year := (field_value->>'year')::integer; date_month := (field_value->>'month')::integer; date_day := (field_value->>'day')::integer;
      maximum_day := CASE WHEN date_month=2 THEN CASE WHEN date_year IS NULL OR date_year%400=0 OR (date_year%4=0 AND date_year%100<>0) THEN 29 ELSE 28 END WHEN date_month IN (4,6,9,11) THEN 30 ELSE 31 END;
      IF date_month NOT BETWEEN 1 AND 12 OR date_day NOT BETWEEN 1 AND maximum_day OR octet_length(field_value->>'text')>4096 THEN
        RAISE EXCEPTION 'Source profile date precision is invalid' USING ERRCODE='23514';
      END IF;
    ELSE
      IF jsonb_typeof(field_value)<>'string' THEN RAISE EXCEPTION 'Source profile text must be a string' USING ERRCODE='23514'; END IF;
      IF (field_name='url' AND ((field_value #>> '{}') !~ '^[A-Za-z][A-Za-z0-9+.-]*:' OR octet_length(field_value #>> '{}')>8192))
        OR (field_name='localTime' AND (field_value #>> '{}') !~ '^([01][0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9](\.[0-9]{1,6})?)?$')
        OR (field_name='address' AND octet_length(field_value #>> '{}')>16384)
        OR (field_name='setlist' AND octet_length(field_value #>> '{}')>65536)
      THEN RAISE EXCEPTION 'Source profile text violates its native field contract' USING ERRCODE='23514'; END IF;
    END IF;
  END LOOP;
  IF NEW.source_profile->>'shape'='place' AND (NEW.source_profile->'latitude'='null'::jsonb) IS DISTINCT FROM (NEW.source_profile->'longitude'='null'::jsonb) THEN
    RAISE EXCEPTION 'Source profile coordinates must be paired' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION public.catalog_validate_profile_baseline()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE valid boolean; current_revision bigint;
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Profile source baselines are retained correspondence' USING ERRCODE='23514'; END IF;
  IF TG_OP='UPDATE' AND (OLD.source_record_id,OLD.mapping_key,OLD.correspondence_revision,OLD.mapping_owner,OLD.owner_id) IS DISTINCT FROM (NEW.source_record_id,NEW.mapping_key,NEW.correspondence_revision,NEW.mapping_owner,NEW.owner_id) THEN
    RAISE EXCEPTION 'Profile source baseline identity is immutable' USING ERRCODE='23514';
  END IF;
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE source_record_id=$1 AND snapshot_id=$2 AND owner_id=$3 AND source_path=$4 AND revision=$5 AND mapping_key=$6 AND correspondence_revision=$7)',TG_ARGV[0] || '_profile_source_occurrence') INTO valid USING NEW.source_record_id,NEW.source_snapshot_id,NEW.owner_id,NEW.source_path,NEW.source_revision,NEW.mapping_key,NEW.correspondence_revision;
  IF NOT valid THEN RAISE EXCEPTION 'Profile baseline requires exact immutable source occurrence' USING ERRCODE='23514'; END IF;
  EXECUTE format('SELECT revision FROM public.%I WHERE owner_id=$1 ORDER BY revision DESC LIMIT 1',TG_ARGV[0] || '_catalog_profile_revision') INTO current_revision USING NEW.owner_id;
  IF current_revision IS DISTINCT FROM NEW.current_revision THEN RAISE EXCEPTION 'Profile baseline must identify the current native profile head' USING ERRCODE='23514'; END IF;
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I c JOIN public.catalog_source_adoption_proposal p ON p.source_record_id=c.source_record_id AND p.id=c.proposal_id WHERE c.source_record_id=$1 AND c.proposal_id=$2 AND c.action=$3 AND c.owner_id=$4 AND c.after_revision=$5 AND p.mapping_key=$6)',TG_ARGV[0] || '_source_profile_application_change') INTO valid USING NEW.source_record_id,NEW.last_proposal_id,NEW.last_action,NEW.owner_id,NEW.current_revision,NEW.mapping_key;
  IF NOT valid THEN RAISE EXCEPTION 'Profile baseline requires its exact native application' USING ERRCODE='23514'; END IF;
  IF NOT public.catalog_source_application_includes_epoch(NEW.source_record_id,NEW.last_proposal_id,NEW.mapping_key,NEW.correspondence_revision) OR NOT EXISTS (
    SELECT 1 FROM public.catalog_source_binding_revision r WHERE r.source_record_id=NEW.source_record_id AND r.mapping_key=NEW.mapping_key AND r.revision=NEW.correspondence_revision AND r.owner=NEW.mapping_owner)
  THEN RAISE EXCEPTION 'Profile baseline requires its proposal owner correspondence epoch' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;

DO $$ DECLARE owner_name text;
BEGIN
  FOREACH owner_name IN ARRAY ARRAY['entity','reference'] LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS catalog_profile_source_immutable ON public.%I',owner_name || '_profile_source_occurrence');
    EXECUTE format('CREATE TRIGGER catalog_profile_source_immutable BEFORE UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.catalog_source_guard_immutable_evidence()',owner_name || '_profile_source_occurrence');
    EXECUTE format('DROP TRIGGER IF EXISTS catalog_profile_source_exact ON public.%I',owner_name || '_profile_source_occurrence');
    EXECUTE format('CREATE TRIGGER catalog_profile_source_exact BEFORE INSERT ON public.%I FOR EACH ROW EXECUTE FUNCTION public.catalog_validate_profile_source(%L)',owner_name || '_profile_source_occurrence',owner_name);
    EXECUTE format('DROP TRIGGER IF EXISTS catalog_profile_baseline_exact ON public.%I',owner_name || '_source_profile_baseline');
    EXECUTE format('CREATE TRIGGER catalog_profile_baseline_exact BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.catalog_validate_profile_baseline(%L)',owner_name || '_source_profile_baseline',owner_name);
  END LOOP;
END $$;


CREATE OR REPLACE FUNCTION public.catalog_capture_structure_revision()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE body jsonb; native_owner uuid; native_revision bigint; component_key text := ''; ordinal integer; next_sequence bigint; history_key uuid;
BEGIN
  body := CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
  native_owner := (body ->> TG_ARGV[1])::uuid;
  IF TG_OP='UPDATE' THEN
    FOR ordinal IN 1..TG_NARGS-1 LOOP
      IF (to_jsonb(OLD)->TG_ARGV[ordinal]) IS DISTINCT FROM (body->TG_ARGV[ordinal]) THEN
        RAISE EXCEPTION 'Structural component identity and owner are immutable' USING ERRCODE='23514';
      END IF;
    END LOOP;
  END IF;
  EXECUTE format('SELECT revision FROM public.%I WHERE id=$1', TG_ARGV[0] || '_identity') INTO STRICT native_revision USING native_owner;
  FOR ordinal IN 2..TG_NARGS-1 LOOP
    component_key := component_key || CASE WHEN ordinal=2 THEN '' ELSE '/' END || replace(replace(body->>TG_ARGV[ordinal], '~', '~0'), '/', '~1');
  END LOOP;
  EXECUTE format('SELECT component_sequence FROM public.%I WHERE owner_id=$1 AND component=$2 AND component_key=$3 FOR UPDATE',TG_ARGV[0] || '_component_head') INTO next_sequence USING native_owner,TG_TABLE_NAME,component_key;
  next_sequence := coalesce(next_sequence,0) + 1;
  EXECUTE format('INSERT INTO public.%I(owner_id,component,component_key,component_sequence,owner_revision,operation,value) VALUES($1,$2,$3,$4,$5,$6,$7) RETURNING id',TG_ARGV[0] || '_component_revision') INTO history_key USING native_owner,TG_TABLE_NAME,component_key,next_sequence,native_revision,TG_OP,body;
  IF next_sequence=1 THEN
    EXECUTE format('INSERT INTO public.%I(owner_id,component,component_key,component_sequence,history_id) VALUES($1,$2,$3,$4,$5)',TG_ARGV[0] || '_component_head') USING native_owner,TG_TABLE_NAME,component_key,next_sequence,history_key;
  ELSE
    EXECUTE format('UPDATE public.%I SET component_sequence=$4,history_id=$5 WHERE owner_id=$1 AND component=$2 AND component_key=$3',TG_ARGV[0] || '_component_head') USING native_owner,TG_TABLE_NAME,component_key,next_sequence,history_key;
  END IF;
  RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;

CREATE OR REPLACE FUNCTION public.catalog_guard_structure_head()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE valid boolean;
BEGIN
  IF TG_OP='DELETE' OR pg_trigger_depth()<2 THEN RAISE EXCEPTION 'Structural heads are maintained by native history capture' USING ERRCODE='23514'; END IF;
  IF TG_OP='INSERT' AND NEW.component_sequence<>1 THEN RAISE EXCEPTION 'Structural sequence must start at one' USING ERRCODE='23514'; END IF;
  IF TG_OP='UPDATE' AND ((OLD.owner_id,OLD.component,OLD.component_key) IS DISTINCT FROM (NEW.owner_id,NEW.component,NEW.component_key) OR NEW.component_sequence<>OLD.component_sequence+1) THEN RAISE EXCEPTION 'Structural sequence must advance exactly once' USING ERRCODE='23514'; END IF;
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE owner_id=$1 AND id=$2 AND component=$3 AND component_key=$4 AND component_sequence=$5)', TG_ARGV[0] || '_component_revision') INTO valid USING NEW.owner_id,NEW.history_id,NEW.component,NEW.component_key,NEW.component_sequence;
  IF NOT valid THEN RAISE EXCEPTION 'Structural head requires exact immutable history' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION public.catalog_guard_structure_revision_insert()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
BEGIN
  IF pg_trigger_depth()<2 THEN RAISE EXCEPTION 'Structural history is captured from native rows' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION public.catalog_guard_structure_history()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
BEGIN
  RAISE EXCEPTION 'Native structural history and source evidence are immutable' USING ERRCODE='23514';
END $$;

CREATE OR REPLACE FUNCTION public.catalog_validate_structure_source()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE valid boolean;
BEGIN
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE owner_id=$1 AND id=$2 AND component=$3 AND component_key=$4 AND operation <> ''DELETE'')',TG_ARGV[0] || '_component_revision') INTO valid USING NEW.owner_id,NEW.history_id,NEW.component,NEW.component_key;
  IF NOT valid THEN RAISE EXCEPTION 'Structural source support requires the exact native component history' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;

DO $$
DECLARE row record; owner_name text; relation_name text;
BEGIN
  FOR row IN SELECT * FROM (VALUES
    ('program','program_work','id','id'),('program','program_season','id','id'),('program','program_version','id','id'),('program','program_episode','id','id'),('program','program_episode_occurrence','owner_id','id'),
    ('publishing','publishing_work','id','id'),('publishing','publishing_text_version','id','id'),('publishing','publishing_publication','id','id'),('publishing','publishing_serialization','id','id'),
    ('publishing','publishing_text_work','text_version_id','work_id'),('publishing','publishing_publication_text','publication_id','text_version_id'),('publishing','publishing_publication_work','publication_id','work_id'),('publishing','publishing_publication_facet','publication_id','definition_revision_id'),
    ('publishing','publishing_release_event','publication_id','id'),('publishing','publishing_installment','serialization_id','id')
  ) values(owner_name,table_name,owner_column,key_column) LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS catalog_capture_structure_revision ON public.%I',row.table_name);
    EXECUTE format('CREATE TRIGGER catalog_capture_structure_revision AFTER INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.catalog_capture_structure_revision(%L,%L,%L)',row.table_name,row.owner_name,row.owner_column,row.key_column);
  END LOOP;
  FOREACH owner_name IN ARRAY ARRAY['program','publishing'] LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS catalog_structure_head_maintained ON public.%I',owner_name || '_component_head');
    EXECUTE format('CREATE TRIGGER catalog_structure_head_maintained BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.catalog_guard_structure_head(%L)',owner_name || '_component_head',owner_name);
    EXECUTE format('DROP TRIGGER IF EXISTS catalog_structure_revision_capture_only ON public.%I',owner_name || '_component_revision');
    EXECUTE format('CREATE TRIGGER catalog_structure_revision_capture_only BEFORE INSERT ON public.%I FOR EACH ROW EXECUTE FUNCTION public.catalog_guard_structure_revision_insert()',owner_name || '_component_revision');
    FOREACH relation_name IN ARRAY ARRAY[owner_name || '_component_revision',owner_name || '_component_source_occurrence'] LOOP
      EXECUTE format('DROP TRIGGER IF EXISTS catalog_structure_history_immutable ON public.%I',relation_name);
      EXECUTE format('CREATE TRIGGER catalog_structure_history_immutable BEFORE UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.catalog_guard_structure_history()',relation_name);
    END LOOP;
    EXECUTE format('DROP TRIGGER IF EXISTS catalog_structure_source_exact ON public.%I',owner_name || '_component_source_occurrence');
    EXECUTE format('CREATE TRIGGER catalog_structure_source_exact BEFORE INSERT ON public.%I FOR EACH ROW EXECUTE FUNCTION public.catalog_validate_structure_source(%L)',owner_name || '_component_source_occurrence',owner_name);
  END LOOP;
END $$;


CREATE OR REPLACE FUNCTION public.catalog_child_source_projection_valid(component_name text, source_value jsonb, observed_fields text[])
RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path = pg_catalog, public AS $$
DECLARE shape_name text; allowed text[]; uuids text[] := '{}'; integers text[] := '{}'; numbers text[] := '{}'; strings text[] := '{}'; fields jsonb; field_name text; scalar jsonb; numeric_value numeric; yr numeric; mon numeric; dy numeric; maximum_day integer;
BEGIN
  CASE component_name
    WHEN 'program_episode_occurrence' THEN shape_name:='episode_occurrence'; uuids:=ARRAY['episodeId']; strings:=ARRAY['position','sourceNumber'];
    WHEN 'publishing_text_work' THEN shape_name:='text_work'; uuids:=ARRAY['targetId']; integers:=ARRAY['position']; strings:=ARRAY['coverageText'];
    WHEN 'publishing_publication_text' THEN shape_name:='publication_text'; uuids:=ARRAY['targetId']; integers:=ARRAY['position']; strings:=ARRAY['coverageText'];
    WHEN 'publishing_publication_work' THEN shape_name:='publication_work'; uuids:=ARRAY['targetId']; integers:=ARRAY['position']; strings:=ARRAY['coverageText'];
    WHEN 'publishing_publication_facet' THEN shape_name:='facet'; uuids:=ARRAY['definitionRevisionId'];
    WHEN 'publishing_release_event' THEN shape_name:='event'; uuids:=ARRAY['publisherEntityId','areaId']; strings:=ARRAY['publisherCredit','dateText'];
    WHEN 'publishing_installment' THEN shape_name:='installment'; uuids:=ARRAY['parentId','kindRevisionId']; strings:=ARRAY['position','label','dateText'];
    ELSE RETURN false;
  END CASE;
  IF source_value IS NULL OR jsonb_typeof(source_value) IS DISTINCT FROM 'object' OR source_value->>'kind' IS DISTINCT FROM shape_name
    OR source_value-'kind'-'fields'<>'{}'::jsonb OR jsonb_typeof(source_value->'fields') IS DISTINCT FROM 'object' THEN RETURN false; END IF;
  fields:=source_value->'fields'; allowed:=uuids||integers||numbers||strings;
  IF component_name IN ('publishing_release_event','publishing_installment') THEN allowed:=allowed||ARRAY['date']; END IF;
  IF NOT fields ?& allowed OR fields-allowed<>'{}'::jsonb OR observed_fields IS NULL OR cardinality(observed_fields)>32
    OR NOT observed_fields<@allowed OR (SELECT count(*)<>count(DISTINCT k) FROM unnest(observed_fields) k) THEN RETURN false; END IF;
  FOREACH field_name IN ARRAY allowed LOOP
    scalar:=fields->field_name;
    IF NOT field_name=ANY(observed_fields) THEN
      IF field_name='date' THEN
        IF scalar<>'{"year":null,"month":null,"day":null}'::jsonb THEN RETURN false; END IF;
      ELSIF scalar<>'null'::jsonb THEN RETURN false; END IF;
    END IF;
    IF scalar='null'::jsonb THEN
      IF field_name='date' THEN RETURN false; END IF;
      CONTINUE;
    END IF;
    IF field_name=ANY(uuids) THEN
      IF jsonb_typeof(scalar)<>'string' OR fields->>field_name !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RETURN false; END IF;
    ELSIF field_name=ANY(integers) OR field_name=ANY(numbers) THEN
      IF jsonb_typeof(scalar)<>'number' THEN RETURN false; END IF;
      numeric_value:=(fields->>field_name)::numeric;
      IF field_name=ANY(integers) AND (numeric_value<0 OR numeric_value>9007199254740991 OR trunc(numeric_value)<>numeric_value) THEN RETURN false; END IF;
      IF abs(numeric_value)>1.7976931348623157e308::numeric THEN RETURN false; END IF;
    ELSIF field_name=ANY(strings) THEN
      IF jsonb_typeof(scalar)<>'string' OR char_length(fields->>field_name)>(CASE WHEN field_name IN('sourceNumber','dateText') THEN 4096 WHEN field_name='position' THEN 512 ELSE 131072 END) THEN RETURN false; END IF;
    ELSE
      IF jsonb_typeof(scalar)<>'object' OR NOT scalar ?& ARRAY['year','month','day'] OR scalar-'year'-'month'-'day'<>'{}'::jsonb THEN RETURN false; END IF;
      IF EXISTS(SELECT 1 FROM jsonb_each(scalar) f WHERE jsonb_typeof(f.value) NOT IN ('number','null')) THEN RETURN false; END IF;
      yr:=(scalar->>'year')::numeric; mon:=(scalar->>'month')::numeric; dy:=(scalar->>'day')::numeric;
      IF yr IS NOT NULL AND (yr<>trunc(yr) OR yr NOT BETWEEN -2147483648 AND 2147483647) THEN RETURN false; END IF;
      IF mon IS NOT NULL AND (mon<>trunc(mon) OR mon NOT BETWEEN 1 AND 12) THEN RETURN false; END IF;
      IF dy IS NOT NULL AND (dy<>trunc(dy) OR dy NOT BETWEEN 1 AND 31) THEN RETURN false; END IF;
      IF mon IS NOT NULL AND dy IS NOT NULL THEN
        maximum_day:=CASE WHEN mon=2 THEN CASE WHEN yr IS NULL OR mod(yr,400)=0 OR (mod(yr,4)=0 AND mod(yr,100)<>0) THEN 29 ELSE 28 END WHEN mon IN(4,6,9,11) THEN 30 ELSE 31 END;
        IF dy>maximum_day THEN RETURN false; END IF;
      END IF;
    END IF;
  END LOOP;
  RETURN true;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN false;
END $$;

CREATE OR REPLACE FUNCTION public.catalog_child_source_guard_occurrence()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE root public.catalog_source_binding_revision%ROWTYPE; native record; shape_name text; parent_id uuid; source_definition_id uuid; field_name text; expected_shape text;
BEGIN
  IF TG_ARGV[0] NOT IN ('program','publishing') OR NEW.component NOT LIKE TG_ARGV[0]||'_%' OR NEW.component_key !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    OR NOT public.catalog_child_source_projection_valid(NEW.component,NEW.source_value,NEW.observed_fields) THEN
    RAISE EXCEPTION 'Child source projection must contain only typed observed values' USING ERRCODE='23514';
  END IF;
  SELECT * INTO STRICT root FROM public.catalog_source_binding_revision WHERE source_record_id=NEW.source_record_id AND mapping_key=NEW.mapping_key AND revision=NEW.correspondence_revision;
  IF root.correspondence_revision<>root.revision OR root.owner<>NEW.mapping_owner THEN RAISE EXCEPTION 'Child source requires its exact root correspondence epoch' USING ERRCODE='23514'; END IF;
  EXECUTE format('SELECT component,component_key,operation FROM public.%I WHERE owner_id=$1 AND id=$2',TG_ARGV[0]||'_component_revision') INTO STRICT native USING NEW.owner_id,NEW.history_id;
  IF native.component<>NEW.component OR native.component_key<>NEW.component_key OR native.operation='DELETE' THEN RAISE EXCEPTION 'Child source history belongs to another native component' USING ERRCODE='23514'; END IF;
  field_name:=CASE WHEN TG_ARGV[0]='program' THEN 'episodeId' ELSE 'targetId' END;
  parent_id:=(NEW.source_value->'fields'->>field_name)::uuid;
  IF parent_id IS NOT NULL THEN
    expected_shape:=CASE NEW.component WHEN 'program_episode_occurrence' THEN 'episode' WHEN 'publishing_publication_text' THEN 'text_version' ELSE 'work' END;
    EXECUTE format('SELECT shape FROM public.%I WHERE id=$1',TG_ARGV[0]||'_identity') INTO STRICT shape_name USING parent_id;
    IF shape_name<>expected_shape THEN RAISE EXCEPTION 'Child source target has another native shape' USING ERRCODE='23514'; END IF;
    IF TG_ARGV[0]='publishing' AND parent_id::text<>NEW.component_key THEN RAISE EXCEPTION 'Coverage source target differs from native component identity' USING ERRCODE='23514'; END IF;
  END IF;
  IF NEW.component='publishing_publication_facet' AND NEW.source_value->'fields'->>'definitionRevisionId' IS NOT NULL AND (NEW.source_value->'fields'->>'definitionRevisionId')::uuid::text<>NEW.component_key THEN RAISE EXCEPTION 'Facet source meaning differs from component identity' USING ERRCODE='23514'; END IF;
  FOREACH field_name IN ARRAY ARRAY['definitionRevisionId','kindRevisionId'] LOOP
    source_definition_id:=(NEW.source_value->'fields'->>field_name)::uuid;
    IF source_definition_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.catalog_definition_revision r JOIN public.catalog_definition d ON d.id=r.definition_id WHERE r.id=source_definition_id AND d.kind='vocabulary') THEN RAISE EXCEPTION 'Child source classification requires an exact vocabulary revision' USING ERRCODE='23514'; END IF;
  END LOOP;
  RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION public.catalog_child_source_guard_application()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE application public.catalog_source_application%ROWTYPE; proposal_state text; before_row record; after_row record; current_id uuid;
BEGIN
  IF TG_ARGV[0] NOT IN ('program','publishing') OR NEW.component NOT LIKE TG_ARGV[0]||'_%' OR NEW.component_key !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RAISE EXCEPTION 'Child application owner differs' USING ERRCODE='23514'; END IF;
  SELECT * INTO STRICT application FROM public.catalog_source_application WHERE source_record_id=NEW.source_record_id AND proposal_id=NEW.proposal_id AND action=NEW.action;
  SELECT state INTO STRICT proposal_state FROM public.catalog_source_adoption_proposal WHERE source_record_id=NEW.source_record_id AND id=NEW.proposal_id;
  IF NEW.position>=application.change_count OR (NEW.action='apply' AND proposal_state<>'pending') OR (NEW.action='withdraw' AND proposal_state<>'applied') THEN RAISE EXCEPTION 'Child change requires its in-progress source application' USING ERRCODE='23514'; END IF;
  EXECUTE format('SELECT component,component_key,component_sequence FROM public.%I WHERE owner_id=$1 AND id=$2',TG_ARGV[0]||'_component_revision') INTO STRICT after_row USING NEW.owner_id,NEW.after_revision_id;
  IF after_row.component<>NEW.component OR after_row.component_key<>NEW.component_key THEN RAISE EXCEPTION 'Child application after history differs' USING ERRCODE='23514'; END IF;
  IF NEW.before_revision_id IS NOT NULL THEN
    EXECUTE format('SELECT component,component_key,component_sequence FROM public.%I WHERE owner_id=$1 AND id=$2',TG_ARGV[0]||'_component_revision') INTO STRICT before_row USING NEW.owner_id,NEW.before_revision_id;
    IF before_row.component<>NEW.component OR before_row.component_key<>NEW.component_key OR before_row.component_sequence>=after_row.component_sequence THEN RAISE EXCEPTION 'Child application history order differs' USING ERRCODE='23514'; END IF;
  END IF;
  EXECUTE format('SELECT history_id FROM public.%I WHERE owner_id=$1 AND component=$2 AND component_key=$3',TG_ARGV[0]||'_component_head') INTO STRICT current_id USING NEW.owner_id,NEW.component,NEW.component_key;
  IF current_id<>NEW.after_revision_id THEN RAISE EXCEPTION 'Child application does not identify the current child head' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION public.catalog_child_source_guard_baseline()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE source_row record; native record; previous_sequence bigint; root public.catalog_source_binding_revision%ROWTYPE; matched boolean;
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Child source baselines are retained evidence' USING ERRCODE='23514'; END IF;
  IF TG_OP='UPDATE' AND (NEW.source_record_id,NEW.mapping_key,NEW.correspondence_revision,NEW.mapping_owner,NEW.owner_id,NEW.component,NEW.component_key) IS DISTINCT FROM (OLD.source_record_id,OLD.mapping_key,OLD.correspondence_revision,OLD.mapping_owner,OLD.owner_id,OLD.component,OLD.component_key) THEN RAISE EXCEPTION 'Child baseline identity is immutable' USING ERRCODE='23514'; END IF;
  SELECT * INTO STRICT root FROM public.catalog_source_binding_revision WHERE source_record_id=NEW.source_record_id AND mapping_key=NEW.mapping_key AND revision=NEW.correspondence_revision;
  IF root.correspondence_revision<>root.revision OR root.owner<>NEW.mapping_owner OR NOT public.catalog_source_application_includes_epoch(NEW.source_record_id,NEW.proposal_id,NEW.mapping_key,NEW.correspondence_revision) THEN RAISE EXCEPTION 'Child baseline requires an admitted application epoch' USING ERRCODE='23514'; END IF;
  EXECUTE format('SELECT history_id,source_path FROM public.%I WHERE source_record_id=$1 AND mapping_key=$2 AND correspondence_revision=$3 AND snapshot_id=$4 AND owner_id=$5 AND component=$6 AND component_key=$7',TG_ARGV[0]||'_component_source_occurrence') INTO STRICT source_row USING NEW.source_record_id,NEW.mapping_key,NEW.correspondence_revision,NEW.snapshot_id,NEW.owner_id,NEW.component,NEW.component_key;
  IF source_row.history_id<>NEW.source_history_id OR source_row.source_path<>NEW.source_path THEN RAISE EXCEPTION 'Child baseline source occurrence differs' USING ERRCODE='23514'; END IF;
  EXECUTE format('SELECT h.id,h.component,h.component_key,h.component_sequence FROM public.%I head JOIN public.%I h ON h.owner_id=head.owner_id AND h.id=head.history_id WHERE head.owner_id=$1 AND head.component=$2 AND head.component_key=$3',TG_ARGV[0]||'_component_head',TG_ARGV[0]||'_component_revision') INTO STRICT native USING NEW.owner_id,NEW.component,NEW.component_key;
  IF native.id<>NEW.current_history_id THEN RAISE EXCEPTION 'Child baseline current history is stale' USING ERRCODE='23514'; END IF;
  IF TG_OP='UPDATE' THEN
    EXECUTE format('SELECT component_sequence FROM public.%I WHERE owner_id=$1 AND id=$2',TG_ARGV[0]||'_component_revision') INTO STRICT previous_sequence USING OLD.owner_id,OLD.current_history_id;
    IF native.component_sequence<=previous_sequence THEN RAISE EXCEPTION 'Child baseline history must advance' USING ERRCODE='23514'; END IF;
  END IF;
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE source_record_id=$1 AND proposal_id=$2 AND action=$3 AND owner_id=$4 AND component=$5 AND component_key=$6 AND after_revision_id=$7)',TG_ARGV[0]||'_component_source_application_change') INTO matched USING NEW.source_record_id,NEW.proposal_id,NEW.action,NEW.owner_id,NEW.component,NEW.component_key,NEW.current_history_id;
  IF NOT matched THEN RAISE EXCEPTION 'Child baseline current history lacks its exact application' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;

DO $$
DECLARE owner_name text; table_name text;
BEGIN
  FOREACH owner_name IN ARRAY ARRAY['program','publishing'] LOOP
    FOREACH table_name IN ARRAY ARRAY[owner_name||'_component_source_occurrence',owner_name||'_component_source_application_change'] LOOP
      EXECUTE format('DROP TRIGGER IF EXISTS catalog_child_source_immutable ON public.%I',table_name);
      EXECUTE format('CREATE TRIGGER catalog_child_source_immutable BEFORE UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.catalog_source_guard_immutable_evidence()',table_name);
    END LOOP;
    EXECUTE format('DROP TRIGGER IF EXISTS catalog_child_source_occurrence_guard ON public.%I',owner_name||'_component_source_occurrence');
    EXECUTE format('CREATE TRIGGER catalog_child_source_occurrence_guard BEFORE INSERT ON public.%I FOR EACH ROW EXECUTE FUNCTION public.catalog_child_source_guard_occurrence(%L)',owner_name||'_component_source_occurrence',owner_name);
    EXECUTE format('DROP TRIGGER IF EXISTS catalog_child_source_application_guard ON public.%I',owner_name||'_component_source_application_change');
    EXECUTE format('CREATE TRIGGER catalog_child_source_application_guard BEFORE INSERT ON public.%I FOR EACH ROW EXECUTE FUNCTION public.catalog_child_source_guard_application(%L)',owner_name||'_component_source_application_change',owner_name);
    EXECUTE format('DROP TRIGGER IF EXISTS catalog_child_source_baseline_guard ON public.%I',owner_name||'_component_source_baseline');
    EXECUTE format('CREATE TRIGGER catalog_child_source_baseline_guard BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.catalog_child_source_guard_baseline(%L)',owner_name||'_component_source_baseline',owner_name);
  END LOOP;
END $$;


CREATE OR REPLACE FUNCTION public.catalog_guard_supporting_revision()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE owner_revision bigint;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'Supporting catalog history is append-only'
      USING ERRCODE = '23514', CONSTRAINT = 'catalog_supporting_history_immutable';
  END IF;
  EXECUTE format('SELECT revision FROM public.%I WHERE id = $1', TG_ARGV[0])
    INTO owner_revision USING NEW.owner_id;
  IF owner_revision IS DISTINCT FROM NEW.revision THEN
    RAISE EXCEPTION 'Supporting catalog revision must match its current owner revision'
      USING ERRCODE = '23514', CONSTRAINT = 'catalog_supporting_revision_head_check';
  END IF;
  RETURN NEW;
END;
$$;

