-- Ordinary search callers request Tag documents. Tag Path curation requests
-- Tag Path documents explicitly through the same bounded PGroonga primitive.
CREATE OR REPLACE FUNCTION public.search_tag_suggestion_candidates(
    p_query text,
    p_languages text[],
    p_estimated_postings_limit integer,
    p_limit integer
) RETURNS TABLE (tag_id uuid, search_score double precision, candidate_rank integer)
    LANGUAGE plpgsql
    SECURITY DEFINER
    SET search_path = pg_catalog, public, pg_temp
    AS $$
DECLARE
    candidate_language text;
    candidate_column text;
    index_column text;
    keyword text;
    keyword_result jsonb;
    keyword_size bigint;
    estimated_postings bigint := 0;
    estimated_postings_limit_ceiling constant integer := 50000;
    match_columns text := '';
    search_columns text[] := ARRAY[]::text[];
    filter_expression text := 'pgroonga_tuple_is_alive(_key)';
    command_result jsonb;
    return_code integer;
    escaped_query text;
BEGIN
    IF p_query IS NULL OR btrim(p_query) = '' OR char_length(p_query) > 80 THEN
        RAISE EXCEPTION 'invalid Tag suggestion query' USING ERRCODE = '22023';
    END IF;
    IF p_languages IS NULL
       OR NOT p_languages <@ ARRAY['zh', 'en', 'ja', 'ko', 'de', 'fr', 'es']::text[] THEN
        RAISE EXCEPTION 'invalid text language boundary' USING ERRCODE = '22023';
    END IF;
    IF p_limit IS NULL OR p_limit < 1 OR p_limit > 80 THEN
        RAISE EXCEPTION 'invalid Tag suggestion result limit' USING ERRCODE = '22023';
    END IF;
    IF p_estimated_postings_limit IS NULL
       OR p_estimated_postings_limit < 1
       OR p_estimated_postings_limit > estimated_postings_limit_ceiling THEN
        RAISE EXCEPTION 'invalid text posting budget' USING ERRCODE = '22023';
    END IF;

    escaped_query := public.pgroonga_query_escape(p_query);
    IF cardinality(p_languages) = 0 THEN
        search_columns := ARRAY['text_all'];
    ELSE
        FOREACH candidate_language IN ARRAY ARRAY['zh', 'en', 'ja', 'ko', 'de', 'fr', 'es']::text[]
        LOOP
            IF candidate_language = ANY(p_languages) THEN
                search_columns := array_append(search_columns, 'text_' || candidate_language);
            END IF;
        END LOOP;
    END IF;

    FOREACH candidate_column IN ARRAY search_columns LOOP
        match_columns := match_columns
            || CASE WHEN match_columns = '' THEN '' ELSE ' || ' END
            || candidate_column;
        index_column := public.pgroonga_index_column_name(
            'unit_search_document_pgroonga_idx', candidate_column
        );
        FOREACH keyword IN ARRAY public.pgroonga_query_extract_keywords(escaped_query)
        LOOP
            keyword_result := public.pgroonga_command('table_tokenize', ARRAY[
                'table', split_part(index_column, '.', 1),
                'string', keyword,
                'index_column', split_part(index_column, '.', 2),
                'mode', 'GET'
            ])::jsonb;
            return_code := (keyword_result #>> '{0,0}')::integer;
            IF return_code IS DISTINCT FROM 0 THEN
                RAISE EXCEPTION 'Groonga estimate command failed with code %', return_code;
            END IF;
            SELECT coalesce(sum((token.value ->> 'estimated_size')::bigint), 0)
            INTO keyword_size
            FROM jsonb_array_elements(coalesce(keyword_result #> '{1}', '[]'::jsonb)) AS token(value);
            estimated_postings := estimated_postings + keyword_size;
            EXIT WHEN estimated_postings > p_estimated_postings_limit;
        END LOOP;
        EXIT WHEN estimated_postings > p_estimated_postings_limit;
    END LOOP;

    -- Suggestions must never degrade into unrelated recent Tags. Callers show an
    -- empty result and allow a narrower query when the fixed posting budget is exceeded.
    IF estimated_postings > p_estimated_postings_limit THEN
        RETURN;
    END IF;

    filter_expression := filter_expression || ' && unit_owner == '
        || public.pgroonga_escape('tag');
    command_result := public.pgroonga_command('select', ARRAY[
        'table', public.pgroonga_table_name('unit_search_document_pgroonga_idx'),
        'command_version', '3',
        'cache', 'yes',
        'match_columns', match_columns,
        'query', escaped_query,
        'filter', filter_expression,
        'sort_keys', '-_score,-search_order_key',
        'limit', p_limit::text,
        'output_columns', '_score,search_order_key'
    ])::jsonb;
    return_code := (command_result #>> '{header,return_code}')::integer;
    IF return_code IS DISTINCT FROM 0 THEN
        RAISE EXCEPTION 'PGroonga Tag suggestion command failed with code %', return_code;
    END IF;

    RETURN QUERY
    SELECT right(record.value ->> 1, 36)::uuid,
        (record.value ->> 0)::double precision,
        record.position::integer
    FROM jsonb_array_elements(
        coalesce(command_result #> '{body,records}', '[]'::jsonb)
    ) WITH ORDINALITY AS record(value, position)
    ORDER BY record.position;
END;
$$;

REVOKE ALL ON FUNCTION public.search_tag_suggestion_candidates(
    text, text[], integer, integer
) FROM PUBLIC;

CREATE OR REPLACE FUNCTION public.search_text_candidates(
    p_queries text[],
    p_languages text[],
    p_unit_owner text,
    p_shapes text[],
    p_after_updated_at_micros bigint,
    p_after_unit_id uuid,
    p_estimated_postings_limit integer,
    p_limit integer
) RETURNS TABLE (unit_id uuid, unit_updated_at_micros bigint, search_matched boolean)
    LANGUAGE plpgsql
    SECURITY DEFINER
    SET search_path = pg_catalog, public, pg_temp
    AS $$
DECLARE
    candidate_language text;
    candidate_column text;
    index_column text;
    keyword text;
    keyword_result jsonb;
    keyword_size bigint;
    estimated_postings bigint := 0;
    estimated_postings_limit_ceiling constant integer := 50000;
    match_columns text := '';
    search_columns text[] := ARRAY[]::text[];
    after_order_key text;
    filter_expression text := 'pgroonga_tuple_is_alive(_key)';
    command_result jsonb;
    return_code integer;
    expanded_query text;
BEGIN
    IF p_queries IS NULL
       OR cardinality(p_queries) < 1
       OR cardinality(p_queries) > 3
       OR EXISTS (
           SELECT 1
           FROM unnest(p_queries) AS query_variant(value)
           WHERE value IS NULL
              OR btrim(value) = ''
              OR char_length(value) > 512
       )
       OR coalesce((SELECT sum(char_length(value)) FROM unnest(p_queries) AS query_variant(value)), 0) > 1536 THEN
        RAISE EXCEPTION 'invalid text query variants' USING ERRCODE = '22023';
    END IF;
    IF p_languages IS NULL
       OR NOT p_languages <@ ARRAY['zh', 'en', 'ja', 'ko', 'de', 'fr', 'es']::text[] THEN
        RAISE EXCEPTION 'invalid text language boundary' USING ERRCODE = '22023';
    END IF;
    IF p_shapes IS NULL OR cardinality(p_shapes)>50 THEN RAISE EXCEPTION 'invalid shape boundary' USING ERRCODE='22023'; END IF;
    IF p_unit_owner IS NULL OR p_unit_owner NOT IN ('publishing','music','program','software','entity','grouping','reference','distribution','post','video','audio','poll','zone','realm','realm_rule','custom_theme','collection','tag','tag_path','label') THEN
      RAISE EXCEPTION 'invalid Unit owner boundary' USING ERRCODE='22023';
    END IF;
    IF p_limit IS NULL OR p_limit < 1 OR p_limit > 4097 THEN
        RAISE EXCEPTION 'invalid text result limit' USING ERRCODE = '22023';
    END IF;
    IF p_estimated_postings_limit IS NULL
       OR p_estimated_postings_limit < 1
       OR p_estimated_postings_limit > estimated_postings_limit_ceiling THEN
        RAISE EXCEPTION 'invalid text posting budget' USING ERRCODE = '22023';
    END IF;
    IF num_nonnulls(p_after_updated_at_micros, p_after_unit_id) NOT IN (0, 2)
       OR p_after_updated_at_micros < 0 THEN
        RAISE EXCEPTION 'invalid text cursor' USING ERRCODE = '22023';
    END IF;

    SELECT string_agg(
        '(' || public.pgroonga_query_escape(value) || ')',
        ' OR ' ORDER BY ordinality
    )
    INTO expanded_query
    FROM unnest(p_queries) WITH ORDINALITY AS query_variant(value, ordinality);

    IF cardinality(p_languages) = 0 THEN
        search_columns := ARRAY['text_all'];
    ELSE
        FOREACH candidate_language IN ARRAY ARRAY['zh', 'en', 'ja', 'ko', 'de', 'fr', 'es']::text[]
        LOOP
            IF candidate_language = ANY(p_languages) THEN
                search_columns := array_append(search_columns, 'text_' || candidate_language);
            END IF;
        END LOOP;
    END IF;

    FOREACH candidate_column IN ARRAY search_columns LOOP
        match_columns := match_columns
            || CASE WHEN match_columns = '' THEN '' ELSE ' || ' END
            || candidate_column;
        index_column := public.pgroonga_index_column_name(
            'unit_search_document_pgroonga_idx', candidate_column
        );
        FOREACH keyword IN ARRAY public.pgroonga_query_extract_keywords(expanded_query)
        LOOP
            keyword_result := public.pgroonga_command('table_tokenize', ARRAY[
                'table', split_part(index_column, '.', 1),
                'string', keyword,
                'index_column', split_part(index_column, '.', 2),
                'mode', 'GET'
            ])::jsonb;
            return_code := (keyword_result #>> '{0,0}')::integer;
            IF return_code IS DISTINCT FROM 0 THEN
                RAISE EXCEPTION 'Groonga estimate command failed with code %', return_code;
            END IF;
            SELECT coalesce(sum((token.value ->> 'estimated_size')::bigint), 0)
            INTO keyword_size
            FROM jsonb_array_elements(coalesce(keyword_result #> '{1}', '[]'::jsonb)) AS token(value);
            estimated_postings := estimated_postings + keyword_size;
            EXIT WHEN estimated_postings > p_estimated_postings_limit;
        END LOOP;
        EXIT WHEN estimated_postings > p_estimated_postings_limit;
    END LOOP;

    IF estimated_postings > p_estimated_postings_limit THEN
        RETURN QUERY EXECUTE format('SELECT candidate.id,(extract(epoch FROM candidate.updated_at)*1000000)::bigint,false FROM public.%I candidate
         WHERE candidate.status=''published'' AND candidate.visibility=''public'' AND candidate.moderation_status=''approved'' AND candidate.deleted_at IS NULL
          AND (cardinality($4)=0 OR %s=ANY($4))
          AND ($1 IS NULL OR (candidate.updated_at,candidate.id)<(to_timestamp($2::numeric/1000000),$1))
         ORDER BY candidate.updated_at DESC,candidate.id DESC LIMIT $3',CASE WHEN p_unit_owner=ANY(ARRAY['publishing','music','program','software','entity','grouping','reference','distribution']) THEN p_unit_owner||'_identity' ELSE p_unit_owner END,CASE WHEN p_unit_owner=ANY(ARRAY['publishing','music','program','software','entity','grouping','reference','distribution']) THEN 'candidate.shape' WHEN p_unit_owner='post' THEN 'candidate.kind::text' ELSE quote_literal(p_unit_owner) END)
         USING p_after_unit_id,p_after_updated_at_micros,p_limit,p_shapes;
        RETURN;
    END IF;

    filter_expression := filter_expression || ' && unit_owner == '
        || public.pgroonga_escape(p_unit_owner);
    IF cardinality(p_shapes)>0 THEN
     filter_expression := filter_expression||' && ('||(SELECT string_agg('unit_shape == '||public.pgroonga_escape(shape),' || ') FROM unnest(p_shapes) shape)||')';
    END IF;
    IF p_after_unit_id IS NOT NULL THEN
        after_order_key := lpad(p_after_updated_at_micros::text, 20, '0')
            || ':' || p_after_unit_id::text;
        filter_expression := filter_expression || ' && search_order_key < '
            || public.pgroonga_escape(after_order_key);
    END IF;

    command_result := public.pgroonga_command('select', ARRAY[
        'table', public.pgroonga_table_name('unit_search_document_pgroonga_idx'),
        'command_version', '3',
        'cache', 'no',
        'match_columns', match_columns,
        'query', expanded_query,
        'filter', filter_expression,
        'sort_keys', '-search_order_key',
        'limit', p_limit::text,
        'output_columns', 'search_order_key'
    ])::jsonb;
    return_code := (command_result #>> '{header,return_code}')::integer;
    IF return_code IS DISTINCT FROM 0 THEN
        RAISE EXCEPTION 'PGroonga text command failed with code %', return_code;
    END IF;

    RETURN QUERY
    SELECT right(record.value ->> 0, 36)::uuid,
        split_part(record.value ->> 0, ':', 1)::bigint,
        true
    FROM jsonb_array_elements(
        coalesce(command_result #> '{body,records}', '[]'::jsonb)
    ) WITH ORDINALITY AS record(value, position)
    ORDER BY record.position;
END;
$$;

REVOKE ALL ON FUNCTION public.search_text_candidates(
    text[], text[], text, text[], bigint, uuid, integer, integer
) FROM PUBLIC;


-- Canonical current definitions for independent Unit license grants.
--
-- Grant facts are immutable. Offering end is write-once. Recognition may move
-- only between recognized and invalidated, and only while the offering is open.

CREATE OR REPLACE FUNCTION public.guard_unit_license_grant_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'unit_license_grant history is immutable';
  END IF;

  IF ROW(
    NEW.id,
    NEW.unit_id,
    NEW.license_id,
    NEW.granted_by_profile_id,
    NEW.granted_at
  ) IS DISTINCT FROM ROW(
    OLD.id,
    OLD.unit_id,
    OLD.license_id,
    OLD.granted_by_profile_id,
    OLD.granted_at
  ) THEN
    RAISE EXCEPTION 'unit_license_grant grant facts are immutable';
  END IF;

  IF OLD.offering_ended_at IS NOT NULL
     AND ROW(NEW.offering_ended_at, NEW.offering_ended_by_profile_id)
         IS DISTINCT FROM ROW(OLD.offering_ended_at, OLD.offering_ended_by_profile_id)
  THEN
    RAISE EXCEPTION 'unit_license_grant offering end is terminal';
  END IF;

  IF OLD.offering_ended_at IS NULL
     AND NEW.offering_ended_at IS NOT NULL
     AND NEW.offering_ended_by_profile_id IS NULL
  THEN
    RAISE EXCEPTION 'unit_license_grant offering end requires an actor';
  END IF;

  IF OLD.offering_ended_at IS NULL
     AND NEW.offering_ended_at IS NULL
     AND NEW.offering_ended_by_profile_id IS DISTINCT FROM OLD.offering_ended_by_profile_id
  THEN
    RAISE EXCEPTION 'unit_license_grant offering end cannot be rewritten';
  END IF;

  IF NEW.recognition_status IS DISTINCT FROM OLD.recognition_status THEN
    IF OLD.offering_ended_at IS NOT NULL THEN
      RAISE EXCEPTION 'unit_license_grant recognition cannot change after offering end';
    END IF;
    IF NOT (
      (OLD.recognition_status = 'recognized' AND NEW.recognition_status = 'invalidated')
      OR (OLD.recognition_status = 'invalidated' AND NEW.recognition_status = 'recognized')
    ) THEN
      RAISE EXCEPTION 'unit_license_grant recognition transition is not allowed';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS unit_license_grant_guard_mutation ON public.unit_license_grant;
CREATE TRIGGER unit_license_grant_guard_mutation
    BEFORE DELETE OR UPDATE ON public.unit_license_grant
    FOR EACH ROW
    EXECUTE FUNCTION public.guard_unit_license_grant_mutation();


-- Retired identities have no live search projection. The empty upsert removes its old document.
CREATE OR REPLACE FUNCTION public.refresh_unit_search_document(p_unit_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path = pg_catalog, public
    AS $$
BEGIN
    INSERT INTO public.unit_search_document (
        unit_id,
        unit_updated_at_micros,
        search_order_key,
        text_all, text_zh, text_en, text_ja, text_ko, text_de, text_fr, text_es
    )
    SELECT candidate.id,
        (extract(epoch FROM candidate.updated_at) * 1000000)::bigint,
        lpad(((extract(epoch FROM candidate.updated_at) * 1000000)::bigint)::text, 20, '0')
            || ':' || candidate.id::text,
        nullif(concat_ws(E'\n',
            localization.metadata_zh, localization.content_zh,
            localization.metadata_en, localization.content_en,
            localization.metadata_ja, localization.content_ja,
            localization.metadata_ko, localization.content_ko,
            localization.metadata_de, localization.content_de,
            localization.metadata_fr, localization.content_fr,
            localization.metadata_es, localization.content_es,
            alias_document.aliases_all), ''),
        nullif(concat_ws(E'\n', localization.metadata_zh,
            localization.content_zh, alias_document.aliases_neutral,
            alias_document.aliases_zh), ''),
        nullif(concat_ws(E'\n', localization.metadata_en,
            localization.content_en, alias_document.aliases_neutral,
            alias_document.aliases_en), ''),
        nullif(concat_ws(E'\n', localization.metadata_ja,
            localization.content_ja, alias_document.aliases_neutral,
            alias_document.aliases_ja), ''),
        nullif(concat_ws(E'\n', localization.metadata_ko,
            localization.content_ko, alias_document.aliases_neutral,
            alias_document.aliases_ko), ''),
        nullif(concat_ws(E'\n', localization.metadata_de,
            localization.content_de, alias_document.aliases_neutral,
            alias_document.aliases_de), ''),
        nullif(concat_ws(E'\n', localization.metadata_fr,
            localization.content_fr, alias_document.aliases_neutral,
            alias_document.aliases_fr), ''),
        nullif(concat_ws(E'\n', localization.metadata_es,
            localization.content_es, alias_document.aliases_neutral,
            alias_document.aliases_es), '')
    FROM public.read_unit_state(p_unit_id) AS candidate
    LEFT JOIN LATERAL (
        SELECT
            max(public.current_search_metadata_v1(title, summary, description))
                FILTER (WHERE language = 'zh') AS metadata_zh,
            max(public.current_search_metadata_v1(title, summary, description))
                FILTER (WHERE language = 'en') AS metadata_en,
            max(public.current_search_metadata_v1(title, summary, description))
                FILTER (WHERE language = 'ja') AS metadata_ja,
            max(public.current_search_metadata_v1(title, summary, description))
                FILTER (WHERE language = 'ko') AS metadata_ko,
            max(public.current_search_metadata_v1(title, summary, description))
                FILTER (WHERE language = 'de') AS metadata_de,
            max(public.current_search_metadata_v1(title, summary, description))
                FILTER (WHERE language = 'fr') AS metadata_fr,
            max(public.current_search_metadata_v1(title, summary, description))
                FILTER (WHERE language = 'es') AS metadata_es,
            max(public.current_search_text_v1(content))
                FILTER (WHERE language = 'zh' AND content_status = 'published') AS content_zh,
            max(public.current_search_text_v1(content))
                FILTER (WHERE language = 'en' AND content_status = 'published') AS content_en,
            max(public.current_search_text_v1(content))
                FILTER (WHERE language = 'ja' AND content_status = 'published') AS content_ja,
            max(public.current_search_text_v1(content))
                FILTER (WHERE language = 'ko' AND content_status = 'published') AS content_ko,
            max(public.current_search_text_v1(content))
                FILTER (WHERE language = 'de' AND content_status = 'published') AS content_de,
            max(public.current_search_text_v1(content))
                FILTER (WHERE language = 'fr' AND content_status = 'published') AS content_fr,
            max(public.current_search_text_v1(content))
                FILTER (WHERE language = 'es' AND content_status = 'published') AS content_es
        FROM public.unit_localization
        WHERE unit_id = candidate.id
    ) AS localization ON true
    LEFT JOIN LATERAL (
        SELECT
            string_agg(search_alias.term, E'\n' ORDER BY search_alias.id) AS aliases_all,
            string_agg(search_alias.term, E'\n' ORDER BY search_alias.id)
                FILTER (WHERE search_alias.language IS NULL) AS aliases_neutral,
            string_agg(search_alias.term, E'\n' ORDER BY search_alias.id)
                FILTER (WHERE search_alias.language = 'zh') AS aliases_zh,
            string_agg(search_alias.term, E'\n' ORDER BY search_alias.id)
                FILTER (WHERE search_alias.language = 'en') AS aliases_en,
            string_agg(search_alias.term, E'\n' ORDER BY search_alias.id)
                FILTER (WHERE search_alias.language = 'ja') AS aliases_ja,
            string_agg(search_alias.term, E'\n' ORDER BY search_alias.id)
                FILTER (WHERE search_alias.language = 'ko') AS aliases_ko,
            string_agg(search_alias.term, E'\n' ORDER BY search_alias.id)
                FILTER (WHERE search_alias.language = 'de') AS aliases_de,
            string_agg(search_alias.term, E'\n' ORDER BY search_alias.id)
                FILTER (WHERE search_alias.language = 'fr') AS aliases_fr,
            string_agg(search_alias.term, E'\n' ORDER BY search_alias.id)
                FILTER (WHERE search_alias.language = 'es') AS aliases_es
        FROM public.unit_alias AS search_alias
        LEFT JOIN public.unit_alias_vote_stat AS vote_stat
            ON vote_stat.alias_id = search_alias.id
        WHERE search_alias.unit_id = candidate.id
          AND search_alias.withdrawn_at IS NULL
          AND (search_alias.pinned OR coalesce(vote_stat.score, 0) >= 3)
    ) AS alias_document ON true
    WHERE candidate.id = p_unit_id
      AND candidate.deleted_at IS NULL
    ON CONFLICT (unit_id) DO UPDATE SET
        unit_updated_at_micros = excluded.unit_updated_at_micros,
        search_order_key = excluded.search_order_key,
        text_all = excluded.text_all,
        text_zh = excluded.text_zh,
        text_en = excluded.text_en,
        text_ja = excluded.text_ja,
        text_ko = excluded.text_ko,
        text_de = excluded.text_de,
        text_fr = excluded.text_fr,
        text_es = excluded.text_es;

    IF NOT FOUND THEN
        DELETE FROM public.unit_search_document WHERE unit_id = p_unit_id;
    END IF;
END;
$$;


-- Installation state, not imported legacy content.
INSERT INTO public.catalog_routing_control(singleton, ready) VALUES (true, true)
ON CONFLICT (singleton) DO NOTHING;
